using INPS.Pensioni.Liquidazione.BLCommon;
using System;
using System.Collections.Generic;
using System.Linq;
using EntityBLCommon = INPS.Pensioni.Liquidazione.BLCommon.Entity;

namespace INPS.Pensioni.LiquidazioneAgo
{
    public class GestioneControlli
    {
        #region DatiCalcolo
        public static bool ControlsDatiRetributivi(GestioneCalcolo.DatiCalcoloRetributivo retr, char? codiceLiquidazione, GestionePensione.DatiPensione datiPensione,
            List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> listaCodeGestioneCalcoloRetributivo, DateTime? dataMorteDA, Utility.TipoCalcolo tipoCalcolo, bool isRiaperturaDomanda, List<GestioneCalcolo.DatiCalcoloContributivo> listaDatiCalcoloContributivo, List<GestioneDecodifica.CodeGestioneCalcoloContributivo> listaCodeGestioneCalcoloContributivo,
            GestioneDanteCausa.DatiDanteCausa danteCausa, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            int pdirsup = 0;
            int plavaut = 0;

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            //ENG - Aggiornamento Memo 68/2022 IOPGI
            //ENG - Spacchettate SOPGI
            if (GestioneControlli.BypassaControlliRicSdaiContributivoK(datiPensione, listaDatiCalcoloContributivo, listaCodeGestioneCalcoloContributivo) ||
                GestioneControlli.BypassaControlliRic_VOCRED_CRED27_ContributivoL(datiPensione, listaDatiCalcoloContributivo, listaCodeGestioneCalcoloContributivo) ||
                Utility.IsDomandaVOPGI(datiPensione.SiglaCategoria) || (Utility.IsDomandaIOPGI(datiPensione.SiglaCategoria) && !Utility.IsDomandaIOPGI_AGI(datiPensione))
                || Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa))
                return true;


            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);

            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);

            GetPdirusp_Plavaut(datiPensione, out pdirsup, out plavaut);

            char codNat1;
            char codNat2;
            char codNat3;
            Utility.GetCodiciNatura(datiPensione.NaturaPensione, out codNat1, out codNat2, out codNat3);
            #endregion Recupero Dati

            if (retr != null)
            {
                string codiceGestione = GetGestioneRetributiva(retr.CodiceGestione, listaCodeGestioneCalcoloRetributivo);

                //I Codici Gestione (VRGEST) ammessi sono “1”, “2”, “3”, “4”, “7”, “H”, “Q", "S"
                //Con il Campo DO-NOTE = a "RAL", "R22", "R23", "R24", "R25", "R44",  "R45"
                //I Codici Gestione (VRGEST) ammessi sono “1”, “2”, “3”, “4”, “7”, “H”, “Q", "S", "1H", "2H", "3H", "4H"
                switch (codiceGestione)
                {
                    case "1":
                    case "2":
                    case "3":
                    case "4":
                    case "7":
                    case "H":
                    case "Q":
                    case "S":
                    case "P":
                        break;
                    case "1H":
                    case "2H":
                    case "3H":
                    case "4H":
                        if (filtro != "RAL" && filtro != "R22" && filtro != "R23" && filtro != "R24" &&
                            filtro != "R25" && filtro != "R44" && filtro != "R45" && (!(Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && codNat2 == 'H')))
                        {
                            messaggioVideo = "Codice gestione " + codiceGestione + " non ammesso";
                            return false;
                        }
                        break;
                    case "A":
                        if (siglaCategoria != "VDAI" && siglaCategoria != "SDAI" && siglaCategoria != "IDAI" && siglaCategoria != "VOPGI" && siglaCategoria != "IOPGI")
                        {
                            messaggioVideo = "Il Codice Gestione A non è ammesso per la sigla categoria " + siglaCategoria;
                            return false;
                        }
                        break;
                    case "I":
                    case "M":
                    case "N":
                        if (siglaCategoria != "VR" && siglaCategoria != "VOART" && siglaCategoria != "VOCOM" && siglaCategoria != "VDAI" && siglaCategoria != "SDAI" && siglaCategoria != "IDAI")
                        {
                            messaggioVideo = "Il Codice Gestione " + codiceGestione + " non è ammesso per la sigla categoria " + siglaCategoria;
                            return false;
                        }
                        break;
                    case "B":
                    case "C":
                    case "D":
                    case "F":
                    case "G":
                    case "L":
                    case "O":
                        if (siglaCategoria != "VDAI" && siglaCategoria != "SDAI" && siglaCategoria != "IDAI")
                        {
                            messaggioVideo = "Codice gestione " + codiceGestione + " non ammesso";
                            return false;
                        }
                        break;
                    default:
                        messaggioVideo = "Codice gestione " + codiceGestione + " non ammesso";
                        return false;
                }

                //Se l'Attività Economica (RAU1013) è = a 4 e la Professione Individuale (RAU1014) è = a 350:
                if (datiPensione.AttivitaEconomica.HasValue && datiPensione.AttivitaEconomica.Value == 4 &&
                    datiPensione.ProfessioneIndividuale.HasValue && datiPensione.ProfessioneIndividuale.Value == 350)
                {
                    //se il Campo PDIRSUP è = a 1 e la Data morte dell'assicurato (DAU1010) è antecedente a gennaio 2004 
                    //non è ammesso il Codice Gestione (VRGEST) = a “Q”
                    if (pdirsup == 1)
                    {
                        if (dataMorteDA.HasValue)
                        {
                            if (!Utility.DataSuccessivaA(dataMorteDA.Value, new DateTime(2004, 1, 1)))
                            {
                                if (codiceGestione == "Q")
                                {
                                    messaggioVideo = "Codice gestione Q non è ammesso";
                                    return false;
                                }
                            }
                        }
                    }
                    //se il Campo PDIRSUP è = a zero e la Decorrenza Originaria (RAU104) è superiore a gennaio 2004 non è ammesso 
                    //il Codice Gestione (VRGEST) = a “Q”
                    else
                    {
                        if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2004, 1, 1)))
                        {
                            if (codiceGestione == "Q")
                            {
                                messaggioVideo = "Codice gestione Q non è ammesso";
                                return false;
                            }
                        }
                    }
                }

                //Se l'Attività Economica (RAU1013) è diversa da 4 e la Professione Individuale (RAU1014) 
                //è diversa da 350 non è ammesso il Codice Gestione (VRGEST) = a “Q”
                if (datiPensione.AttivitaEconomica.HasValue && datiPensione.AttivitaEconomica.Value != 4 &&
                    datiPensione.ProfessioneIndividuale.HasValue && datiPensione.ProfessioneIndividuale.Value != 350)
                {
                    if (codiceGestione == "Q")
                    {
                        messaggioVideo = "Codice gestione Q non è ammesso";
                        return false;
                    }
                }

                //Il Codice Gestione (VRGEST) = a “7” è ammesso solo per la Categoria = a “VOMIN”, “SOMIN”
                if (codiceGestione == "7" && siglaCategoria != "VOMIN" && siglaCategoria != "SOMIN")
                {
                    messaggioVideo = "Codice gestione 7 è ammesso solo per la categoria VOMIN e SOMIN";
                    return false;
                }

                //Il Codice Gestione (VRGEST) = a “H” è ammesso solo per la Categoria = a “VOBANC”, “IOBANC”, “SOBANC”
                if (codiceGestione == "H" && siglaCategoria != "VOBANC" && siglaCategoria != "IOBANC" && siglaCategoria != "SOBANC" && siglaCategoria != "VDAI" && siglaCategoria != "IDAI" && siglaCategoria != "SDAI")
                {
                    messaggioVideo = "Codice gestione H è ammesso solo per la categoria VOBANC, IOBANC e SOBANC";
                    return false;
                }

                //Se la Categoria è = a "VO", "IO", "SO", "VOBANC", "IOBANC", "SOBANC", "VOCRED", "VOCOOP", "VOESO", 
                //"VOP", "IOP", "SOP", "VOMIN", "SOMIN" non sono ammessi i Codici Gestione (VRGEST) = a “2”, “3”, “4”
                switch (siglaCategoria)
                {
                    case "VO":
                    case "IO":
                    case "SO":
                    case "VOBANC":
                    case "IOBANC":
                    case "SOBANC":
                    case "VOCRED":
                    case "CRED27":
                    case "VOCOOP":
                    case "VOESO":
                    case "VOP":
                    case "IOP":
                    case "SOP":
                    case "VOMIN":
                    case "SOMIN":
                    case "COOP28":
                        if (codiceGestione == "2" || codiceGestione == "3" || codiceGestione == "4")
                        {
                            messaggioVideo = "Non sono ammessi i codici gestione 2, 3 e 4";
                            return false;
                        }
                        break;
                    default:
                        break;
                }

                //I Codici Quota (VRQUOTA) ammessi sono “A”, “B”
                if (retr.QuotePrimeLiquidate.HasValue &&
                    retr.QuotePrimeLiquidate.Value != 'A' && retr.QuotePrimeLiquidate.Value != 'B')
                {
                    messaggioVideo = "I codici quota ammessi sono A e B";
                    return false;
                }

                //Con il Campo DO-NOTE = a "RAL", "R22", "R23", "R24", "R25", "R44",  "R45" 
                if (filtro == "RAL" || filtro == "R22" || filtro == "R23" || filtro == "R24" ||
                    filtro == "R25" || filtro == "R44" || filtro == "R45")
                {
                    //Se la Categoria è = a “VO”, “IO”, “SO” non sono ammessi i Codici Gestione (VRGEST) = a “2”, “3”, “4”, “2H”, “3H”, “4H”
                    switch (siglaCategoria)
                    {
                        case "VO":
                        case "IO":
                        case "SO":
                            if (codiceGestione == "2H" || codiceGestione == "3H" || codiceGestione == "4H")
                            {
                                messaggioVideo = "Non sono ammessi i codici gestione 2H, 3H e 4H";
                                return false;
                            }
                            break;
                        default:
                            break;
                    }
                }
                if (!Utility.IsDomandaINPDAI(datiPensione.SiglaCategoria))
                {
                    //Le Settimane (VRSET) non possono essere più di 2080
                    if ((retr.NSettimaneQuotaA.HasValue && retr.NSettimaneQuotaA.Value > 2080) ||
                        (retr.NSettimaneQuotaB.HasValue && retr.NSettimaneQuotaB.Value > 2080))
                    {
                        messaggioVideo = "Le settimane non possono essere più di 2080";
                        return false;
                    }
                }
                //G.Arru -  I controlli per le DAI sono stati implementati nel metodo GestioneContrib.ControlsDatiCalcoloINPDAI(...)
                //else
                //{
                //    //Domande DAI
                //    //G.Arru - mail 20151117: Liq Pens - controllo DAI
                //    if ((retr.NSettimaneQuotaA.HasValue && retr.NSettimaneQuotaA.Value > 14400) ||
                //        (retr.NSettimaneQuotaB.HasValue && retr.NSettimaneQuotaB.Value > 14400))
                //    {
                //        messaggioVideo = "I giorni non possono essere più di 14400.";
                //        return false;
                //    }
                //}               

                if (Utility.IsDomandaVESO29(datiPensione.SiglaCategoria) && filtro == "OBG" && codiceGestione != "1")
                {
                    messaggioVideo = "Codice gestione retributiva " + codiceGestione + " non ammesso";
                    return false;
                }
            }
            //Se il Campo RAUE23 è = a “P” possono non esistere i dati Retributivi
            //(RETRIB)
            else
            {
                if (tipoCalcolo != Utility.TipoCalcolo.Contributivo)
                {
                    if (!(codiceLiquidazione.HasValue && codiceLiquidazione.Value.ToString().ToUpperInvariant() == "P"))
                    {
                        messaggioVideo = "I dati retributivi sono obbligatori";
                        return false;
                    }
                }
            }

            return true;
        }

        public static bool ControlsDatiRetributiviFinal(ref List<GestioneCalcolo.DatiCalcoloRetributivo> datiRetr, ref EntityBLCommon.ContenitoreObject contenitore, ref EntityBLCommon.ContenitoreDecodifica contenitoreDecodifica, List<GestioneAggiornamentoPECO.DatiContributivi> lDatiContributivi, List<GestioneCalcolo.DatiCalcoloContributivo> datiContr, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';
            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            int pdirsup = 0;
            int plavaut = 0;
            int panvein = 0;
            bool posticipo = false;
            bool presente = false;
            Utility.TipoDomanda tipoDomanda = Utility.GetTipoDomanda(contenitore.DatiPensione.Gruppo, contenitore.DatiPensione.Prodotto);
            List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> listaCodeGestioneCalcoloRetributivo = contenitoreDecodifica.ElencoCodeGestioneCalcoloRetributivo;

            bool isAnte96 = (Utility.IsDomandaAnte96(contenitore.DatiPensione, contenitore.DatiPensione, contenitore.DatiDanteCausa, contenitore.IsRiaperturaDomanda) != null);


            //ENG - Aggiornamento Memo 68/2022 IOPGI
            //ENG - Spacchettate SOPGI
            if (Utility.IsDomandaVOPGI(contenitore.DatiPensione.SiglaCategoria) || (Utility.IsDomandaIOPGI(contenitore.DatiPensione.SiglaCategoria) && !Utility.IsDomandaIOPGI_AGI(contenitore.DatiPensione))
                || Utility.IsDomandaSpacchettamentoSOPGIPost072022(contenitore.DatiPensione, contenitore.DatiDanteCausa) || isAnte96)
                return true;

            #region Recupero Dati
            Utility.GetCodiciNatura(contenitore.DatiPensione.NaturaPensione, out codNat1, out codNat2, out codNat3);

            GetFiltro_SiglaCategoria(contenitore.DatiPensione, out filtro, out siglaCategoria);

            GetCertificato_DecorrenzaPensione(contenitore.DatiPensione, out decorrenzaOriginaria, out certificato);

            GetPdirusp_Plavaut(contenitore.DatiPensione, out pdirsup, out plavaut);

            GetPanvein_Posticipo(contenitore.DatiPensione.NaturaPensione, contenitore.DatiPensione, out panvein, out posticipo);

            #endregion Recupero Dati

            if (datiRetr != null && datiRetr.Count > 0)
            {
                List<short> mesiDecDatiRetr = new List<short>();
                List<short> anniDecDatiRetr = new List<short>();
                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetr)
                {
                    short mese = 0;
                    short anno = 0;
                    MappingVersoHost.GetDecorrenzaRetr(GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo),
                        r.QuotePrimeLiquidate.HasValue ? r.QuotePrimeLiquidate.Value : ' ', r.CodiceTipoQuota, contenitore.DatiPensione, contenitore.DatiDanteCausa, contenitore.DatiControlloFelpe, contenitoreDecodifica.ElencoCtrlDecorrenzaRetrExINPDAI, contenitore.DatiIstruttoria != null ? contenitore.DatiIstruttoria.DecorrenzaOpzione : null,
                        r.DecorrenzaOriginariaPensione.HasValue ? new Utility.DifferenzaDateTime(r.DecorrenzaOriginariaPensione.Value) : null, r.RMS, out mese, out anno);
                    mesiDecDatiRetr.Add(mese);
                    anniDecDatiRetr.Add(anno);
                }
                List<GestioneCalcolo.DatiCalcoloRetributivo> datiRetrOrdered = null;
                OrdinaDatiRetributivi(contenitore.DatiPensione, datiRetr, mesiDecDatiRetr, listaCodeGestioneCalcoloRetributivo, out datiRetrOrdered);

                if (contenitore.DatiPensione != null && Utility.IsRicostituzione(contenitore.DatiPensione.Gruppo) && !String.IsNullOrEmpty(contenitore.DatiPensione.SiglaCategoria)
                  && contenitore.DatiPensione.SiglaCategoria.Trim().ToUpperInvariant() == "SDAI")
                {
                    if (contenitoreDecodifica.ElencoCodeGestioneCalcoloContributivo != null && contenitoreDecodifica.ElencoCodeGestioneCalcoloContributivo.Count > 0
                        && ((lDatiContributivi != null && lDatiContributivi.Count > 0) || (datiContr != null && datiContr.Count > 0)))
                    {
                        GestioneDecodifica.CodeGestioneCalcoloContributivo gestioneK = contenitoreDecodifica.ElencoCodeGestioneCalcoloContributivo.Find(x => x.TraduzioneSuGP.Trim().ToUpperInvariant() == "K");
                        if (gestioneK != null)
                        {
                            if ((lDatiContributivi != null && lDatiContributivi.Count > 0 && lDatiContributivi.Exists(x => x.CodGestione == gestioneK.Id))
                                || (datiContr != null && datiContr.Count > 0 && datiContr.Exists(x => x.CodiceGestione == gestioneK.Id)))
                            {
                                datiRetr = datiRetrOrdered;
                                return true;
                            }
                        }
                    }
                }

                if (contenitore.DatiPensione != null && Utility.IsRicostituzioneOrRiapertura(contenitore.DatiPensione, contenitore.IsRiaperturaDomanda)
                    && Utility.IsDomandaVOCRED_CRED27(contenitore.DatiPensione.SiglaCategoria))
                {
                    if (contenitoreDecodifica.ElencoCodeGestioneCalcoloContributivo != null && contenitoreDecodifica.ElencoCodeGestioneCalcoloContributivo.Count > 0
                        && ((lDatiContributivi != null && lDatiContributivi.Count > 0) || (datiContr != null && datiContr.Count > 0)))
                    {
                        GestioneDecodifica.CodeGestioneCalcoloContributivo gestioneL = contenitoreDecodifica.ElencoCodeGestioneCalcoloContributivo.Find(x => x.TraduzioneSuGP.Trim().ToUpperInvariant() == "L");
                        if (gestioneL != null)
                        {
                            if ((lDatiContributivi != null && lDatiContributivi.Count > 0 && lDatiContributivi.Exists(x => x.CodGestione == gestioneL.Id))
                                || (datiContr != null && datiContr.Count > 0 && datiContr.Exists(x => x.CodiceGestione == gestioneL.Id)))
                            {
                                datiRetr = datiRetrOrdered;
                                return true;
                            }
                        }
                    }
                }



                if (posticipo)
                {
                    //Se la variabile W-POSTICIPO è = a “S” è obbligatorio anche il 2° elemento della tabella RETRIB
                    if (datiRetrOrdered == null || datiRetrOrdered.Count < 2)
                    {
                        messaggioVideo = "Sono obbligatori almeno 2 record riguardanti i dati retributivi";
                        return false;
                    }

                    //Se la variabile W-POSTICIPO è = a “S” il Codice Quota (VRQUOTA) del 1° elemento della tabella RETRIB deve essere “A”
                    if (datiRetrOrdered != null && datiRetrOrdered.Count > 0)
                    {
                        if (!datiRetrOrdered[0].QuotePrimeLiquidate.HasValue || datiRetrOrdered[0].QuotePrimeLiquidate.Value != 'A')
                        {
                            messaggioVideo = "Il codice quota del 1° elemento dei dati retributivi deve essere A. " +
                                "L'ordinamento considera come 1° elemento il record con codice gestione pari a " +
                                GetGestioneRetributiva(datiRetrOrdered[0].CodiceGestione, listaCodeGestioneCalcoloRetributivo);
                            return false;
                        }
                    }
                }

                //Se il Campo DO-NOTE è = a “SUT” le Settimane (VRSET) del 1° elemento della Tabella Retributiva (RETRIB) 
                //non possono essere superiore a 259
                if (filtro == "SUT")
                {
                    if (datiRetrOrdered != null && datiRetrOrdered.Count > 0)
                    {
                        if ((datiRetrOrdered[0].NSettimaneQuotaA.HasValue && datiRetrOrdered[0].NSettimaneQuotaA.Value > 259) ||
                        (datiRetrOrdered[0].NSettimaneQuotaB.HasValue && datiRetrOrdered[0].NSettimaneQuotaB.Value > 259))
                        {
                            messaggioVideo = "Le settimane del 1° elemento dei dati retributivi non possono essere superiore a 259. " +
                                "L'ordinamento considera come 1° elemento il record con codice gestione pari a " +
                                GetGestioneRetributiva(datiRetrOrdered[0].CodiceGestione, listaCodeGestioneCalcoloRetributivo);
                            return false;
                        }
                    }
                }

                if (datiRetrOrdered != null && datiRetrOrdered.Count > 0)
                {
                    //Verificare che non ci siano doppie registrazioni di Codice Gestione (VRGEST) e Quota (VRQUOTA)
                    if (!((siglaCategoria == "VOMIN" || siglaCategoria == "SOMIN") && Utility.IsRicostituzioneOrRiapertura(contenitore.DatiPensione, contenitore.IsRiaperturaDomanda)))
                    {
                        for (int i = 0; i < datiRetrOrdered.Count; i++)
                            for (int j = i + 1; j < datiRetrOrdered.Count; j++)
                            {
                                if (datiRetrOrdered[i].CodiceGestione == datiRetrOrdered[j].CodiceGestione &&
                                    datiRetrOrdered[i].QuotePrimeLiquidate == datiRetrOrdered[j].QuotePrimeLiquidate &&
                                    datiRetrOrdered[i].CodiceTipoQuota == datiRetrOrdered[j].CodiceTipoQuota)
                                {
                                    messaggioVideo = "Non possono esserci doppie registrazioni di codice gestione e quota";
                                    return false;
                                }
                            }
                    }

                    //Se la Categoria (RACATEG) è = a "VR", "IR", "SR", "VOART", "IOART", "SOART", "VOCOM", "IOCOM", "SOCOM" e 
                    //l'Attività Economica (RAU1013) è = a 4 e la Professione Individuale (RAU1014) è = a 350 
                    //verificare negli elementi della tabella che ci sia un Codice Gestione (VRGEST) = a “1” o = a "1H"
                    switch (siglaCategoria)
                    {
                        case "VR":
                        case "IR":
                        case "SR":
                        case "VOART":
                        case "IOART":
                        case "SOART":
                        case "VOCOM":
                        case "IOCOM":
                        case "SOCOM":
                            if (contenitore.DatiPensione.AttivitaEconomica.HasValue && contenitore.DatiPensione.AttivitaEconomica.Value == 4 &&
                                contenitore.DatiPensione.ProfessioneIndividuale.HasValue && contenitore.DatiPensione.ProfessioneIndividuale.Value == 350)
                            {
                                presente = false;
                                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrOrdered)
                                {
                                    if (GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1" || GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1H")
                                        presente = true;
                                }
                                if (!presente)
                                {
                                    if (filtro == "RAL" || filtro == "R44" || filtro == "R45")
                                        messaggioVideo = "Deve essere presente almeno un codice gestione pari a 1 o a 1H";
                                    else
                                        messaggioVideo = "Deve essere presente almeno un codice gestione pari a 1";
                                    return false;
                                }
                            }
                            break;
                        default:
                            break;
                    }

                    //Se esiste nel 1° elemento della tabella RETRIB il Codice Gestione (VRGEST) = a “S”: 
                    //per le Categorie (RACATEG) = a "VR", "IR", "SR", "VOART", "IOART", "SOART", "VOCOM", "IOCOM", "SOCOM" 
                    //deve esistere un altro elemento con il Codice Gestione (VRGEST) 
                    //relativo alla categoria (VR, IR, SR = a “2” - VOART, IOART, SOART = a “3” - VOCOM, IOCOM, SOCOM = a “4”) e 
                    //la Quota (VRQUOTA) = a “A”
                    //per le Categorie (RACATEG) diverse da VR", "IR", "SR", "VOART", "IOART", "SOART", "VOCOM", "IOCOM", "SOCOM"  
                    //non deve esistere un altro elemento con il Codice Gestione (VRGEST) = a “1” la Quota (VRQUOTA) = a “A” 
                    //per tutte e Categorie (RACATEG) deve esistere una registrazione con il Codice Gestione (VRGEST) = a “1” e la Quota (VRQUOTA) = a “B”
                    if (GetGestioneRetributiva(datiRetrOrdered[0].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "S")
                    {
                        switch (siglaCategoria)
                        {
                            case "VR":
                            case "IR":
                            case "SR":
                                presente = false;
                                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrOrdered)
                                {
                                    if (GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "2" && r.QuotePrimeLiquidate.HasValue && r.QuotePrimeLiquidate.Value == 'A')
                                        presente = true;
                                }
                                if (!presente)
                                {
                                    messaggioVideo = "Deve esistere almeno un elemento con codice gestione pari a 2 e quota pari ad A";
                                    return false;
                                }
                                break;
                            case "VOART":
                            case "IOART":
                            case "SOART":
                                presente = false;
                                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrOrdered)
                                {
                                    if (GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "3" && r.QuotePrimeLiquidate.HasValue && r.QuotePrimeLiquidate.Value == 'A')
                                        presente = true;
                                }
                                if (!presente)
                                {
                                    messaggioVideo = "Deve esistere almeno un elemento con codice gestione pari a 3 e quota pari ad A";
                                    return false;
                                }
                                break;
                            case "VOCOM":
                            case "IOCOM":
                            case "SOCOM":
                                presente = false;
                                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrOrdered)
                                {
                                    if (GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "4" && r.QuotePrimeLiquidate.HasValue && r.QuotePrimeLiquidate.Value == 'A')
                                        presente = true;
                                }
                                if (!presente)
                                {
                                    messaggioVideo = "Deve esistere almeno un elemento con codice gestione pari a 4 e quota pari ad A";
                                    return false;
                                }
                                break;
                            case "VDAI":
                            case "IDAI":
                            case "SDAI":
                                // Controllo rimosso come indicato nel documento LiqPens AGO - Interventi Puntuali@20180928_v7.5
                                break;
                            default:
                                presente = false;
                                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrOrdered)
                                {
                                    if (GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1" && r.QuotePrimeLiquidate.HasValue && r.QuotePrimeLiquidate.Value == 'A')
                                        presente = true;
                                }
                                if (presente)
                                {
                                    messaggioVideo = "Non deve esistere un elemento con codice gestione pari a 1 e quota pari ad A";
                                    return false;
                                }
                                break;
                        }

                    }

                    //Se la Categoria è = a “VOBANC”, “IOBANC”, SOBANC” effettuare le seguenti verifiche: 
                    //se il Campo DO-NOTE è = a “BNS” deve esserci nella tabella RETRIB
                    //la Gestione (VRGEST) = a “S” con la Quota (VRQUOTA) = a “A” 
                    //altrimenti 
                    //deve esserci nella tabella RETRIB la Gestione (VRGEST) = a “1” con la Quota (VRQUOTA) = a “A” 
                    //deve  esistere la Gestione (VRGEST) = a “1” con la Quota (VRQUOTA) = a “B” 
                    //deve  esistere la Gestione (VRGEST) = a “H” con la Quota (VRQUOTA) = a “A” e le Settimane (VRSET) 
                    //devono essere inferiori alle Settimane (VRSET) della Gestione “1” e Quota “A” 
                    //deve  esistere la Gestione (VRGEST) = a “H” con la Quota (VRQUOTA) = a “B” e le Settimane (VRSET) 
                    //devono essere inferiori alle Settimane (VRSET) della Gestione “1” e Quota “B” 
                    //la somma delle Settimane (VRSET) delle Gestioni (VRGEST) = a “S” o “1” o “H” non può essere maggiore di 2080
                    switch (siglaCategoria)
                    {
                        case "VOBANC":
                        case "IOBANC":
                        case "SOBANC":
                            if (filtro == "BNS" || ((Utility.IsRicostituzioneOrRiapertura(contenitore.DatiPensione, contenitore.IsRiaperturaDomanda) || Utility.IsDomandaRipristino(contenitore.DatiPensione).GetValueOrDefault()) && codNat2 == 'Y'))
                            {
                                presente = false;
                                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrOrdered)
                                {
                                    if (GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "S" &&
                                        r.QuotePrimeLiquidate.HasValue && r.QuotePrimeLiquidate.Value == 'A')
                                    {
                                        presente = true;
                                    }
                                }
                                if (!presente)
                                {
                                    messaggioVideo = "Deve esistere almeno un elemento con codice gestione pari a S e quota pari ad A";
                                    return false;
                                }
                            }
                            else
                            {
                                presente = false;
                                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrOrdered)
                                {
                                    if (GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1" &&
                                        r.QuotePrimeLiquidate.HasValue && r.QuotePrimeLiquidate.Value == 'A')
                                    {
                                        presente = true;
                                    }
                                }
                                if (!presente)
                                {
                                    messaggioVideo = "Deve esistere almeno un elemento con codice gestione pari a 1 e quota pari ad A";
                                    return false;
                                }
                            }
                            if (!Utility.IsDomandaRipristino(contenitore.DatiPensione).GetValueOrDefault() && contenitore.DatiPensione.FineAssicurazione.HasValue && !Utility.DataStrettamenteSuccessivaA(new DateTime(1992, 12, 31), contenitore.DatiPensione.FineAssicurazione.Value))
                            {

                                presente = false;
                                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrOrdered)
                                {
                                    if (GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1" && r.QuotePrimeLiquidate.HasValue && r.QuotePrimeLiquidate.Value == 'B')
                                        presente = true;
                                }
                                if (!presente)
                                {
                                    messaggioVideo = "Deve esistere almeno un elemento con codice gestione pari a 1 e quota pari a B";
                                    return false;
                                }
                            }
                            //Rimosso con la migrazione
                            //presente = false;
                            //foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrOrdered)
                            //{
                            //    if (GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "H" && r.QuotePrimeLiquidate.HasValue && r.QuotePrimeLiquidate.Value == 'A')
                            //        presente = true;
                            //}
                            //if (!presente)
                            //{
                            //    messaggioVideo = "Deve esistere almeno un elemento con codice gestione pari a H e quota pari ad A";
                            //    return false;
                            //}
                            //presente = false;
                            //foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrOrdered)
                            //{
                            //    if (GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "H" && r.QuotePrimeLiquidate.HasValue && r.QuotePrimeLiquidate.Value == 'B')
                            //        presente = true;
                            //}
                            //if (!presente)
                            //{
                            //    messaggioVideo = "Deve esistere almeno un elemento con codice gestione pari a H e quota pari ad B";
                            //    return false;
                            //}

                            List<GestioneCalcolo.DatiCalcoloRetributivo> retr_H = datiRetrOrdered.FindAll(x => GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "H" && x.QuotePrimeLiquidate.HasValue);
                            if (retr_H != null && retr_H.Count > 0 && !Utility.IsRicostituzioneOrRiapertura(contenitore.DatiPensione, contenitore.IsRiaperturaDomanda))
                            {
                                foreach (var item in retr_H)
                                {
                                    List<GestioneCalcolo.DatiCalcoloRetributivo> retr_1 = datiRetrOrdered.FindAll(x => (GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1" || GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "S")
                                    && x.QuotePrimeLiquidate.HasValue && x.QuotePrimeLiquidate == item.QuotePrimeLiquidate);
                                    if (retr_1 == null)
                                    {
                                        messaggioVideo = "Non può esistere una quota retributiva(A/B) con gestione H in assenza di corrispondente quota retributiva(A/B) con gestione 1";
                                        return false;
                                    }
                                }
                            }

                            List<GestioneCalcolo.DatiCalcoloRetributivo> retrH_A = datiRetrOrdered.FindAll(x => GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "H"
                                && x.QuotePrimeLiquidate.HasValue && x.QuotePrimeLiquidate.Value == 'A');
                            List<GestioneCalcolo.DatiCalcoloRetributivo> retr1_A = datiRetrOrdered.FindAll(x => (GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1")
                                && x.QuotePrimeLiquidate.HasValue && x.QuotePrimeLiquidate.Value == 'A');
                            List<GestioneCalcolo.DatiCalcoloRetributivo> retrS_A = datiRetrOrdered.FindAll(x => (GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "S")
                                && x.QuotePrimeLiquidate.HasValue && x.QuotePrimeLiquidate.Value == 'A');

                            if (retrH_A != null && retrH_A.Count > 0 && retrH_A[0].NSettimaneQuotaA.HasValue &&
                                ((retr1_A != null && retr1_A.Count > 0 && retr1_A[0].NSettimaneQuotaA.HasValue && retrH_A[0].NSettimaneQuotaA.Value >= retr1_A[0].NSettimaneQuotaA.Value) ||
                                (retrS_A != null && retrS_A.Count > 0 && retrS_A[0].NSettimaneQuotaA.HasValue && retrH_A[0].NSettimaneQuotaA.Value >= retrS_A[0].NSettimaneQuotaA.Value))
                                )
                            {
                                string gestione = (retr1_A != null && retr1_A.Count > 0 && retr1_A[0].NSettimaneQuotaA.HasValue) ? "1" : "S";
                                messaggioVideo = String.Format("Le settimane della gestione H con quota A devono essere strettamente inferiori alle settimane della gestione {0} con quota A", gestione);
                                return false;

                            }

                            List<GestioneCalcolo.DatiCalcoloRetributivo> retrH_B = datiRetrOrdered.FindAll(x => GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "H"
                                && x.QuotePrimeLiquidate.HasValue && x.QuotePrimeLiquidate.Value == 'B');
                            List<GestioneCalcolo.DatiCalcoloRetributivo> retr1_B = datiRetrOrdered.FindAll(x => GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1"
                                && x.QuotePrimeLiquidate.HasValue && x.QuotePrimeLiquidate.Value == 'B');

                            if (retrH_B != null && retrH_B.Count > 0 && retr1_B != null && retr1_B.Count > 0)
                            {
                                if (retrH_B[0].NSettimaneQuotaA.HasValue &&
                                    retr1_B[0].NSettimaneQuotaA.HasValue &&
                                    retrH_B[0].NSettimaneQuotaA.Value > retr1_B[0].NSettimaneQuotaA.Value)
                                {
                                    messaggioVideo = "Le settimane della gestione H con quota B devono essere inferiore o uguale alle settimane della gestione 1 con quota B";
                                    return false;
                                }
                                if (retrH_B[0].NSettimaneQuotaB.HasValue &&
                                    retr1_B[0].NSettimaneQuotaB.HasValue &&
                                    retrH_B[0].NSettimaneQuotaB.Value > retr1_B[0].NSettimaneQuotaB.Value)
                                {
                                    messaggioVideo = "Le settimane della gestione H con quota B devono essere inferiori o uguali alle settimane della gestione 1 con quota B";
                                    return false;
                                }
                            }

                            List<GestioneCalcolo.DatiCalcoloRetributivo> retrS = datiRetrOrdered.FindAll(x => GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "S");
                            if (retrS != null && retrS.Count > 0)
                            {
                                var retrS_B = retrS.Where(x => x.QuotePrimeLiquidate.Value == 'B').FirstOrDefault();
                                if (retrS_B != null)
                                {
                                    messaggioVideo = "Non è possibile selezionare inserire codice gestione S-Bonus/ART 75 con la Quota B";
                                    return false;
                                }

                                int settimane = 0;
                                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in retrS)
                                {
                                    if (r.NSettimaneQuotaA.HasValue)
                                        settimane += r.NSettimaneQuotaA.Value;
                                    else if (r.NSettimaneQuotaB.HasValue)
                                        settimane += r.NSettimaneQuotaB.Value;
                                }
                                if (settimane > 2080)
                                {
                                    messaggioVideo = "La somma delle settimane delle gestioni pari a S non può essere maggiore di 2080";
                                    return false;
                                }
                            }
                            List<GestioneCalcolo.DatiCalcoloRetributivo> retr1 = datiRetrOrdered.FindAll(x => GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1");
                            if (retr1 != null && retr1.Count > 0)
                            {
                                int settimane = 0;
                                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in retr1)
                                {
                                    if (r.NSettimaneQuotaA.HasValue)
                                        settimane += r.NSettimaneQuotaA.Value;
                                    else if (r.NSettimaneQuotaB.HasValue)
                                        settimane += r.NSettimaneQuotaB.Value;
                                }
                                if (settimane > 2080)
                                {
                                    messaggioVideo = "La somma delle settimane delle gestioni pari a 1 non può essere maggiore di 2080";
                                    return false;
                                }
                            }
                            List<GestioneCalcolo.DatiCalcoloRetributivo> retrH = datiRetrOrdered.FindAll(x => GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "H");
                            if (retrH != null && retrH.Count > 0)
                            {
                                int settimane = 0;
                                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in retrH)
                                {
                                    if (r.NSettimaneQuotaA.HasValue)
                                        settimane += r.NSettimaneQuotaA.Value;
                                    else if (r.NSettimaneQuotaB.HasValue)
                                        settimane += r.NSettimaneQuotaB.Value;
                                }
                                if (settimane > 2080)
                                {
                                    messaggioVideo = "La somma delle settimane delle gestioni pari a H non può essere maggiore di 2080";
                                    return false;
                                }
                            }
                            break;
                        case "VOMIN":
                        case "SOMIN":
                            presente = false;
                            foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrOrdered)
                            {
                                if (GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1" && r.QuotePrimeLiquidate.HasValue && r.QuotePrimeLiquidate.Value == 'A')
                                    presente = true;
                            }
                            if (!presente)
                            {
                                messaggioVideo = "Deve esistere almeno un elemento con codice gestione pari a 1 e quota pari ad A";
                                return false;
                            }
                            break;
                        case "VO":
                        case "VOART":
                        case "VR":
                        case "VOCOM":
                            if (filtro == "BNS" || ((Utility.IsRicostituzioneOrRiapertura(contenitore.DatiPensione, contenitore.IsRiaperturaDomanda) || Utility.IsDomandaRipristino(contenitore.DatiPensione).GetValueOrDefault()) && codNat2 == 'Y'))
                            {
                                presente = false;
                                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrOrdered)
                                {
                                    if (GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "S" &&
                                        r.QuotePrimeLiquidate.HasValue && r.QuotePrimeLiquidate.Value == 'A')
                                    {
                                        presente = true;
                                    }
                                }
                                if (!presente)
                                {
                                    messaggioVideo = "Deve esistere almeno un elemento con codice gestione pari a S e quota pari ad A";
                                    return false;
                                }
                            }
                            break;
                        default:
                            break;
                    }

                    //Se l'Attività Economica (RAU1013)è = a 4 e la Professione Individuale (RAU1014) è = a 350: 
                    //se il Campo PDIRSUP è = a zero e la Decorrenza Originaria (RAU104) è inferiore a febbraio 2004 verificare 
                    //che esista una Gestione (VRGEST) “Q”
                    //se esiste la Gestione (VRGEST) = a “Q” con la Quota (VRQUOTA) = a “A” 
                    //deve esistere anche la Gestione (VRGEST) = a “1” con la Quota (VRQUOTA) = a “A” 
                    //se esiste la Gestione (VRGEST) = a “Q” con la Quota (VRQUOTA) = a “B” 
                    //deve esistere anche la Gestione (VRGEST) = a “1” con la Quota (VRQUOTA) = a “B” 
                    //le Retribuzioni Medie Settimanali (VRRETR) della Gestione (VRGEST) = a “1” con Quota (VRQUOTA) = a “A” e 
                    //della Gestione (VRGEST) = a “Q” con Quota (VRQUOTA) = a “A” devono essere uguali 
                    //le Settimane (VRSET) della Gestione (VRGEST) = a “Q” con Quota (VRQUOTA) = a “A” 
                    //non possono essere superiori alla metà delle Settimane (VRSET) della Gestione (VRGEST) = a “1” con Quota (VRQUOTA) = a “A” 
                    //le Retribuzioni Medie Settimanali (VRRETR) della Gestione (VRGEST) = a “1” con Quota (VRQUOTA) = a “B” e 
                    //della Gestione (VRGEST) = a “Q” con Quota (VRQUOTA) = a “B” devono essere uguali 
                    //le Settimane (VRSET) della Gestione (VRGEST) = a “Q” con Quota (VRQUOTA) = a “A” 
                    //non possono essere superiori alla metà delle Settimane (VRSET) della Gestione (VRGEST) = a “1” con Quota (VRQUOTA) = a “B”
                    if (contenitore.DatiPensione.AttivitaEconomica.HasValue && contenitore.DatiPensione.AttivitaEconomica.Value == 4 &&
                        contenitore.DatiPensione.ProfessioneIndividuale.HasValue && contenitore.DatiPensione.ProfessioneIndividuale.Value == 350 &&
                        !Utility.IsDomandaBancari(siglaCategoria))
                    {
                        if (pdirsup == 0 && !Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2004, 2, 1)))
                        {
                            presente = false;
                            foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrOrdered)
                            {
                                if (GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "Q")
                                    presente = true;
                            }
                            if (!presente)
                            {
                                messaggioVideo = "Deve esistere almeno un elemento con codice gestione pari a Q";
                                return false;
                            }
                        }

                        List<GestioneCalcolo.DatiCalcoloRetributivo> retrQ_A = datiRetrOrdered.FindAll(x => GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "Q" &&
                            x.QuotePrimeLiquidate.HasValue && x.QuotePrimeLiquidate.Value == 'A');
                        if (retrQ_A != null && retrQ_A.Count > 0)
                        {
                            List<GestioneCalcolo.DatiCalcoloRetributivo> retr1_A = datiRetrOrdered.FindAll(x => GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1" &&
                                x.QuotePrimeLiquidate.HasValue && x.QuotePrimeLiquidate.Value == 'A');
                            if (retr1_A == null || retr1_A.Count == 0)
                            {
                                messaggioVideo = "Deve esistere almeno un elemento con codice gestione pari a 1 e quota pari ad A";
                                return false;
                            }

                            if (retrQ_A[0].RMSQuotaA.HasValue &&
                                retr1_A[0].RMSQuotaA.HasValue &&
                                retrQ_A[0].RMSQuotaA.Value != retr1_A[0].RMSQuotaA.Value)
                            {
                                messaggioVideo = "Le retribuzioni medie settimanali della gestione pari a 1 con quota pari ad A e della gestione pari a Q con quota pari ad A devono essere uguali";
                                return false;
                            }

                            if (retrQ_A[0].NSettimaneQuotaA.HasValue &&
                                retr1_A[0].NSettimaneQuotaA.HasValue)
                            {
                                double metaSett = (double)retr1_A[0].NSettimaneQuotaA.Value / 2;
                                if (retrQ_A[0].NSettimaneQuotaA.Value > metaSett)
                                {
                                    messaggioVideo = "Le settimane della gestione pari a Q con quota pari ad A non possono essere superiori alla metà delle settimane della gestione pari a 1 con quota pari ad A";
                                    return false;
                                }
                            }
                        }

                        List<GestioneCalcolo.DatiCalcoloRetributivo> retrQ_B = datiRetrOrdered.FindAll(x => GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "Q" &&
                            x.QuotePrimeLiquidate.HasValue && x.QuotePrimeLiquidate.Value == 'B');
                        if (retrQ_B != null && retrQ_B.Count > 0)
                        {
                            List<GestioneCalcolo.DatiCalcoloRetributivo> retr1_B = datiRetrOrdered.FindAll(x => GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1" &&
                                x.QuotePrimeLiquidate.HasValue && x.QuotePrimeLiquidate.Value == 'B');
                            if (retr1_B == null || retr1_B.Count == 0)
                            {
                                messaggioVideo = "Deve esistere almeno un elemento con codice gestione pari a 1 e quota pari a B";
                                return false;
                            }

                            if (retrQ_B[0].RMSQuotaB.HasValue &&
                                retr1_B[0].RMSQuotaB.HasValue &&
                                retrQ_B[0].RMSQuotaB.Value != retr1_B[0].RMSQuotaB.Value)
                            {
                                messaggioVideo = "Le retribuzioni medie settimanali della gestione pari a 1 con quota pari a B e della gestione pari a Q con quota pari a B devono essere uguali";
                                return false;
                            }

                            if (retrQ_B[0].NSettimaneQuotaB.HasValue &&
                                retr1_B[0].NSettimaneQuotaB.HasValue)
                            {
                                double metaSett = (double)retr1_B[0].NSettimaneQuotaB.Value / 2;
                                if (retrQ_B[0].NSettimaneQuotaB.Value > metaSett)
                                {
                                    messaggioVideo = "Le settimane della gestione pari a Q con quota pari a B non possono essere superiori alla metà delle settimane della gestione pari a 1 con quota pari a B";
                                    return false;
                                }
                            }
                        }
                    }

                    //Con il Campo DO-NOTE = a "RAL", "R22", "R23", "R24", "R25", "R44",  "R45" 
                    if (filtro == "RAL" || filtro == "R22" || filtro == "R23" || filtro == "R24" ||
                        filtro == "R25" || filtro == "R44" || filtro == "R45")
                    {
                        //Se esiste una registrazione con Codice Gestione (VRGEST) = a “1H” e Codice Quota (VRQUOTA) = a “B” 
                        //e non esiste una registrazione con Codice Gestione = a “1” o “1H” con Codice Quota (VRQUOTA) = a “A” 
                        //creare una registrazione con i seguenti valori: 
                        //mettere “1” in VRGEST 
                        //mettere “A” in VRQUOTA 
                        //mettere RAU104 in VRDEC 
                        //mettere 1 in VRSET 
                        //mettere 0.004000 in VRRETR
                        List<GestioneCalcolo.DatiCalcoloRetributivo> retr1H_B = datiRetrOrdered.FindAll(x => GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1H" &&
                                x.QuotePrimeLiquidate.HasValue && x.QuotePrimeLiquidate.Value == 'B');
                        if (retr1H_B != null && retr1H_B.Count > 0)
                        {
                            List<GestioneCalcolo.DatiCalcoloRetributivo> retr1_1H_A = datiRetrOrdered.FindAll(x => (GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1" ||
                            GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1H") &&
                                    x.QuotePrimeLiquidate.HasValue && x.QuotePrimeLiquidate.Value == 'A');
                            if (retr1_1H_A == null || retr1_1H_A.Count == 0)
                            {
                                GestioneCalcolo.DatiCalcoloRetributivo retr = new GestioneCalcolo.DatiCalcoloRetributivo();
                                List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> codiciGestRetr = null;
                                GestioneDecodifica.GetCodeGestioneCalcoloRetributivo(out codiciGestRetr);
                                if (codiciGestRetr != null && codiciGestRetr.Count > 0)
                                {
                                    List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> cgr = codiciGestRetr.FindAll(x => x.TraduzioneSuGP == "1");
                                    if (cgr != null && cgr.Count > 0)
                                    {
                                        retr.CodiceGestione = cgr[0].Id;
                                        retr.QuotePrimeLiquidate = 'A';
                                        mesiDecDatiRetr.Add((short)decorrenzaOriginaria.Month);
                                        anniDecDatiRetr.Add((short)decorrenzaOriginaria.Year);
                                        retr.NSettimaneQuotaA = 1;
                                        retr.RMSQuotaA = 0.004M;
                                        datiRetr.Add(retr);
                                        datiRetrOrdered.Add(retr);
                                    }
                                }
                            }
                        }

                        //Se il Codice gestione (VRGEST) è = a “1” e il Codice Quota (VRQUOTA) è = a “A” e 
                        //la Retribuzione Media Settimanale (VRRETR) è diverso da 0.004000 le Retribuzioni Media Settimanali (VRRETR) 
                        //del Codice Gestione (VRGEST) = a “1H” con Codice Quota (VRQUOTA) = a “A” e con la stessa Decorrenza (VRDEC) devono essere uguali 
                        for (int i = 0; i < datiRetrOrdered.Count; i++)
                        {
                            if (GetGestioneRetributiva(datiRetrOrdered[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1" &&
                                datiRetrOrdered[i].QuotePrimeLiquidate.HasValue && datiRetrOrdered[i].QuotePrimeLiquidate.Value == 'A' &&
                                datiRetrOrdered[i].RMSQuotaA.HasValue && datiRetrOrdered[i].RMSQuotaA.Value != 0.004M)
                            {
                                for (int j = 0; j < datiRetrOrdered.Count; j++)
                                {
                                    if (GetGestioneRetributiva(datiRetrOrdered[j].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1H" &&
                                        datiRetrOrdered[j].QuotePrimeLiquidate.HasValue && datiRetrOrdered[j].QuotePrimeLiquidate.Value == 'A' &&
                                        mesiDecDatiRetr[i] == mesiDecDatiRetr[j] &&
                                        anniDecDatiRetr[i] == anniDecDatiRetr[j])
                                    {
                                        if (datiRetrOrdered[j].RMSQuotaA.HasValue &&
                                            datiRetrOrdered[j].RMSQuotaA.Value != datiRetrOrdered[i].RMSQuotaA.Value)
                                        {
                                            messaggioVideo = "Se il codice gestione è pari a 1 e il Codice Quota è pari ad A e la retribuzione media settimanale è " +
                                                "diverso da 0.004000 le retribuzioni media settimanali del Codice Gestione pari a 1H con Codice Quota " +
                                                "pari ad A e con la stessa decorrenza devono essere uguali";
                                            return false;
                                        }
                                    }
                                }
                            }
                        }

                        //Se il Codice gestione (VRGEST) è = a “2” e il Codice Quota (VRQUOTA) è = a “A” le Retribuzioni Media Settimanali (VRRETR) 
                        //del Codice Gestione (VRGEST) = a “2H” con Codice Quota (VRQUOTA) = a “A” e con la stessa Decorrenza (VRDEC) devono essere uguali 
                        for (int i = 0; i < datiRetrOrdered.Count; i++)
                        {
                            if (GetGestioneRetributiva(datiRetrOrdered[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "2" &&
                                datiRetrOrdered[i].QuotePrimeLiquidate.HasValue && datiRetrOrdered[i].QuotePrimeLiquidate.Value == 'A')
                            {
                                for (int j = 0; j < datiRetrOrdered.Count; j++)
                                {
                                    if (GetGestioneRetributiva(datiRetrOrdered[j].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "2H" &&
                                        datiRetrOrdered[j].QuotePrimeLiquidate.HasValue && datiRetrOrdered[j].QuotePrimeLiquidate.Value == 'A' &&
                                        mesiDecDatiRetr[i] == mesiDecDatiRetr[j] &&
                                        anniDecDatiRetr[i] == anniDecDatiRetr[j])
                                    {
                                        if (datiRetrOrdered[j].RMSQuotaA.HasValue &&
                                            datiRetrOrdered[j].RMSQuotaA.Value != datiRetrOrdered[i].RMSQuotaA.Value)
                                        {
                                            messaggioVideo = "Se il codice gestione è pari a 2 e il Codice Quota è pari ad A " +
                                                "le retribuzioni media settimanali del Codice Gestione pari a 2H con Codice Quota " +
                                                "pari ad A e con la stessa decorrenza devono essere uguali";
                                            return false;
                                        }
                                    }
                                }
                            }
                        }
                        //Se il Codice gestione (VRGEST) è = a “3” e il Codice Quota (VRQUOTA) è = a “A” le Retribuzioni Media Settimanali (VRRETR) 
                        //del Codice Gestione (VRGEST) = a “3H” con Codice Quota (VRQUOTA) = a “A” e con la stessa Decorrenza (VRDEC) devono essere uguali 
                        for (int i = 0; i < datiRetrOrdered.Count; i++)
                        {
                            if (GetGestioneRetributiva(datiRetrOrdered[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "3" &&
                                datiRetrOrdered[i].QuotePrimeLiquidate.HasValue && datiRetrOrdered[i].QuotePrimeLiquidate.Value == 'A')
                            {
                                for (int j = 0; j < datiRetrOrdered.Count; j++)
                                {
                                    if (GetGestioneRetributiva(datiRetrOrdered[j].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "3H" &&
                                        datiRetrOrdered[j].QuotePrimeLiquidate.HasValue && datiRetrOrdered[j].QuotePrimeLiquidate.Value == 'A' &&
                                        mesiDecDatiRetr[i] == mesiDecDatiRetr[j] &&
                                        anniDecDatiRetr[i] == anniDecDatiRetr[j])
                                    {
                                        if (datiRetrOrdered[j].RMSQuotaA.HasValue &&
                                            datiRetrOrdered[j].RMSQuotaA.Value != datiRetrOrdered[i].RMSQuotaA.Value)
                                        {
                                            messaggioVideo = "Se il codice gestione è pari a 3 e il Codice Quota è pari ad A " +
                                                "le retribuzioni media settimanali del Codice Gestione pari a 3H con Codice Quota " +
                                                "pari ad A e con la stessa decorrenza devono essere uguali";
                                            return false;
                                        }
                                    }
                                }
                            }
                        }
                        //Se il Codice gestione (VRGEST) è = a “4” e il Codice Quota (VRQUOTA) è = a “A” le Retribuzioni Media Settimanali (VRRETR) 
                        //del Codice Gestione (VRGEST) = a “4H” con Codice Quota (VRQUOTA) = a “A” e con la stessa Decorrenza (VRDEC) devono essere uguali 
                        for (int i = 0; i < datiRetrOrdered.Count; i++)
                        {
                            if (GetGestioneRetributiva(datiRetrOrdered[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "4" &&
                                datiRetrOrdered[i].QuotePrimeLiquidate.HasValue && datiRetrOrdered[i].QuotePrimeLiquidate.Value == 'A')
                            {
                                for (int j = 0; j < datiRetrOrdered.Count; j++)
                                {
                                    if (GetGestioneRetributiva(datiRetrOrdered[j].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "4H" &&
                                        datiRetrOrdered[j].QuotePrimeLiquidate.HasValue && datiRetrOrdered[j].QuotePrimeLiquidate.Value == 'A' &&
                                        mesiDecDatiRetr[i] == mesiDecDatiRetr[j] &&
                                        anniDecDatiRetr[i] == anniDecDatiRetr[j])
                                    {
                                        if (datiRetrOrdered[j].RMSQuotaA.HasValue &&
                                            datiRetrOrdered[j].RMSQuotaA.Value != datiRetrOrdered[i].RMSQuotaA.Value)
                                        {
                                            messaggioVideo = "Se il codice gestione è pari a 4 e il Codice Quota è pari ad A " +
                                                "le retribuzioni media settimanali del Codice Gestione pari a 4H con Codice Quota " +
                                                "pari ad A e con la stessa decorrenza devono essere uguali";
                                            return false;
                                        }
                                    }
                                }
                            }
                        }
                        //Se il Codice gestione (VRGEST) è = a “1” e il Codice Quota (VRQUOTA) è = a “B” le Retribuzioni Media Settimanali (VRRETR) 
                        //del Codice Gestione (VRGEST) = a “1H” con Codice Quota (VRQUOTA) = a “B” e con la stessa Decorrenza (VRDEC) devono essere uguali 
                        for (int i = 0; i < datiRetrOrdered.Count; i++)
                        {
                            if (GetGestioneRetributiva(datiRetrOrdered[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1" &&
                                datiRetrOrdered[i].QuotePrimeLiquidate.HasValue && datiRetrOrdered[i].QuotePrimeLiquidate.Value == 'B')
                            {
                                for (int j = 0; j < datiRetrOrdered.Count; j++)
                                {
                                    if (GetGestioneRetributiva(datiRetrOrdered[j].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1H" &&
                                        datiRetrOrdered[j].QuotePrimeLiquidate.HasValue && datiRetrOrdered[j].QuotePrimeLiquidate.Value == 'B' &&
                                        mesiDecDatiRetr[i] == mesiDecDatiRetr[j] &&
                                        anniDecDatiRetr[i] == anniDecDatiRetr[j])
                                    {
                                        if (datiRetrOrdered[j].RMSQuotaB.HasValue &&
                                            datiRetrOrdered[j].RMSQuotaB.Value != datiRetrOrdered[i].RMSQuotaB.Value)
                                        {
                                            messaggioVideo = "Se il codice gestione è pari a 1 e il Codice Quota è pari a B " +
                                                "le retribuzioni media settimanali del Codice Gestione pari a 1H con Codice Quota " +
                                                "pari a B e con la stessa decorrenza devono essere uguali";
                                            return false;
                                        }
                                    }
                                }
                            }
                        }
                        //Se il Codice gestione (VRGEST) è = a “2” e il Codice Quota (VRQUOTA) è = a “B” le Retribuzioni Media Settimanali (VRRETR) 
                        //del Codice Gestione (VRGEST) = a “2H” con Codice Quota (VRQUOTA) = a “B” e con la stessa Decorrenza (VRDEC) devono essere uguali 
                        for (int i = 0; i < datiRetrOrdered.Count; i++)
                        {
                            if (GetGestioneRetributiva(datiRetrOrdered[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "2" &&
                                datiRetrOrdered[i].QuotePrimeLiquidate.HasValue && datiRetrOrdered[i].QuotePrimeLiquidate.Value == 'B')
                            {
                                for (int j = 0; j < datiRetrOrdered.Count; j++)
                                {
                                    if (GetGestioneRetributiva(datiRetrOrdered[j].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "2H" &&
                                        datiRetrOrdered[j].QuotePrimeLiquidate.HasValue && datiRetrOrdered[j].QuotePrimeLiquidate.Value == 'B' &&
                                        mesiDecDatiRetr[i] == mesiDecDatiRetr[j] &&
                                        anniDecDatiRetr[i] == anniDecDatiRetr[j])
                                    {
                                        if (datiRetrOrdered[j].RMSQuotaB.HasValue &&
                                            datiRetrOrdered[j].RMSQuotaB.Value != datiRetrOrdered[i].RMSQuotaB.Value)
                                        {
                                            messaggioVideo = "Se il codice gestione è pari a 2 e il Codice Quota è pari a B " +
                                                "le retribuzioni media settimanali del Codice Gestione pari a 2H con Codice Quota " +
                                                "pari a B e con la stessa decorrenza devono essere uguali";
                                            return false;
                                        }
                                    }
                                }
                            }
                        }
                        //Se il Codice gestione (VRGEST) è = a “3” e il Codice Quota (VRQUOTA) è = a “B” le Retribuzioni Media Settimanali (VRRETR) 
                        //del Codice Gestione (VRGEST) = a “3H” con Codice Quota (VRQUOTA) = a “B” e con la stessa Decorrenza (VRDEC) devono essere uguali 
                        for (int i = 0; i < datiRetrOrdered.Count; i++)
                        {
                            if (GetGestioneRetributiva(datiRetrOrdered[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "3" &&
                                datiRetrOrdered[i].QuotePrimeLiquidate.HasValue && datiRetrOrdered[i].QuotePrimeLiquidate.Value == 'B')
                            {
                                for (int j = 0; j < datiRetrOrdered.Count; j++)
                                {
                                    if (GetGestioneRetributiva(datiRetrOrdered[j].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "3H" &&
                                        datiRetrOrdered[j].QuotePrimeLiquidate.HasValue && datiRetrOrdered[j].QuotePrimeLiquidate.Value == 'B' &&
                                        mesiDecDatiRetr[i] == mesiDecDatiRetr[j] &&
                                        anniDecDatiRetr[i] == anniDecDatiRetr[j])
                                    {
                                        if (datiRetrOrdered[j].RMSQuotaB.HasValue &&
                                            datiRetrOrdered[j].RMSQuotaB.Value != datiRetrOrdered[i].RMSQuotaB.Value)
                                        {
                                            messaggioVideo = "Se il codice gestione è pari a 3 e il Codice Quota è pari a B " +
                                                "le retribuzioni media settimanali del Codice Gestione pari a 3H con Codice Quota " +
                                                "pari a B e con la stessa decorrenza devono essere uguali";
                                            return false;
                                        }
                                    }
                                }
                            }
                        }
                        //Se il Codice gestione (VRGEST) è = a “4” e il Codice Quota (VRQUOTA) è = a “B” le Retribuzioni Media Settimanali (VRRETR) 
                        //del Codice Gestione (VRGEST) = a “4H” con Codice Quota (VRQUOTA) = a “B” e con la stessa Decorrenza (VRDEC) devono essere uguali
                        for (int i = 0; i < datiRetrOrdered.Count; i++)
                        {
                            if (GetGestioneRetributiva(datiRetrOrdered[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "4" &&
                                datiRetrOrdered[i].QuotePrimeLiquidate.HasValue && datiRetrOrdered[i].QuotePrimeLiquidate.Value == 'B')
                            {
                                for (int j = 0; j < datiRetrOrdered.Count; j++)
                                {
                                    if (GetGestioneRetributiva(datiRetrOrdered[j].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "4H" &&
                                        datiRetrOrdered[j].QuotePrimeLiquidate.HasValue && datiRetrOrdered[j].QuotePrimeLiquidate.Value == 'B' &&
                                        mesiDecDatiRetr[i] == mesiDecDatiRetr[j] &&
                                        anniDecDatiRetr[i] == anniDecDatiRetr[j])
                                    {
                                        if (datiRetrOrdered[j].RMSQuotaB.HasValue &&
                                            datiRetrOrdered[j].RMSQuotaB.Value != datiRetrOrdered[i].RMSQuotaB.Value)
                                        {
                                            messaggioVideo = "Se il codice gestione è pari a 4 e il Codice Quota è pari a B " +
                                                "le retribuzioni media settimanali del Codice Gestione pari a 4H con Codice Quota " +
                                                "pari a B e con la stessa decorrenza devono essere uguali";
                                            return false;
                                        }
                                    }
                                }
                            }
                        }
                    }

                    if (!ControlsDatiRetributiviMaternita(ref contenitore, ref contenitoreDecodifica, datiRetrOrdered, out messaggioVideo))
                        return false;

                    if (!Utility.IsDomandaBancari(contenitore.DatiPensione.SiglaCategoria) && !Utility.IsDomandaDAIAnte2003(contenitore.DatiPensione, contenitore.DatiPensioniDatiGenerici != null && contenitore.DatiPensioniDatiGenerici.DataAssunzioneCarico.HasValue ? contenitore.DatiPensioniDatiGenerici.DataAssunzioneCarico.Value : DateTime.MaxValue))
                    {
                        if (codNat2 == 'H' && !datiRetrOrdered.Any(x => GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo).EndsWith("H")))
                        {
                            messaggioVideo = "Se il secondo codice natura è pari ad 'H' è necessario che sia presente almeno una registrazione retributiva con codice gestione che contenga H";
                            return false;
                        }

                        if (datiRetrOrdered.Any(x => GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo).EndsWith("H")) && codNat2 != 'H')
                        {
                            messaggioVideo = "In presenza di almeno una registrazione retributiva con codice gestione che contenga H è necessario che il secondo codice natura sia 'H'";
                            return false;
                        }
                    }

                    datiRetr = datiRetrOrdered;
                }
            }
            return true;
        }

        public static bool ControlsDatiCalcoloFinal(List<GestioneCalcolo.DatiCalcoloRetributivo> datiRetr, List<GestioneCalcolo.DatiCalcoloContributivo> datiContr,
            List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> listaCodeGestioneCalcoloRetributivo, List<GestioneDecodifica.CodeGestioneCalcoloContributivo> listaCodeGestioneCalcoloContributivo,
            GestionePensione.DatiPensione datiPensione, int nSettimaneOBG, int nContributiVolontari, Utility.TipoCalcolo tipoCalcolo, GestioneDanteCausa.DatiDanteCausa danteCausa, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';
            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            int pdirsup = 0;
            int plavaut = 0;
            int panvein = 0;
            bool posticipo = false;
            bool presente = false;

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            //ENG - Aggiornamento Memo 68/2022 IOPGI
            //ENG - Spacchettate SOPGI
            if (BypassaControlliRicSdaiContributivoK(datiPensione, datiContr, listaCodeGestioneCalcoloContributivo) ||
                BypassaControlliRic_VOCRED_CRED27_ContributivoL(datiPensione, datiContr, listaCodeGestioneCalcoloContributivo) ||
                Utility.IsDomandaVOPGI(datiPensione.SiglaCategoria) || (Utility.IsDomandaIOPGI(datiPensione.SiglaCategoria) && !Utility.IsDomandaIOPGI_AGI(datiPensione))
                || Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa))
                return true;

            Utility.GetCodiciNatura(datiPensione.NaturaPensione, out codNat1, out codNat2, out codNat3);

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);

            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);


            GetPdirusp_Plavaut(datiPensione, out pdirsup, out plavaut);

            GetPanvein_Posticipo(datiPensione.NaturaPensione, datiPensione, out panvein, out posticipo);
            #endregion Recupero Dati

            //Se il 3° Codice Natura (RAU1033) è = a “G”  verificare che esista  una registrazione nella Tabella Retributiva (RETRIB) 
            //con la Gestione (VRGEST) = a “1” o “A” e oppure una registrazione nella Tabella Contributiva (VCTR335) con la Gestione (VGES335) = a “1” o “A”
            if (!Utility.IsDomandaENPALS(datiPensione.Gestione) && !Utility.IsDomandaSPED(siglaCategoria) && codNat3 == 'G')
            {
                if (datiRetr != null && datiRetr.Count > 0)
                {
                    foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetr)
                    {
                        if (GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1" ||
                            GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "A")
                            presente = true;
                    }
                }
                if (!presente && datiContr != null && datiContr.Count > 0)
                {
                    foreach (GestioneCalcolo.DatiCalcoloContributivo c in datiContr)
                    {
                        if (GetGestioneContributiva(c.CodiceGestione, listaCodeGestioneCalcoloContributivo) == "1" ||
                            GetGestioneContributiva(c.CodiceGestione, listaCodeGestioneCalcoloContributivo) == "A")
                            presente = true;
                    }
                }

                if (!presente)
                {
                    if (siglaCategoria == "VDAI" || siglaCategoria == "IDAI" || siglaCategoria == "SDAI")
                        messaggioVideo = "Deve esistere almeno una registrazione contributiva o retributiva con gestione pari a 1 o A";
                    else
                        messaggioVideo = "Deve esistere almeno una registrazione contributiva o retributiva con gestione pari a 1";
                    return false;
                }
            }

            if (filtro == "RAL" || filtro == "R22" || filtro == "R23" || filtro == "R24" ||
                    filtro == "R25" || filtro == "R44" || filtro == "R45")
            {

                //Se solo la Tabella Contributiva (VCTR335) contiene dati e la somma dei Campi Numero Contributi (RAU113A) e 
                //Numero Contributi Volontari (RAU113B) è inferiore a 780 la Data Inizio Assicurazione (VINASS) non  può essere precedente a gennaio 1996
                if (datiContr != null && datiContr.Count > 0 && (datiRetr == null || datiRetr.Count == 0) && datiPensione.InizioAssicurazione.HasValue)
                {
                    if ((nSettimaneOBG + nContributiVolontari) < 780)
                    {
                        if (!Utility.DataSuccessivaA(datiPensione.InizioAssicurazione.Value, new DateTime(1996, 1, 1)))
                        {
                            messaggioVideo = "La data di inizio assicurazione non può essere precedente a gennaio 1996";
                            return false;
                        }
                    }
                }

                if ((datiContr == null || datiContr.Count == 0) && datiRetr != null && datiRetr.Count > 0 && datiPensione.FineAssicurazione.HasValue)
                {
                    //Se nella Tabella Contributiva (VCTR335) non esistono registrazioni e nella Tabella Retributiva (RETRIB) 
                    //esiste un elemento con il Codice Quota (VRQUOTA) = a “B” e il Codice Gestione (VRGEST) = a “1H”, “2H”, “3H”, “4H”  
                    //e un altro Codice Quota (VRQUOTA) = a “B” con il Codice Gestione (VRGEST) = a “1H”, “2H”, “3H”, “4H” 
                    //la Data Fine Assicurazione non può essere successiva al 31 dicembre 1997
                    int count = 0;
                    foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetr)
                    {
                        switch (GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo))
                        {
                            case "1H":
                            case "2H":
                            case "3H":
                            case "4H":
                                if (r.QuotePrimeLiquidate.HasValue && r.QuotePrimeLiquidate.Value == 'A')
                                    count++;
                                break;
                            default:
                                break;
                        }
                    }
                    if (count >= 2)
                    {
                        if (Utility.DataStrettamenteSuccessivaA(datiPensione.FineAssicurazione.Value, new DateTime(1997, 12, 31)))
                        {
                            messaggioVideo = "La data di fine assicurazione non può essere successiva al 31 dicembre 1997";
                            return false;
                        }
                    }

                    //Se nella Tabella Contributiva (VCTR335) non esistono registrazioni e nella Tabella Retributiva (RETRIB) 
                    //esiste un elemento con il Codice Quota (VRQUOTA) = a “A” e nessun altro elemento con Codice Quota (VRQUOTA) = a “B” 
                    //la Data Fine Assicurazione non può essere successiva al 31 dicembre 1992 

                    count = 0;
                    presente = false;
                    foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetr)
                    {
                        if (r.QuotePrimeLiquidate.HasValue && r.QuotePrimeLiquidate.Value == 'A')
                            presente = true;
                        if (r.QuotePrimeLiquidate.HasValue && r.QuotePrimeLiquidate.Value == 'B')
                            count++;
                    }
                    if (presente && count == 0)
                    {
                        if (Utility.DataStrettamenteSuccessivaA(datiPensione.FineAssicurazione.Value, new DateTime(1992, 12, 31)))
                        {
                            messaggioVideo = "La data di fine assicurazione non può essere successiva al 31 dicembre 1992";
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        public static bool ControlsDatiContributivi(GestioneCalcolo.DatiCalcoloContributivo contr, GestionePensione.DatiPensione datiPensione,
            List<GestioneDecodifica.CodeGestioneCalcoloContributivo> listaCodeGestioneCalcoloContributivo, byte? provenienzaDA, string siglaCatDiretta, string tipoSettimaneBeneficio,
            Utility.TipoCalcolo tipoCalcolo, List<GestioneCalcolo.DatiCalcoloContributivo> listaDatiCalcoloContributivo, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            int pdirsup = 0;
            int plavaut = 0;

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            //ENG - Aggiornamento Memo 68/2022 IOPGI
            //ENG - Spacchettate SOPGI
            if (BypassaControlliRicSdaiContributivoK(datiPensione, listaDatiCalcoloContributivo, listaCodeGestioneCalcoloContributivo) ||
                BypassaControlliRic_VOCRED_CRED27_ContributivoL(datiPensione, listaDatiCalcoloContributivo, listaCodeGestioneCalcoloContributivo) ||
                Utility.IsDomandaVOPGI(datiPensione.SiglaCategoria) || (Utility.IsDomandaIOPGI(datiPensione.SiglaCategoria) && !Utility.IsDomandaIOPGI_AGI(datiPensione))
                || Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, datiDanteCausa))
                return true;

            var IsAnte96 = Utility.IsDomandaAnte96(datiPensione, datiPensione, datiDanteCausa, Utility.IsRiaperturaDomanda(datiPensione.Id));
            if (IsAnte96 != null)
            {
                decimal min = 0;
                decimal max = 4.1998276m;



                if (contr.Montante.HasValue && contr.ImportoContributivoTotale.HasValue)
                {
                    if (contr.ImportoContributivoTotale.Value != 0 && contr.Montante.Value > contr.ImportoContributivoTotale.Value)
                    {
                        messaggioVideo = "La “Base” deve essere inferiore o uguale all’ ”IVS”.";
                        return false;
                    }
                    if (min < contr.Montante.Value && contr.Montante.Value > max)
                    {
                        messaggioVideo = "La “Base” deve essere compresa tra 0 e 4.1998276";
                        return false;
                    }
                }
                return true;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);

            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);

            GetPdirusp_Plavaut(datiPensione, out pdirsup, out plavaut);

            byte codProv = provenienzaDA.HasValue ? provenienzaDA.Value : (byte)0;
            #endregion Recupero Dati

            if (contr != null)
            {
                string codiceGestione = GetGestioneContributiva(contr.CodiceGestione, listaCodeGestioneCalcoloContributivo);

                //I Codici Gestione Contributiva (VGES335) ammessi sono “1”, “2”, “3”, “4”, “G”, “H”, “A”
                switch (codiceGestione)
                {
                    case "1":
                    case "2":
                    case "3":
                    case "4":
                    case "G":
                    case "H":
                    case "A":
                    case "K":
                    case "O":
                    case "P":
                        //Il Codice Gestione Contributiva (VGES335) = a “A” è ammesso solo per le “VOAUT”, “SOAUT” indiretta 
                        //(Codice di Provenienza (DAU107) = a zero) o se la Categoria della Diretta (DAUE11) è = a “VOAUT”
                        if (codiceGestione == "A")
                        {
                            if ((!(siglaCategoria == "VOAUT" || (siglaCategoria == "SOAUT" && (codProv == 0 || (!string.IsNullOrEmpty(siglaCatDiretta) && siglaCatDiretta == "VOAUT"))))) &&
                                (siglaCategoria != "VDAI" && siglaCategoria != "IDAI" && siglaCategoria != "SDAI"))
                            {

                                messaggioVideo = "Il codice gestione contributiva pari ad A è ammesso solo per le VDAI, le IDAI, le SDAI, le VOAUT, le SOAUT indirette o con la categoria della diretta pari a VOAUT";
                                return false;
                            }
                        }
                        //Il Codice Gestione Contributiva (VGES335) = a “G” è ammesso solo per la Categoria (RACATEG) = a “VOAUT”, “IOAUT”, “SOAUT”
                        else if (codiceGestione == "G")
                        {
                            if (siglaCategoria != "VOAUT" && siglaCategoria != "SOAUT" && siglaCategoria != "IOAUT")
                            {
                                messaggioVideo = "Il codice gestione contributiva pari a G è ammesso solo per la categoria VOAUT, IOAUT ed SOAUT";
                                return false;
                            }
                        }
                        //Il Codice Gestione Contributiva (VGES335) = a “H” è ammesso solo per la Categoria (RACATEG) = a “VOBANC”, “IOBANC”, “SOBANC
                        else if (codiceGestione == "H")
                        {
                            if (siglaCategoria != "VOBANC" && siglaCategoria != "SOBANC" && siglaCategoria != "IOBANC")
                            {
                                messaggioVideo = "Il codice gestione contributiva pari a H è ammesso solo per la categoria VOBANC, IOBANC ed SOBANC";
                                return false;
                            }
                        }
                        else if (!Utility.IsDomandaBancRicAnte1991(datiPensione, datiDanteCausa) && (codiceGestione == "O" || codiceGestione == "P"))
                        {
                            messaggioVideo = "Codice gestione contributiva " + codiceGestione + " non ammesso";
                            return false;
                        }
                        break;

                    //I Codici Gestione Contributiva (VGES335) ammessi sono  “1”, “2”, “3”, “4”, “G”, “H”, “A”, “1H”, “2H”, “3H”, “4H”
                    case "1H":
                    case "2H":
                    case "3H":
                    case "4H":
                        if (filtro != "RAL" && filtro != "R22" && filtro != "R23" && filtro != "R24" &&
                            filtro != "R25" && filtro != "R44" && filtro != "R45")
                        {
                            messaggioVideo = "Codice gestione contributiva " + codiceGestione + " non ammesso";
                            return false;
                        }
                        break;
                    case "C1":
                    case "C2":
                    case "C3":
                    case "C4":
                    case "C5":
                    case "E1":
                    case "E2":
                    case "F0":
                    case "F1":
                    case "D1":
                    case "A5":
                    case "A6":
                    case "A7":
                    case "A8":
                    case "A9":
                    case "B1":
                    case "B2":
                    case "B3":
                    case "B4":
                        if (!Utility.IsDomandaAUT(datiPensione))
                        {
                            messaggioVideo = "Codice gestione contributiva " + codiceGestione + " non ammesso";
                            return false;
                        }
                        break;

                    default:
                        if (siglaCategoria == "VDAI" || siglaCategoria == "IDAI" || siglaCategoria == "SDAI")
                            messaggioVideo = "I codici gestione contributiva ammessi sono 1, 2, 3, 4, G, H, A";
                        else if (Utility.IsRenditaCasalinghe(datiPensione) || Utility.IsRenditaFacoltativa(datiPensione))
                            break;
                        else
                            messaggioVideo = "I codici gestione contributiva ammessi sono 1, 2, 3, 4, G, H";
                        return false;
                }

                //Se la Categoria è = a "VO", "IO", "SO",, "VOBANC", "IOBANC", "SOBANC", "VOCRED", "VOCOOP", "VOESO", 
                //"VOP", "IOP", "SOP", "VOMIN", "SOMIN" il Codice Gestione Contributiva (VGES335) deve essere solo “1”
                switch (siglaCategoria)
                {
                    case "VO":
                    case "IO":
                    case "SO":
                    case "VOBANC":
                    case "IOBANC":
                    case "SOBANC":
                    case "VOCRED":
                    case "CRED27":
                    case "VOCOOP":
                    case "VOESO":
                    case "VOP":
                    case "IOP":
                    case "SOP":
                    case "VOMIN":
                    case "SOMIN":
                    case "COOP28":
                        if (codiceGestione != "1")
                        {
                            switch (codiceGestione)
                            {
                                case "Q":
                                    if (!(datiPensione.AttivitaEconomica == 4 && datiPensione.ProfessioneIndividuale == 350 && tipoSettimaneBeneficio == "09" &&
                                        !Utility.DataSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, new DateTime(2004, 02, 01))))
                                    {
                                        messaggioVideo = "Il codice gestione contributiva non può essere pari a Q";
                                        return false;
                                    }
                                    break;
                                case "S":
                                    if (filtro != "BNS" && filtro != "BNX")
                                    {
                                        messaggioVideo = "Il codice gestione contributiva non può essere pari a S";
                                        return false;
                                    }
                                    break;
                                case "1H":
                                    if (filtro != "RAL" && filtro != "R44" && filtro != "R45")
                                    {
                                        messaggioVideo = "Il codice gestione contributiva non può essere pari a 1H";
                                        return false;
                                    }
                                    break;
                                default:
                                    if (!Utility.IsDomandaBancRicAnte1991(datiPensione, datiDanteCausa))
                                    {
                                        messaggioVideo = "Il codice gestione contributiva deve essere pari a 1" + ((filtro == "RAL" || filtro == "R44" || filtro == "R45") ? " o 1H" : string.Empty);
                                        return false;
                                    }
                                    break;
                            }
                        }
                        break;
                }

                //Le Settimane Contributive (VSET335) non possono essere più di 2600
                if (contr.NSettimane.HasValue && contr.NSettimane.Value > 2600)
                {
                    messaggioVideo = "Le settimane contributive non possono essere più di 2600";
                    return false;
                }

                //L'Ammontare dei Contributi (VAMM335) di ogni elemento non può essere superiore al Montante dei Contributi (VMON335) di ogni elemento corrispondente
                if ((contr.ImportoContributivoTotale.HasValue && contr.Montante.HasValue &&
                    contr.ImportoContributivoTotale.Value > contr.Montante.Value) ||
                    (contr.ImportoContribTotaleQuotaDL214.HasValue && contr.MontanteQuotaDL214.HasValue && contr.ImportoContribTotaleQuotaDL214.Value > contr.MontanteQuotaDL214.Value))
                {
                    messaggioVideo = "L'ammontare dei contributi non può essere superiore al montante";
                    return false;
                }

                //Se la Categoria (RACATEG) è = a “VO”, “IO”, “SO” non si possono acquisire i Codici Gestione Contributiva (VGES335) “2H”, “3H”, “4H”
                if (filtro == "RAL" || filtro == "R22" || filtro == "R23" || filtro == "R24" ||
                    filtro == "R25" || filtro == "R44" || filtro == "R45")
                {

                    switch (siglaCategoria)
                    {
                        case "VO":
                        case "IO":
                        case "SO":
                            if (codiceGestione == "2H" || codiceGestione == "3H" || codiceGestione == "4H")
                            {
                                messaggioVideo = "Non sono ammessi i codici gestione 2H, 3H e 4H";
                                return false;
                            }
                            break;
                        default:
                            break;
                    }
                }

                if (Utility.IsDomandaVESO29(datiPensione.SiglaCategoria) && filtro == "OBG" && codiceGestione != "1")
                {
                    messaggioVideo = "Codice gestione contributiva " + codiceGestione + " non ammesso";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsDatiContributiviFinal(ref List<GestioneCalcolo.DatiCalcoloContributivo> datiContr,
            GestionePensione.DatiPensione datiPensione, GestioneDanteCausa.DatiDanteCausa datiDA, List<GestioneDecodifica.CodeGestioneCalcoloContributivo> listaCodeGestioneCalcoloContributivo,
            int nSettimaneOBG, int? nSettimaneBeneficio, Utility.TipoCalcolo tipoCalcolo, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';
            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            int pdirsup = 0;
            int plavaut = 0;
            int panvein = 0;
            bool posticipo = false;

            var isAnte96 = Utility.IsDomandaAnte96(datiPensione, datiPensione, datiDA, Utility.IsRiaperturaDomanda(datiPensione.Id));

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            //ENG - Aggiornamento Memo 68/2022 IOPGI
            //ENG - Spacchettate SOPGI
            if (Utility.IsDomandaVOPGI(datiPensione.SiglaCategoria) || (Utility.IsDomandaIOPGI(datiPensione.SiglaCategoria) && !Utility.IsDomandaIOPGI_AGI(datiPensione))
                || Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, datiDA))
                return true;

            Utility.GetCodiciNatura(datiPensione.NaturaPensione, out codNat1, out codNat2, out codNat3);

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);

            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);

            GetPdirusp_Plavaut(datiPensione, out pdirsup, out plavaut);

            GetPanvein_Posticipo(datiPensione.NaturaPensione, datiPensione, out panvein, out posticipo);
            #endregion Recupero Dati

            if (Utility.IsRenditaCasalinghe(datiPensione) || Utility.IsRenditaFacoltativa(datiPensione) || isAnte96 != null)
                return true;

            if (datiContr != null && datiContr.Count > 0)
            {
                List<GestioneCalcolo.DatiCalcoloContributivo> datiContrOrdered = null;
                OrdinaDatiContributivi(datiPensione, datiContr, listaCodeGestioneCalcoloContributivo, out datiContrOrdered);

                if (BypassaControlliRicSdaiContributivoK(datiPensione, datiContr, listaCodeGestioneCalcoloContributivo) ||
                    BypassaControlliRic_VOCRED_CRED27_ContributivoL(datiPensione, datiContr, listaCodeGestioneCalcoloContributivo))
                {
                    datiContr = datiContrOrdered;
                    return true;
                }

                //Verificare che non ci siano doppie registrazioni di Codice Gestione (VRGEST) e Quota (VRQUOTA)
                if (siglaCategoria != "VOMIN" && siglaCategoria != "SOMIN" && !(Utility.IsRenditaCasalinghe(datiPensione) || Utility.IsRenditaFacoltativa(datiPensione)))
                {
                    for (int i = 0; i < datiContrOrdered.Count; i++)
                        for (int j = i + 1; j < datiContrOrdered.Count; j++)
                        {
                            if (datiContrOrdered[i].CodiceGestione == datiContrOrdered[j].CodiceGestione &&
                                (datiContrOrdered[i].IsQuotaDL214Presente() == datiContrOrdered[j].IsQuotaDL214Presente() ||
                                datiContrOrdered[i].IsQuotaL335Presente(datiPensione) == datiContrOrdered[j].IsQuotaL335Presente(datiPensione)))
                            {
                                messaggioVideo = "Non possono esserci doppie registrazioni di codice gestione e quota";
                                return false;
                            }
                        }
                }

                //Se la Categoria (RACATEG) è = a “VOMIN”, “SOMIN”, non sono ammesse più di 4 registrazioni nella tabella VCTR335
                if (siglaCategoria == "VOMIN" || siglaCategoria == "SOMIN")
                {
                    if (datiContrOrdered.Count > 4)
                    {
                        messaggioVideo = "Non sono ammesse più di 4 registrazioni contributive";
                        return false;
                    }

                    if (datiContrOrdered.Where(x => x.IsQuotaDL214Presente()).Count() > 2)
                    {
                        messaggioVideo = "Non sono ammesse più di due quote D";
                        return false;
                    }

                    if (datiContrOrdered.Where(x => x.IsQuotaL335Presente()).Count() > 2)
                    {
                        messaggioVideo = "Non sono ammesse più di due quote C";
                        return false;
                    }
                }
                //Se la Categoria (RACATEG) è = a “VO”, “IO”, “SO” e il Codice Gestione (VGES335) è = a “1” non è ammessa più di una registrazione nella tabella VCTR335 
                //solo per ultimo versament >= 01/01/2012 sono ammesse 2 registrazioni C, D
                else if (siglaCategoria == "VO" || siglaCategoria == "SO" || siglaCategoria == "IO")
                {
                    if (GetGestioneContributiva(datiContrOrdered[0].CodiceGestione, listaCodeGestioneCalcoloContributivo) == "1" && datiContrOrdered.Count > 1)
                    {
                        if ((datiPensione.FineAssicurazione.HasValue && Utility.DataSuccessivaA(datiPensione.FineAssicurazione.Value, new DateTime(2012, 1, 1))) ||
                            (Utility.IsPensioneInabilitaGenericaPost2012(datiPensione) && nSettimaneBeneficio.GetValueOrDefault() > 0))
                        {
                            if (GetGestioneContributiva(datiContrOrdered[1].CodiceGestione, listaCodeGestioneCalcoloContributivo) == "1")
                            {
                                if (datiContrOrdered.Count > 2)
                                {
                                    messaggioVideo = "Non sono ammesse più di 2 registrazioni contributive";
                                    return false;
                                }

                                if (!(((datiContrOrdered[0].ImportoContributivoTotale.HasValue || datiContrOrdered[0].Montante.HasValue) &&
                                (!datiContrOrdered[1].ImportoContributivoTotale.HasValue && !datiContrOrdered[1].Montante.HasValue)) ||
                                ((datiContrOrdered[1].ImportoContributivoTotale.HasValue || datiContrOrdered[1].Montante.HasValue) &&
                                (!datiContrOrdered[0].ImportoContributivoTotale.HasValue && !datiContrOrdered[0].Montante.HasValue))))
                                {
                                    messaggioVideo = "Non sono ammesse 2 registrazioni contributive con la stessa quota";
                                    return false;
                                }
                            }
                        }
                        else
                        {
                            if ((Utility.IsPensioneInabilitaGenericaPost2012(datiPensione) && nSettimaneBeneficio.GetValueOrDefault() == 0))
                                messaggioVideo = "Trattasi di pensione di inabilità sprovvista di settimane beneficio. Spuntare la casella benefici dei dati generici e acquisire le settimane beneficio attribuite.";
                            else
                                messaggioVideo = "Non è ammessa più di 1 registrazione contributiva perché la fine assicurazione è antecedente al 01/01/2012.";
                            return false;
                        }
                    }
                }

                if ((datiDA != null && datiDA.DecorrenzaPensione.HasValue && !Utility.DataSuccessivaA(datiDA.DecorrenzaPensione.Value, new DateTime(1996, 1, 1))) ||
                    ((datiDA == null || !datiDA.DecorrenzaPensione.HasValue) && datiPensione != null && datiPensione.DecorrenzaOriginaria.HasValue && !Utility.DataSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, new DateTime(1996, 1, 1))))
                {
                    //Se la Categoria (RACATEG) è diversa da “VOMIN”, “SOMIN” e il Codice Gestione (VGES335) è = a “1” e 
                    //il Campo RINSIEME è = a “SI” non è ammessa più di una registrazione nella tabella VCTR335
                    if (siglaCategoria != "VOMIN" && siglaCategoria != "SOMIN" && GetGestioneContributiva(datiContrOrdered[0].CodiceGestione, listaCodeGestioneCalcoloContributivo) == "1"
                        && datiContrOrdered.Count > 1 && tipoCalcolo == Utility.TipoCalcolo.Contributivo)
                    {
                        if (datiPensione.FineAssicurazione.HasValue && Utility.DataSuccessivaA(datiPensione.FineAssicurazione.Value, new DateTime(2012, 1, 1)))
                        {
                            if (GetGestioneContributiva(datiContrOrdered[1].CodiceGestione, listaCodeGestioneCalcoloContributivo) == "1")
                            {
                                if (datiContrOrdered.Count > 2)
                                {
                                    messaggioVideo = "Non sono ammesse più di 2 registrazioni contributive con decorrenza inferiore al 1996";
                                    return false;
                                }
                                if (!(((datiContrOrdered[0].ImportoContributivoTotale.HasValue || datiContrOrdered[0].Montante.HasValue) &&
                                (!datiContrOrdered[1].ImportoContributivoTotale.HasValue && !datiContrOrdered[1].Montante.HasValue)) ||
                                ((datiContrOrdered[1].ImportoContributivoTotale.HasValue || datiContrOrdered[1].Montante.HasValue) &&
                                (!datiContrOrdered[0].ImportoContributivoTotale.HasValue && !datiContrOrdered[0].Montante.HasValue))))
                                {
                                    messaggioVideo = "Non sono ammesse 2 registrazioni contributive con la stessa quota";
                                    return false;
                                }
                            }
                        }
                        else
                        {
                            messaggioVideo = "Non è ammessa più di 1 registrazione contributiva";
                            return false;
                        }
                    }
                }

                //Se la Categoria (RACATEG) è = a “VOTOT”, “IOTOT”, “SOTOT” e il 1° elemento della Tabella Contributiva (VCTR335) 
                //il Codice Gestione (VCGES335) è = a “G” (Non più: e non esistono altre registrazioni in Tabella )
                //la Data Inizio Assicurazione (VINASS) non può essere antecedente al 31 marzo 1991 
                if ((siglaCategoria == "VOTOT" || siglaCategoria == "IOTOT" || siglaCategoria == "SOTOT") && GetGestioneContributiva(datiContrOrdered[0].CodiceGestione, listaCodeGestioneCalcoloContributivo) == "G")
                {
                    if (datiPensione.InizioAssicurazione.HasValue && !Utility.DataSuccessivaA(datiPensione.InizioAssicurazione.Value, new DateTime(1991, 03, 31)))
                    {
                        messaggioVideo = "La data di inizio assicurazione non può essere antecedente al 31 marzo 1991";
                        return false;
                    }
                }

                //Un ulteriore controllo incrociato va fatto quando il Campo RINSIEME è = a “SI” e il 1° Codice Natura è diverso da “5” 
                //(in pratica una Contributiva non pensione supplementare): 
                //la Data Fine Assicurazione (VFIASS) non può essere inferiore al 31 dicembre 2000 ad eccezione dei seguenti casi: 
                //quando DO-NOTE è = a “SUT”, “ERI” 
                //se la Categoria (RACATEG) è = “IOAUT” e il Campo DO-NOTE è diverso a “SUT” la Data Fine Assicurazione (VFIASS) non può essere inferiore al 31 marzo 2001 
                //se la Categoria (RACATEG) è = “VOAUT”, “IOAUT” e il Numero Contributi Totali (RAU113A) è inferiore a 780 e non esiste una seconda registrazione nella tabella Contributiva VCTR335 la Data Fine Assicurazione (VFIASS) non può essere inferiore al 31 marzo 2001
                if (tipoCalcolo == Utility.TipoCalcolo.Contributivo && codNat1 != '5')
                {
                    if (datiPensione.FineAssicurazione.HasValue && !Utility.DataSuccessivaA(datiPensione.FineAssicurazione.Value, new DateTime(2000, 12, 31)))
                    {
                        if (filtro != "SUT" && filtro != "ERI" && !Utility.IsDomandaBancari(datiPensione.SiglaCategoria))
                        {
                            messaggioVideo = "La data fine assicurazione non può essere inferiore al 31 dicembre 2000";
                            return false;
                        }
                        if (siglaCategoria == "IOAUT" && filtro != "SUT" && !Utility.DataSuccessivaA(datiPensione.FineAssicurazione.Value, new DateTime(2001, 03, 31)))
                        {
                            messaggioVideo = "La data fine assicurazione non può essere inferiore al 31 marzo 2001";
                            return false;
                        }
                        if ((siglaCategoria == "VOAUT" || siglaCategoria == "IOAUT") && nSettimaneOBG < 780 && datiContr.Count == 1 &&
                            !Utility.DataSuccessivaA(datiPensione.FineAssicurazione.Value, new DateTime(2001, 03, 31)))
                        {
                            messaggioVideo = "La data fine assicurazione non può essere inferiore al 31 marzo 2001";
                            return false;
                        }
                    }
                }

                if (filtro == "RAL" || filtro == "R22" || filtro == "R23" || filtro == "R24" ||
                            filtro == "R25" || filtro == "R44" || filtro == "R45")
                {
                    //Se il Campo RINSIEME è = a “SI” e la Categoria (RACATEG) è = a “VO”, “IO”, “SO” 
                    //non sono ammessi più di 4 registrazioni in tabella che possono essere solo con Codice gestione (VGES335) = a “1” e “1H”
                    if (tipoCalcolo == Utility.TipoCalcolo.Contributivo && (siglaCategoria == "VO" || siglaCategoria == "IO" || siglaCategoria == "SO"))
                    {
                        if (datiContrOrdered.Count > 4)
                        {
                            messaggioVideo = "Non sono ammesse più di 4 registrazioni contributive";
                            return false;
                        }
                        foreach (GestioneCalcolo.DatiCalcoloContributivo c in datiContrOrdered)
                        {
                            if (GetGestioneContributiva(c.CodiceGestione, listaCodeGestioneCalcoloContributivo) != "1" && GetGestioneContributiva(c.CodiceGestione, listaCodeGestioneCalcoloContributivo) != "1H")
                            {
                                messaggioVideo = "Il codice gestione contributivo " + GetGestioneContributiva(c.CodiceGestione, listaCodeGestioneCalcoloContributivo) + " non è ammesso";
                                return false;
                            }
                        }
                    }

                    //Se il Campo RINSIEME è = a “SI” e il 1° Codice Natura è diverso da “5” (in pratica una Contributiva non pensione supplementare) 
                    //la Data Fine Assicurazione (VFIASS) non può essere inferiore al 31 dicembre 2000
                    if (tipoCalcolo == Utility.TipoCalcolo.Contributivo && codNat1 != '5')
                    {
                        if (datiPensione.FineAssicurazione.HasValue && !Utility.DataSuccessivaA(datiPensione.FineAssicurazione.Value, new DateTime(2000, 12, 31)))
                        {
                            messaggioVideo = "La data fine assicurazione non può essere inferiore al 31 dicembre 2000";
                            return false;
                        }
                    }

                    //Se nella Tabella Contributiva (VCTR335) e la Data Fine Assicurazione è successiva al 31 dicembre 1997 
                    //deve esistere un elemento con Codice Gestione (VGES335) = a “1H”, “2H”, “3H”, “4H”
                    if (datiPensione.FineAssicurazione.HasValue && Utility.DataStrettamenteSuccessivaA(datiPensione.FineAssicurazione.Value, new DateTime(1997, 12, 31)))
                    {
                        bool presente = false;
                        foreach (GestioneCalcolo.DatiCalcoloContributivo c in datiContrOrdered)
                        {
                            if (GetGestioneContributiva(c.CodiceGestione, listaCodeGestioneCalcoloContributivo) != "1H" &&
                                GetGestioneContributiva(c.CodiceGestione, listaCodeGestioneCalcoloContributivo) != "2H" &&
                                GetGestioneContributiva(c.CodiceGestione, listaCodeGestioneCalcoloContributivo) != "3H" &&
                                GetGestioneContributiva(c.CodiceGestione, listaCodeGestioneCalcoloContributivo) != "4H")
                                presente = true;
                        }
                        if (!presente)
                        {
                            messaggioVideo = "Deve esistere almeno un elemento contributivo con codice gestione diverso da 1H e 2H e 3H e 4H";
                            return false;
                        }
                    }
                }

                datiContr = datiContrOrdered;
            }
            return true;
        }

        public static bool ControlsDatiContribRetribFinal(List<GestioneCalcolo.DatiCalcoloContributivo> datiContr, List<GestioneCalcolo.DatiCalcoloRetributivo> datiRetrib,
            GestionePensione.DatiPensione datiPensione, List<GestioneCalcoloVittimeTerrorismo.DatiCalcoloVittimeTerrorismo> listaDatiCalcoloVittimeTerrorismo,
            GestioneBeneficioVittimeTerrorismo.DatiBeneficioVittimeTerrorismo datiBeneficioVittimeTerrorismo, List<Liquidazione.BLCommon.CtrlDecorrenzaRetrExINPDAI> lstCtrlDecorrenza,
            List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> listaCodeGestioneCalcoloRetributivo, List<GestioneDecodifica.CodeGestioneCalcoloContributivo> listaCodeGestioneCalcoloContributivo,
            string tipoSettimaneBeneficio, Utility.TipoCalcolo tipoCalcolo, GestioneDanteCausa.DatiDanteCausa danteCausa, GestioneIntegrazioneArt11.IntegrazioneArt11 datiIntegrazioneArt11, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';
            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            int pdirsup = 0;
            int plavaut = 0;
            int panvein = 0;
            bool posticipo = false;

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            //ENG - Aggiornamento Memo 68/2022 IOPGI
            //ENG - Spacchettate SOPGI
            if (BypassaControlliRicSdaiContributivoK(datiPensione, datiContr, listaCodeGestioneCalcoloContributivo) ||
                BypassaControlliRic_VOCRED_CRED27_ContributivoL(datiPensione, datiContr, listaCodeGestioneCalcoloContributivo) ||
                Utility.IsDomandaVOPGI(datiPensione.SiglaCategoria) || (Utility.IsDomandaIOPGI(datiPensione.SiglaCategoria) && !Utility.IsDomandaIOPGI_AGI(datiPensione))
                || Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa))
                return true;

            Utility.GetCodiciNatura(datiPensione.NaturaPensione, out codNat1, out codNat2, out codNat3);

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);

            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);

            GetPdirusp_Plavaut(datiPensione, out pdirsup, out plavaut);

            GetPanvein_Posticipo(datiPensione.NaturaPensione, datiPensione, out panvein, out posticipo);

            #endregion Recupero Dati

            if (!ControlsSettimaneGestioneDatiCalcolo(datiPensione, datiContr, datiRetrib, listaCodeGestioneCalcoloRetributivo, listaCodeGestioneCalcoloContributivo, danteCausa, datiIntegrazioneArt11, out messaggioVideo))
                return false;

            if (!ControlsGestioneHContribRetrib(datiContr, datiRetrib, filtro, listaCodeGestioneCalcoloRetributivo, listaCodeGestioneCalcoloContributivo, out messaggioVideo))
                return false;

            if (!ControlsSettimane707(datiPensione, datiRetrib, datiContr, listaCodeGestioneCalcoloRetributivo, listaCodeGestioneCalcoloContributivo, lstCtrlDecorrenza,
                listaCodeGestioneCalcoloRetributivo, datiBeneficioVittimeTerrorismo, tipoSettimaneBeneficio, tipoCalcolo, out messaggioVideo))
                return false;

            bool IsContribOK = false;
            bool IsRetribOK = false;

            if (datiContr != null && datiContr.Count > 0)
            {
                foreach (GestioneCalcolo.DatiCalcoloContributivo contr in datiContr)
                {
                    IsContribOK = ControlsGestioneDatiCalcolo(siglaCategoria, filtro, GetGestioneContributiva(contr.CodiceGestione, listaCodeGestioneCalcoloContributivo), out messaggioVideo);
                    if (IsContribOK)
                        break;
                }
            }
            if (!IsContribOK && datiRetrib != null && datiRetrib.Count > 0)
            {
                foreach (GestioneCalcolo.DatiCalcoloRetributivo retr in datiRetrib)
                {
                    IsRetribOK = ControlsGestioneDatiCalcolo(siglaCategoria, filtro, GetGestioneRetributiva(retr.CodiceGestione, listaCodeGestioneCalcoloRetributivo), out messaggioVideo);
                    if (IsRetribOK)
                        break;
                }
            }

            if (datiPensione.SbloccaPannelliAnte96.GetValueOrDefault() && datiPensione.TipoCalcolo == 21)
            {
                bool isListeCorrispondenti = datiRetrib != null && datiRetrib.Count > 0 && datiContr != null && datiContr.Count > 0 ? !datiRetrib.Select(o => o.CodiceGestione).Except(datiContr.Select(o => o.CodiceGestione)).Any() &&
                                             !datiContr.Select(o => o.CodiceGestione).Except(datiRetrib.Select(o => o.CodiceGestione)).Any() : false;
                if (!isListeCorrispondenti)
                {
                    IsRetribOK = false;
                    messaggioVideo = "Pensione con contribuzione versata in più gestioni assicurative, deve essere effettuata una registrazione 'retributiva' per ogni registrazione 'contributiva' e viceversa";
                    return false;
                }
            }

            if (!IsContribOK && !IsRetribOK && !string.IsNullOrEmpty(messaggioVideo))
                return false;

            if (!GestioneControlli.ControlsDatiCalcoloWithBeneficioTerrorismo(datiPensione, listaDatiCalcoloVittimeTerrorismo, datiRetrib, datiContr, listaCodeGestioneCalcoloRetributivo,
                listaCodeGestioneCalcoloContributivo, datiBeneficioVittimeTerrorismo, out messaggioVideo))
                return false;

            return true;
        }

        public static bool ControlsDatiRetributiviENPALS(GestioneCalcolo.DatiCalcoloRetributivoENPAL datiRetributivi, decimal? importoPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (datiRetributivi != null)
            {
                if (!Utility.VerificaRegex(datiRetributivi.RMQuotaA, cifreIntere: 7, cifreDecimali: 6))
                {
                    messaggioVideo = "RM Quota A in formato non corretto (max 7 interi, 6 decimali)";
                    return false;
                }

                if (!Utility.VerificaRegex(datiRetributivi.RMQuotaB, cifreIntere: 7, cifreDecimali: 6))
                {
                    messaggioVideo = "RM Quota B in formato non corretto (max 7 interi, 6 decimali)";
                    return false;
                }
            }

            if (importoPensione.HasValue)
            {
                if (!Utility.VerificaRegex(importoPensione, cifreIntere: 8, cifreDecimali: 7))
                {
                    messaggioVideo = "Importo Pensione in formato non corretto (max 8 interi, 7 decimali)";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsDatiContributiviENPALS(GestioneCalcolo.DatiCalcoloContributivoENPAL datiContributivi, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (datiContributivi != null)
            {
                if (!Utility.VerificaRegex(datiContributivi.Montante, cifreIntere: 8, cifreDecimali: 7))
                {
                    messaggioVideo = "Montante in formato non corretto (max 8 interi, 7 decimali)";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsQuotePensioneObbligatori(GestioneCalcolo.QuotePensione quotePensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (quotePensione == null)
            {
                messaggioVideo = "Quote Pensione assenti.";
                return false;
            }

            if (quotePensione.EnteGestioneFondo == 0)
            {
                messaggioVideo = "Il campo 'Ente / Gestione - Fondo' è obbligatorio.";
                return false;
            }

            if (!quotePensione.Settimane.HasValue)
            {
                messaggioVideo = "Il campo 'Settimane' è obbligatorio.";
                return false;
            }

            if (!quotePensione.Importo.HasValue)
            {
                messaggioVideo = "Il campo 'Importo Quota' è obbligatorio.";
                return false;
            }
            return true;
        }

        public static bool ControlsQuotePensionePerVecchiaia(GestionePensione.DatiPensione datiPensione, GestioneCalcolo.QuotePensione quotePensione, bool? tipoCumulo, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!datiPensione.SiglaCategoria.StartsWith("V"))
                return true;

            if (tipoCumulo.HasValue && !tipoCumulo.Value)
                return true;

            if (quotePensione.Settimane.GetValueOrDefault() < 1)
            {
                messaggioVideo = "Il numero di settimane non può essere inferiore a 1.";
                return false;
            }

            return true;
        }

        public static bool ControlsQuotePensionePerInabilita(GestionePensione.DatiPensione datiPensione, List<GestioneCalcolo.QuotePensione> lQuotePensione, long? enteCassa, bool? tipoCumulo,
            out string messaggioVideo, List<GestioneDecodifica.DecodificaEnteCassaProfessionale> listaDecodificaEnteCassaProfessionale = null,
            List<GestioneDecodifica.DecEnteGestioneFondo> listaDecEnteGestioneFondo = null)
        {
            messaggioVideo = string.Empty;

            GestioneControlliDinamici.ControlloDinamico ctrlAbilitazioneMemo93 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo93", out ctrlAbilitazioneMemo93);

            if (!datiPensione.SiglaCategoria.StartsWith("I"))
                return true;

            if (!(tipoCumulo.HasValue && !tipoCumulo.Value) && lQuotePensione.Exists(x => x.Settimane.GetValueOrDefault() < 1))
            {
                messaggioVideo = "Il numero di settimane non può essere inferiore a 1.";
                return false;
            }

            if (lQuotePensione.Sum(x => x.Settimane) > 2080 && !Utility.IsDomandaIOCUM(datiPensione.SiglaCategoria) && !Utility.IsDomandaIOTOT(datiPensione.SiglaCategoria))
            {
                messaggioVideo = "La somma delle settimane non può essere superiore a 2080.";
                return false;
            }

            if (enteCassa.HasValue)
            {
                if (listaDecodificaEnteCassaProfessionale == null)
                    GestioneDecodifica.GetDecodificaEnteCassaProfessionale(out listaDecodificaEnteCassaProfessionale);

                if (listaDecEnteGestioneFondo == null)
                    GestioneDecodifica.GetDecEnteGestioneFondo(out listaDecEnteGestioneFondo);

                GestioneDecodifica.DecodificaEnteCassaProfessionale enteCassaProfessionale = listaDecodificaEnteCassaProfessionale.Find(x => x.Id == enteCassa);
                List<GestioneDecodifica.DecEnteGestioneFondo> listaApp = null;
                if (enteCassaProfessionale != null)
                {
                    if (enteCassaProfessionale.TraduzioneSuGP == "0805")
                    {
                        if (tipoCumulo.HasValue && !tipoCumulo.Value && ctrlAbilitazioneMemo93 != null && !String.IsNullOrEmpty(ctrlAbilitazioneMemo93.ValoreControllo)
                            && ctrlAbilitazioneMemo93.ValoreControllo.ToUpperInvariant().Trim() == "SI")
                            listaApp = listaDecEnteGestioneFondo.FindAll(x => x.Codice == "F1");
                        else
                            listaApp = listaDecEnteGestioneFondo.FindAll(x => x.Codice == "F0" || x.Codice == "F1");
                    }
                    else if (ctrlAbilitazioneMemo93 != null && !String.IsNullOrEmpty(ctrlAbilitazioneMemo93.ValoreControllo) && ctrlAbilitazioneMemo93.ValoreControllo.ToUpperInvariant() == "SI")
                        listaApp = listaDecEnteGestioneFondo;
                    else
                        listaApp = listaDecEnteGestioneFondo.FindAll(x => x.Codice != "F0" && x.Codice != "F1");

                    if (!lQuotePensione.Exists(x => listaApp.Exists(y => y.Id == x.EnteGestioneFondo)))
                    {
                        string str = string.Join(", ", listaApp.Select(x => x.Codice).ToArray());

                        messaggioVideo = "Per Ente / Cassa pari a " + enteCassaProfessionale.TraduzioneSuGP + " - " + enteCassaProfessionale.Descrizione + " è necessario acquisire almeno un record con " +
                            "Ente / Gestione - Fondo pari a " + str + ".";
                        return false;
                    }
                }
            }

            return true;
        }

        public static bool ControlsQuotePensioneIsEnteIstruttoreFondoExINPDAP(List<GestioneCalcolo.QuotePensione> listaQuotePensione, bool? enteIstruttoreExInpdap, List<GestioneDecodifica.DecEnteGestioneFondo> listaDecEnteGestioneFondo,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            bool isEnteExist = false;

            if ((enteIstruttoreExInpdap != null) && (enteIstruttoreExInpdap.GetValueOrDefault()))
            {
                List<GestioneDecodifica.DecEnteGestioneFondo> listaApp = listaDecEnteGestioneFondo.FindAll(x => x.Codice == "C1" || x.Codice == "C2" || x.Codice == "C3" || x.Codice == "C4" || x.Codice == "C5" || x.Codice == "D1" || x.Codice == "A6");
                foreach (GestioneCalcolo.QuotePensione quotePensione in listaQuotePensione)
                {
                    if (listaApp.Exists(x => x.Id == quotePensione.EnteGestioneFondo))
                        isEnteExist = true;
                }

                if (!isEnteExist)
                {
                    messaggioVideo = "In presenza di ente istruttore fondo valorizzato a SI, è necessario inserire almeno un fondo ex INPDAP/IPOST/FFSS.";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsQuotePensionePerRicostituzioneCumuloProgressiva(GestionePensione.DatiPensione datiPensione, GestioneCalcolo.QuotePensione quotePensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (Utility.IsRicostituzioneCumuloProgressiva(datiPensione) && quotePensione.IsQuotaProgressiva)
            {
                if (!Utility.DataStrettamenteSuccessivaA(quotePensione.Decorrenza.Value, datiPensione.DecorrenzaOriginaria.Value))
                {
                    messaggioVideo = "La decorrenza quota pensione deve essere successiva alla decorrenza della pensione";
                    return false;
                }
                if (!(quotePensione.Decorrenza.HasValue && quotePensione.Decorrenza.Equals(new DateTime(9999, 1, 1)) && quotePensione.Importo != null && quotePensione.Importo <= 0.02m) &&
                    Utility.DataSuccessivaA(quotePensione.Decorrenza.Value, Utility.FirstDayOfMonth(Utility.DataSistemaAgo.AddMonths(2))))
                {
                    messaggioVideo = "La decorrenza quota pensione non può essere può essere maggiore del mese successivo alla data odierna";
                    return false;
                }
            }
            return true;
        }

        public static bool ControlsTrattenuteQuotePensione(GestioneCalcolo.TrattenuteQuotePensione trattenute, List<GestioneDecodifica.DecEnteGestioneFondo> elencoDecEnteGestioneFondo,
                                                           List<GestioneDecodifica.DecCodiceTrattenute> elencoDecCodiceTrattenute, GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (trattenute == null)
            {
                messaggioVideo = "Trattenute Quote Pensione assenti.";
                return false;
            }
            GestioneDecodifica.DecEnteGestioneFondo decEnteGestioneFondo = elencoDecEnteGestioneFondo.FirstOrDefault(x => x.Id == trattenute.EnteGestioneFondoQuote);
            if (!decEnteGestioneFondo.IsTrattenuteAmmesse.GetValueOrDefault())
            {
                messaggioVideo = string.Format("L'Ente/Gestione Fondo {0} non ammette trattenute.", decEnteGestioneFondo.Codice);
                return false;
            }

            if (trattenute.AnnoCompetenza == 0)
            {
                messaggioVideo = "Il campo 'Anno di competenza è obbligatorio.";
                return false;
            }

            if (string.IsNullOrEmpty(trattenute.CodiceTrattenute))
            {
                messaggioVideo = "Il campo 'Codice Trattenute' è obbligatorio.";
                return false;
            }

            if (!elencoDecCodiceTrattenute.Any(x => x.CodiceTrattenute == trattenute.CodiceTrattenute && x.CodiceEnteGestioneFondo == decEnteGestioneFondo.Codice))
            {
                messaggioVideo = string.Format("Il Codice Trattenute {0} non è valido.", trattenute.CodiceTrattenute);
                return false;
            }

            if (trattenute.ImportoTrattenute == 0 && !Utility.IsDomandaTotalizzazione(datiPensione.SiglaCategoria) &&
                !(Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) && datiPensione.IsCumuloAutomatica.GetValueOrDefault()))
            {
                messaggioVideo = "Il campo 'Importo Trattenute' è obbligatorio.";
                return false;
            }

            if (Utility.IsDomandaIOCUM(datiPensione.SiglaCategoria) || Utility.IsDomandaSOCUM(datiPensione.SiglaCategoria)
                || Utility.IsDomandaIOTOT(datiPensione.SiglaCategoria) || Utility.IsDomandaSOTOT(datiPensione.SiglaCategoria))
            {
                int annoCompetenza = 0;
                GestioneControlliDinamici.GetAnnoCompetenza(Utility.TipoAppartenenza.AGO, out annoCompetenza);
                if (trattenute.AnnoCompetenza < datiPensione.DecorrenzaOriginaria.Value.Year && trattenute.CodiceTrattenute == "770")
                {
                    messaggioVideo = string.Format("L'anno competenza per Codice Trattenuta = 770 deve essere maggiore o uguale dell'anno decorrenza pensione ({0})", datiPensione.DecorrenzaOriginaria.Value.Year);
                    return false;
                }
                if (trattenute.AnnoCompetenza > annoCompetenza && trattenute.CodiceTrattenute == "770")
                {
                    messaggioVideo = string.Format("L'anno competenza per Codice Trattenuta = 770 deve essere minore o uguale dell'anno di competenza in corso ({0})", annoCompetenza);
                    return false;
                }
            }

            if (!Utility.VerificaRegex(trattenute.ImportoTrattenute, cifreIntere: 8, cifreDecimali: 2))
            {
                messaggioVideo = "Importo Trattenute in formato non corretto (max 8 interi, 2 decimali)";
                return false;
            }
            return true;
        }

        public static bool ControlsSettimane707(GestionePensione.DatiPensione datiPensione, List<GestioneCalcolo.DatiCalcoloRetributivo> lDatiRetributivi,
            List<GestioneCalcolo.DatiCalcoloContributivo> lDatiContributivi, List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> listaCodeGestioneCalcoloRetributivo,
            List<GestioneDecodifica.CodeGestioneCalcoloContributivo> listaCodeGestioneCalcoloContributivo, List<INPS.Pensioni.Liquidazione.BLCommon.CtrlDecorrenzaRetrExINPDAI> lstCtrlDecorrenza,
            List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> lstDecGestioneCalcoloRetributivo, GestioneBeneficioVittimeTerrorismo.DatiBeneficioVittimeTerrorismo datiBeneficioVittimeTerrorismo,
            string tipoSettimaneBeneficio, Utility.TipoCalcolo tipoCalcolo, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!GestioneContrib.IsSettimane707Visible(datiPensione, lDatiRetributivi, lDatiContributivi, datiBeneficioVittimeTerrorismo, tipoCalcolo))
            {
                if (lDatiRetributivi != null && lDatiRetributivi.Count > 0 && lDatiRetributivi.Exists(x => x.NSettimane707.HasValue))
                {
                    messaggioVideo = "Settimane 707 non ammesse.";
                    return false;
                }

                return true;
            }

            if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.DatiCalcolo_DatiCalcolo_AGO.FALSO_RETRIBUTIVO_MONTI))
            {
                if (!Utility.IsDomandaINPDAI(datiPensione.SiglaCategoria))
                {
                    List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> lCodeGestioneRetributivoInserito = null;
                    if (lDatiRetributivi != null)
                        lCodeGestioneRetributivoInserito = listaCodeGestioneCalcoloRetributivo.FindAll(x => lDatiRetributivi.Select(y => y.CodiceGestione).Contains(x.Id));

                    List<GestioneDecodifica.CodeGestioneCalcoloContributivo> lCodeGestioneContributivoInserito = null;
                    if (lDatiContributivi != null)
                        lCodeGestioneContributivoInserito = listaCodeGestioneCalcoloContributivo.FindAll(x => lDatiContributivi.Select(y => y.CodiceGestione).Contains(x.Id));

                    List<string> lCodiceGestione = new List<string>();
                    if (lCodeGestioneRetributivoInserito != null && lCodeGestioneRetributivoInserito.Count > 0)
                        lCodiceGestione.AddRange(lCodeGestioneRetributivoInserito.Select(x => x.TraduzioneSuGP).ToList());
                    if (lCodeGestioneContributivoInserito != null && lCodeGestioneContributivoInserito.Count > 0)
                        lCodiceGestione.AddRange(lCodeGestioneContributivoInserito.Select(x => x.TraduzioneSuGP).ToList());

                    lCodiceGestione = lCodiceGestione.Distinct().ToList();

                    GestioneControlliDinamici.ControlloDinamico ctrl = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRilascioRIC_31082020", out ctrl);
                    foreach (string codiceGestione in lCodiceGestione)
                    {
                        if (!string.IsNullOrEmpty(codiceGestione))
                        {
                            long? gestione = null;
                            GestioneDecodifica.CodeGestioneCalcoloRetributivo gestioneCalcoloRetributivo = listaCodeGestioneCalcoloRetributivo.Find(x => x.TraduzioneSuGP.Trim() == codiceGestione.Trim());
                            if (gestioneCalcoloRetributivo != null)
                                gestione = gestioneCalcoloRetributivo.Id;

                            GestioneCalcolo.DatiCalcoloRetributivo retributiviB = null;
                            if (gestione.HasValue && lDatiRetributivi != null && lDatiRetributivi.Count > 0)
                                retributiviB = lDatiRetributivi.Find(x => x.CodiceGestione == gestione && x.QuotePrimeLiquidate == 'B');
                            int settimaneB = 0;
                            int settimane707 = 0;
                            if (retributiviB != null)
                            {
                                settimaneB = retributiviB.NSettimaneQuotaB.GetValueOrDefault();
                                settimane707 = retributiviB.NSettimane707.GetValueOrDefault();
                            }

                            gestione = null;
                            GestioneDecodifica.CodeGestioneCalcoloContributivo gestioneCalcoloContributivo = listaCodeGestioneCalcoloContributivo.Find(x => x.TraduzioneSuGP.Trim() == codiceGestione.Trim());
                            if (gestioneCalcoloContributivo != null)
                                gestione = gestioneCalcoloContributivo.Id;

                            GestioneCalcolo.DatiCalcoloContributivo contributiviD = null;
                            if (gestione.HasValue && lDatiContributivi != null && lDatiContributivi.Count > 0)
                                contributiviD = lDatiContributivi.Find(x => x.CodiceGestione == gestione && x.IsQuotaDL214Presente());
                            int settimaneD = 0;
                            if (contributiviD != null)
                                settimaneD = contributiviD.NSettimaneQuotaDL214.GetValueOrDefault();

                            if (contributiviD != null && retributiviB == null)
                            {
                                messaggioVideo = "E' obbligatorio inserire la quota B per la gestione " + codiceGestione;
                                return false;
                            }
                            if (settimane707 < settimaneB + settimaneD)
                            {
                                messaggioVideo = "Il campo Sett. 707 della quota B della gestione " + codiceGestione + " non può essere minore della somma delle settimane della quota B e delle settimane della quota D relative alla stessa gestione";
                                return false;
                            }
                        }
                    }
                    int CountQuoteD = lDatiContributivi != null ? lDatiContributivi.Where(x => x.IsQuotaDL214Presente()).Count() : 0;
                    if (ctrl != null && ctrl.ValoreControllo != "NO" && Utility.IsRicostituzione(datiPensione.Gruppo) &&
                        GestioneContrib.IsFineAssicurazionePost2012(datiPensione.FineAssicurazione) && CountQuoteD == 0 &&
                        !Utility.IsDomandaENPALS(datiPensione.Gestione) && !Utility.CheckMemo97(datiPensione))
                    {
                        messaggioVideo = "Per domande con data fine assicurazione pari o successiva al 01/01/2012 è necessario inserire la quota D";
                        return false;
                    }
                }

                if (lDatiRetributivi != null)
                    foreach (GestioneCalcolo.DatiCalcoloRetributivo retributivi in lDatiRetributivi)
                    {
                        if (retributivi.QuotePrimeLiquidate == 'A' && retributivi.NSettimane707.GetValueOrDefault() < retributivi.NSettimaneQuotaA.GetValueOrDefault())
                        {
                            messaggioVideo = "Mancanza di una quota D o incongruenza tra gli elementi di calcolo (registrazioni) presenti e la data di ultimo contributo";

                            if (Utility.IsRicostituzione(datiPensione.Gruppo))
                                messaggioVideo += " o mancanza di dati per il calcolo del comma 707.";
                            else
                                messaggioVideo += ".";
                            return false;
                        }

                        if (retributivi.NSettimane707.GetValueOrDefault() < retributivi.NSettimaneQuotaB.GetValueOrDefault())
                        {
                            messaggioVideo = "Le settimane 707 della quota B devono essere maggiori o uguali alle settimane della quota B.";
                            return false;
                        }
                    }

                if (Utility.IsDomandaINPDAI(datiPensione.SiglaCategoria))
                {
                    List<GestioneContrib.DatiRetributiviExInpdai> lstDatiRetrExInpdai = lDatiRetributivi.Select(x => new GestioneContrib.DatiRetributiviExInpdai(x, lstCtrlDecorrenza, lstDecGestioneCalcoloRetributivo)).ToList();

                    //(Oggetto mail 20160208: RE: LiqPens AGO - Doppio calcolo DAI)
                    //Controllo massimo inseribile delle settimane 707 per le differenti decorrenze: per 16,17,76,61,71 max=14400 per 21,31 max=720 per 41 max=2160 per 51,91 max=2080
                    foreach (var elem in lstDatiRetrExInpdai)
                    {
                        int maxValue = int.MaxValue;
                        int ggMMForRecord = elem.NSettimane707.GetValueOrDefault();
                        switch (elem.DecorrenzaExInpdai)
                        {
                            case 16:
                                if (!string.IsNullOrEmpty(tipoSettimaneBeneficio) && tipoSettimaneBeneficio == "04")
                                    maxValue = 5400;
                                else
                                    maxValue = 14400;
                                break;
                            case 17:
                            case 76:
                            case 61:
                            case 71:
                                maxValue = 14400;
                                break;
                            case 21:
                            case 31:
                                if (!string.IsNullOrEmpty(tipoSettimaneBeneficio) && tipoSettimaneBeneficio == "04")
                                    maxValue = 1080;
                                else
                                    maxValue = 720;
                                break;
                            case 41:
                                if (!string.IsNullOrEmpty(tipoSettimaneBeneficio) && tipoSettimaneBeneficio == "04")
                                    maxValue = 3240;
                                else
                                    maxValue = 2160;
                                break;
                            case 51:
                            case 91:
                                maxValue = 2080;
                                break;
                        }
                        if (ggMMForRecord > maxValue)
                        {
                            messaggioVideo = string.Format("Il valore dei Giorni / Settimane 707 inserito ({0}) per la decorrenza {1} supera il massimo valore consentito ({2}).", ggMMForRecord.ToString(), elem.DecorrenzaExInpdai.ToString(), maxValue.ToString());
                            return false;
                        }
                    }

                    if (lDatiContributivi != null && lDatiContributivi.Count > 0)
                    {
                        foreach (GestioneCalcolo.DatiCalcoloContributivo record in lDatiContributivi.FindAll(x => x.MontanteQuotaDL214.HasValue || x.ImportoContribTotaleQuotaDL214.HasValue || x.NSettimaneQuotaDL214.HasValue))
                        {
                            GestioneDecodifica.CodeGestioneCalcoloContributivo codeGestioneContributivoInserito = listaCodeGestioneCalcoloContributivo.Find(x => x.Id == record.CodiceGestione);
                            GestioneDecodifica.CodeGestioneCalcoloRetributivo codeGestioneRetributivo = listaCodeGestioneCalcoloRetributivo.Find(x => x.TraduzioneSuGP.Trim() == codeGestioneContributivoInserito.TraduzioneSuGP.Trim());

                            GestioneCalcolo.DatiCalcoloRetributivo recordRetributivo = null;
                            switch (codeGestioneContributivoInserito.TraduzioneSuGP.Trim())
                            {
                                case "A":
                                    if (lDatiRetributivi != null && lDatiRetributivi.Count > 0)
                                        recordRetributivo = lDatiRetributivi.Find(x => x.CodiceGestione == codeGestioneRetributivo.Id && x.QuotePrimeLiquidate == 'B' && x.CodiceTipoQuota == "B4");
                                    if (recordRetributivo == null)
                                    {
                                        messaggioVideo = "E' obbligatorio inserire la quota B con tipo quota B4 per la gestione A - INPDAI.";
                                        return false;
                                    }
                                    else
                                    {
                                        if (record.NSettimaneQuotaDL214.GetValueOrDefault() + recordRetributivo.NSettimaneQuotaB.GetValueOrDefault() > recordRetributivo.NSettimane707.GetValueOrDefault())
                                        {
                                            messaggioVideo = "Il campo Giorni / Settimane 707 della quota B con tipo quota B4 della gestione A - INPDAI non può essere minore della somma delle settimane della quota B con tipo quota B4 e delle settimane della quota D relative alla stessa gestione.";
                                            return false;
                                        }
                                    }
                                    break;
                                case "1":
                                case "2":
                                case "3":
                                case "4":
                                    if (lDatiRetributivi != null && lDatiRetributivi.Count > 0)
                                        recordRetributivo = lDatiRetributivi.Find(x => x.CodiceGestione == codeGestioneRetributivo.Id && x.QuotePrimeLiquidate == 'B' && x.CodiceTipoQuota == "B9");
                                    if (recordRetributivo == null)
                                    {
                                        messaggioVideo = "E' obbligatorio inserire la quota B con tipo quota B9 per la gestione " + codeGestioneRetributivo.TraduzioneSuGP + " - " + codeGestioneRetributivo.Descrizione + ".";
                                        return false;
                                    }
                                    else
                                    {
                                        if (record.NSettimaneQuotaDL214.GetValueOrDefault() + recordRetributivo.NSettimaneQuotaB.GetValueOrDefault() > recordRetributivo.NSettimane707.GetValueOrDefault())
                                        {
                                            messaggioVideo = "Il campo Giorni / Settimane 707 della quota B con tipo quota B9 della gestione " + codeGestioneRetributivo.TraduzioneSuGP + " - " + codeGestioneRetributivo.Descrizione + " non può essere minore della somma delle settimane della quota B con tipo quota B9 e delle settimane della quota D relative alla stessa gestione.";
                                            return false;
                                        }
                                    }
                                    break;
                            }
                        }
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// Verifica la correttenza del valore della Decorrenza Beneficio dei dati Calcolo Vittime Terrorismo
        /// </summary>
        /// <param name="datiPensione"></param>
        /// <param name="listaDatiCalcoloVittimeTerrorismo"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool ControlsDecorrenzaBeneficioVittimeTerrorismo(GestionePensione.DatiPensione datiPensione,
            List<GestioneCalcoloVittimeTerrorismo.DatiCalcoloVittimeTerrorismo> listaDatiCalcoloVittimeTerrorismo,
            GestioneBeneficioVittimeTerrorismo.DatiBeneficioVittimeTerrorismo datiBeneficioVittimeTerrorismo, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaPensioneReversibilitaOrRicostituzione(datiPensione, datiDanteCausa) && Utility.IsRicostituzione(datiPensione.Gruppo))
                return true;

            if (Utility.IsDomandaBeneficioTerrorismoOver80(datiPensione, datiBeneficioVittimeTerrorismo) || Utility.IsDomandaBeneficioTerrorismoUnder80(datiPensione, datiBeneficioVittimeTerrorismo))
            {
                if (listaDatiCalcoloVittimeTerrorismo != null && listaDatiCalcoloVittimeTerrorismo.Count() > 0)
                {
                    // Decorrenza beneficio: non può contenere una data precedente al mese di settembre 2004 ed, in ogni caso, 
                    // non può essere precedente la decorrenza della pensione.
                    if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'R') &&
                        (!Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2004, 9, 1)) || !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, datiPensione.DecorrenzaOriginaria.Value))))
                    {
                        messaggioVideo = string.Format("La Decorrenza Beneficio dei Dati Retributivi Vittime non può essere precedente al Settembre 2004 ed, in ogni caso, non può essere precedente alla Decorrenza Pensione {0:dd/MM/yyyy}",
                                                    datiPensione.DecorrenzaOriginaria);
                        return false;
                    }

                    // Decorrenza beneficio: non può contenere una data precedente al mese di settembre 2004 ed, in ogni caso, 
                    // non può essere precedente la decorrenza della pensione.
                    if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'C') &&
                        (!Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2004, 9, 1)) || !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, datiPensione.DecorrenzaOriginaria.Value))))
                    {
                        messaggioVideo = string.Format("La Decorrenza Beneficio dei Dati Contributivi Vittime non può essere precedente al Settembre 2004 ed, in ogni caso, non può essere precedente alla Decorrenza Pensione {0:dd/MM/yyyy}",
                                                    datiPensione.DecorrenzaOriginaria);
                        return false;
                    }

                    // Se campo soggetto beneficiario = Vittima (valore 3 al 1° byte e valore 5 al 3° byte del GP1AC01 e valore 2 al 2 byte del GP1AC02)
                    if (Utility.IsDomandaBeneficioTerrorismoUnder80(datiPensione, datiBeneficioVittimeTerrorismo) && datiBeneficioVittimeTerrorismo != null && datiBeneficioVittimeTerrorismo.SoggettoBeneficiario.GetValueOrDefault() == 2 &&
                        datiBeneficioVittimeTerrorismo.TipologiaPrestazione.GetValueOrDefault() == 3 && datiBeneficioVittimeTerrorismo.TipologiaBeneficio.GetValueOrDefault() == 5)
                    {
                        // Decorrenza beneficio: non può contenere una data precedente al mese di gennaio 2007 ed, in ogni caso, non può essere precedente la decorrenza della pensione. 
                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'I') &&
                            (!Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2007, 1, 1)) || !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, datiPensione.DecorrenzaOriginaria.Value))))
                        {
                            messaggioVideo = string.Format("La Decorrenza Beneficio dell'Importo Pensione Vittime non può essere precedente al Gennaio 2007 ed, in ogni caso, non può essere precedente alla Decorrenza Pensione {0:dd/MM/yyyy}",
                                                        datiPensione.DecorrenzaOriginaria);
                            return false;
                        }
                    }
                    else
                    {
                        // Decorrenza beneficio: non può contenere una data precedente al mese di gennaio 2008 ed, in ogni caso, non può essere precedente la decorrenza della pensione. 
                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'I') &&
                            (!Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2008, 1, 1)) || !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, datiPensione.DecorrenzaOriginaria.Value))))
                        {
                            messaggioVideo = string.Format("La Decorrenza Beneficio dell'Importo Pensione Vittime non può essere precedente al Gennaio 2008 ed, in ogni caso, non può essere precedente alla Decorrenza Pensione {0:dd/MM/yyyy}",
                                                        datiPensione.DecorrenzaOriginaria);
                            return false;
                        }
                    }

                    // Se campo “codice evento” è Estero (E al 2° byte del GP1AC01) e  campo “data evento” è precedente  al 1° gennaio 2003 la 
                    // “Decorrenza beneficio” non potrà essere anteriore al 1° gennaio 2008.
                    if (datiBeneficioVittimeTerrorismo != null && datiBeneficioVittimeTerrorismo.CodiceEvento.GetValueOrDefault() == 'E' && datiBeneficioVittimeTerrorismo.DataEventoTerroristico.HasValue &&
                        !Utility.DataSuccessivaA(datiBeneficioVittimeTerrorismo.DataEventoTerroristico.Value, new DateTime(2003, 1, 1)) &&
                        listaDatiCalcoloVittimeTerrorismo.Exists(x => !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2008, 1, 1))))
                    {
                        messaggioVideo = "La Decorrenza Beneficio non può essere antecedente a Gennaio 2008 se l'evento terroristico si è verificato all'Estero in data antecedente al Gennaio 2003.";
                        return false;
                    }

                    if (datiBeneficioVittimeTerrorismo != null && datiBeneficioVittimeTerrorismo.DataEventoTerroristico.HasValue &&
                        listaDatiCalcoloVittimeTerrorismo.Exists(x => !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, datiBeneficioVittimeTerrorismo.DataEventoTerroristico.Value)))
                    {
                        messaggioVideo = string.Format("La Decorrenza Beneficio non può essere antecedente alla Data Evento Terroristico ({0:dd/MM/yyyy}).", datiBeneficioVittimeTerrorismo.DataEventoTerroristico);
                        return false;
                    }
                }
            }

            return true;
        }

        /// <summary>
        /// Verifica la correttezza del valore del Beneficio dei dati Calcolo Vittime Terrorismo
        /// </summary>
        /// <param name="datiPensione"></param>
        /// <param name="listaDatiCalcoloVittimeTerrorismo"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool ControlsBeneficioTerrorismo(GestionePensione.DatiPensione datiPensione,
            List<GestioneCalcoloVittimeTerrorismo.DatiCalcoloVittimeTerrorismo> listaDatiCalcoloVittimeTerrorismo,
            GestioneBeneficioVittimeTerrorismo.DatiBeneficioVittimeTerrorismo datiBeneficioVittimeTerrorismo, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaBeneficioTerrorismoOver80(datiPensione, datiBeneficioVittimeTerrorismo) || Utility.IsDomandaBeneficioTerrorismoUnder80(datiPensione, datiBeneficioVittimeTerrorismo))
            {
                #region Scenario 1
                // Beneficio: può assumere i seguenti valori :
                // a)	Per decorrenza beneficio > 08/2004 e < 01/2007 il carattere W
                // b)	Per decorrenza beneficio > 12/2006 e < 01/2008  il carattere Y
                if (Utility.IsDomandaBeneficioTerrorismoOver80(datiPensione, datiBeneficioVittimeTerrorismo))
                {
                    if (listaDatiCalcoloVittimeTerrorismo != null && listaDatiCalcoloVittimeTerrorismo.Count > 0)
                    {
                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'R') && x.Beneficio != 'Y' && x.Beneficio != 'W' && x.Beneficio != 'Z'))
                        {
                            messaggioVideo = "Il Beneficio dei Dati Retributivi Vittime deve essere 'Y', 'W' o 'Z'.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'C') && x.Beneficio != 'Y' && x.Beneficio != 'W' && x.Beneficio != 'Z'))
                        {
                            messaggioVideo = "Il Beneficio dei Dati Contributivi Vittime deve essere 'Y', 'W' o 'Z'.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'R') &&
                            !(Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2004, 9, 1)) && !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2007, 1, 1))) &&
                            x.Beneficio == 'W'))
                        {
                            messaggioVideo = "Il Beneficio 'W' dei Dati Retributivi Vittime deve avere Decorrenza Beneficio > 08/2004 e < 01/2007.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'R') &&
                            !(Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2007, 1, 1)) && !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2008, 1, 1))) &&
                            x.Beneficio == 'Y'))
                        {
                            messaggioVideo = "Il Beneficio 'Y' dei Dati Retributivi Vittime deve avere Decorrenza Beneficio > 12/2006 e < 01/2008.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'R') &&
                            !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2008, 1, 1)) &&
                            x.Beneficio == 'Z'))
                        {
                            messaggioVideo = "Il Beneficio 'Z' dei Dati Retributivi Vittime deve avere Decorrenza Beneficio > 12/2007.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'C') &&
                            !(Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2004, 9, 1)) && !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2007, 1, 1))) &&
                            x.Beneficio == 'W'))
                        {
                            messaggioVideo = "Il Beneficio 'W' dei Dati Contributivi Vittime deve avere Decorrenza Beneficio > 08/2004 e < 01/2007.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'C') &&
                            !(Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2007, 1, 1)) && !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2008, 1, 1))) &&
                            x.Beneficio == 'Y'))
                        {
                            messaggioVideo = "Il Beneficio 'Y' dei Dati Contributivi Vittime deve avere Decorrenza Beneficio > 12/2006 e < 01/2008.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'C') &&
                            !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2008, 1, 1)) &&
                            x.Beneficio == 'Z'))
                        {
                            messaggioVideo = "Il Beneficio 'Z' dei Dati Contributivi Vittime deve avere Decorrenza Beneficio > 12/2007.";
                            return false;
                        }
                    }
                }
                #endregion Scenario 1

                #region Scenario 2: Coniuge, Figlio, Genitore
                // Se soggetto beneficiario = Coniuge, Figlio, Genitore (valore 2 al 1° byte e valore 2 al 3° byte del GP1AC01)
                if (Utility.IsDomandaBeneficioTerrorismoUnder80(datiPensione, datiBeneficioVittimeTerrorismo) && datiBeneficioVittimeTerrorismo != null &&
                    (datiBeneficioVittimeTerrorismo.SoggettoBeneficiario.GetValueOrDefault() == 5 || datiBeneficioVittimeTerrorismo.SoggettoBeneficiario.GetValueOrDefault() == 6 ||
                                datiBeneficioVittimeTerrorismo.SoggettoBeneficiario.GetValueOrDefault() == 8) &&
                    datiBeneficioVittimeTerrorismo.TipologiaPrestazione.GetValueOrDefault() == 2 && datiBeneficioVittimeTerrorismo.TipologiaBeneficio.GetValueOrDefault() == 2)
                {
                    if (listaDatiCalcoloVittimeTerrorismo != null && listaDatiCalcoloVittimeTerrorismo.Count > 0)
                    {
                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'C') && x.Beneficio != 'Y'))
                        {
                            messaggioVideo = "Il Beneficio dei Dati Contributivi Vittime deve essere 'Y'.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'R') && x.Beneficio != 'Y'))
                        {
                            messaggioVideo = "Il Beneficio dei Dati Retributivi Vittime deve essere 'Y'.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'R') &&
                            !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2007, 1, 1)) &&
                            x.Beneficio == 'Y'))
                        {
                            messaggioVideo = "Il Beneficio 'Y' dei Dati Retributivi Vittime deve avere Decorrenza Beneficio > 12/2006.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'C') &&
                            !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2007, 1, 1)) &&
                            x.Beneficio == 'Y'))
                        {
                            messaggioVideo = "Il Beneficio 'Y' dei Dati Contributivi Vittime deve avere Decorrenza Beneficio > 12/2006.";
                            return false;
                        }
                    }
                }
                #endregion Scenario 2: Coniuge, Figlio, Genitore

                #region Scenario 2: Vittima (valore 3 al 1° byte e valore 5 al 3° byte del GP1AC01 e valore 2 al 2 byte del GP1AC02)
                // Se campo soggetto beneficiario = Vittima (valore 3 al 1° byte e valore 5 al 3° byte del GP1AC01 e valore 2 al 2 byte del GP1AC02)
                if (Utility.IsDomandaBeneficioTerrorismoUnder80(datiPensione, datiBeneficioVittimeTerrorismo) && datiBeneficioVittimeTerrorismo != null && datiBeneficioVittimeTerrorismo.SoggettoBeneficiario.GetValueOrDefault() == 2 &&
                    datiBeneficioVittimeTerrorismo.TipologiaPrestazione.GetValueOrDefault() == 3 && datiBeneficioVittimeTerrorismo.TipologiaBeneficio.GetValueOrDefault() == 5)
                {
                    if (listaDatiCalcoloVittimeTerrorismo != null && listaDatiCalcoloVittimeTerrorismo.Count > 0)
                    {
                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'R') && x.Beneficio != 'W'))
                        {
                            messaggioVideo = "Il Beneficio dei Dati Retributivi Vittime deve essere 'W'.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'C') && x.Beneficio != 'W'))
                        {
                            messaggioVideo = "Il Beneficio dei Dati Contributivi Vittime deve essere 'W'.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'I') && x.Beneficio != 'X'))
                        {
                            messaggioVideo = "Il Beneficio dei Dati Importo Pensione Vittime deve essere 'X'.";
                            return false;
