                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'C') && x.Beneficio != 'W' && x.Beneficio != 'Y'))
                        {
                            messaggioVideo = "Il Beneficio dei Dati Contributivi Vittime deve essere 'W' o 'Y'.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'R') &&
                            !(Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2004, 9, 1)) && !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2007, 1, 1)) && datiBeneficioVittimeTerrorismo.TipologiaBeneficio.GetValueOrDefault() == 1) &&
                            x.Beneficio == 'W'))
                        {
                            messaggioVideo = "Il Beneficio 'W' dei Dati Retributivi Vittime deve avere Decorrenza Beneficio > 08/2004 e < 01/2007 e la 1° Tipologia del Beneficio.";
