                            messaggioVideo = "Il Beneficio 'Y' dei Dati Contributivi Vittime deve avere Decorrenza Beneficio > 12/2006 e la 2° Tipologia del Beneficio.";
                            return false;
                        }
                    }
                }
                #endregion Scenario 2: Vittima (valore 1 al 2° byte del GP1AC02, valore 2 al 1° byte del GP1AC01 e valore 1 oppure 2 al 3° byte del GP1AC01)

                #region Scenario 2: Coniuge/vedovo, Figlio/orfano (valore 2 al 1° byte e valore 3 al 3° byte del GP1AC01)
                // Se campo soggetto beneficiario = Coniuge/vedovo, Figlio/orfano  (valore 2 al 1° byte e valore 3 al 3° byte del GP1AC01)
                if (Utility.IsDomandaBeneficioTerrorismoUnder80(datiPensione, datiBeneficioVittimeTerrorismo) && datiBeneficioVittimeTerrorismo != null &&
                    (datiBeneficioVittimeTerrorismo.SoggettoBeneficiario.GetValueOrDefault() == 4 || datiBeneficioVittimeTerrorismo.SoggettoBeneficiario.GetValueOrDefault() == 7) &&
                    datiBeneficioVittimeTerrorismo.TipologiaPrestazione.GetValueOrDefault() == 2 && datiBeneficioVittimeTerrorismo.TipologiaBeneficio.GetValueOrDefault() == 3)
                {
                    if (listaDatiCalcoloVittimeTerrorismo != null && listaDatiCalcoloVittimeTerrorismo.Count > 0)
                    {
                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'C') && x.Beneficio != 'Y' && x.Beneficio != 'W'))
                        {
                            messaggioVideo = "Il Beneficio dei Dati Contributivi Vittime deve essere 'Y' o 'W'.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'R') && x.Beneficio != 'Y' && x.Beneficio != 'W'))
                        {
                            messaggioVideo = "Il Beneficio dei Dati Retributivi Vittime deve essere 'Y' o 'W'.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'R') &&
                            !(Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2004, 9, 1)) && !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2007, 1, 1))) &&
                            x.Beneficio == 'W'))
                        {
                            messaggioVideo = "Il Beneficio 'W' dei Dati Retributivi Vittime deve avere Decorrenza Beneficio > 08/2004 e < 01/2007.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'R') &&
                            !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2007, 1, 1)) &&
                            x.Beneficio == 'Y'))
                        {
                            messaggioVideo = "Il Beneficio 'Y' dei Dati Retributivi Vittime deve avere Decorrenza Beneficio > 12/2006.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'C') &&
                            !(Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2004, 9, 1)) && !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2007, 1, 1))) &&
                            x.Beneficio == 'W'))
                        {
                            messaggioVideo = "Il Beneficio 'W' dei Dati Contributivi Vittime deve avere Decorrenza Beneficio > 08/2004 e < 01/2007.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'C') &&
                            !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2007, 1, 1)) &&
                            x.Beneficio == 'Y'))
                        {
                            messaggioVideo = "Il Beneficio 'Y' dei Dati Contributivi Vittime deve avere Decorrenza Beneficio > 12/2006.";
                            return false;
                        }
                    }
                }
                #endregion Scenario 2: Coniuge/vedovo, Figlio/orfano (valore 2 al 1° byte e valore 3 al 3° byte del GP1AC01)

                #region Scenario 2: Coniuge/vedovo, Figlio/orfano (valore 2 al 1° byte e valore 2 al 3° byte del GP1AC01)
                // Se soggetto beneficiario Coniuge/vedovo, Figlio/orfano  (valore 2 al 1° byte e valore 2 al 3° byte del GP1AC01)
                if (Utility.IsDomandaBeneficioTerrorismoUnder80(datiPensione, datiBeneficioVittimeTerrorismo) && datiBeneficioVittimeTerrorismo != null &&
                    (datiBeneficioVittimeTerrorismo.SoggettoBeneficiario.GetValueOrDefault() == 4 || datiBeneficioVittimeTerrorismo.SoggettoBeneficiario.GetValueOrDefault() == 7) &&
                    datiBeneficioVittimeTerrorismo.TipologiaPrestazione.GetValueOrDefault() == 2 && datiBeneficioVittimeTerrorismo.TipologiaBeneficio.GetValueOrDefault() == 2)
                {
                    if (listaDatiCalcoloVittimeTerrorismo != null && listaDatiCalcoloVittimeTerrorismo.Count > 0)
                    {
                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'C') && x.Beneficio != 'Y'))
                        {
                            messaggioVideo = "Il Beneficio dei Dati Contributivi Vittime deve essere 'Y'.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'R') && x.Beneficio != 'Y'))
                        {
                            messaggioVideo = "Il Beneficio dei Dati Retributivi Vittime deve essere 'Y'.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'R') &&
                            !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2007, 1, 1)) &&
                            x.Beneficio == 'Y'))
                        {
                            messaggioVideo = "Il Beneficio 'Y' dei Dati Retributivi Vittime deve avere Decorrenza Beneficio > 12/2006.";
                            return false;
                        }

                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'C') &&
                            !Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2007, 1, 1)) &&
                            x.Beneficio == 'Y'))
                        {
                            messaggioVideo = "Il Beneficio 'Y' dei Dati Contributivi Vittime deve avere Decorrenza Beneficio > 12/2006.";
                            return false;
                        }
                    }
                }
                #endregion Scenario 2: Coniuge/vedovo, Figlio/orfano (valore 2 al 1° byte e valore 2 al 3° byte del GP1AC01)

                // Tutti tranne Scenario 2: Vittima
                if (!(Utility.IsDomandaBeneficioTerrorismoUnder80(datiPensione, datiBeneficioVittimeTerrorismo) && datiBeneficioVittimeTerrorismo != null && datiBeneficioVittimeTerrorismo.SoggettoBeneficiario.GetValueOrDefault() == 2 &&
                    datiBeneficioVittimeTerrorismo.TipologiaPrestazione.GetValueOrDefault() == 3 && datiBeneficioVittimeTerrorismo.TipologiaBeneficio.GetValueOrDefault() == 5))
                {
                    if (listaDatiCalcoloVittimeTerrorismo != null && listaDatiCalcoloVittimeTerrorismo.Count > 0)
                    {
                        // Beneficio - Importo Pensione: può assumere il valore 'Z'
                        if (listaDatiCalcoloVittimeTerrorismo.Exists(x => (x.Tipo == 'I') && x.Beneficio != 'Z'))
                        {
                            messaggioVideo = "Il Beneficio dell'Importo Pensione Vittime deve essere 'Z'.";
                            return false;
                        }
                    }
                }
            }

            return true;
        }

        public static bool ControlsDatiCalcoloWithBeneficioTerrorismo(GestionePensione.DatiPensione datiPensione,
            List<GestioneCalcoloVittimeTerrorismo.DatiCalcoloVittimeTerrorismo> listaDatiCalcoloVittimeTerrorismo, List<GestioneCalcolo.DatiCalcoloRetributivo> listaDatiCalcoloRetributivo,
            List<GestioneCalcolo.DatiCalcoloContributivo> listaDatiCalcoloContributivo, List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> listaCodeGestioneCalcoloRetributivo,
            List<GestioneDecodifica.CodeGestioneCalcoloContributivo> listaCodeGestioneCalcoloContributivo, GestioneBeneficioVittimeTerrorismo.DatiBeneficioVittimeTerrorismo datiBeneficioVittimeTerrorismo,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaBeneficioTerrorismoOver80(datiPensione, datiBeneficioVittimeTerrorismo) || Utility.IsDomandaBeneficioTerrorismoUnder80(datiPensione, datiBeneficioVittimeTerrorismo))
            {
                if (Utility.IsDomandaBeneficioTerrorismoOver80(datiPensione, datiBeneficioVittimeTerrorismo) ||
                    (datiBeneficioVittimeTerrorismo != null && datiBeneficioVittimeTerrorismo.TipologiaPrestazione == 3 && datiBeneficioVittimeTerrorismo.TipologiaBeneficio == 6 &&
                    datiBeneficioVittimeTerrorismo.SoggettoBeneficiario == 2))
                {
                    // Se nel campo “Beneficio” è presente il valore W o Y il totale del numero di settimane non può superare 2080 contributi settimanali fra tutte le gestioni, 
                    // per decorrenze pensioni anteriori a 01/2012.
                    if (!Utility.DataSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, new DateTime(2012, 1, 1)) && listaDatiCalcoloVittimeTerrorismo != null &&
                        listaDatiCalcoloVittimeTerrorismo.Count > 0 && listaDatiCalcoloVittimeTerrorismo.Exists(x => x.Beneficio == 'W' || x.Beneficio == 'Y'))
                    {
                        int sommaSettRetr = listaDatiCalcoloRetributivo != null ?
                            (listaDatiCalcoloRetributivo.Sum(x => x.NSettimaneQuotaA.GetValueOrDefault()) + listaDatiCalcoloRetributivo.Sum(x => x.NSettimaneQuotaB.GetValueOrDefault())) : 0;
                        int sommaSettContr = listaDatiCalcoloContributivo != null ?
                            (listaDatiCalcoloContributivo.Sum(x => x.NSettimane.GetValueOrDefault()) + listaDatiCalcoloContributivo.Sum(x => x.NSettimaneQuotaDL214.GetValueOrDefault())) : 0;

                        if (sommaSettRetr + sommaSettContr > 2080)
                        {
                            messaggioVideo = "La somma dei contributi settimanali fra tutte le gestioni non può superare 2080.";
                            return false;
                        }
                    }
                }

                if (listaDatiCalcoloVittimeTerrorismo != null && listaDatiCalcoloVittimeTerrorismo.Count > 0)
                {
                    List<string> codGestioneDatiVittimeTraduzioneSuGP = new List<string>();
                    List<GestioneCalcoloVittimeTerrorismo.DatiCalcoloVittimeTerrorismo> listaApp = new List<GestioneCalcoloVittimeTerrorismo.DatiCalcoloVittimeTerrorismo>();
                    listaApp = listaDatiCalcoloVittimeTerrorismo.FindAll(x => x.CodiceGestioneRetr.HasValue && x.Tipo.GetValueOrDefault() == 'R');
                    if (listaApp.Count > 0)
                    {
                        var a = (from e in listaApp
                                 select e.CodiceGestioneRetr).Distinct();
                        var b = (from e in listaCodeGestioneCalcoloRetributivo
                                 where a.Contains(e.Id)
                                 select "'" + e.TraduzioneSuGP.Trim() + " - " + e.Descrizione.Trim() + "'");

                        codGestioneDatiVittimeTraduzioneSuGP.AddRange(b);
                    }

                    listaApp = listaDatiCalcoloVittimeTerrorismo.FindAll(x => x.CodiceGestioneContr.HasValue && x.Tipo.GetValueOrDefault() == 'C');
                    if (listaApp.Count > 0)
                    {
                        var a = (from e in listaApp
                                 select e.CodiceGestioneContr).Distinct();
                        var b = (from e in listaCodeGestioneCalcoloContributivo
                                 where a.Contains(e.Id)
                                 select "'" + e.TraduzioneSuGP.Trim() + " - " + e.Descrizione.Trim() + "'");

                        codGestioneDatiVittimeTraduzioneSuGP.AddRange(b.Except(codGestioneDatiVittimeTraduzioneSuGP));
                    }

                    List<string> codGestioneDatiCalcoloTraduzioneSuGP = new List<string>();
                    if (listaDatiCalcoloRetributivo != null && listaDatiCalcoloRetributivo.Count > 0)
                    {
                        var a = (from e in listaDatiCalcoloRetributivo
                                 select e.CodiceGestione).Distinct();
                        var b = (from e in listaCodeGestioneCalcoloRetributivo
                                 where a.Contains(e.Id)
                                 select "'" + e.TraduzioneSuGP.Trim() + " - " + e.Descrizione.Trim() + "'");

                        codGestioneDatiCalcoloTraduzioneSuGP.AddRange(b);
                    }

                    if (listaDatiCalcoloContributivo != null && listaDatiCalcoloContributivo.Count > 0)
                    {
                        var a = (from e in listaDatiCalcoloContributivo
                                 select e.CodiceGestione).Distinct();
                        var b = (from e in listaCodeGestioneCalcoloContributivo
                                 where a.Contains(e.Id)
                                 select "'" + e.TraduzioneSuGP.Trim() + " - " + e.Descrizione.Trim() + "'").ToList();

                        codGestioneDatiCalcoloTraduzioneSuGP.AddRange(b.Except(codGestioneDatiCalcoloTraduzioneSuGP));
                    }

                    codGestioneDatiVittimeTraduzioneSuGP.Sort();
                    codGestioneDatiVittimeTraduzioneSuGP.RemoveAll(x => codGestioneDatiCalcoloTraduzioneSuGP.Contains(x));
                    if (codGestioneDatiVittimeTraduzioneSuGP.Count > 0)
                    {
                        messaggioVideo = "Non è possibile acquisire i dati Retributivi e/o Contributivi Vittime con i seguenti codici gestione: " + string.Join(", ", codGestioneDatiVittimeTraduzioneSuGP.ToArray());
                        return false;
                    }
                }
            }

            return true;
        }

        public static bool ControlsDatiCalcoloVittimeTerrorismoWithVisibility(GestionePensione.DatiPensione datiPensione, List<GestioneCalcolo.DatiCalcoloContributivo> lDatiCalcoloContributivo,
            List<GestioneCalcoloVittimeTerrorismo.DatiCalcoloVittimeTerrorismo> listaDatiCalcoloVittimeTerrorismo,
            GestioneBeneficioVittimeTerrorismo.DatiBeneficioVittimeTerrorismo datiBeneficioVittimeTerrorismo, Utility.TipoCalcolo tipoCalcolo, long? soggettoBeneficiario, long? tipologiaPrestazione,
            long? tipologiaBeneficio, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (listaDatiCalcoloVittimeTerrorismo != null && listaDatiCalcoloVittimeTerrorismo.Count > 0)
            {
                if (!Utility.IsDatiRetributiviVittimeVisible(datiPensione, datiBeneficioVittimeTerrorismo, tipoCalcolo) &&
                    listaDatiCalcoloVittimeTerrorismo.Exists(x => x.Tipo == 'R'))
                {
                    messaggioVideo = "Non è possibile acquisire i Dati Retributivi Vittime.";
                    return false;
                }

                if (!Utility.IsDatiContributiviVittimeVisible(datiPensione, datiBeneficioVittimeTerrorismo, tipoCalcolo, lDatiCalcoloContributivo != null && lDatiCalcoloContributivo.Exists(x => x.IsQuotaDL214Presente())) &&
                    listaDatiCalcoloVittimeTerrorismo.Exists(x => x.Tipo == 'C'))
                {
                    messaggioVideo = "Non è possibile acquisire i Dati Contributivi Vittime.";
                    return false;
                }

                if (!Utility.IsDatiImportoPensioneVittimeVisible(datiPensione, soggettoBeneficiario, tipologiaPrestazione, tipologiaBeneficio) &&
                    listaDatiCalcoloVittimeTerrorismo.Exists(x => x.Tipo == 'I'))
                {
                    messaggioVideo = "Non è possibile acquisire i dati Importo Pensione Vittime se il Soggetto Beneficiario è diverso da Vittima.";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsCoerenzaDatiCalcoloVittimeTerrorismo(GestionePensione.DatiPensione datiPensione, List<GestioneCalcoloVittimeTerrorismo.DatiCalcoloVittimeTerrorismo> listaDatiCalcoloVittimeTerrorismo,
            GestioneBeneficioVittimeTerrorismo.DatiBeneficioVittimeTerrorismo datiBeneficioVittimeTerrorismo, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (listaDatiCalcoloVittimeTerrorismo != null && listaDatiCalcoloVittimeTerrorismo.Count > 0)
            {
                #region Scenario 1
                if (Utility.IsDomandaBeneficioTerrorismoOver80(datiPensione, datiBeneficioVittimeTerrorismo))
                {
                    // Se esiste un record di "Importo Pensione Vittime" con decorrenza maggiore o uguale al 01/2008 allora non devono essere presenti record aggiuntivi 
                    // dei Dati Retributivi e Contributivi Vittime Terrorismo
                    if (listaDatiCalcoloVittimeTerrorismo.Exists(x => x.Tipo == 'I' && x.DecorrenzaBeneficio.HasValue && Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2008, 1, 1))) &&
                        listaDatiCalcoloVittimeTerrorismo.Exists(x => x.Tipo == 'R' || x.Tipo == 'C'))
                    {
                        messaggioVideo = "Non è possibile acquisire record di Dati Retributivi e Contributivi.";
                        return false;
                    }
                }
                #endregion Scenario 1

                #region Scenario 2: Vittima (valore 3 al 1° byte e valore 5 al 3° byte del GP1AC01 e valore 2 al 2 byte del GP1AC02)
                // Se campo soggetto beneficiario = Vittima (valore 3 al 1° byte e valore 5 al 3° byte del GP1AC01 e valore 2 al 2 byte del GP1AC02)
                if (Utility.IsDomandaBeneficioTerrorismoUnder80(datiPensione, datiBeneficioVittimeTerrorismo) && datiBeneficioVittimeTerrorismo != null && datiBeneficioVittimeTerrorismo.SoggettoBeneficiario.GetValueOrDefault() == 2 &&
                    datiBeneficioVittimeTerrorismo.TipologiaPrestazione.GetValueOrDefault() == 3 && datiBeneficioVittimeTerrorismo.TipologiaBeneficio.GetValueOrDefault() == 5)
                {
                    // Se esiste un record di "Importo Pensione Vittime" con decorrenza maggiore o uguale al 01/2007 allora non devono essere presenti record aggiuntivi 
                    // dei Dati Retributivi e Contributivi Vittime Terrorismo
                    if (listaDatiCalcoloVittimeTerrorismo.Exists(x => x.Tipo == 'I' && x.DecorrenzaBeneficio.HasValue && Utility.DataSuccessivaA(x.DecorrenzaBeneficio.Value, new DateTime(2007, 1, 1))) &&
                        listaDatiCalcoloVittimeTerrorismo.Exists(x => x.Tipo == 'R' || x.Tipo == 'C'))
                    {
                        messaggioVideo = "Non è possibile acquisire record di Dati Retributivi e Contributivi.";
                        return false;
                    }
                }

                #endregion Scenario 2: Vittima (valore 3 al 1° byte e valore 5 al 3° byte del GP1AC01 e valore 2 al 2 byte del GP1AC02)
            }

            return true;
        }

        public static bool ControlsDatiCalcoloVittimeTerrorismoINPDAI(GestionePensione.DatiPensione datiPensione, List<GestioneCalcoloVittimeTerrorismo.DatiCalcoloVittimeTerrorismo> listaDatiCalcoloVittimeTerrorismo,
            List<GestioneCalcolo.DatiCalcoloRetributivo> lDatiCalcoloRetributivo, List<GestioneCalcolo.DatiCalcoloContributivo> lDatiCalcoloContributivo,
            GestioneBeneficioVittimeTerrorismo.DatiBeneficioVittimeTerrorismo datiBeneficioVittimeTerrorismo, List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> listaDecodificaCalcoloRetributivo,
            List<GestioneDecodifica.CodeGestioneCalcoloContributivo> listaDecodificaCalcoloContributivo, List<CtrlDecorrenzaRetrExINPDAI> listaCtrlDecorrenzaRetrExINPDAI,
            string tipoSettimaneBeneficio, Utility.TipoCalcolo tipoCalcolo, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!(Utility.IsDomandaINPDAI(datiPensione.SiglaCategoria) && (Utility.IsDomandaBeneficioTerrorismoOver80(datiPensione, datiBeneficioVittimeTerrorismo) || Utility.IsDomandaBeneficioTerrorismoUnder80(datiPensione, datiBeneficioVittimeTerrorismo))))
                return true;

            decimal coefNormSettInGG = 6.9231M;
            decimal maxGGConsentiti = 14400M;

            if (listaDatiCalcoloVittimeTerrorismo != null && listaDatiCalcoloVittimeTerrorismo.Count > 0)
            {
                #region Controlli Dati Retributivi
                if (listaDatiCalcoloVittimeTerrorismo.Any(x => x.Tipo == 'R'))
                {
                    List<GestioneContrib.DatiRetributiviExInpdai> lstDatiRetrExInpdai = new List<GestioneContrib.DatiRetributiviExInpdai>();
                    List<GestioneContrib.DatiRetributiviExInpdai> lstDatiRetrApp = lDatiCalcoloRetributivo.Select(x => new GestioneContrib.DatiRetributiviExInpdai(x, listaCtrlDecorrenzaRetrExINPDAI, listaDecodificaCalcoloRetributivo)).ToList();
                    List<GestioneContrib.DatiRetributiviExInpdai> lstDatiRetrVittimeApp = listaDatiCalcoloVittimeTerrorismo.Where(x => x.Tipo == 'R').Select(x => new GestioneContrib.DatiRetributiviExInpdai(x, listaCtrlDecorrenzaRetrExINPDAI, listaDecodificaCalcoloRetributivo)).ToList();

                    foreach (GestioneContrib.DatiRetributiviExInpdai app in lstDatiRetrApp)
                    {
                        if (lstDatiRetrVittimeApp.Exists(x => x.CodGestione == app.CodGestione && x.Quota == app.Quota && x.CodiceTipoQuota == app.CodiceTipoQuota))
                            lstDatiRetrExInpdai.Add(lstDatiRetrVittimeApp.FirstOrDefault(x => x.CodGestione == app.CodGestione && x.Quota == app.Quota && x.CodiceTipoQuota == app.CodiceTipoQuota));
                        else
                            lstDatiRetrExInpdai.Add(app);
                    }


                    if (lstDatiRetrExInpdai.Exists(x => x.DecorrenzaExInpdai.GetValueOrDefault() == 0))
                    {
                        GestioneContrib.DatiRetributiviExInpdai app = lstDatiRetrExInpdai.Find(x => x.DecorrenzaExInpdai.GetValueOrDefault() == 0);
                        messaggioVideo = "La terna Gestione '" + app.DecCodGestione + "', Quota '" + app.Quota + "' e Tipo Quota '" + app.CodiceTipoQuota + "' non è valida.";
                        return false;
                    }

                    //Controllo 1  
                    //Il primo record presente nella griglia dei dati retributivi deve essere  bloccato con codice Gestione A e Quota A. (Valorizzazione decorrenza: MM/AAAA)
                    GestioneContrib.DatiRetributiviExInpdai firstElem = lstDatiRetrExInpdai.FirstOrDefault();
                    if (firstElem == null)
                    {
                        messaggioVideo = "Il primo record deve essere valorizzato.";
                        return false;
                    }
                    else if (firstElem.DecCodGestione != "A" && firstElem.DecCodGestione != "S")
                    {
                        messaggioVideo = "Codice gestione " + firstElem.DecCodGestione + " non ammesso per il primo record.";
                        return false;
                    }
                    //controllo che siano corretti i record successivi al primo 
                    if (lstDatiRetrExInpdai.Count > 1 &&
                        lstDatiRetrExInpdai.GetRange(1, lstDatiRetrExInpdai.Count - 1).Exists(x => (x.DecCodGestione != "A" && x.DecCodGestione != "1" && x.DecCodGestione != "2" && x.DecCodGestione != "3" && x.DecCodGestione != "4")))
                    {
                        messaggioVideo = "Codice Gestione non ammesso.";
                        return false;
                    }

                    //Controllo 3 
                    //Per tutti i codiceGestione i campi Quota, Giorni e Retribuzione sono obbligatori. Se la quota = B allora anche TipoQuota è obbligatorio
                    foreach (var elem in lstDatiRetrExInpdai)
                    {
                        if (elem.CodGestione == null || elem.Quota == null)
                        {
                            messaggioVideo = "Codice Gestioni e Quota per i dati retributivi sono campi obbligatori.";
                        }
                        switch (elem.Quota)
                        {
                            case 'A':
                                if (!elem.SettimaneA.HasValue || !elem.RMSQuotaA.HasValue)
                                {
                                    messaggioVideo = "Per la quota 'A' la 'Reddito'/'Retribuzione media' e 'Settimane'/'Giorni' sono dati obbligatori.";
                                    return false;
                                }
                                break;
                            case 'B':
                                if (!elem.SettimaneB.HasValue || !elem.RMSQuotaB.HasValue || string.IsNullOrEmpty(elem.CodiceTipoQuota))
                                {
                                    messaggioVideo = "Per la quota 'B' la 'Reddito'/'Retribuzione media', 'Settimane'/'Giorni' e 'Tipo Quota' sono dati obbligatori.";
                                    return false;
                                }
                                break;
                        }
                    }
                    //Controllo 5
                    //Verificare che se ci stanno 2 record con Quota = A appartenti al periodo precedente 31.12.1992 (quota = A) allora tali quote dovranno avere lo steso RM
                    // Ad eccezione della quota fittizia
                    List<GestioneContrib.DatiRetributiviExInpdai> lstAnte93QuotaA = lstDatiRetrExInpdai.Where(x => x.DecCodGestione == "A" && x.Quota == 'A' && (x.SettimaneA.GetValueOrDefault() != 1
                            || x.RMSQuotaA.GetValueOrDefault() > 0.004M)).ToList();
                    if (lstAnte93QuotaA.Count > 1 && (lstAnte93QuotaA[0].RMSQuotaA != lstAnte93QuotaA[1].RMSQuotaA))
                    {
                        messaggioVideo = "Se presenti più record per quota 'A' gestione 'A' con periodo precedente al 31-12-1992 devono avere la stessa 'Retribuzione Media'.";
                        return false;
                    }
                    //Controllo 6
                    //Verificare che se ci stanno 2 record con Quota = B appartenti al periodo precedente 31.12.2002 (quota = A) allora tali quote dovranno avere lo steso RM
                    List<GestioneContrib.DatiRetributiviExInpdai> lstAnte2002QuotaBGestioneA = lstDatiRetrExInpdai.Where(x => x.DecCodGestione == "A" && x.Quota == 'B' && x.CodiceTipoQuota != "B4").ToList();
                    if (lstAnte2002QuotaBGestioneA.Count > 1)
                    {
                        decimal? rms = lstAnte2002QuotaBGestioneA[0].RMSQuotaB;
                        for (int i = 1; i < lstAnte2002QuotaBGestioneA.Count; i++)
                        {
                            if (rms != lstAnte2002QuotaBGestioneA[i].RMSQuotaB)
                            {
                                messaggioVideo = "Se presenti più record per quota 'B' gestione 'A' precedenti al 31-12-2002 devono avere la stessa 'Retribuzione Media Giornaliera'.";
                                return false;
                            }
                        }

                    }

                    GestioneContrib.DatiRetributiviExInpdai quota76 = lstDatiRetrExInpdai.Where(x => x.DecCodGestione == "A" && x.Quota == 'A' && x.CodiceTipoQuota == "A1").FirstOrDefault();
                    if (quota76 != null)
                    {
                        if (quota76.SettimaneA > 1 && quota76.RMSQuotaA <= 0.004M)
                        {
                            messaggioVideo = "Attenzione per valori di “RMS / RMG” inferiori o uguali a 0,0040 il numero di “Giorni / Settimane” ammissibili è 1.";
                            return false;
                        }
                    }

                    var lstSenzaQuotaFittizia = lstDatiRetrExInpdai.Where(x => x.SettimaneA.GetValueOrDefault() + x.SettimaneB.GetValueOrDefault() != 1
                            || x.RMSQuotaA.GetValueOrDefault() + x.RMSQuotaB.GetValueOrDefault() > 0.004M).ToList();

                    //(Oggetto mail 20151118: LIQPENS - analisi DAI)
                    //Controllo massimo inseribile per le differenti decorrenze: per 16,17,76,61,71 max=14400 per 21,31 max=720 per 41 max=2160 per 51,91 max=2080
                    foreach (var elem in lstDatiRetrExInpdai)
                    {
                        int maxValue = int.MaxValue;
                        int ggMMForRecord = elem.SettimaneA.GetValueOrDefault() + elem.SettimaneB.GetValueOrDefault();
                        GestioneCalcoloVittimeTerrorismo.DatiCalcoloVittimeTerrorismo datiCalcoloVittimeApp = listaDatiCalcoloVittimeTerrorismo.Where(x => x.Tipo == 'R' && x.CodiceGestioneRetr == elem.CodGestione && x.CodiceTipoQuota == elem.CodiceTipoQuota && x.Quota == elem.Quota).FirstOrDefault();
                        switch (elem.DecorrenzaExInpdai)
                        {
                            case 16:
                                if (!string.IsNullOrEmpty(tipoSettimaneBeneficio) && tipoSettimaneBeneficio == "04")
                                {
                                    if (tipoCalcolo == Utility.TipoCalcolo.Misto)
                                        maxValue = 1620;
                                    else if (tipoCalcolo == Utility.TipoCalcolo.Retributivo)
                                        maxValue = 5400;
                                }
                                else
                                {
                                    if (tipoCalcolo == Utility.TipoCalcolo.Misto)
                                        maxValue = 1080;
                                    else if (tipoCalcolo == Utility.TipoCalcolo.Retributivo)
                                        maxValue = 3600;
                                }
                                break;
                            case 17:
                            case 76:
                            case 61:
                            case 71:
                                maxValue = 14400;
                                break;
                            case 21:
                            case 31:
                                if (!(Utility.IsDomandaVDAI(datiPensione.SiglaCategoria) && datiCalcoloVittimeApp != null && new List<char> { 'Y', 'W' }.Contains(datiCalcoloVittimeApp.Beneficio.Value)))
                                {
                                    if (!string.IsNullOrEmpty(tipoSettimaneBeneficio) && tipoSettimaneBeneficio == "04")
                                        maxValue = 1080;
                                    else
                                        maxValue = 720;
                                }
                                break;
                            case 41:
                                if (!(Utility.IsDomandaVDAI(datiPensione.SiglaCategoria) && datiCalcoloVittimeApp != null && new List<char> { 'Y', 'W' }.Contains(datiCalcoloVittimeApp.Beneficio.Value)))
                                {
                                    if (!string.IsNullOrEmpty(tipoSettimaneBeneficio) && tipoSettimaneBeneficio == "04")
                                        maxValue = 3240;
                                    else
                                        maxValue = 2160;
                                }
                                break;
                            case 51:
                            case 91:
                                maxValue = 2080;
                                break;
                        }
                        if (ggMMForRecord > maxValue)
                        {
                            messaggioVideo = string.Format("Il valore inserito ({0}) per la decorrenza {1}  supera il massimo valore consentito ({2}).", ggMMForRecord.ToString(), elem.DecorrenzaExInpdai.ToString(), maxValue.ToString());
                            return false;
                        }
                    }
                    //(Oggetto mail 20151118: LIQPENS - analisi DAI)
                    //Controllo sulla somma dei gg inseribili per i retributivi calcolati nel seguente modo: somma = (76+21+31)/0.75 + [(51+91)*6.9231] + (41+16+17+71+61) 
                    decimal somma = 0;
                    foreach (var elem in lstSenzaQuotaFittizia)
                    {
                        int ggMMForRecord = elem.SettimaneA.GetValueOrDefault() + elem.SettimaneB.GetValueOrDefault();
                        switch (elem.DecorrenzaExInpdai)
                        {
                            case 76:
                            case 21:
                                somma += Math.Round(ggMMForRecord / 0.75M);
                                break;
                            case 51:
                            case 91:
                                somma += Math.Round(ggMMForRecord * coefNormSettInGG);
                                break;
                            case 31:
                            case 41:
                            case 16:
                            case 17:
                            case 71:
                            case 61:
                                somma += ggMMForRecord;
                                break;
                        }
                    }
                    if (somma > maxGGConsentiti)
                    {
                        messaggioVideo = string.Format("La somma dei giorni ({0}) supera il massimo valore consentito 14400.", somma.ToString("#.00"));
                        return false;
                    }
                }
                #endregion Controlli Dati Retributivi

                #region Controlli Dati Contributivi
                if (listaDatiCalcoloVittimeTerrorismo.Any(x => x.Tipo == 'C'))
                {
                    List<GestioneContrib.DatiContributiviExInpdai> lDatiContributivi = new List<GestioneContrib.DatiContributiviExInpdai>();
                    List<GestioneContrib.DatiContributiviExInpdai> listaDatiContribApp = lDatiCalcoloContributivo.Select(x => new GestioneContrib.DatiContributiviExInpdai(x, listaDecodificaCalcoloContributivo)).ToList();
                    List<GestioneContrib.DatiContributiviExInpdai> listaDatiContribVittimeApp = listaDatiCalcoloVittimeTerrorismo.Where(x => x.Tipo == 'C').Select(x => new GestioneContrib.DatiContributiviExInpdai(x, listaDecodificaCalcoloContributivo)).ToList();
                    foreach (var app in listaDatiContribApp)
                    {
                        if (listaDatiContribVittimeApp.Exists(x => x.CodGestione == app.CodGestione && x.Quota == app.Quota))
                            lDatiContributivi.Add(listaDatiContribVittimeApp.FirstOrDefault(x => x.CodGestione == app.CodGestione && x.Quota == app.Quota));
                        else
                            lDatiContributivi.Add(app);
                    }
                    //Controllo 1
                    //NSettimane non può essere inserito un  valore superiore a 2600 
                    if (lDatiContributivi.Where(x => (x.Settimane > 2600 || x.SettimaneQuotaD > 2600)).Count() > 0)
                    {
                        messaggioVideo = "Il numero di settimane per la quota contributiva non può essere superiore a 2600.";
                        return false;
                    }

                    if (tipoCalcolo == Utility.TipoCalcolo.Contributivo)
                    {
                        GestioneDecodifica.CodeGestioneCalcoloContributivo gestione = listaDecodificaCalcoloContributivo.Find(x => x.TraduzioneSuGP.Trim() == "A");

                        if (lDatiContributivi.FindAll(x => x.CodGestione == gestione.Id && x.Quota == 'C').Count == 0)
                        {
                            messaggioVideo = "E' obbligatorio inserire una registrazione con gestione 'A - INPDAI' e quota 'C'.";
                            return false;
                        }
                    }
                }
                #endregion Controlli Dati Contributivi
            }
            return true;
        }

        public static bool ControlsProRataTemporisWithNaturaPensione(GestionePensione.DatiPensione datiPensione, string naturaPensione, decimal? importoProRataTemporis, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (importoProRataTemporis.HasValue && (string.IsNullOrEmpty(naturaPensione) || naturaPensione.Substring(2, 1) != "V"))
            {
                messaggioVideo = "In presenza del campo Importo pro rata temporis, il terzo byte del codice natura deve essere 'V'.";
                return false;
            }

            return true;
        }

        public static bool ControlsDatiRetributiviMaternita(ref EntityBLCommon.ContenitoreObject contenitore, ref EntityBLCommon.ContenitoreDecodifica contenitoreDecodifica, List<GestioneCalcolo.DatiCalcoloRetributivo> listaDatiRetr, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> elencoCodeGestioneCalcoloRetributivo = contenitoreDecodifica.ElencoCodeGestioneCalcoloRetributivo;
            if (listaDatiRetr != null && listaDatiRetr.Count > 0 && listaDatiRetr.Any(x => GetGestioneRetributiva(x.CodiceGestione, elencoCodeGestioneCalcoloRetributivo) == "P"))
            {
                GestioneAnagrafica.DatiAnagrafici soggetto = null;
                if (Utility.IsDomandaPensioneSuperstitiOrRicostituzione(contenitore.DatiPensione))
                    soggetto = contenitore.DatiAnagraficiDanteCausa;
                else
                    soggetto = contenitore.DatiAnagraficiTitolare;

                if (soggetto.Sesso != 'F')
                {
                    messaggioVideo = "Non è possibile inserire dati retributivi con gestione 'P' se il sesso del Titolare/Dante Causa non è 'F'.";
                    return false;
                }

                DateTime? decorrenza = Utility.GetDecorrenzaPensioneOrDecorrenzaDantecausa(contenitore.DatiPensione.DecorrenzaOriginaria, contenitore.DatiDanteCausa != null ? contenitore.DatiDanteCausa.DecorrenzaPensione : null);
                if (decorrenza > new DateTime(2001, 5, 1))
                {
                    messaggioVideo = "Non è possibile inserire dati retributivi con gestione 'P' se la decorrenza della pensione è successiva al 05/2001.";
                    return false;
                }

                List<GestioneCalcolo.DatiCalcoloRetributivo> listaDatiRetributiviMaternita = listaDatiRetr.FindAll(x => GetGestioneRetributiva(x.CodiceGestione, elencoCodeGestioneCalcoloRetributivo) == "P");

                if (listaDatiRetributiviMaternita.Sum(x => x.NSettimaneQuotaA.GetValueOrDefault() + x.NSettimaneQuotaB.GetValueOrDefault()) > 260)
                {
                    messaggioVideo = "Il numero di settimane totali per la gestione 'P' dovrà essere minore o uguale a 260.";
                    return false;
                }

                if (listaDatiRetributiviMaternita.Any(x => x.QuotePrimeLiquidate == 'A') && !listaDatiRetr.Any(x => GetGestioneRetributiva(x.CodiceGestione, elencoCodeGestioneCalcoloRetributivo) == "1" && x.QuotePrimeLiquidate == 'A'))
                {
                    messaggioVideo = "E' necessario inserire una registrazione con gestione '1' e quota 'A'.";
                    return false;
                }

                if (listaDatiRetributiviMaternita.Any(x => x.QuotePrimeLiquidate == 'B') && !listaDatiRetr.Any(x => GetGestioneRetributiva(x.CodiceGestione, elencoCodeGestioneCalcoloRetributivo) == "1" && x.QuotePrimeLiquidate == 'B'))
                {
                    messaggioVideo = "E' necessario inserire una registrazione con gestione '1' e quota 'B'.";
                    return false;
                }

                foreach (GestioneCalcolo.DatiCalcoloRetributivo mater in listaDatiRetributiviMaternita)
                {
                    GestioneCalcolo.DatiCalcoloRetributivo retr = listaDatiRetr.Where(x => GetGestioneRetributiva(x.CodiceGestione, elencoCodeGestioneCalcoloRetributivo) == "1" && x.QuotePrimeLiquidate == mater.QuotePrimeLiquidate).FirstOrDefault();
                    int? settimaneGestione1 = retr.NSettimaneQuotaA.GetValueOrDefault() + retr.NSettimaneQuotaB.GetValueOrDefault();
                    int? settimaneGestioneP = mater.NSettimaneQuotaA.GetValueOrDefault() + mater.NSettimaneQuotaB.GetValueOrDefault();

                    if (settimaneGestioneP.GetValueOrDefault() >= settimaneGestione1.GetValueOrDefault())
                    {
                        messaggioVideo = string.Format("Il numero di settimane per la gestione 'P' e quota '{0}' deve essere minore di {1}.", mater.QuotePrimeLiquidate, settimaneGestione1.GetValueOrDefault());
                        return false;
                    }

                    if ((mater.RMSQuotaA.GetValueOrDefault() + mater.RMSQuotaB.GetValueOrDefault()) != (retr.RMSQuotaA.GetValueOrDefault() + retr.RMSQuotaB.GetValueOrDefault()))
                    {
                        messaggioVideo = string.Format("Il reddito / retribuzione media della registrazione con gestione P deve essere uguale al reddito / retribuzione media della corrispondente registrazione di gestione 1 e quota '{0}'.", mater.QuotePrimeLiquidate);
                        return false;
                    }
                }

            }
            return true;
        }
        #endregion DatiCalcolo

        #region LiquidazionePensione
        public static bool ControlsCodiciNatura(string tipoBeneficio, string naturaPensione, byte? codiceDomandaRicorso, int? attivitaEconomica, int? professioneIndividuale,
            GestioneDanteCausa.DatiDanteCausa datiDanteCausa, byte? tipoCalcolo, char? contributivo, GestionePensione.DatiPensione datiPensione, GestioneLavorazione.DatiLavorazione datiLavorazione,
            GestioneDatiGenericiAgoCi.PensioniDatiGenerici datiPensioniDatiGenerici, int? nSettimane, bool isRiaperturaDomanda, List<EntityBLCommon.DatiSupplementi> listaSupplementi,
            byte? tipoPensioneExInpdai, DateTime? dataAssunzioneCarico, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';
            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            byte codiceRicorso = 0;
            int pdirsup = 0;
            int plavaut = 0;
            byte codProv = (datiDanteCausa != null && datiDanteCausa.ProvenienzaPensione.HasValue) ? datiDanteCausa.ProvenienzaPensione.Value : (byte)0;
            string dauCtrDai = string.Empty;
            char? tipoDomanda = null;
            bool isDomandaTrasfomazioneInvalidita;


            #region Recupero Dati
            Utility.GetCodiciNatura(naturaPensione, out codNat1, out codNat2, out codNat3);

            if (codiceDomandaRicorso.HasValue)
                codiceRicorso = codiceDomandaRicorso.Value;

            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);

            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);

            GetPdirusp_Plavaut(datiPensione, out pdirsup, out plavaut);

            if (datiLavorazione != null)
                tipoDomanda = datiLavorazione.TipoDomanda;

            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2021 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo123_2021", out ctrlMemo123_2021);

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024", out ctrlMemo123_2024);

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024OpzioneContrib = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024OpzioneContrib", out ctrlMemo123_2024OpzioneContrib);

            //(DAU-CTR-DAI: in fase di prelievo dati dalla domanda e nel caso di
            //reversibilità da pensionato va a leggere i dati della diretta e da qui valorizza il
            //campo con questa specifica sui dati della diretta: se la Categoria è = “SDAI”
            //e la Decorrenza Originaria (GP1AD01) è superiore a dicembre 1996 e la
            //Data di Assunzione in carico (GP1AF09Z) è superiore a novembre 2003 e se
            //presente i dati contributivi/retributivi (GP2BC01(1)) o i dati retributivi L. 335
            //(GP2BB07(1)) il campo viene valorizzato a “S”, altrimenti a “N”)
            Utility.TipoDomanda tipologiaDomanda = Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto);
            if (tipologiaDomanda == Utility.TipoDomanda.Superstiti && datiDanteCausa != null && datiDanteCausa.DecorrenzaPensione.HasValue)
            {
                if (siglaCategoria == "SDAI")
                {
                    dauCtrDai = "N";
                    if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(1996, 12, 31)) &&
                        datiPensione.DataAcquisizione.HasValue && Utility.DataStrettamenteSuccessivaA(datiPensione.DataAcquisizione.Value, new DateTime(2003, 11, 30)))
                    {
                        GetDauCtrDai(datiPensione, ref dauCtrDai);
                    }
                }
            }

            isDomandaTrasfomazioneInvalidita = Utility.IsDomandaTrasformazioneInvalidita(datiPensione);
            #endregion Recupero Dati

            #region Controlli Primo Codice Natura
            switch (filtro)
            {
                //Se il campo DO-NOTE, proveniente dalla domanda, è = a “MPA”, “MPM”,
                //“ESO”, “SAA”, “SAM”, “SSA”, “SSM” il 1° Codice Natura deve essere = a “1”
                //o “2”

                case "MPA":
                case "MPM":
                case "ESO":
                case "SAA":
                case "SAM":
                    //è previsto un controllo più ampio
                    //case "SSA":
                    //case "SSM":
                    if (!(siglaCategoria == "VOCOOP" || siglaCategoria == "VOCRED" || (siglaCategoria == "VOESO" && (datiPensione.Tipo == "0036" || datiPensione.Tipo == "0034"))))
                    {
                        if (codNat1 != '1' && codNat1 != '2')
                        {
                            messaggioVideo = "Il primo codice natura deve essere uguale a 1 o a 2";
                            return false;
                        }
                    }
                    break;
                //Se il campo DO-NOTE, proveniente dalla domanda, = “SVA”, “SVM”, “STA”,
                //“STM”, “ERI” il 1° Codice Natura deve essere vuoto o = a “6”
                case "SVA":
                case "SVM":
                case "STA":
                case "STM":
                case "ERI":
                    if (codNat1 != ' ' && codNat1 != '6')
                    {
                        messaggioVideo = "Il primo codice natura deve essere vuoto o uguale a 6";
                        return false;
                    }
                    break;
                //Se il campo DO-NOTE, proveniente dalla domanda, è = a “CSL”, “SSA”,
                //“SSM” il 1° Codice Natura deve essere = a “1” o “2” o “3” o “4”
                //Se il campo DO-NOTE, proveniente dalla domanda, è = a “222” il 1° Codice
                //Natura deve essere = a “1”, “2”, "3", "4"
                case "CSL":
                case "SSA":
                case "SSM":
                case "222":
                    if (codNat1 != '1' && codNat1 != '2' && codNat1 != '3' && codNat1 != '4')
                    {
                        messaggioVideo = "Il primo codice natura deve essere uguale a 1 o a 2 o a 3 o a 4";
                        return false;
                    }
                    break;
                //Se il campo DO-NOTE = “SUT” il 1° Codice Natura deve essere vuoto o
                //“6”,il 2° Codice Natura deve essere “U”, il 3° Codice Natura deve essere
                //assente
                case "SUT":
                    if (codNat1 != ' ' && codNat1 != '6')
                    {
                        messaggioVideo = "Il primo codice natura deve essere vuoto o uguale a 6";
                        return false;
                    }
                    if (codNat2 != 'U')
                    {
                        messaggioVideo = "Il secondo codice natura deve essere uguale a U";
                        return false;
                    }
                    if (codNat3 != ' ')
                    {
                        messaggioVideo = "Il terzo codice natura deve essere vuoto";
                        return false;
                    }
                    break;
                default:
                    break;
            }

            //Se il contenuto della Categoria (RACATEG) dal 3° al 5° carattere è = a “TOT”
            //il 1° Codice Natura deve essere diverso da “5”
            if (siglaCategoria.Length >= 5 && siglaCategoria.Substring(2, 3) == "TOT")
            {
                if (codNat1 == '5')
                {
                    messaggioVideo = "Il primo codice natura deve essere diverso da 5";
                    return false;
                }
            }

            switch (siglaCategoria)
            {
                //Se la Categoria (RACATEG) = “IOTOT” il 1° Codice Natura deve essere solo
                //“3” o “4”: cioè possono essere solo inabilità
                case "IOTOT":
                case "IOCUM":
                    if (codNat1 != '3' && codNat1 != '4')
                    {
                        messaggioVideo = "Il primo codice natura deve essere uguale a 3 o a 4";
                        return false;
                    }
                    break;
                //Se la Categoria (RACATEG) = “VOBIS”, “IOBIS”, VMP”, “VOSPED” il 1°
                //Codice Natura può essere solo vuoto o = a “6”
                case "VOSPED":
                    if (codNat1 != ' ' && codNat1 != '6')
                    {
                        messaggioVideo = "Il primo codice natura deve essere vuoto o uguale a 6";
                        return false;
                    }
                    break;
                case "VOBIS":
                case "IOBIS":
                case "VMP":
                    if (!Utility.IsRicostituzione(datiPensione.Gruppo))
                    {
                        if (codNat1 != ' ' && codNat1 != '6')
                        {
                            messaggioVideo = "Il primo codice natura deve essere vuoto o uguale a 6";
                            return false;
                        }
                    }
                    break;
                case "VOCUM":
                    if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                        if (Utility.IsDomandaAnticipataCumuloL232(datiPensione))
                        {
                            if (codNat1 != '1' && codNat1 != '2')
                            {
                                messaggioVideo = "Il primo codice natura deve essere uguale a 1 o a 2";
                                return false;
                            }
                        }
                        else if (codNat1 != ' ' && codNat1 != '6')
                        {
                            messaggioVideo = "Il primo codice natura deve essere vuoto o uguale a 6";
                            return false;
                        }
                    break;
                //Se la Categoria (RACATEG) = “IMP” e la Decorrenza Originaria (RAU104) è
                //superiore a Gennaio 1997, il 1° Codice Natura deve essere = a “3” o “4”; per
                //quelle con la Decorrenza Originaria (RAU104) antecedente Febbraio 1997
                //(cioè fino a Gennaio 1997) il 1° Codice Natura non può essere = a “3” o “4”
                // REING: per quelle con la Decorrenza Originaria (RAU104) antecedente Febbraio 1997
                //(cioè fino a Gennaio 1997) il 1° Codice Natura deve essere = a spazio o “6”
                case "IMP":
                    if (!Utility.IsRicostituzione(datiPensione.Gruppo))
                    {
                        if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, 1997, 1, 31))
                        {
                            if (codNat1 != '3' && codNat1 != '4')
                            {
                                messaggioVideo = "Il primo codice natura deve essere uguale a 3 o a 4";
                                return false;
                            }
                        }
                        else
                        {
                            if (codNat1 != ' ' && codNat1 != '6')
                            {
                                messaggioVideo = "Il primo codice natura deve essere uguale a spazio o a 6";
                                return false;
                            }
                        }
                    }
                    break;
                //Se la Categoria (RACATEG) è = a “SO”, “SR”, “SOART” con tipocalcolo != contributivo o “SOCOM”, “SDAI” e
                //il 2° Codice Natura = “O” il 1° Codice Natura deve essere = a “2”

                // ACCENTURE :  Le "SDAI" sono state unite alla logica delle “SO”, “SR”, “SOART” ovvero per le "SDAI" con tipocalcolo != contributivo e
                //il 2° Codice Natura = “O” il 1° Codice Natura deve essere = a “2”
                case "SO":
                case "SR":
                case "SOART":
                case "SOCOM":
                case "SDAI":
                case "SOCUM":
                    if (!(tipoCalcolo == 1 && siglaCategoria != "SOCUM") && codNat2 == 'O')
                    {
                        if (codNat1 != '2')
                        {
                            messaggioVideo = "Il primo codice natura deve essere uguale a 2";
                            return false;
                        }
                    }
                    break;
                //Se la Categoria (RACATEG) è = a “VOAUT”, “IOAUT” e la Decorrenza
                //Originaria (RAU104) è inferiore ad Aprile 2001 il 1° Codice Natura deve
                //essere = a “5”
                case "VOAUT":
                case "IOAUT":
                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2001, 04, 01)))
                    {
                        if (codNat1 != '5')
                        {
                            messaggioVideo = "Il primo codice natura deve essere uguale a 5";
                            return false;
                        }
                    }
                    if (!GestioneCrossControls.AGO_ControlsCodNatura1WithDecPensForAut(naturaPensione, decorrenzaOriginaria, out messaggioVideo))
                        return false;


                    break;
                //Se la Categoria (RACATEG) è = “IO”, “IDAI”, “IR”, “IOART”, “IOCOM”, “IOP”,
                //“IOBANC” il 1° Codice Natura deve essere vuoto o = a “3”, “4”, “5”, "6", “8”, “9”
                case "IO":
                case "IDAI":
                case "IR":
                case "IOART":
                case "IOCOM":
                case "IOP":
                case "IOBANC":
                    if (codNat1 != ' ' && codNat1 != '3' && codNat1 != '4' && codNat1 != '5' && codNat1 != '6' && codNat1 != '8' && codNat1 != '9')
                    {
                        messaggioVideo = "Il primo codice natura deve essere vuoto o uguale a 3 o a 4 o a 5 o a 6 o a 8 o a 9";
                        return false;
                    }
                    break;
                //Se la Categoria (RACATEG) è = “INDCOM” tutte e tre Codici Natura devono
                //essere assenti
                case "INDCOM":
                    if ((codNat1 != ' ' || codNat2 != ' ' || codNat3 != ' ') && !Utility.IsRicostituzione(datiPensione.Gruppo))
                    {
                        messaggioVideo = "I tre codici natura devono essere vuoti";
                        return false;
                    }
                    break;
                //Se la categoria è = a “VOCRED”, “VOCOOP”, “VOESO” il 1° Codice Natura
                //(RAU1031) deve essere = a “1” o “ ”
                case "VOCRED":
                case "CRED27":
                case "VOCOOP":
                case "VOESO":
                case "COOP28":
                    if (codNat1 != '1' && codNat1 != ' ')
                    {
                        messaggioVideo = "Il primo codice natura deve essere uguale a 1 o a spazio";
                        return false;
                    }
                    break;
                case "VOTOT":
                    if (!(Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) || Utility.IsDomandaRipristinoOrRiliquidazione(datiPensione)))
                    {
                        //Se la Categoria (RACATEG) è = a “VOTOT” e il campo Tipo Domanda (PTIPODO)
                        //è = “1” il 1° Codice Natura deve essere = a “1” o “2”
                        if (tipoDomanda.HasValue && tipoDomanda.Value == '1')
                        {
                            if (codNat1 != '1' && codNat1 != '2')
                            {
                                messaggioVideo = "Il primo codice natura deve essere uguale a 1 o a 2";
                                return false;
                            }
                        }
                        //Se la Categoria (RACATEG) è = a “VOTOT” e il campo Tipo Domanda (PTIPODO)
                        //è diverso da “1” il 1° Codice Natura non può essere = a “1” o “2”
                        else if (tipoDomanda.HasValue && tipoDomanda.Value != '1')
                        {
                            if (codNat1 == '1' || codNat1 == '2')
                            {
                                messaggioVideo = "Il primo codice natura non può essere uguale a 1 o a 2";
                                return false;
                            }
                        }
                    }
                    break;
                case "SOAUT":
                    //Se la Categoria (RACATEG) è = “SOAUT”, il campo Tipo Domanda (PTIPODO)
                    //è = a “0” e la Decorrenza Originaria (RAU104) è inferiore ad Aprile
                    //2001 il 1° Codice Natura deve essere = a “5”
                    if (tipoDomanda.HasValue && tipoDomanda.Value == '0')
                    {
                        if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2001, 4, 1)))
                        {
                            if (codNat1 != '5')
                            {
                                messaggioVideo = "Il primo codice natura deve essere uguale a 5";
                                return false;
                            }
                        }
                    }
                    if (!GestioneCrossControls.AGO_ControlsCodNatura1WithDecPensForAut(naturaPensione, (datiDanteCausa != null && datiDanteCausa.DecorrenzaPensione.HasValue) ? datiPensione.DecorrenzaOriginaria : null, out messaggioVideo))
                        return false;
                    break;
                default:
                    break;
            }



            switch (siglaCategoria)
            {
                //Se la Categoria (RACATEG) = “VOART”, “IOART”, “SOART”, “VOCOM”,
                //“IOCOM”, “SOCOM”, “VR”, “IR”, “SR”, “VOMIN”, “SOMIN” e la Decorrenza
                //Originaria (RAU104) è superiore a Luglio 1984 il 1° Codice Natura deve
                //essere diverso da “8” o “9”   
                case "VOART":
                case "SOART":
                case "VOCOM":
                case "SOCOM":
                case "VR":
                case "SR":
                case "VO":
                case "SO":
                case "VOMIN":
                case "SOMIN":
                    if (Utility.IsRicostituzione(datiPensione.Gruppo) && siglaCategoria.StartsWith("S") && Utility.IsDomandaAnte96(datiPensione, datiPensione, datiDanteCausa, isRiaperturaDomanda) != null)
                    {
                        if (datiDanteCausa != null && datiDanteCausa.DecorrenzaPensione.HasValue && Utility.DataStrettamenteSuccessivaA(datiDanteCausa.DecorrenzaPensione.GetValueOrDefault(), new DateTime(1984, 07, 31)))
                        {
                            if (codNat1 == '8' || codNat1 == '9')
                            {
                                messaggioVideo = "Il primo codice natura deve essere diverso da 8 e da 9 quando la decorrenza pensione è maggiore o uguale a 08/1984";
                                return false;
                            }
                        }
                    }

                    else if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(1984, 07, 31)))
                    {
                        if (codNat1 == '8' || codNat1 == '9')
                        {
                            messaggioVideo = "Il primo codice natura deve essere diverso da 8 e da 9 quando la decorrenza pensione è maggiore o uguale a 08/1984";
                            return false;
                        }
                    }
                    break;
                case "IOCOM":
                case "IOART":
                case "IR":
                case "IO":
                    break;
                //Per tutte le categorie (RACATEG) diverse da “VOART”, “IOART”, “SOART”,
                //“VOCOM”, “IOCOM”, “SOCOM”, “VR”, “IR”, “SR”, “VOMIN”, “SOMIN” il 1°
                //Codice Natura deve essere diverso da “8” o “9”
                default:
                    if (codNat1 == '8' || codNat1 == '9')
                    {
                        messaggioVideo = "Il primo codice natura deve essere diverso da 8 e da 9";
                        return false;
                    }
                    break;
            }

            switch (siglaCategoria)
            {
                case "VOMIN":
                    if (codNat2 == 'A' && codNat1 != '4')
                    {
                        messaggioVideo = "Il primo codice natura deve essere '4' se il secondo è 'A'";
                        return false;
                    }
                    if (Utility.IsPensioneVecchiaiaOrRicostituzione(datiPensione, null))
                    {
                        if ((codNat1 == '4' || codNat1 == '3') && !Utility.DataStrettamenteSuccessivaA(Utility.FirstDayOfMonth(decorrenzaOriginaria), Utility.FirstDayOfMonth(datiPensione.DataPresentazioneDomanda)))
                        {
                            messaggioVideo = "Se il primo codice natura è '3' o '4' allora la decorrenza pensione deve essere almeno pari al messe successivo della data di presentazione domanda";
                            return false;
                        }
                    }

                    if (tipoCalcolo == 1 && codNat1 == '0')
                    {
                        messaggioVideo = "Se il primo codice natura è '0' il tipo calcolo non può essere contributivo";
                        return false;
                    }
                    break;
                //Se la Categoria (RACATEG) e = a “SOMIN” il 1° Codice Natura può essere
                //solo “0”, “1”, “2”, “6”, “8”, “9”
                case "SOMIN":
                    var lstCodiciNaturaSOMIN = new List<string> { "blank", "0", "3", "4", "6", "8", "9" };
                    if (!(Utility.IsDomandaPensioneIndiretta(datiPensione) && Utility.IsDomandaPL(datiPensione)))
                    {
                        lstCodiciNaturaSOMIN.Add("1");
                        lstCodiciNaturaSOMIN.Add("2");
                    }

                    if (!lstCodiciNaturaSOMIN.Contains(codNat1.ToString()) && codNat1 != ' ')
                    {
                        messaggioVideo = string.Format("Il primo codice natura deve essere uguale a uno tra {0}", lstCodiciNaturaSOMIN.Aggregate((a, b) => { return a + ", " + b; }));
                        return false;
                    }

                    if (tipoCalcolo == 1 && codNat1 == '0')
                    {
                        messaggioVideo = "Se il primo codice natura è '0' il tipo calcolo non può essere contributivo";
                        return false;
                    }
                    break;
                //Se la Categoria (RACATEG) è diversa da “VOMIN” e “SOMIN”, il 1° Codice
                //Natura non può essere = a “0”
                default:
                    if (codNat1 == '0')
                    {
                        messaggioVideo = "Il primo codice natura non può essere uguale a 0";
                        return false;
                    }
                    break;
            }

            // Commentato a seguito della mail del 26/11/2013 con oggetto: RE: Reeng Pensioni AGO - Verifica controllo
            ////Se il Codice Ricorso è diverso da 9 o 8 il 1° Codice Natura non può essere =
            ////a “5”
            //if (codiceRicorso != 9 && codiceRicorso != 8)
            //{
            //    if (codNat1 == '5')
            //    {
            //        messaggioVideo = "Il primo codice natura non può essere uguale a 5";
            //        return false;
            //    }
            //}

            //Se il campo DO-TIPDO è = a “1” o “9” e il campo DO-NOTE è diverso da
            //“LS1”, “LS2”, “LSU” il 1° Codice Natura deve essere = a “1” o “2”
            if (!Utility.IsDomandaRipristino(datiPensione).GetValueOrDefault())
            {
                switch (filtro)
                {
                    case "LS1":
                    case "LS2":
                    case "LSU":
                        break;
                    default:
                        if (!(siglaCategoria == "VOCOOP" || siglaCategoria == "VOCRED" || (siglaCategoria == "VOESO" && (datiPensione.Tipo == "0036" || datiPensione.Tipo == "0034"))))
                        {
                            if (tipoDomanda.HasValue && (tipoDomanda.Value == '1' || tipoDomanda.Value == '9'))
                            {
                                if (codNat1 != '1' && codNat1 != '2')
                                {
                                    messaggioVideo = "Il primo codice natura deve essere uguale a 1 o a 2";
                                    return false;
                                }
                            }
                        }
                        break;
                }
            }


            //controllo slegato dai precedenti. Fornitoci in seguito alla mail del 13/03/2013 - Reeng Pensioni AGO - Esito test
            if (datiPensione.Gruppo == "0002" && datiPensione.Prodotto == "0012")   //pensione di inabilità
            {
                if (codNat1 != '3' && codNat1 != '4')
                {
                    messaggioVideo = "Il primo codice natura deve essere uguale a 3 o a 4";
                    return false;
                }
            }
            if (datiPensione.Gruppo == "0002" && datiPensione.Prodotto == "0011")   //assegno di invalidità
            {
                if (codNat1 != ' ' && codNat1 != '6')
                {
                    messaggioVideo = "Il primo codice natura deve essere uguale a vuoto o a 6";
                    return false;
                }
            }

            //Controlli codice natura 1 per ricostituzioni 
            if (Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Tipo) == Utility.TipoDomanda.Ricostituzione && datiPensione.NaturaPensione != null && !Utility.IsDomandaMIN(datiPensione.SiglaCategoria))
            {
                char codNat1Old, codNat2Old, codNat3Old;
                Utility.GetCodiciNatura(datiPensione.NaturaPensione, out codNat1Old, out codNat2Old, out codNat3Old);

                switch (codNat1Old)
                {
                    case ' ':
                    case '6':
                        if (codNat1 != ' ' && codNat1 != '6')
                        {
                            messaggioVideo = "Il codice natura 1 può essere blank o 6.";
                            return false;
                        }
                        break;
                    case '1':
                    case '2':
                        if (codNat1 != '1' && codNat1 != '2')
                        {
                            messaggioVideo = "Il codice natura 1 può essere 1 o 2.";
                            return false;
                        }
                        break;
                    case '3':
                    case '4':
                        if (codNat1 != '3' && codNat1 != '4')
                        {
                            messaggioVideo = "Il codice natura 1 può essere 3 o 4.";
                            return false;
                        }
                        break;
                    case '5':
                        if (codNat1 != '5')
                        {
                            messaggioVideo = "Il codice natura 1 può essere solo 5.";
                            return false;
                        }
                        break;
                    case '8':
                    case '9':
                        if (codNat1 != '8' && codNat1 != '9')
                        {
                            messaggioVideo = "Il codice natura 1 può essere 8 o 9.";
                            return false;
                        }
                        break;
                }
            }
            #endregion Controlli Primo Codice Natura

            #region Controlli Secondo Codice Natura
            switch (siglaCategoria)
            {
                //Se la Categoria (RACATEG) è = a “IOBIS”, “VOBIS”, “VMP”, “IMP”,
                //“VOAUT”, “IOAUT”, “SOAUT” e il campo DO-NOTE è diverso da “ERI”,
                //“RAL”, “R22”, “R23”, “R24”, “R25”, “R44”, “R45” il 2° Codice Natura deve
                //essere assente
                case "IOBIS":
                case "VOBIS":
                case "VMP":
                case "IMP":
                case "VOAUT":
                case "IOAUT":
                case "SOAUT":
                    if ((Utility.IsRenditaCasalinghe(datiPensione) || Utility.IsRenditaFacoltativa(datiPensione)) && Utility.IsRicostituzione(datiPensione.Gruppo))
                        break;
                    switch (filtro)
                    {
                        case "ERI":
                        case "RAL":
                        case "R22":
                        case "R23":
                        case "R24":
                        case "R25":
                        case "R44":
                        case "R45":
                        case "PAV":
                            break;
                        default:
                            if (codNat2 != ' ' && !Utility.IsDomandaIndennitaUnaTantum_AGO(datiPensione) && !(ctrlMemo123_2021 != null && !String.IsNullOrEmpty(ctrlMemo123_2021.ValoreControllo) && ctrlMemo123_2021.ValoreControllo.Trim().ToUpperInvariant() == "SI" && datiPensione.IdTipoPLPerRIC.HasValue && datiPensione.IdTipoPLPerRIC == (byte)Utility.TipoPLPerRIC.RicAnticipateComputoConFiltroPAV) &&
                                !((!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))) ||
                                   (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && ((ctrlMemo123_2024 != null && ctrlMemo123_2024.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione)) || (ctrlMemo123_2024OpzioneContrib != null && ctrlMemo123_2024OpzioneContrib.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))))) &&
                                !Utility.IsDomandaVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE(datiPensione) && !Utility.IsDomandaVOAUTAnticipataTipoContributivoFiltroGSE(datiPensione) && !Utility.IsDomandaVOAUTVecchiaiaTipoContributivoFiltroGSE(datiPensione))
                            {
                                messaggioVideo = "Il secondo codice natura deve essere vuoto";
                                return false;
                            }
                            break;
                    }
                    break;
                //Se la Categoria (RACATEG) è = a “VOMIN” il 2° Codice Natura non può
                //essere “Y”
                case "VOMIN":
                    if (codNat2 == 'Y')
                    {
                        messaggioVideo = "Il secondo codice natura non può essere Y";
                        return false;
                    }
                    break;
                //Se la Categoria (RACATEG) è = a “SOTOT” il 2° Codice Natura non può
                //essere “C”
                case "SOTOT":
                    if (codNat2 == 'C')
                    {
                        messaggioVideo = "Il secondo codice natura non può essere C";
                        return false;
                    }
                    break;
                //Se la Categoria (RACATEG) è = a “SO”, “SR”, “SOART”, “SOCOM” con tipocalcolo != contributivo o “SDAI” e
                //il campo DO-NOTE è diverso da “CSL”, “SSA”, “SSM” il 2° Codice Natura
                //non può essere = a “O”

                // ACCENTURE :  Le "SDAI" sono state unite alla logica delle “SO”, “SR”, “SOART”, “SOCOM” ovvero  se tipocalcolo != contributivo e
                //il campo DO-NOTE è diverso da “CSL”, “SSA”, “SSM” il 2° Codice Natura
                //non può essere = a “O”
                case "SO":
                case "SR":
                case "SOART":
                case "SOCOM":
                case "SDAI":
                    switch (filtro)
                    {
                        case "CSL":
                        case "SSA":
                        case "SSM":
                            break;
                        default:
                            if (tipoCalcolo != 1 && codNat2 == 'O')
                            {
                                messaggioVideo = "Il secondo codice natura non può essere O";
                                return false;
                            }
                            break;
                    }
                    break;
                //Se la Categoria (RACATEG) è = a “IDAI” e la data della domanda (RAUE24)
                //è superiore al 9 luglio 1997 e il 1° Codice Natura è diverso da “3” o “4” il 2°
                //Codice Natura deve essere “B”, altrimenti deve essere vuoto
                case "IDAI":
                    if (!(Utility.IsRicostituzione(datiPensione.Gruppo) && dataAssunzioneCarico.HasValue && Utility.DataStrettamenteSuccessivaSenzaGiorno(new DateTime(2003, 12, 01), dataAssunzioneCarico.Value) && tipoPensioneExInpdai.HasValue && tipoPensioneExInpdai.Value != '4'))
                    {
                        if ((Utility.DataStrettamenteSuccessivaA(datiPensione.DataPresentazioneDomanda, new DateTime(1997, 07, 09)) && codNat1 != '3' && codNat1 != '4'))
                        {
                            if (codNat2 != 'B' && codNat2 != 'E')
                            {
                                messaggioVideo = "Il secondo codice natura deve essere uguale a B o E.";
                                return false;
                            }
                        }
                        else
                        {
                            if (codNat2 != ' ')
                            {
                                messaggioVideo = "Il secondo codice natura deve essere vuoto";
                                return false;
                            }
                        }
                    }
                    break;
                case "IOCUM":
                    if (Utility.IsDomandaPensioneInabilita(datiPensione))
                    {
                        if (codNat2 != 'P' && codNat2 != 'Q')
                        {
                            messaggioVideo = "Inserire P se ex comma 239 o Q se ex comma 240 sul secondo codice natura.";
                            return false;
                        }
                    }
                    break;
                default:
                    break;
            }

            //Se il campo DO-NOTE è diverso da “RAL”, “R22”, “R23”, “R24”, “R25”, “R44”,
            //“R45” il 2° Codice Natura non può essere = a “H”
            switch (filtro)
            {
                case "RAL":
                case "R22":
                case "R23":
                case "R24":
                case "R25":
                case "R44":
                case "R45":
                    break;
                default:
                    if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && codNat2 == 'H')
                    {
                        messaggioVideo = "Il secondo codice natura non può essere H";
                        return false;
                    }
                    break;
            }

            //Se la Categoria (RACATEG) è diversa da “IDAI” il 2° Codice Natura deve
            //essere diverso da “V”
            if (siglaCategoria != "IDAI")
            {
                if (codNat2 == 'B')
                {
                    messaggioVideo = "Il secondo codice natura deve essere diverso da B";
                    return false;
                }
            }

            //Se il 1° Codice Natura è = a “5” il 2° Codice Natura deve essere assente
            if (codNat1 == '5' && !(Utility.IsRenditaCasalinghe(datiPensione) || Utility.IsRenditaFacoltativa(datiPensione)))
            {
                if (codNat2 != ' ')
                {
                    messaggioVideo = "Il secondo codice natura deve essere vuoto";
                    return false;
                }
            }

            switch (siglaCategoria)
            {
                case "IO":
                case "IDAI":
                case "IOP":
                case "IOBANC":
                    break;
                //Se la Categoria (RACATEG) è = a “PMO” con il 3° numero del certificato = a “3” o “5”, il 2°
                //Codice Natura deve essere diverso da “Z”
                case "PMO":
                    if (certificato.Substring(2, 1) == "3" || certificato.Substring(2, 1) == "5")
                    {
                        if (codNat2 == 'Z')
                        {
                            messaggioVideo = "Il secondo codice natura deve essere diverso da Z";
                            return false;
                        }
                    }
                    break;
                //Se la Categoria (RACATEG) è diversa da “IO”, “IDAI”, “IOP”, “PMO”,
                //IOBANC il 2°
                //Codice Natura deve essere diverso da “Z”
                default:
                    if (codNat2 == 'Z')
                    {
                        messaggioVideo = "Il secondo codice natura deve essere diverso da Z";
                        return false;
                    }
                    break;
            }

            //Se il campo PDIRSUP è = a 1 il 2° Codice Natura deve essere diverso da
            //“G”, “R”, “Z”
            if (pdirsup == 1)
            {
                if (codNat2 == 'G' || codNat2 == 'R' || codNat2 == 'Z')
                {
                    messaggioVideo = "Il secondo codice natura deve essere diverso da G o da R o da Z";
                    return false;
                }
            }
            //Se il campo PDIRSUP è = a 0 il 2° Codice Natura non può essere = a “C”
            else
            {
                if (codNat2 == 'C')
                {
                    messaggioVideo = "Il secondo codice natura non può essere uguale a C";
                    return false;
                }
            }

            //Se il campo PLAVAUT è = a 1 il 2° Codice Natura deve essere diverso da “F”
            if (plavaut == 1)
            {
                if (codNat2 == 'F')
                {
                    messaggioVideo = "Il secondo codice natura deve essere diverso da F";
                    return false;
                }
            }

            //Il 2° Codice Natura può essere = a “Y” solo se il campo DO-NOTE è = a
            //“BNS”, “BNX” oppure il (1° carattere della Categoria (RACATEG) è = a “S” e
            //il campo DAU107 è = a “1” o “2”)
            if (codNat2 == 'Y')
            {
                // Effettuo il bypass solo per le ricostituzioni, perchè per le riaperture ho il filtro e quindi posso effettuare il controllo senza problemi
                if (!((filtro == "BNX" || filtro == "BNS" || Utility.IsRicostituzioneOrRiapertura(datiPensione, false)) || Utility.IsDomandaRipristino(datiPensione).GetValueOrDefault() || (siglaCategoria.Substring(0, 1) == "S" && (codProv == 1 || codProv == 2))))
                {
                    messaggioVideo = "Il secondo codice natura non può essere uguale a Y";
                    return false;
                }
            }

            //20141022 - Commentanto controllo in seguito a mail 'RE: LIQPENS - Rilascio Sviluppo INPS v20151022_1' 

            //Se la Categoria (RACATEG) è = a “VO” oppure (“SO” con il campo (anno
            //decorrenza della diretta) DAU106AA maggiore di zero) e il 1° Codice Natura
            //è diverso da “1”, allora il 2° Codice Natura può essere = a “V”
            //if (codNat2 == 'V')
            //{
            //    if (!((siglaCategoria == "VO" ||
            //        (siglaCategoria == "SO" && decPensDA.HasValue)) && codNat1 != '1'))
            //    {
            //        messaggioVideo = "Il secondo codice natura non può essere uguale a V";
            //        return false;
            //    }
            //}

            //Se la Categoria (RACATEG) è diversa da “VOTOT” e il campo DAU06AA è =
            //a zero il 2° Codice Natura deve essere diverso da “M” e “N”
            if (siglaCategoria != "VOTOT" && datiDanteCausa != null && !datiDanteCausa.DecorrenzaPensione.HasValue)
            {
                if (codNat2 == 'M' || codNat2 == 'N')
                {
                    messaggioVideo = "Il secondo codice natura deve essere diverso da M e da N";
                    return false;
                }
            }

            #endregion Controlli Secondo Codice Natura

            #region Controlli Terzo Codice Natura
            switch (siglaCategoria)
            {
                //Se la Categoria (RACATEG) è = a “IOBIS”, “VOBIS”, “VMP”, “IMP” il 3°
                //Codice Natura deve essere assente
                case "IOBIS":
                case "VOBIS":
                case "VMP":
                case "IMP":
                    if (Utility.IsRicostituzione(datiPensione.Gruppo))
                        break;
                    if (codNat3 != ' ')
                    {
                        messaggioVideo = "Il terzo codice natura deve essere vuoto";
                        return false;
                    }
                    break;
                case "IOAUT":
                    if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                    {
                        //Se la Categoria (RACATEG) è = a “VOAUT”, “IOAUT”, “SOAUT” e il 1°
                        //Codice Natura è = a “5” il 3° Codice Natura deve essere vuoto
                        if (codNat1 == '5')
                        {
                            if (codNat3 != ' ')
                            {
                                messaggioVideo = "Il terzo codice natura deve essere vuoto";
                                return false;
                            }
                        }
                        //Se la Categoria (RACATEG) è = a “VOAUT”, “IOAUT”, “SOAUT” il 3° Codice
                        //Natura può essere vuoto o = a “V”
                        else
                        {
                            if (codNat3 != ' ' && codNat3 != 'V')
                            {
                                messaggioVideo = "Il terzo codice natura può essere vuoto o uguale a V";
                                return false;
                            }
                        }
                    }
                    break;
                case "VOAUT":
                case "SOAUT":
                    if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                    {
                        //si lasciano tutte le possibilità e si rimanda il controllo ai dati assicurativi
                        if (codNat1 == '5')
                        {
                            if (codNat3 != ' ' && codNat3 != 'D')
                            {
                                messaggioVideo = "Il terzo codice natura può essere vuoto o uguale a D";
                                return false;
                            }
                        }
                        else
                        {
                            if (codNat3 != ' ' && codNat3 != 'D' && codNat3 != 'V')
                            {
                                messaggioVideo = "Il terzo codice natura può essere vuoto o uguale a D o V";
                                return false;
                            }
                        }
                    }
                    break;
                //Se la Categoria
                //(RACATEG) è = a “SO”, “SR”, “SOART”, “SOCOM”, “SDAI” e il 2° Codice
                //Natura è = a “O” il 3° Codice Natura può essere solo vuoto o = a “I”, “M”, “N”,
                //“R”, “D”, “U”, “G”, “V”
                case "SO":
                case "SR":
                case "SOART":
                case "SOCOM":
                case "SDAI":
                    if (codNat2 == 'O')
                    {
                        if (codNat3 != ' ' && codNat3 != 'I' && codNat3 != 'M' && codNat3 != 'N' && codNat3 != 'R'
                            && codNat3 != 'D' && codNat3 != 'U' && codNat3 != 'G' && codNat3 != 'V')
                        {
                            messaggioVideo = "Il terzo codice natura può essere vuoto o uguale a I o a M o a N o a R o a D o a U o a G o a V";
                            return false;
                        }
                    }
                    break;
                //Se la Categoria (RACATEG) è = a “VO”, “VDAI”, “VOBANC”, “VR”, “VOART”,
                //“VOCOM” e il 1° Codice Natura è = a “1” o “2” e la Decorrenza Originaria
                //(RAU104) è inferiore a ottobre 1996 il 3° Codice Natura non può essere “I”
                case "VO":
                case "VDAI":
                case "VOBANC":
                case "VR":
                case "VOART":
                case "VOCOM":
                    if ((codNat1 == '1' || codNat1 == '2') && !Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1996, 10, 01)))
                    {
                        if (codNat3 == 'I')
                        {
                            messaggioVideo = "Il terzo codice natura non può essere I";
                            return false;
                        }
                    }
                    break;
                //Se la categoria è = a “VOCRED”, “VOCOPP”, “VOESO” e il Campo DONOTE
                //è = a “LS1”, “LS2” il 3° Codice Natura (RAU1033) deve essere = a “L”
                case "VOCRED":
                case "CRED27":
                case "VOCOPP":
                case "VOESO":
                    switch (filtro)
                    {
                        case "LS1":
                        case "LS2":
                            if (codNat3 != 'L')
                            {
                                messaggioVideo = "Il terzo codice natura deve essere uguale a L";
                                return false;
                            }
                            break;
                        default: break;
                    }

                    if (Utility.IsDomandaQuota100CRED27(datiPensione))
                    {
                        if (codNat3 != 'Q')
                        {
                            messaggioVideo = "Il terzo codice natura deve essere 'Q'.";
                            return false;
                        }
                    }
                    else
                    {
                        if (siglaCategoria.Trim() == "VOCOPP")
                        {
                            if (codNat3 != 'B' && codNat3 != 'V' && codNat3 != ' ')
                            {
                                messaggioVideo = "Il terzo codice natura deve essere 'B' (Gestioni Speciali), 'V' (Contribuzione estera) o spazio.";
                                return false;
                            }
                        }
                        else
                        {
                            if (codNat3 != 'B' && codNat3 != 'V' && codNat3 != ' ' && codNat3 != 'Q')
                            {
                                messaggioVideo = "Il terzo codice natura deve essere 'B' (Gestioni Speciali), 'V' (Contribuzione estera), 'Q' o spazio.";
                                return false;
                            }
                        }

                    }
                    break;
                case "VOCOOP":
                case "VESO33":
                case "COOP28":
                case "ESOTEL":
                case "ESOAMB":
                    if (Utility.IsDomandaQuota100VESO33(datiPensione) || Utility.IsDomandaQuota100COOP28(datiPensione) ||
                        Utility.IsDomandaQuota100ESOTEL(datiPensione) || Utility.IsDomandaQuota100ESOAMB(datiPensione))
                    {
                        if (codNat3 != 'Q')
                        {
                            messaggioVideo = "Il terzo codice natura deve essere 'Q'.";
                            return false;
                        }
                    }
                    else
                    {
                        if (Utility.IsDomandaESOAMB(siglaCategoria) || Utility.IsDomandaESOTEL(siglaCategoria))
                        {
                            if (codNat3 != 'B' && codNat3 != 'V' && codNat3 != ' ')
                            {
                                messaggioVideo = "Il terzo codice natura deve essere 'B' (Gestioni Speciali), 'V' (Contribuzione estera) o spazio.";
                                return false;
                            }
                        }
                        else
                        {
                            if (codNat3 != 'B' && codNat3 != 'V' && codNat3 != ' ' && codNat3 != 'Q')
                            {
                                messaggioVideo = "Il terzo codice natura deve essere 'B' (Gestioni Speciali), 'V' (Contribuzione estera), 'Q' o spazio.";
                                return false;
                            }
                        }

                    }
                    break;
                case "VESO29":
                    if (Utility.IsDomandaQuota100VESO29(datiPensione))
                    {
                        if (codNat3 != 'Q')
                        {
                            messaggioVideo = "Il terzo codice natura deve essere 'Q'.";
                            return false;
                        }
                    }
                    break;
                case "APE":
                    if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica &&
                        datiPensioniDatiGenerici != null)
                    {
                        if (datiPensioniDatiGenerici.TipoCertificazioneFelpe == "CII")
                        {
                            if (codNat3 != 'V')
                            {
                                messaggioVideo = "Il terzo codice natura deve essere 'V' (Contribuzione estera).";
                                return false;
                            }
                        }
                        else
                        {
                            if (codNat3 == 'V')
                            {
                                messaggioVideo = "Il terzo codice natura non può essere 'V'";
                                return false;
                            }
                        }
                    }
                    break;
                case "IOTOT":
                case "SOTOT":
                    if (codNat3 == 'G' && contributivo == '8') // Contributivo
                    {
                        messaggioVideo = "Il terzo codice natura G è ammesso solo se “Contributivo” è diverso da “SI”.";
                        return false;
                    }
                    break;
                case "VESO92":
                case "ESPA":
                    if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica &&
                        datiPensioniDatiGenerici != null)
                    {
                        if (datiPensioniDatiGenerici.TipoCertificazioneFelpe == "CII")
                        {
                            if (codNat3 != 'V')
                            {
                                messaggioVideo = "Il terzo codice natura deve essere 'V' (Contribuzione estera).";
                                return false;
                            }
                        }
                        else
                        {
                            if (codNat3 == 'V')
                            {
                                messaggioVideo = "Il terzo codice natura non può essere 'V'";
                                return false;
                            }
                        }

                        if (datiPensioniDatiGenerici.TipoCertificazioneFelpe == "AUT")
                        {
                            if (codNat3 != 'B')
                            {
                                messaggioVideo = "Il terzo codice natura deve essere 'B' (Gestioni Speciali).";
                                return false;
                            }
                        }
                        else
                        {
                            if (codNat3 == 'B')
                            {
                                messaggioVideo = "Il terzo codice natura non può essere 'B'";
                                return false;
                            }
                        }
                    }

                    if (codNat3 != 'B' && codNat3 != 'V' && codNat3 != ' ' && codNat3 != 'Q')
                    {
                        messaggioVideo = "Il terzo codice natura deve essere 'B' (Gestioni Speciali), 'V' (Contribuzione estera), 'Q' o spazio.";
                        return false;
                    }

                    break;
                case "IOCUM":
                case "SOCUM":
                    if (codNat3 == 'G' && contributivo == '8') // Contributivo
                    {
                        messaggioVideo = "Se il terzo codice natura è G, il campo “Contributivo” non può essere “SI”.";
                        return false;
                    }
                    break;
                default:
                    break;
            }

            switch (filtro)
            {
                //Se il campo DO-NOTE è = a “CSL”, “SSA”, “SSM” 
                //il 3° Codice Natura può essere solo vuoto o = a “I”, “M”, “N”,
                //“R”, “D”, “U”, “G”, “V”
                case "CSL":
                case "SSA":
                case "SSM":
                    if (codNat3 != ' ' && codNat3 != 'I' && codNat3 != 'M' && codNat3 != 'N' && codNat3 != 'R'
                            && codNat3 != 'D' && codNat3 != 'U' && codNat3 != 'G' && codNat3 != 'V')
                    {
                        messaggioVideo = "Il terzo codice natura può essere vuoto o uguale a I o a M o a N o a R o a D o a U o a G o a V";
                        return false;
                    }
                    break;
                //Se il campo DO-NOTE è = a “LS2” e il 1° Codice Natura è = a “1” o “2” il 3°
                //Codice Natura deve essere = a “L” (sovrascritto da controllo successivo)
                //Se il campo DO-NOTE è = a “LS1”, “LS2”, “LS3” il 3° Codice Natura deve
                //essere = a “L”
                case "LS1":
                case "LS2":
                case "LS3":
                    if (codNat3 != 'L')
                    {
                        messaggioVideo = "Il terzo codice natura deve essere uguale a L";
                        return false;
                    }
                    break;
                //Se il campo DO-NOTE è = a “CDP” il 3° Codice Natura deve essere = a “E”
                case "CDP":
                    if (codNat3 != 'E')
                    {
                        messaggioVideo = "Il terzo codice natura deve essere uguale a E";
                        return false;
                    }
                    break;
                default:
                    break;
            }

            switch (siglaCategoria)
            {
                case "VO":
                case "IO":
                case "SO":
                case "VOBANC":
                case "IOBANC":
                case "SOBANC":
                case "VDAI":
                case "IDAI":
                case "SDAI":
                case "VR":
                case "IR":
                case "SR":
                case "VOART":
                case "IOART":
                case "SOART":
                case "VOCOM":
                case "IOCOM":
                case "SOCOM":
                case "INDCOM":
                    break;
                //Se la Categoria (RACATEG) è diversa da “VO”, “IO”, “SO”, “VOBANC”,
                //“IOBANC”, “SOBANC”, “VDAI”, “IDAI”, “SDAI”, "VR", "IR", "SR", "VOART", "IOART", "SOART", "VOCOM",
                //"IOCOM", "SOCOM", "INDCOM" il 3° Codice Natura deve
                //essere diverso da “M”
                default:
                    if (codNat3 == 'M')
                    {
                        messaggioVideo = "Il terzo codice natura deve essere diverso da M";
                        return false;
                    }
                    break;
            }

            switch (siglaCategoria)
            {
                //Solo se la Categoria (RACATEG) è = a “VO”, “SO”, “VDAI”, “SDAI”,
                //“VOBANC”, “SOBANC” il 3° Codice Natura può essere “U”
                case "VO":
                case "SO":
                case "VOBANC":
                case "SOBANC":
                case "VDAI":
                case "SDAI":
                case "IO":
                    break;
                //Se la Categoria (RACATEG) è diversa da “VO”, “SO”, “VOBANC”,
                //“SOBANC”, VDAI”, “SDAI” il 3° Codice Natura non può essere “Q”, “K”, “W”,
                //“J”, “Y”, “P”
                case "VESO33":
                case "COOP28":
                case "CRED27":
                case "VESO29":
                case "ESOTEL":
                case "ESOAMB":
                    if (Utility.IsDomandaQuota100VESO33(datiPensione) || Utility.IsDomandaQuota100COOP28(datiPensione) || Utility.IsDomandaQuota100CRED27(datiPensione) ||
                        Utility.IsDomandaQuota100VESO29(datiPensione) || Utility.IsDomandaQuota100ESOTEL(datiPensione) || Utility.IsDomandaQuota100ESOAMB(datiPensione))
                    {
                        if (codNat3 == 'K' || codNat3 == 'W' || codNat3 == 'J' || codNat3 == 'Y' || codNat3 == 'P')
                        {
                            messaggioVideo = "Il terzo codice natura non può essere uguale a K o a W o a J o a Y o a P";
                            return false;
                        }
                    }
                    else
                    {
                        if (Utility.IsDomandaESOAMB(siglaCategoria) || Utility.IsDomandaESOTEL(siglaCategoria))
                        {
                            if (codNat3 == 'Q' || codNat3 == 'K' || codNat3 == 'W' || codNat3 == 'J' || codNat3 == 'Y' || codNat3 == 'P')
                            {
                                messaggioVideo = "Il terzo codice natura non può essere uguale a Q o a K o a W o a J o a Y o a P";
                                return false;
                            }
                        }
                        else
                        {
                            if (codNat3 == 'K' || codNat3 == 'W' || codNat3 == 'J' || codNat3 == 'Y' || codNat3 == 'P')
                            {
                                messaggioVideo = "Il terzo codice natura non può essere uguale a K o a W o a J o a Y o a P";
                                return false;
                            }
                        }

                    }
                    break;
                case "ESPA":
                case "VESO92":
                case "VOCRED":
                case "VOCOOP":
                case "VOESO":
                    if (codNat3 == 'K' || codNat3 == 'W' || codNat3 == 'J' || codNat3 == 'Y' || codNat3 == 'P')
                    {
                        messaggioVideo = "Il terzo codice natura non può essere uguale a K o a W o a J o a Y o a P";
                        return false;
                    }
                    break;
                default:
                    if (codNat3 == 'Q' || codNat3 == 'K' || codNat3 == 'W' || codNat3 == 'J' || codNat3 == 'Y' || codNat3 == 'P')
                    {
                        messaggioVideo = "Il terzo codice natura non può essere uguale a Q o a K o a W o a J o a Y o a P";
                        return false;
                    }
                    break;
            }

            if (!((siglaCategoria == "VO" || siglaCategoria == "SO" || siglaCategoria == "VOBANC" || siglaCategoria == "SOBANC") && (codNat1 == '1' || codNat1 == '2')) &&
                codNat3 == 'U')
            {
                messaggioVideo = "Il terzo codice natura non può essere uguale a U";
                return false;
            }

            //Se la Decorrenza Originaria (RAU104) è inferiore a gennaio 1994 il 3°
            //Codice Natura non può essere “P”
            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1994, 01, 01)))
            {
                if (codNat3 == 'P')
                {
                    messaggioVideo = "Il terzo codice natura non può essere uguale a P";
                    return false;
                }
            }


            //Se il 1° Codice Natura è diverso da “1” o “2” il 3° Codice Natura non può
            //essere = a “Q”, “K”, “W”, “J”, “Y”, “P”
            if (codNat1 != '1' && codNat1 != '2')
            {
                bool IsCodiceGestioneSupplementi9Presente = listaSupplementi != null ? listaSupplementi.Any(x => x.CodGestioneSupplemento == "9") : false;
                if (Utility.IsRicostituzione(datiPensione.Gruppo) && IsCodiceGestioneSupplementi9Presente && Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, datiDanteCausa))
                {
                    if (codNat3 != 'X' && codNat3 != 'Y' && codNat3 != 'K' && codNat3 != 'J')
                    {
                        messaggioVideo = "Presenza di un supplemento di codice gestione 9 (prepensionamento): verificare il codice natura presente sulla pensione del dante causa e acquisirlo nel pannello dei generici";
                        return false;
                    }
                }
                else if ((codNat3 == 'Q' || codNat3 == 'K' || codNat3 == 'W' || codNat3 == 'J' ||
                            codNat3 == 'Y' || codNat3 == 'P') && siglaCategoria != null && siglaCategoria != "IO")
                {
                    messaggioVideo = "Il terzo codice natura non può essere uguale a Q o a K o a W o a J o a Y o a P";
                    return false;
                }
            }


            //Il 3° Codice Natura può essere “O” solo se la Categoria (RACATEG) è = a
            //“VO” o “VDAI”
            switch (siglaCategoria)
            {
                case "VO":
                case "VDAI":
                case "SO":
                case "SDAI":
                    break;
                default:
                    if (codNat3 == 'O' && !((Utility.IsPrepensionamentoEditoriaFiltroEAA(datiPensione) || Utility.IsPrepensionamentoEditoriaFiltroEBA(datiPensione)) && datiPensione.SiglaCategoria.Trim() == "VOPGI"))
                    {
                        messaggioVideo = "Il terzo codice natura non può essere uguale a O";
                        return false;
                    }
                    break;
            }

            //Se il campo PLAVAUT è = a 0 il 3° Codice Natura non può essere = a “N”
            if (plavaut == 0)
            {
                if (codNat3 == 'N')
                {
                    messaggioVideo = "Il terzo codice natura non può essere uguale a N";
                    return false;
                }
            }

            //Se il campo DO-NOTE è diverso da “TRA” e il campo PDIRSUP è = a 0 il 3°
            //Codice Natura non può essere = a “H”
            if (filtro != "TRA" && pdirsup == 0 && !isDomandaTrasfomazioneInvalidita && !Utility.IsRicostituzione(datiPensione.Gruppo) && !Utility.IsDomandaRipristino(datiPensione).GetValueOrDefault())
            {
                if (codNat3 == 'H')
                {
                    messaggioVideo = "Il terzo codice natura non può essere uguale a H";
                    return false;
                }
            }

            //Se il campo DO-NOTE è = a “TRA” il 3° Codice Natura deve essere = “H”
            if (filtro == "TRA")
            {
                if (codNat3 != 'H')
                {
                    messaggioVideo = "Il terzo codice natura deve essere uguale a H";
                    return false;
                }
            }

            if (isDomandaTrasfomazioneInvalidita)
            {
                if (codNat3 != 'H')
                {
                    messaggioVideo = "Il terzo codice natura deve essere uguale a H";
                    return false;
                }
            }

            //Se il Campo contributiva (RINSIEME) è = a “SI” il 3° Codice Natura deve
            //essere diverso da “G” e “O”
            if (tipoCalcolo == 1) // Contributivo
            {
                // ENG - Per le VOPGI filtro EBA il controllo sul terzo codice natura non deve essere effettuato 
                if (((!(Utility.IsRicostituzione(datiPensione.Gruppo) && tipoBeneficio == "08") && codNat3 == 'G') || codNat3 == 'O') &&
                    !(Utility.IsDomandaVOPGI(datiPensione.SiglaCategoria) && datiPensione.CodiceTipoRichiesta == "EB") &&
                    !(Utility.IsDomandaVOPGI(datiPensione.SiglaCategoria) && Utility.GetEnumTipoPLPerRICbyId(datiPensione.IdTipoPLPerRIC) == Utility.TipoPLPerRIC.RicPrepensionamentoEditoriaArt37L416_1981_LetteraB))
                {
                    messaggioVideo = "Il terzo codice natura deve essere diverso da G o da O";
                    return false;
                }
            }

            //Se il campo DO-NOTE è = a “DAI” o il campo DAU-CTR-DAI è = a “N” il 3°
            //Codice Natura deve essere = a “T”
            if (filtro == "DAI" || dauCtrDai == "N")
            {
                if (codNat3 != 'T')
                {
                    messaggioVideo = "Il terzo codice natura deve essere uguale a T";
                    return false;
                }
            }

            switch (siglaCategoria)
            {
                case "LS1":
                case "LS2":
                case "LS3":
                    break;
                //Se il campo DO-NOTE è diverso da “LS1”, “LS2”, “LS3” il 3° Codice Natura
                //non può essere = a “L”
                default:
                    if (codNat3 == 'L')
                    {
                        messaggioVideo = "Il terzo codice natura non può essere uguale a L";
                        return false;
                    }
                    break;
            }

            //Se il campo DO-NOTE è = a “LS1” oppure “LSU” con il campo DO-TIPDO =
            //a “0”, e il 1° Codice Natura è = a spazio o “6” il 3° Codice Natura deve essere
            //= a “L”
            if (filtro == "LSU" || filtro == "LS1")
            {
                if (tipoDomanda.HasValue && tipoDomanda.Value == '0' && (codNat1 == ' ' || codNat1 == '6'))
                {
                    if (codNat3 != 'L')
                    {
                        messaggioVideo = "Il terzo codice natura deve essere uguale a L";
                        return false;
                    }
                }
            }
            #endregion Controlli Terzo Codice Natura

            #region Controlli Incrociati
            switch (filtro)
            {
                //Se il campo DO-NOTE è = a “LS1”, “LS2” e il 1° Codice Natura è = a spazio,
                //“1”, “2”, “6” e il 3° Codice Natura è = a “L” la Decorrenza Originaria (RAU104)
                //deve essere tra febbraio 2003 e aprile 2004
                case "LS1":
                case "LS2":
                    if ((codNat1 == ' ' || codNat1 == '2' || codNat1 == '6') && codNat3 == 'L')
                    {
                        if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2004, 04, 30)) ||
                            !Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2003, 02, 01)))
                        {
                            messaggioVideo = "La decorrenza originaria deve essere compresa tra febbraio 2003 e aprile 2004";
                            return false;
                        }
                    }
                    break;
                //Se il campo DO-NOTE è = a “LSU” e il 1° Codice Natura è = a spazio, “1”,
                //“2”, “6” e il 3° Codice Natura è = a “ L” la Decorrenza Originaria (RAU104)
                //deve essere tra luglio 1998 e maggio 2001
                case "LSU":
                    if ((codNat1 == ' ' || codNat1 == '2' || codNat1 == '6') && codNat3 == 'L')
                    {
                        if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2001, 05, 31)) ||
                            !Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1998, 07, 01)))
                        {
                            messaggioVideo = "La decorrenza originaria deve essere compresa tra luglio 1998 e maggio 2001";
                            return false;
                        }
                    }
                    break;
                default:
                    break;
            }

            //Verificare congruità tra 1° Codice Natura e 2° Codice Natura: non sono
            //congrui se il 1° Codice Natura è = a spazio, “0”, “1”, “3”, “8” e il 2° Codice
            //Natura è = a “A”, “C”, “L”, “R”, “T”, “Z”
            if ((codNat1 == ' ' || codNat1 == '0' || codNat1 == '1' || codNat1 == '3' || codNat1 == '8') &&
                (codNat2 == 'A' || codNat2 == 'C' || codNat2 == 'L' || codNat2 == 'R' || codNat2 == 'T' || codNat2 == 'Z'))
            {
                messaggioVideo = "Il primo codice natura ed il secondo codice natura non sono congrui. " +
                    "La non congruità si ha quando il primo codice natura è vuoto o uguale a 0 o a 1 o a 3 o a 8 ed il " +
                    "secondo codice natura è uguale a A o a C o a L o a R o a T o a Z";
                return false;
            }

            //Il 2° Codice Natura e il 3° Codice Natura non possono essere = entrambi a
            //“X”
            if (codNat2 == 'X' && codNat3 == 'X')
            {
                messaggioVideo = "Il secondo ed il terzo codice natura non possono essere entrambi uguali a X";
                return false;
            }

            if (!Utility.IsRicostituzione(datiPensione.Gruppo))
            {
                //Se il 2° Codice Natura è = a “X” e il campo DO-NOTE è diverso da “SCO”
                //verificare che il 1° Codice Natura sia = a “1” e la Categoria (RACATEG) sia =
                //a “VO”, “SO”, “VDAI”, “SDAI”, “VOBANC”, “SOBANC”
                if (codNat2 == 'X' && filtro != "SCO")
                {
                    if (codNat1 != '1')
                    {
                        messaggioVideo = "Il primo codice natura deve essere uguale a 1";
                        return false;
                    }
                    switch (siglaCategoria)
                    {
                        case "VO":
                        case "SO":
                        case "VDAI":
                        case "SDAI":
                        case "VOBANC":
                        case "SOBANC":
                            break;
                        default:
                            messaggioVideo = "Il secondo codice natura non è valido per la categoria e il filtro associati alla domanda";
                            return false;
                    }
                }
                //Il 2° Codice Natura può essere = a “X” solo se il campo DO-NOTE è = a
                //“SCO” oppure il (1° carattere della Categoria (RACATEG) = “S” e il campo
                //DAU107 è = a “1” o “2”)
                else if (codNat2 == 'X')
                {
                    if (!(siglaCategoria.Substring(0, 1) == "S" && (codProv == 1 || codProv == 2)))
                    {
                        messaggioVideo = "Il secondo codice natura non può essere uguale a X";
                        return false;
                    }
                }
            }

            //Il 3° Codice Natura può essere = a “X” se il 1° Codice Natura è diversa da “1”
            //o “2” e l'Attività Economica (RAU1013) = a 94 e a Professione Individuale
            //(RAU1014) = a 984
            //Il 3° Codice Natura può essere = a “X” se la Categoria (RACATEG) è 
            //= a “IO”, “IDAI”, “IOBANC” con l'Attività Economica (RAU1013) = a 94
            //e a Professione Individuale (RAU1014) = a 984
            if (codNat3 == 'X')
            {
                //Per tutte le domande di trasformazione e ricostituzione della linea AGO (non ENPALS) è necessario rimuovere il controllo
                if (!(Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) &&
                    !Utility.IsDomandaENPALS(datiPensione.Gestione)) && !Utility.IsDomandaVOMIN(datiPensione.SiglaCategoria))
                {
                    if (!((codNat1 != '1' && codNat1 != '2' && attivitaEconomica == 94 && professioneIndividuale == 984) ||
                    ((siglaCategoria == "IO" || siglaCategoria == "IDAI" || siglaCategoria == "IOBANC") && attivitaEconomica == 94 && professioneIndividuale == 984)))
                    {
                        messaggioVideo = "Il terzo codice natura non può essere uguale a X";
                        return false;
                    }
                }
            }

            if (Utility.IsDomandaENPALS(datiPensione.Gestione) && Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, datiDanteCausa) &&
                Utility.IsPensioneInvaliditaInabilitaENPALSOrCasellario(datiDanteCausa))
            {
                if (datiDanteCausa.DecorrenzaPensione.HasValue && Utility.DataSuccessivaA(datiDanteCausa.DecorrenzaPensione.Value, new DateTime(1984, 8, 1)) &&
                    (codNat1 != '3' && codNat1 != '4' && codNat1 != '5' && (datiDanteCausa.SiglaCategoria == "IOSPORT" || codNat2 != '1')))
                {
                    messaggioVideo = "Il primo codice natura ed il secondo codice natura non sono congrui. " +
                                     "E' necessario verificare che il primo codice natura sia 3 o 4 o 5 e/o che il secondo codice natura sia 1";
                    return false;
                }
            }

            if (!ControlsNatura_AttEc(codNat1, codNat3, filtro, attivitaEconomica, out messaggioVideo))
                return false;

            if (!ControlsNatura_ProfInd(codNat1, codNat3, filtro, professioneIndividuale, out messaggioVideo))
                return false;

            if (!GestioneCrossControls.ALL_CodNaturOrganizzazioniInternazionali(datiPensione, naturaPensione, out messaggioVideo))
                return false;

            #endregion Controlli Incrociati
            return true;
        }

        public static bool ControlsAttivitaEconomica(int? attivitaEconomica, string naturaPensione, int? professioneIndividuale,
            char? codiceLiquidazione, GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, GestioneDanteCausa.DatiDanteCausa danteCausa, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';
            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            int pdirsup = 0;
            int plavaut = 0;

            #region Recupero Dati
            Utility.GetCodiciNatura(naturaPensione, out codNat1, out codNat2, out codNat3);

            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);
            GetPdirusp_Plavaut(datiPensione, out pdirsup, out plavaut);

            //ENG - RIC/TRF (NO ENPALS): rendere non obbligatori i campi "Attivita Economica" e "Professione Individuale" se dal prelievo arrivano vuoti
            GestioneDatiStoricoGP.DatiStoricoGP datiStoricoGP = null;
            GestioneDatiStoricoGP.GetDatiStoricoGPByIdPensione(datiPensione.Id, out datiStoricoGP);

            #endregion Recupero Dati

            if (Utility.IsDomandaINPDAI(datiPensione.SiglaCategoria) && !Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1997, 1, 1)) && Utility.IsDomandaRipristino(datiPensione).GetValueOrDefault() && GestioneBypassControllo.CheckBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.BYPASS_ANTE96_BANC_AGO))
                return true;

            if (!ControlsNatura_AttEc(codNat1, codNat3, filtro, attivitaEconomica, out messaggioVideo))
                return false;

            //L'Attività Economica (RAU1013) e la Professione Individuale (RA1014)
            //quando vanno acquisiti sono sempre in coppia, quindi o ci sono entrambi o
            //non ci sono entrambi


            if (((attivitaEconomica.HasValue && attivitaEconomica.Value != 0 && (!professioneIndividuale.HasValue || professioneIndividuale.Value == 0)) ||
                (professioneIndividuale.HasValue && professioneIndividuale.Value != 0 && (!attivitaEconomica.HasValue || attivitaEconomica.Value == 0))))
            {
                messaggioVideo = "Attività economica e professione individuale vanno acquisiti in coppia, quindi o ci sono entrambi o non ci sono entrambi";
                return false;
            }

            //Se la domanda è quota 100, quota 102 oppure APE precoci non deve essere possibile acquisire attività economica e professione individuale relative all'amianto
            if ((((Utility.IsDomandaQuota100(datiPensione) || Utility.IsDomandaQuota102(datiPensione)) && !Utility.IsRicostituzione(datiPensione.Gruppo)) ||
                Utility.IsDomandaAPEPrecoci(datiPensione) ||
                Utility.IsRenditaCasalinghe(datiPensione) ||
                Utility.IsRenditaFacoltativa(datiPensione)) &&
                (attivitaEconomica.HasValue && professioneIndividuale.HasValue))
            {
                if ((attivitaEconomica == 3 && professioneIndividuale == 326) || (attivitaEconomica == 3 && professioneIndividuale == 350) ||
                    (attivitaEconomica == 4 && professioneIndividuale == 350) || (attivitaEconomica == 92 && professioneIndividuale == 257) ||
                    (attivitaEconomica == 7 && professioneIndividuale == 247) || (attivitaEconomica == 2 && professioneIndividuale == 247) ||
                    (attivitaEconomica == 14 && professioneIndividuale == 190))
                {
                    messaggioVideo = string.Format("La combinazione attività economica - professione individuale {0} - {1} non è ammessa per questa tipologia di domanda", attivitaEconomica.ToString().PadLeft(2, '0'), professioneIndividuale);
                    return false;
                }
            }

            //Se la domanda è automatica non è possibile inserire attivà economica e professioneIndividuale di aminato 181 manualmente.
            if (Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica)
            {
                if ((datiPensione.Amianto181Unicarpe != true) && Utility.IsDomandaConBeneficioAmianto181(attivitaEconomica, professioneIndividuale))
                {
                    messaggioVideo = "Non è possibile inserire attività economica 14 e professione individuale 190.";
                    return false;
                }
            }

            //Se inserisco AttEconom e ProfIndiv bypasso tutti i controlli su tali campi
            if (Utility.IsDomandaConBeneficioAmianto181(attivitaEconomica, professioneIndividuale))
                return true;

            switch (siglaCategoria)
            {
                //Se la Categoria (RACATEG) è = a “VOSPED”, “IOSPED”, “SOSPED”
                //l'Attività Economica (RAU1013) e la Professione Individuale (RAU1014)
                //devono essere assenti
                case "VOSPED":
                case "IOSPED":
                case "SOSPED":
                    if ((attivitaEconomica.HasValue && attivitaEconomica.Value != 0) ||
                        (professioneIndividuale.HasValue && professioneIndividuale.Value != 0))
                    {
                        messaggioVideo = "Attività economica e professione individuale devono essere assenti";
                        return false;
                    }
                    break;
                //Se la Categoria (RACATEG) è = a “VMP”, “IMP” il Codice Attività Economica
                //(RAU1013) deve essere = a “25”
                case "VMP":
                case "IMP":
                    if (!attivitaEconomica.HasValue || attivitaEconomica.Value != 25)
                    {
                        messaggioVideo = "L'attività economica deve essere 25";
                        return false;
                    }
                    break;
                //Se la Categoria (RACATEG) è = a “INDCOM” il Codice Attività Economica
                //(RAU1013) deve essere = a “61”
                case "INDCOM":
                    if (!attivitaEconomica.HasValue || attivitaEconomica.Value != 61)
                    {
                        messaggioVideo = "L'attività economica deve essere 61";
                        return false;
                    }
                    break;
                //Se Categoria (RACATEG) è = a “VDAI”, “IDAI”, “SDAI” verificare i Codici
                //Attività Economica (RAU1013) e Professionale Individuale (RAU1014); se in
                //coppia sono i seguenti lasciare invariato i due dati:
                //A.E. P.I.
                //92 257
                //3 326
                //3 350
                //4 350
                //7 247
                //2 347
                //71 194
                //altrimenti se la Professione Individuale (RAU1014) non è = a “194”, “247”
                // la Professione Individuale deve essere “194”
                case "VDAI":
                case "IDAI":
                case "SDAI":
                    if ((attivitaEconomica.GetValueOrDefault() == 92 && professioneIndividuale.GetValueOrDefault() != 257) ||
                        (attivitaEconomica.GetValueOrDefault() != 92 && professioneIndividuale.GetValueOrDefault() == 257))
                    {
                        messaggioVideo = "Se l'attività economica è pari a 92 la professione individuale deve essere pari a 257 e viceversa";
                        return false;
                    }
                    if ((attivitaEconomica.GetValueOrDefault() == 3 && professioneIndividuale.GetValueOrDefault() != 326 && professioneIndividuale.GetValueOrDefault() != 350) ||
                        (attivitaEconomica.GetValueOrDefault() != 3 && professioneIndividuale.GetValueOrDefault() == 326) ||
                        (attivitaEconomica.GetValueOrDefault() != 3 && attivitaEconomica.GetValueOrDefault() != 4 && professioneIndividuale.GetValueOrDefault() == 350) ||
                        (attivitaEconomica.GetValueOrDefault() == 4 && professioneIndividuale.GetValueOrDefault() != 326 && professioneIndividuale.GetValueOrDefault() != 350))
                    {
                        messaggioVideo = "Se l'attività economica è pari a 3 la professione individuale deve essere pari a 326 o a 350. " +
                            "Se la professione individuale è pari a 326 l'attività economica deve essere pari a 3, se la professione individuale è " +
                            "pari a 350, l'attività economica deveessere pari a 3 o a 4. Se l'attività economica è pari a 4, la professione individuale " +
                            "deve essere pari a 350";
                        return false;
                    }
                    if ((attivitaEconomica.GetValueOrDefault() == 7 && professioneIndividuale.GetValueOrDefault() != 247) ||
                        (attivitaEconomica.GetValueOrDefault() != 7 && professioneIndividuale.GetValueOrDefault() == 247))
                    {
                        messaggioVideo = "Se l'attività economica è pari a 7 la professione individuale deve essere pari a 247 e viceversa";
                        return false;
                    }
                    if ((attivitaEconomica.GetValueOrDefault() == 2 && professioneIndividuale.GetValueOrDefault() != 347) ||
                        (attivitaEconomica.GetValueOrDefault() != 2 && professioneIndividuale.GetValueOrDefault() == 347))
                    {
                        messaggioVideo = "Se l'attività economica è pari a 2 la professione individuale deve essere pari a 347 e viceversa";
                        return false;
                    }
                    if ((attivitaEconomica.GetValueOrDefault() == 71 && professioneIndividuale.GetValueOrDefault() != 194) ||
                        (attivitaEconomica.GetValueOrDefault() != 71 && professioneIndividuale.GetValueOrDefault() == 194))
                    {
                        messaggioVideo = "Se l'attività economica è pari a 71 la professione individuale deve essere pari a 194 e viceversa";
                        return false;
                    }

                    //Se Categoria (RACATEG) è = a “VDAI”, “IDAI”, “SDAI” e la Decorrenza
                    //Originaria (RAU104) è inferiore a febbraio 2003 l'Attività Economica
                    //(RAU1013) e la Professione Individuale (RAU1014) non possono essere
                    //rispettivamente “92” e “257”
                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2003, 02, 01)))
                    {
                        if ((attivitaEconomica.HasValue && attivitaEconomica.Value == 92) ||
                            (professioneIndividuale.HasValue && professioneIndividuale.Value == 257))
                        {
                            messaggioVideo = "L'attività economica e la professione individuale non possono essere rispettivamente 92 e 257";
                            return false;
                        }
                    }

                    if (!((attivitaEconomica.HasValue && attivitaEconomica.Value == 92 && professioneIndividuale.HasValue && professioneIndividuale.Value == 257) ||
                        (attivitaEconomica.HasValue && attivitaEconomica.Value == 3 && professioneIndividuale.HasValue && professioneIndividuale.Value == 326) ||
                        (attivitaEconomica.HasValue && attivitaEconomica.Value == 3 && professioneIndividuale.HasValue && professioneIndividuale.Value == 350) ||
                        (attivitaEconomica.HasValue && attivitaEconomica.Value == 4 && professioneIndividuale.HasValue && professioneIndividuale.Value == 350) ||
                        (attivitaEconomica.HasValue && attivitaEconomica.Value == 7 && professioneIndividuale.HasValue && professioneIndividuale.Value == 247) ||
                        (attivitaEconomica.HasValue && attivitaEconomica.Value == 2 && professioneIndividuale.HasValue && professioneIndividuale.Value == 347) ||
                        (attivitaEconomica.HasValue && attivitaEconomica.Value == 71 && professioneIndividuale.HasValue && professioneIndividuale.Value == 194) ||
                        (attivitaEconomica.HasValue && attivitaEconomica.Value == 15 && professioneIndividuale.HasValue && professioneIndividuale.Value == 208) || // 15-208 amianto
                        (attivitaEconomica.HasValue && attivitaEconomica.Value == 67 && professioneIndividuale.HasValue && professioneIndividuale.Value == 11)))
                    {
                        if (professioneIndividuale.HasValue &&
                            professioneIndividuale.Value != 194 && professioneIndividuale.Value != 247)
                        {
                            messaggioVideo = "La professione individuale deve essere 194";
                            return false;
                        }
                    }
                    break;
                //Se la Categoria (RACATEG) è = a “VOAUT”, “IOAUT”, “SOAUT” e il Codice
                //Liquidazione (RAUE23) è diverso da “P” il Codice Attività Economica
                //(RAU1013) deve essere = a “71”
                case "VOAUT":
                case "IOAUT":
                case "SOAUT":
                    if ((!codiceLiquidazione.HasValue || codiceLiquidazione.Value.ToString().ToUpperInvariant() != "P") && !Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                    {
                        if (!attivitaEconomica.HasValue || attivitaEconomica.Value != 71)
                        {
                            messaggioVideo = "L'attività economica deve essere 71";
                            return false;
                        }
                    }
                    break;
                default:
                    break;
            }

            //Se il Campo P-DIRSUP è = a zero e la Decorrenza Originaria (RAU104) è
            //inferiore a gennaio 2008 l'Attività Economica (RAU1013) e la Professione
            //Individuale (RAU1014) non possono essere rispettivamente “7” e “247” o “2”
            //e “247”
            if (pdirsup == 0)
            {
                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 01, 01)))
                {
                    if ((attivitaEconomica.HasValue && attivitaEconomica.Value == 7 && professioneIndividuale.HasValue && professioneIndividuale.Value == 247) ||
                        (attivitaEconomica.HasValue && attivitaEconomica.Value == 2 && professioneIndividuale.HasValue && professioneIndividuale.Value == 247))
                    {
                        messaggioVideo = "L'attività economica e la professione individuale non possono essere " +
                            "rispettivamente 7 e 247 o 2 e 247";
                        return false;
                    }
                }
            }
            //Se il Campo P-DIRSUP è = a 1 e la Decorrenza Originaria (RAU104) è
            //inferiore a febbraio 2008 l'Attività Economica (RAU1013) e la Professione
            //Individuale (RAU1014) non possono essere rispettivamente “7” e “247” o “2”
            //e “247”
            else if (pdirsup == 1)
            {
                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 02, 01)))
                {
                    if ((attivitaEconomica.HasValue && attivitaEconomica.Value == 7 && professioneIndividuale.HasValue && professioneIndividuale.Value == 247) ||
                        (attivitaEconomica.HasValue && attivitaEconomica.Value == 2 && professioneIndividuale.HasValue && professioneIndividuale.Value == 247))
                    {
                        messaggioVideo = "L'attività economica e la professione individuale non possono essere " +
                            "rispettivamente 7 e 247 o 2 e 247";
                        return false;
                    }
                }
            }

            //Se la Data Perfezionamento Requisito (PERFREQ) è successiva al 31
            //dicembre 2011 l'Attività Economica (RAU1013) e la Professione Individuale
            //(RAU1014) non possono essere rispettivamente “99” e “247” o “65” e “999
            if (datiPensione.DataPerfezionamentoRequisiti.HasValue &&
                Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 12, 31)))
            {
                if ((attivitaEconomica.HasValue && attivitaEconomica.Value == 99 && professioneIndividuale.HasValue && professioneIndividuale.Value == 247) ||
                    (attivitaEconomica.HasValue && attivitaEconomica.Value == 65 && professioneIndividuale.HasValue && professioneIndividuale.Value == 999))
                {
                    messaggioVideo = "L'attività economica e la professione individuale non possono essere " +
                        "rispettivamente 99 e 247 o 65 e 999";
                    return false;
                }
            }

            //Ad eccezione delle Categorie (RACATEG) “VOSPED”, “IOSPED”,
            //SOSPED”quando il Codice Liquidazione (RAUE23) è diverso da “P” l'Attività
            //Economica (RAU1013) e la Professione Individuale (RAU1014) devono
            //essere acquisiti
            switch (siglaCategoria)
            {
                case "VOSPED":
                case "IOSPED":
                case "SOSPED":
                case "VOST":
                case "PSO":
                    break;
                default:

                    //ENG - RIC/TRF (NO ENPALS): rendere non obbligatori i campi "Attivita Economica" e "Professione Individuale" se dal prelievo arrivano vuoti
                    bool verificaPresenzaAttivitaEconomicaProfessioneIndividuale = true;
                    if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && !Utility.IsDomandaENPALS(datiPensione.Gestione))
                    {
                        if (datiStoricoGP != null)
                        {
                            if (!datiStoricoGP.AttivitaEconomica.HasValue || datiStoricoGP.AttivitaEconomica.Value == 0 || !datiStoricoGP.ProfessioneIndividuale.HasValue
                                || datiStoricoGP.ProfessioneIndividuale.Value == 0)
                                verificaPresenzaAttivitaEconomicaProfessioneIndividuale = false;
                        }
                    }

                    if (!(Utility.IsDomandaRipristino(datiPensione).Value && Utility.IsDomandaINPGI(datiPensione) && datiPensione.GP1AV91B == "2"))
                    {
                        if (!codiceLiquidazione.HasValue || codiceLiquidazione.Value.ToString().ToUpperInvariant() != "P")
                        {
                            if (!attivitaEconomica.HasValue || !professioneIndividuale.HasValue)
                            {
                                if (verificaPresenzaAttivitaEconomicaProfessioneIndividuale)
                                {
                                    messaggioVideo = "L'attività economica e la professione individuale devono essere acquisiti";
                                    return false;
                                }
                            }
                        }
                    }


                    break;
            }

            return true;
        }

        public static bool ControlsPrepensionamentoEditoriaCodiceAnagraficaAccordi(GestionePensione.DatiPensione datiPensione, short? codiceAziendaEditoria, ref EntityBLCommon.ContenitoreDecodifica contenitoreDecodifica, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            List<Entity.DecAnagraficaAccordi> elencoAnagraficaAccordi = null;
            Entity.DecAnagraficaAccordi anagraficaAccordi = new Entity.DecAnagraficaAccordi();
            GestioneLiquidazionePensione.GetAnagraficaAccordi(ref contenitoreDecodifica, out elencoAnagraficaAccordi);
            anagraficaAccordi = elencoAnagraficaAccordi.Find(x => x.Codice == codiceAziendaEditoria);

            if (!codiceAziendaEditoria.HasValue && !(Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaSO(datiPensione.SiglaCategoria)))
            {
                messaggioVideo = "Inserire un codice azienda editoria.";
                return false;
            }

            if (Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Ricostituzione)
                return true;

            if (anagraficaAccordi == null)
            {
                messaggioVideo = "Attenzione: il Codice Accordo inserito non rientra attualmente tra quelli censiti per la liquidazione della prestazione di prepensionamento ex art. 37.";
                return false;
            }

            if (anagraficaAccordi.Codice.HasValue && (anagraficaAccordi.Abilitata == false))
            {
                messaggioVideo = "Il flag per il codice selezionato è impostato a false.";
                return false;
            }
            return true;
        }

