        public static bool ControlsPrepensionamentoEditoriaPerTipo0171CodiceAnagraficaAccordi(ref EntityBLCommon.ContenitoreObject contenitore, ref EntityBLCommon.ContenitoreDecodifica contenitoreDecodifica,
            short? codiceAziendaEditoriaPerTipo0171, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            List<Entity.DecAnagraficaAccordiPerTipo0171> elencoAnagraficaAccordi = null;
            GestioneLiquidazionePensione.GetAnagraficaAccordi(ref contenitoreDecodifica, out elencoAnagraficaAccordi);
            Entity.DecAnagraficaAccordiPerTipo0171 anagraficaAccordi = new Entity.DecAnagraficaAccordiPerTipo0171();
            anagraficaAccordi = elencoAnagraficaAccordi.Find(x => x.Codice == codiceAziendaEditoriaPerTipo0171);

            if (!codiceAziendaEditoriaPerTipo0171.HasValue)
            {
                messaggioVideo = "Inserire un codice azienda editoria.";
                return false;
            }

            if (Utility.GetTipoDomanda(contenitore.DatiPensione.Gruppo, contenitore.DatiPensione.Prodotto) == Utility.TipoDomanda.Ricostituzione)
                return true;

            if (anagraficaAccordi == null)
            {
                messaggioVideo = "Il codice non è presente";
                return false;
            }

            if (anagraficaAccordi.Codice.HasValue && anagraficaAccordi.Abilitata == false)
            {
                messaggioVideo = "Il flag per il codice selezionato è impostato a false.";
                return false;
            }

            if (contenitore.DatiPensione.DecorrenzaOriginaria.HasValue && anagraficaAccordi.DataAccordi.HasValue &&
                !Utility.DataStrettamenteSuccessivaA(contenitore.DatiPensione.DecorrenzaOriginaria.Value, anagraficaAccordi.DataAccordi.Value))
            {
                messaggioVideo = string.Format("La Decorrenza Pensione ({0:dd/MM/yyyy}) deve essere strettamente maggiore alla Data Accordi ({1:dd/MM/yyyy}).", contenitore.DatiPensione.DecorrenzaOriginaria,
                    anagraficaAccordi.DataAccordi);
                return false;
            }

            return true;
        }

