        public static bool ControlsPrepensionamentoEditoriaPerTipo0171OneriAzienda(ref EntityBLCommon.ContenitoreObject contenitore, ref EntityBLCommon.ContenitoreDecodifica contenitoreDecodifica,
            short? codiceAziendaEditoriaPerTipo0171, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsPrepensionamentoEditoriaArt1c154L205_2017(contenitore.DatiPensione))
            {
                List<Entity.DecAnagraficaAccordiPerTipo0171> elencoAnagraficaAccordi = null;
                GestioneLiquidazionePensione.GetAnagraficaAccordi(ref contenitoreDecodifica, out elencoAnagraficaAccordi);

                Entity.DecAnagraficaAccordiPerTipo0171 anagraficaAccordi = new Entity.DecAnagraficaAccordiPerTipo0171();

                if (elencoAnagraficaAccordi != null && elencoAnagraficaAccordi.Count > 0)
                {
                    anagraficaAccordi = elencoAnagraficaAccordi.FirstOrDefault(x => x.Codice.Equals(codiceAziendaEditoriaPerTipo0171));
                    if (anagraficaAccordi != null)
                    {
                        List<Entity.DecAnagraficaAziendePerTipo0171> elencoAnagraficaAziende = null;
                        GestioneLiquidazionePensione.GetAnagraficaAziende(ref contenitoreDecodifica, out elencoAnagraficaAziende);

                        if (elencoAnagraficaAziende != null && elencoAnagraficaAziende.Count > 0)
                        {
                            Entity.DecAnagraficaAziendePerTipo0171 anagraficaAziende = elencoAnagraficaAziende.FirstOrDefault(x => x.Id == anagraficaAccordi.DenominazioneAzienda);
                            if (anagraficaAziende != null)
                            {
                                if (contenitoreDecodifica.ElencoDecCodeSottoGruppoOnere != null && contenitoreDecodifica.ElencoDecCodeSottoGruppoOnere.Count > 0)
                                {
                                    GestioneDecodifica.SottoGruppoOneri primoSottoGruppoOneri = contenitoreDecodifica.ElencoDecCodeSottoGruppoOnere.FirstOrDefault(x => x.Code == anagraficaAziende.SottogruppoPrimoOnere);
                                    if (primoSottoGruppoOneri == null)
                                    {
                                        messaggioVideo = string.Format("Il sottogruppo {0} presente per l'azienda {1} risulta errato.", anagraficaAziende.SottogruppoPrimoOnere, anagraficaAziende.DenominazioneAzienda);
                                        return false;
                                    }
                                    GestioneDecodifica.SottoGruppoOneri secondoSottoGruppoOneri = null;
                                    if (!string.IsNullOrEmpty(anagraficaAziende.SottogruppoSecondoOnere))
                                    {
                                        secondoSottoGruppoOneri = contenitoreDecodifica.ElencoDecCodeSottoGruppoOnere.FirstOrDefault(x => x.Code == anagraficaAziende.SottogruppoSecondoOnere);
                                        if (secondoSottoGruppoOneri == null)
                                        {
                                            messaggioVideo = string.Format("Il sottogruppo {0} presente per l'azienda {1} risulta errato.", anagraficaAziende.SottogruppoSecondoOnere, anagraficaAziende.DenominazioneAzienda);
                                            return false;
                                        }
                                    }

                                    if (contenitore.ListaDatiOneri == null || contenitore.ListaDatiOneri.Count(x => x.IdCodeGruppo == primoSottoGruppoOneri.IdOnere) > 2 ||
                                        !contenitore.ListaDatiOneri.Exists(x => x.IdCodeSottoGruppo == primoSottoGruppoOneri.Id) ||
                                        (secondoSottoGruppoOneri != null && !contenitore.ListaDatiOneri.Exists(x => x.IdCodeSottoGruppo == secondoSottoGruppoOneri.Id)))
                                    {
                                        messaggioVideo = "Gli oneri presenti sulla domanda risultano incongruenti rispetto all'azienda inserita.";
                                        return false;
                                    }
                                }
                            }
                        }
                    }
                }
            }

            return true;
        }

