                                    if (contenitore.ListaDatiOneri == null || contenitore.ListaDatiOneri.Count(x => x.IdCodeGruppo == primoSottoGruppoOneri.IdOnere) > 2 ||
                                        !contenitore.ListaDatiOneri.Exists(x => x.IdCodeSottoGruppo == primoSottoGruppoOneri.Id) ||
                                        (secondoSottoGruppoOneri != null && !contenitore.ListaDatiOneri.Exists(x => x.IdCodeSottoGruppo == secondoSottoGruppoOneri.Id)))
                                    {
                                        messaggioVideo = "Gli oneri presenti sulla domanda risultano incongruenti rispetto all'azienda inserita.";
                                        return false;
                                    }
                                }
                            }
                        }
                    }
                }
            }

            return true;
        }

        public static bool ControlsProfessioneIndividuale(int? professioneIndividuale, int? attivitaEconomica, string naturaPensione, char? codiceLiquidazione,
            GestionePensione.DatiPensione datiPensione, List<GestioneDecodifica.CtrlEnteCassaCodiceGestione> ElencoCtrlEnteCassaCodiceGestione, string enteCassa, bool isRiaperturaDomanda, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';
            string filtro = string.Empty;
            string siglaCategoria = string.Empty;

            #region Recupero Dati
            Utility.GetCodiciNatura(naturaPensione, out codNat1, out codNat2, out codNat3);

            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            #endregion Recupero Dati

            if (!ControlsNatura_ProfInd(codNat1, codNat3, filtro, professioneIndividuale, out messaggioVideo))
                return false;

            if (Utility.IsDomandaConBeneficioAmianto181(attivitaEconomica, professioneIndividuale))
                return true;

            switch (siglaCategoria)
            {
                //Se la Categoria (RACATEG) è = a “VMP”, “IMP” la Professione Individuale
                //deve essere “191”
                case "VMP":
                case "IMP":
                    if (!professioneIndividuale.HasValue || professioneIndividuale.Value != 191)
                    {
                        messaggioVideo = "La professione individuale deve essere 191";
                        return false;
                    }
                    break;
                case "INDCOM":
                    //Se la Categoria (RACATEG) è = a “INDCOM” la Professione Individuale deve
                    //essere “172”
                    if (!professioneIndividuale.HasValue || professioneIndividuale.Value != 172)
                    {
                        messaggioVideo = "La professione individuale deve essere 172";
                        return false;
                    }
                    break;
                //Se la Categoria (RACATEG) è = a “VOAUT”, “IOAUT”, “SOAUT” e il Codice
                //Liquidazione (RAUE23) è diverso da “P” la Professione Individuale deve
                //essere “174”
                case "VOAUT":
                case "IOAUT":
                case "SOAUT":
                    if ((!codiceLiquidazione.HasValue || codiceLiquidazione.Value.ToString().ToUpperInvariant() != "P") && !Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                    {
                        if (!professioneIndividuale.HasValue || professioneIndividuale.Value != 174)
                        {
                            messaggioVideo = "La professione individuale deve essere 174";
                            return false;
                        }
                    }
                    break;
                case "IOCUM":
                case "SOCUM":
                    if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                    {
                        if (ElencoCtrlEnteCassaCodiceGestione != null && ElencoCtrlEnteCassaCodiceGestione.Count > 0 && professioneIndividuale.HasValue)
                        {
                            var professioneCensita = ElencoCtrlEnteCassaCodiceGestione.Where(x => x.CodiceCategoria == siglaCategoria.ToString() && x.TraduzioneSuGP == enteCassa).Select(x => x.Professione).FirstOrDefault();
                            if ((professioneIndividuale.Value.ToString()).PadLeft(3, '0') != professioneCensita && professioneCensita != null)
                            {
                                messaggioVideo = string.Format("La professione individuale deve essere {0} in corrispondenza di ente cassa {1}", professioneCensita, enteCassa);
                                return false;
                            }
                        }
                        if (enteCassa == "0801" && ElencoCtrlEnteCassaCodiceGestione.Where(x => x.CodiceCategoria == siglaCategoria.ToString() && x.Professione == professioneIndividuale.Value.ToString().PadLeft(3, '0') && attivitaEconomica == 71).Count() > 0)
                        {
                            messaggioVideo = string.Format("La professione individuale non può essere {0} in corrispondenza di ente cassa {1} e attività economica 71", professioneIndividuale, enteCassa);
                            return false;
                        }
                    }
                    break;
                case "VOTOT":
                case "SOTOT":
                case "IOTOT":
                    if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                    {
                        if (ElencoCtrlEnteCassaCodiceGestione != null && ElencoCtrlEnteCassaCodiceGestione.Count > 0 && professioneIndividuale.HasValue)
                        {
                            var professioneCensita = ElencoCtrlEnteCassaCodiceGestione.Where(x => x.CodiceCategoria == siglaCategoria.ToString() && x.TraduzioneSuGP == enteCassa).Select(x => x.Professione).FirstOrDefault();
                            if ((professioneIndividuale.Value.ToString()).PadLeft(3, '0') != professioneCensita && professioneCensita != null && attivitaEconomica == 71)
                            {
                                messaggioVideo = string.Format("La professione individuale deve essere {0} in corrispondenza di ente cassa {1} e attività economica 71", professioneCensita, enteCassa);
                                return false;
                            }
                        }
                        if (!((attivitaEconomica == 92 && professioneIndividuale == 257) || (attivitaEconomica == 03 && (professioneIndividuale == 350 || professioneIndividuale == 326)) ||
                       (attivitaEconomica == 04 && professioneIndividuale == 350) || (attivitaEconomica == 07 && professioneIndividuale == 247) ||
                       (attivitaEconomica == 02 && professioneIndividuale == 247) || (attivitaEconomica == 15 && professioneIndividuale == 198) ||
                       (attivitaEconomica == 14 && professioneIndividuale == 190)) && enteCassa != "0801" && attivitaEconomica != 71)
                        {
                            string professioneConsentita = string.Empty;
                            switch (attivitaEconomica)
                            {
                                case 92:
                                    professioneConsentita = "257";
                                    break;
                                case 03:
                                    professioneConsentita = "350 o 326";
                                    break;
                                case 04:
                                    professioneConsentita = "350";
                                    break;
                                case 07:
                                case 02:
                                    professioneConsentita = "247";
                                    break;
                                case 15:
                                    professioneConsentita = "198";
                                    break;
                                case 14:
                                    professioneConsentita = "190";
                                    break;
                                default:
                                    break;
                            }

                            if (!string.IsNullOrEmpty(professioneConsentita))
                                messaggioVideo = string.Format("La professione individuale deve essere {0} in corrispondenza di ente cassa {1} e attività economica {2}", professioneConsentita, enteCassa, attivitaEconomica);
                            else
                                messaggioVideo = string.Format("La combinazione attività economica {0} e professione individuale {1} in corrispondenza di ente cassa {2} non è consentita ", attivitaEconomica, professioneIndividuale, enteCassa);
                            return false;
                        }

                        if (enteCassa == "0801" && ElencoCtrlEnteCassaCodiceGestione.Where(x => x.CodiceCategoria == siglaCategoria.ToString() && x.Professione == professioneIndividuale.Value.ToString().PadLeft(3, '0') && attivitaEconomica == 71).Count() > 0)
                        {
                            messaggioVideo = string.Format("La professione individuale non può essere {0} in corrispondenza di ente cassa {1} e attività economica 71", professioneIndividuale, enteCassa);
                            return false;
                        }
                    }
                    break;
                default:
                    break;
            }

            return true;
        }

        public static bool ControlsCodiceArretrati(byte? codiceArretrati, byte? codiceEliminazione, GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, bool? tipoCumulo, char? cumuloEsterno, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            //Il Codice Accantonamento Arretrati (RAU604) può essere solo 1 o 8
            if (!codiceArretrati.HasValue || (codiceArretrati.Value != 1 && codiceArretrati.Value != 8))
            {
                messaggioVideo = "Il codice accantonamento arretrati è obbligatorio";
                return false;
            }

            if (!GestioneCrossControls.ALL_VerificaCodiceArretratiWithEliminazione(codiceEliminazione, codiceArretrati, datiPensione, out messaggioVideo, isRiaperturaDomanda))
                return false;

            return true;
        }

        public static bool ControlsDecorrenzaArretrati(DateTime? decorrenzaArretrati, DateTime? dataRipristino, GestionePensione.DatiPensione datiPensione, byte? causaCarico, int annoCompetenza,
            bool isRiaperturaDomanda, short? codiceBancaEsodati, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            string siglaCategoria = string.Empty;
            string filtro = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;

            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            #region Recupero Dati
            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);

            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);

            Utility.TipoDomanda tipoDomanda = Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto);

            if (Utility.IsDomandaIOCUM(datiPensione.SiglaCategoria))
            {
                decorrenzaOriginaria = new DateTime(decorrenzaOriginaria.Year, decorrenzaOriginaria.Month, 1);
            }
            #endregion Recupero Dati
            if (decorrenzaArretrati.HasValue)
            {
                if (Utility.IsDomandaENPALS(datiPensione.Gestione))
                {
                    if (!Utility.DataSuccessivaA(decorrenzaArretrati.Value, new DateTime(1995, 10, 01)))
                    {
                        messaggioVideo = "La data decorrenza arretrati non può essere inferiore a ottobre 1995";
                        return false;
                    }
                }
                //La Data Decorrenza Arretrati (RAUDECARR) non può essere inferiore a
                //gennaio 1965
                else if (!Utility.DataSuccessivaA(decorrenzaArretrati.Value, new DateTime(1965, 01, 01)))
                {
                    messaggioVideo = "La data decorrenza arretrati non può essere inferiore a gennaio 1965";
                    return false;
                }

                //Nel caso di Prima Liquidata, se l'anno della Decorrenza Originaria (RAU104)
                //è minore o uguale all’anno di competenza allora la “Decorrenza Arretrati” (RAUDECARR),
                // se inserita, non puo' essere superiore a gennaio dell'anno di competenza e comunque 
                //l'anno della decorrenza arretrati non può essere strettamente maggiore all'anno di competenza oppure all'anno solare
                //per le domande di categoria 027(VOCRED), 028(VOCOOP), 029(VOESO), 127(CRED27), 128(COOP28), 198(VESO33), 199(VESO92), 129(VESO29)
                //la “Decorrenza Arretrati”, se inserita, deve essere uguale alla decorrenza della pensione
                if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                {
                    string cat = datiPensione.SiglaCategoria;
                    //domande non di ripristino
                    if (!Utility.IsDomandaRipristino(datiPensione).GetValueOrDefault())
                    {
                        if (Utility.IsDomandaVOCRED_CRED27(cat) || Utility.IsDomandaVOCOOP_COOP28(cat) || Utility.IsDomandaVOESO(cat) ||
                            Utility.IsDomandaVESO33(cat) || Utility.IsDomandaVESO92(cat) || Utility.IsDomandaVESO29(cat) || Utility.IsDomandaESPA(cat))
                        {
                            if ((DateTime.Compare(decorrenzaArretrati.Value.Date, decorrenzaOriginaria.Date) != 0))
                            {
                                messaggioVideo = "La data decorrenza arretrati deve essere uguale alla decorrenza pensione";
                                return false;
                            }
                        }

                        if (decorrenzaArretrati.Value.Year > annoCompetenza || decorrenzaArretrati.Value.Year > Utility.DataSistemaAgo.Year)
                        {
                            messaggioVideo = "La data decorrenza arretrati non può essere superiore all'anno di competenza o all'anno in corso";
                            return false;
                        }

                        if (decorrenzaOriginaria.Year < annoCompetenza)
                        {
                            if (Utility.DataStrettamenteSuccessivaA(decorrenzaArretrati.Value, new DateTime(annoCompetenza, 01, 01)))
                            {
                                messaggioVideo = "La data decorrenza arretrati non può essere superiore a gennaio dell'anno di competenza.";
                                return false;
                            }
                        }

                        //La Data Decorrenza Arretrati (RAUDECARR) non può essere inferiore alla
                        //Decorrenza Originaria (RAU104)
                        if (!Utility.DataSuccessivaA(decorrenzaArretrati.Value, decorrenzaOriginaria))
                        {
                            messaggioVideo = "La data decorrenza arretrati non può essere inferiore alla decorrenza originaria";
                            return false;
                        }

                        if (decorrenzaOriginaria != DateTime.MinValue && decorrenzaOriginaria.Year == Utility.DataSistemaAgo.Year && decorrenzaArretrati.Value != decorrenzaOriginaria)
                        {
                            messaggioVideo = "La 'Decorrenza Arretrati' deve essere uguale alla 'Decorrenza Pensione'";
                            return false;
                        }
                    }
                    //domande di ripristino
                    else
                    {
                        if (dataRipristino.HasValue)
                        {
                            //se l’anno della decorrenza ripristino è minore  all’anno di competenza allora la “Decorrenza Arretrati”, se inserita, NON puo' essere superiore a gennaio dell'anno solare
                            if (dataRipristino.Value.Year < annoCompetenza)
                            {
                                if (Utility.DataStrettamenteSuccessivaA(decorrenzaArretrati.Value, new DateTime(Utility.DataSistemaAgo.Year, 01, 01)))
                                {
                                    messaggioVideo = "La data decorrenza arretrati non può essere superiore a gennaio dell'anno solare.";
                                    return false;
                                }
                            }
                            //se l’anno della decorrenza ripristino è uguale all’anno solare allora la “Decorrenza Arretrati”, se inserita, deve essere uguale alla decorrenza ripristino
                            if (dataRipristino.Value.Year == Utility.DataSistemaAgo.Year)
                            {
                                if (DateTime.Compare(decorrenzaArretrati.Value.Date, dataRipristino.Value.Date) != 0)
                                {
                                    messaggioVideo = "La data decorrenza arretrati deve essere uguale alla decorrenza ripristino";
                                    return false;
                                }
                            }
                        }
                    }
                }

                //Nel caso in cui la Decorrenza Originaria (RAU104) sia nell'anno in cui si sta
                //liquidando, la Decorrenza Arretrati (RAUDECARR) deve essere uguale alla
                //Decorrenza Originaria (RAU104). Negli altri casi comunque non può essere
                //superiore a gennaio dell'anno in corso
                // Aggiornamento: Nel caso di Prima Liquidata la Decorrenza Arretrati non deve essere uguale alla Decorrenza Originaria
                if (tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiaperturaDomanda)
                {

                    //ENG - RIC/TRF ESODATI
                    if (Utility.IsDomandaVOCRED_CRED27(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCOOP_COOP28(datiPensione.SiglaCategoria) || Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) ||
                          Utility.IsDomandaVESO33(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO29(datiPensione.SiglaCategoria) || Utility.IsDomandaESPA(datiPensione.SiglaCategoria))
                    {
                        if ((DateTime.Compare(decorrenzaArretrati.Value.Date, decorrenzaOriginaria.Date) != 0))
                        {
                            //ENG - Modificato messaggio "pensione in prestazione"
                            messaggioVideo = "La data decorrenza arretrati deve essere uguale alla decorrenza prestazione";
                            return false;
                        }
                    }

                    if (annoCompetenza == decorrenzaOriginaria.Year)
                    {
                        if (DateTime.Compare(decorrenzaArretrati.Value, decorrenzaOriginaria) != 0)
                        {
                            messaggioVideo = "La data decorrenza arretrati deve essere uguale alla decorrenza originaria";
                            return false;
                        }
                    }
                    else
                    {
                        if (decorrenzaArretrati.HasValue && decorrenzaArretrati.Value.Year > Utility.DataSistemaAgo.Year && decorrenzaArretrati.Value.Month == 1)
                        {
                            messaggioVideo = "La decorrenza arretrati non può essere maggiore del mese in corso.";
                            return false;
                        }
                        else if (Utility.DataStrettamenteSuccessivaA(decorrenzaArretrati.Value, new DateTime(annoCompetenza, 01, 01)))
                        {
                            messaggioVideo = "La data decorrenza arretrati non può essere superiore a gennaio dell'anno di competenza.";
                            return false;
                        }

                        if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, decorrenzaArretrati.Value))
                        {
                            messaggioVideo = "La data decorrenza arretrati non può essere inferiore alla decorrenza pensione.";
                            return false;
                        }
                    }


                    if (causaCarico == 3 || causaCarico == 9)
                    {
                        if (dataRipristino.HasValue && Utility.DataStrettamenteSuccessivaA(dataRipristino.Value.Date, decorrenzaArretrati.Value.Date) && (Utility.IsDomandaAnte96(datiPensione, datiPensione, datiDanteCausa, isRiaperturaDomanda) == null))
                        {
                            messaggioVideo = "La decorrenza arretrati non può essere minore della decorrenza ripristino.";
                            return false;
                        }
                    }


                    if (Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO29(datiPensione.SiglaCategoria))
                    {
                        GestioneDecodificaAzienda.DecAzienda azienda = GestioneDecodificaAzienda.GetAziendaById(codiceBancaEsodati.GetValueOrDefault());
                        if (azienda != null)
                        {
                            int codAzienda = 0;
                            int.TryParse(azienda.TraduzioneSuGP, out codAzienda);
                            if (((codAzienda >= 6000 && codAzienda <= 6100) ||
                                (codAzienda >= 601 && codAzienda <= 799)) &&
                                decorrenzaArretrati.Value != decorrenzaOriginaria)
                            {
                                messaggioVideo = "La 'Decorrenza Arretrati' deve essere uguale alla 'Decorrenza Pensione'";
                                return false;
                            }
                        }
                    }
                }

                //In caso sia presente la Decorrenza Ripristino (RAU105) la Data Decorrenza
                //Arretrati (RAUDECARR) non può essere inferiore alla Decorrenza Ripristino
                //(RAU105)
                if (dataRipristino.HasValue)
                {
                    if (!Utility.DataSuccessivaA(decorrenzaArretrati.Value, dataRipristino.Value) && (Utility.IsDomandaAnte96(datiPensione, datiPensione, datiDanteCausa, isRiaperturaDomanda) == null))
                    {
                        messaggioVideo = "La data decorrenza arretrati non può essere inferiore alla decorrenza ripristino";
                        return false;
                    }
                }

                //Se la Categoria (RACATEG) è = a “VOCOOP” e il Codice Banca
                //(RACODBAN4) è = a 801 e il Campo DO-NOTE è = a “AGO”, “PT “ la Data
                //Decorrenza Arretrati (RAUDECARR) deve essere successiva alla
                //Decorrenza Originaria (RAU104)
                if (Utility.IsDomandaVOCOOP_COOP28(datiPensione.SiglaCategoria) && datiPensione.CodiceBancaEsodati.HasValue && datiPensione.CodiceBancaEsodati.Value == 801 &&
                    (filtro == "AGO" || filtro == "PT"))
                {
                    if (!Utility.DataStrettamenteSuccessivaA(decorrenzaArretrati.Value, decorrenzaOriginaria))
                    {
                        messaggioVideo = "La data decorrenza arretrati deve essere successiva alla decorrenza originaria";
                        return false;
                    }
                }

                //Se la Categoria (RACATEG) è = “VOESO” e il Campo DO-NOTE è = a “FS”,
                //“OBG” la Decorrenza Arretrati (RAUDECARR) deve essere uguale alla
                //Decorrenza Originaria (RAU104)
                // Aggiornamento: Nel caso di Prima Liquidata la Decorrenza Arretrati non deve essere uguale alla Decorrenza Originaria
                if (siglaCategoria == "VOESO" && (filtro == "FS" || filtro == "OBG"))
                {
                    if (tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiaperturaDomanda)
                    {
                        if (DateTime.Compare(decorrenzaArretrati.Value.Date, decorrenzaOriginaria.Date) != 0)
                        {
                            messaggioVideo = "La data decorrenza arretrati deve essere uguale alla decorrenza originaria";
                            return false;
                        }
                    }
                }

                // Se siamo nel caso di Prima Liquidata la Decorrenza Arretrati non deve essere uguale alla Decorrenza Originaria 
                //tranne se la categoria è una tra le seguenti: VOCRED, VOCOOP, VOESO, CRED27, COOP28, VESO33, VESO92
                if (tipoDomanda != Utility.TipoDomanda.Ricostituzione && !isRiaperturaDomanda)
                {
                    string cat = datiPensione.SiglaCategoria;
                    if (!(Utility.IsDomandaVOCRED_CRED27(cat) || Utility.IsDomandaVOCOOP_COOP28(cat) || Utility.IsDomandaVOESO(cat) || Utility.IsDomandaVESO33(cat) || Utility.IsDomandaVESO92(cat) ||
                          Utility.IsDomandaVESO29(cat) || Utility.IsDomandaESOAMB(cat) || Utility.IsDomandaESOTEL(cat) || Utility.IsDomandaESPA(cat)))
                    {
                        if (DateTime.Compare(decorrenzaArretrati.Value.Date, decorrenzaOriginaria.Date) == 0)
                        {
                            messaggioVideo = "La data decorrenza arretrati non deve essere uguale alla decorrenza originaria";
                            return false;
                        }
                    }
                }

                if (datiPensione.TipoAutomazione.HasValue && datiPensione.TipoAutomazione == (byte)Utility.TipoAutomazione.Supplementi)
                {
                    DateTime limiteDataPresentazione = new DateTime(datiPensione.DataPresentazioneDomanda.Year, 1, 1);
                    if (!Utility.DataSuccessivaA(decorrenzaArretrati.Value, limiteDataPresentazione))
                    {
                        messaggioVideo = "La data decorrenza arretrati deve essere superiore o uguale al gennaio dell’anno di presentazione della domanda.";
                        return false;
                    }
                }

                //ENG - INPGI migrate
                if (((Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaINPGI(datiPensione)) ||
                    (Utility.IsDomandaSOPGI(datiPensione.SiglaCategoria) && Utility.IsDomandaReversibilita(datiPensione) && !isRiaperturaDomanda)) && datiPensione.GP1AV91B == "2")
                {
                    GestioneControlliDinamici.ControlloDinamico ctrlDecorrenzaArretratiINPGIMigrate = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("DecorrenzaArretratiINPGIMigrate", out ctrlDecorrenzaArretratiINPGIMigrate);

                    if (ctrlDecorrenzaArretratiINPGIMigrate != null && ctrlDecorrenzaArretratiINPGIMigrate.ValoreControllo == "SI" &&
                        !Utility.DataSuccessivaA(decorrenzaArretrati.Value, new DateTime(2022, 07, 01)))
                    {
                        messaggioVideo = "La data decorrenza arretrati deve essere superiore o uguale al 07/2022.";
                        return false;
                    }
                }
            }
            else
            {
                //Se la Categoria (RACATEG) è = a “VOCOOP” e il Codice Banca
                //(RACODBAN4) è = a 801 la Data Decorrenza Arretrati (RAUDECARR) è
                //obbligatoria
                if (Utility.IsDomandaVOCOOP_COOP28(datiPensione.SiglaCategoria) && datiPensione.CodiceBancaEsodati.HasValue && datiPensione.CodiceBancaEsodati.Value == 801)
                {
                    messaggioVideo = "La data decorrenza arretrati è obbligatoria";
                    return false;
                }

                //In caso di ricostituzione la Decorrenza Arretrati è obbligatoria
                if ((tipoDomanda == Utility.TipoDomanda.Ricostituzione || isRiaperturaDomanda) &&
                    !(Utility.IsDomandaCRED27(datiPensione.SiglaCategoria) || Utility.IsDomandaCOOP28(datiPensione.SiglaCategoria)))
                {
                    messaggioVideo = "La data decorrenza arretrati è obbligatoria";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsDataCompletezza(DateTime? dataCompletezza, GestionePensione.DatiPensione datiPensione, DateTime dataSistema, bool isRiaperturaDomanda, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;

            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            if (Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO92(datiPensione.SiglaCategoria)
                || Utility.IsDomandaVOCRED(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCOOP(datiPensione.SiglaCategoria)
                || Utility.IsDomandaVESO33(datiPensione.SiglaCategoria)
                || Utility.IsDomandaESPA(datiPensione.SiglaCategoria) || Utility.IsDomandaRipristino(datiPensione).GetValueOrDefault())
                return true;

            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);

            //La data completezza (DATADOC) non può essere inferiore alla data della
            //domanda (RAUE24) e non superiore alla data del momento dell'acquisizione
            if (dataCompletezza.HasValue)
            {
                if (!(Utility.IsDomandaCumulo(datiPensione.SiglaCategoria) && Utility.IsRicostituzione_MotiviContributivi(datiPensione.Gruppo, datiPensione.Prodotto) && datiPensione.Tipo == "0198"))
                {
                    if (!Utility.DataSuccessivaA(dataCompletezza.Value, datiPensione.DataPresentazioneDomanda))
                    {
                        messaggioVideo = "La data completezza non può essere inferiore alla data di presentazione della domanda";
                        return false;
                    }
                }

                if (Utility.DataStrettamenteSuccessivaA(dataCompletezza.Value, dataSistema))
                {
                    messaggioVideo = "La data completezza non può essere superiore alla data odierna";
                    return false;
                }

                //ENG - RIC CUMULO MONTIVI CONTRIBUTIVI TIPO 0198
                if (Utility.IsDomandaCumulo(datiPensione.SiglaCategoria) && Utility.IsRicostituzione_MotiviContributivi(datiPensione.Gruppo, datiPensione.Prodotto) && datiPensione.Tipo == "0198")
                {
                    if (!Utility.DataSuccessivaA(new DateTime(dataCompletezza.Value.Year, dataCompletezza.Value.Month, 1), decorrenzaOriginaria))
                    {
                        messaggioVideo = "La data completezza non può essere inferiore alla decorrenza della pensione";
                        return false;
                    }
                }
            }
            //La data completezza (DATADOC) è obbligatoria se la data della domanda
            //(RAUE24) è successiva a 31 dicembre 2006
            else
            {
                if (Utility.DataStrettamenteSuccessivaA(datiPensione.DataPresentazioneDomanda, new DateTime(2006, 12, 31))
                    && !Utility.IsDomandaVOST(datiPensione.SiglaCategoria))
                {
                    messaggioVideo = "La data completezza è obbligatoria";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsDataInteressiLegali(DateTime? dataInteressiLegali, DateTime? dataCompletezza, byte? causaCarico, byte? codiceRicorso, DateTime? dataRipristino,
            GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            string filtro = string.Empty;
            string siglaCategoria = string.Empty;

            if (Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) || Utility.IsDomandaIndennitaUnaTantum_AGO(datiPensione) || Utility.IsDomandaRipristino(datiPensione).GetValueOrDefault()
                || Utility.IsDomandaVOCRED(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCOOP(datiPensione.SiglaCategoria)
                || Utility.IsDomandaVESO33(datiPensione.SiglaCategoria)
                || Utility.IsDomandaESPA(datiPensione.SiglaCategoria) || Utility.IsDomandaVOST(datiPensione.SiglaCategoria) || ((Utility.IsRenditaCasalinghe(datiPensione) || Utility.IsRenditaFacoltativa(datiPensione)) && Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                || Utility.IsDomandaCRED27(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO29(datiPensione.SiglaCategoria) || Utility.IsDomandaCOOP28(datiPensione.SiglaCategoria))
                return true;

            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            #region Recupero Dati
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            #endregion Recupero Dati

            //se il campo DO-NOTE è = a “SUT”
            if (filtro == "SUT" && dataInteressiLegali.HasValue)
            {
                messaggioVideo = "La data interessi legali non deve essere acquisita";
                return false;
            }

            //se la Categoria (RACATEG) è = a “”VOBANC”, “IOBANC”, “SOBANC”,
            //“INDCOM”
            switch (siglaCategoria)
            {
                case "INDCOM":
                    if (dataInteressiLegali.HasValue)
                    {
                        messaggioVideo = "La data interessi legali non deve essere acquisita";
                        return false;
                    }
                    if (siglaCategoria == "INDCOM")
                        return true;
                    break;
                default:
                    break;
            }

            if (!Utility.IsRicostituzioneOrRiaperturaAGOAbilitata(datiPensione, isRiaperturaDomanda) && !Utility.IsRicostituzione(datiPensione.Gruppo) && !(Utility.IsDomandaSPED(datiPensione) && Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda)))
            {
                //se la Causa Carico (RAU101) è = a 9
                if (causaCarico.HasValue && causaCarico.Value == 9)
                {
                    if (dataInteressiLegali.HasValue)
                    {
                        messaggioVideo = "La data interessi legali non deve essere acquisita essendo il campo causa carico uguale a 9";
                        return false;
                    }
                }

                //se il Codice Ricorso (RACODRIC) è = a 9
                if (codiceRicorso.HasValue && codiceRicorso.Value == 9)
                {
                    if (dataInteressiLegali.HasValue)
                    {
                        messaggioVideo = "La data interessi legali non deve essere acquisita essendo il campo codice ricorso uguale a 9";
                        return false;
                    }
                }

                //se è presente la Decorrenza Ripristino (RAU105)
                if (dataRipristino.HasValue)
                {
                    if (dataInteressiLegali.HasValue)
                    {
                        messaggioVideo = "La data interessi legali non deve essere acquisita in presenza della decorrenza ripristino";
                        return false;
                    }
                }
            }

            //La data va calcolata aggiuggendo 121 giorni alla data più recente tra la Data
            //della Domanda (RAUE24), la Data Completezza (DATADOC) e la Data
            //Decorrenza Pensione (RAU104) significando che per quest'ultima il giorno è
            //il giorno 1 del mese.
            //CONTROLLO SEGUENTE NON PIU' UTILIZZATO
            //Successivamente si calcola 61 giorni dalla data corrente e si verifica se il
            //risultato precedente è superiore a quest'ultima; in tale caso il campo va
            //azzerato.
            DateTime? dataPrevista = null;
            int nGiorniDaSommare = 121;
            //ENG - RIC CUMULO Motivi Contributivi: valorizzazione data interessi legali
            if ((Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) || Utility.IsDomandaIOCUM(datiPensione.SiglaCategoria) || Utility.IsDomandaSOCUM(datiPensione.SiglaCategoria))
                && Utility.IsRicostituzione_MotiviContributivi(datiPensione) && datiPensione.Tipo == "0198" && dataCompletezza.HasValue)
            {
                nGiorniDaSommare = 30;
                dataPrevista = dataCompletezza.Value.Date.AddDays(nGiorniDaSommare);
            }
            else if (Utility.DataSuccessivaA(datiPensione.DataPresentazioneDomanda, decorrenzaOriginaria))
            {
                if (dataCompletezza.HasValue)
                {
                    if (Utility.DataSuccessivaA(datiPensione.DataPresentazioneDomanda, dataCompletezza.Value))
                    {
                        dataPrevista = datiPensione.DataPresentazioneDomanda.Date.AddDays(nGiorniDaSommare);
                    }
                    else
                    {
                        dataPrevista = dataCompletezza.Value.Date.AddDays(nGiorniDaSommare);
                    }
                }
                else
                {
                    dataPrevista = datiPensione.DataPresentazioneDomanda.Date.AddDays(nGiorniDaSommare);

                }
            }
            else
            {
                if (dataCompletezza.HasValue)
                {
                    if (Utility.DataSuccessivaA(decorrenzaOriginaria, dataCompletezza.Value))
                    {
                        dataPrevista = decorrenzaOriginaria.Date.AddDays(nGiorniDaSommare);
                    }
                    else
                    {
                        dataPrevista = dataCompletezza.Value.Date.AddDays(nGiorniDaSommare);
                    }
                }
                else
                {
                    dataPrevista = decorrenzaOriginaria.Date.AddDays(nGiorniDaSommare);
                }
            }


            if (!dataInteressiLegali.HasValue && !dataRipristino.HasValue && dataPrevista.HasValue)
            {
                messaggioVideo = "La data interessi legali deve essere pari a: " + dataPrevista.Value.Date.ToString("dd/MM/yyyy");
                return false;
            }
            else if (dataInteressiLegali.HasValue && !dataPrevista.HasValue)
            {
                messaggioVideo = "La data interessi legali non deve essere acquisita in funzione degli attuali valori di decorrenza originaria, data presentazione e data completezza";
                return false;
            }
            else if (dataInteressiLegali.HasValue && dataPrevista.HasValue)
            {
                if (DateTime.Compare(dataInteressiLegali.Value.Date, dataPrevista.Value.Date) != 0)
                {
                    messaggioVideo = "La data interessi legali deve essere pari a: " + dataPrevista.Value.Date.ToString("dd/MM/yyyy");
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsCausaCarico(GestionePensione.DatiPensione datiPensione, byte? causaCarico, byte? codiceRicorso, DateTime? dataRipristino, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (causaCarico.HasValue)
            {
                //Valori ammessi: 1 – 9
                switch (causaCarico)
                {
                    case 1:
                    case 9:
                        break;
                    default:
                        if (!(Utility.IsRicostituzione(datiPensione.Gruppo) && (Utility.IsRenditaCasalinghe(datiPensione) || Utility.IsRenditaFacoltativa(datiPensione))))
                        {
                            messaggioVideo = "Il campo causa carico può assumere solo i valori 1 e 9";
                            return false;
                        }
                        break;
                }

                //Se il Codice Ricorso (RACODRIC) è = a 9 la Causa carico (RAU101) deve
                //essere = a 9
                if (codiceRicorso.HasValue && codiceRicorso.Value == 9)
                {
                    if (causaCarico.Value != 9)
                    {
                        messaggioVideo = "Il campo causa carico deve essere uguale a 9";
                        return false;
                    }
                }
            }
            //La Causa Carico (RAU101) = a 9 e la presenza della Data Ripristino
            //(RAU105) sono correlate: in presenza della seconda la prima deve essere =
            //a 9 e viceversa
            if (!Utility.IsDomandaVOST(datiPensione.SiglaCategoria) &&
                !(Utility.IsRicostituzioneOrRiapertura(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id) && (Utility.IsDomandaBancari(datiPensione.SiglaCategoria) || Utility.IsDomandaPMO(datiPensione.SiglaCategoria) || Utility.IsDomandaPSO(datiPensione.SiglaCategoria)))))
            {
                if (dataRipristino.HasValue ^ causaCarico.GetValueOrDefault() == 9)
                {
                    messaggioVideo = "Inserire la decorrenza ripristino.";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsDataRipristino(DateTime? dataRipristino, byte? causaCarico, GestionePensione.DatiPensione datiPensione, DateTime dataSistema, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            string filtro = string.Empty;
            string siglaCategoria = string.Empty;

            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }


            #region Recupero Dati
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            #endregion Recupero Dati

            if (dataRipristino.HasValue)
            {
                //La Data Ripristino (RAU105) non può essere superiore a gennaio dell'anno in
                //corso
                if (Utility.DataStrettamenteSuccessivaA(dataRipristino.Value, new DateTime(dataSistema.Year, 01, 31)))
                {
                    messaggioVideo = "La data ripristino non può essere superiore a gennaio dell'anno in corso";
                    return false;
                }

                //La Data Ripristino (RAU105) deve essere posteriore alla Decorrenza
                //Originaria (RAU104)
                if (!Utility.DataStrettamenteSuccessivaA(dataRipristino.Value, decorrenzaOriginaria))
                {
                    messaggioVideo = "La data ripristino deve essere posteriore alla decorrenza originaria";
                    return false;
                }

                //La Data Ripristino (RAU105) non può essere inferiore a gennaio 1965
                if (!Utility.DataSuccessivaA(dataRipristino.Value, new DateTime(1965, 01, 01)))
                {
                    messaggioVideo = "La data ripristino non può essere inferiore a gennaio 1965";
                    return false;
                }

                //Se la Categoria (RACATEG) è = a “VOCRED”, “VOCOOP”, “VOESO” la
                //Data Ripristino (RAU105) non può essere superiore a giugno 2010
                switch (siglaCategoria)
                {
                    case "VOCRED":
                    case "CRED27":
                    case "VOCOOP":
                    case "VOESO":
                    case "COOP28":
                        if (Utility.DataStrettamenteSuccessivaA(dataRipristino.Value, new DateTime(2010, 06, 30)))
                        {
                            messaggioVideo = "La data ripristino non può essere superiore a giugno 2010";
                            return false;
                        }
                        break;
                    default:
                        break;
                }
            }
            //La Causa Carico (RAU101) = a 9 e la presenza della Data Ripristino
            //(RAU105) sono correlate: in presenza della seconda la prima deve essere =
            //a 9 e viceversa
            else
            {
                if (!Utility.IsDomandaVOST(siglaCategoria) &&
                    !(Utility.IsRicostituzioneOrRiapertura(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id) && (Utility.IsDomandaBancari(datiPensione.SiglaCategoria) || Utility.IsDomandaPMO(datiPensione.SiglaCategoria) || Utility.IsDomandaPSO(datiPensione.SiglaCategoria)))))
                {
                    if (causaCarico.HasValue && causaCarico.Value == 9)
                    {
                        messaggioVideo = "La data ripristino è obbligatoria";
                        return false;
                    }
                }
            }
            return true;
        }

        public static bool ControlsCodiceLiquidazione(char? codiceLiquidazione, DateTime? decPensDA, GestionePensione.DatiPensione datiPensione, GestioneDanteCausa.DatiDanteCausa danteCausa, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            string dauCtrDai = string.Empty;
            bool isRiaperturaDomanda = Utility.IsRiaperturaDomanda(datiPensione.Id);

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);

            //La Modalità Liquidazione (RAUE23) può essere vuoto o contenere “P”
            //ENG - controllo rimosso per le TRF/RIC ai superstiti e mantenuto per le PL e per le ENPALS
            if (codiceLiquidazione.HasValue && (codiceLiquidazione.Value.ToString().ToUpperInvariant() != "P" && codiceLiquidazione.Value != ' ' && codiceLiquidazione.Value.ToString().ToUpperInvariant() != "J")
                && (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) || !Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) || Utility.IsDomandaENPALS(datiPensione.Gestione)))
            {
                messaggioVideo = "Il codice liquidazione può essere vuoto o contenere P o J";
                return false;
            }

            //Se la Categoria (RACATEG) è = a “INDCOM”, “VOBIS”, “IOBIS”, “VMP”,
            //“IMP”, “VOAUT”, “IOAUT” e (“SOAUT” con il campo Tipo Domanda (PTIPODO)
            //diverso da “2”) la Modalità Liquidazione (RAUE23) deve essere
            //assente
            switch (siglaCategoria)
            {
                case "INDCOM":
                case "VOBIS":
                case "IOBIS":
                case "VMP":
                case "IMP":
                case "VOAUT":
                case "IOAUT":
                    if (codiceLiquidazione.HasValue && codiceLiquidazione.Value != ' ')
                    {
                        messaggioVideo = "Il codice liquidazione deve essere assente";
                        return false;
                    }
                    break;
                case "SOAUT":
                    GestioneLavorazione.DatiLavorazione datiLavorazione = null;
                    GestioneLavorazione.GetLavorazioneByIdPensione(datiPensione.Id, out datiLavorazione);
                    if (datiLavorazione != null)
                    {
                        char? tipoDomanda = datiLavorazione.TipoDomanda;
                        if (!tipoDomanda.HasValue || (tipoDomanda.Value != '2'))
                        {
                            if (codiceLiquidazione.HasValue && codiceLiquidazione.Value != ' ')
                            {
                                messaggioVideo = "Il codice liquidazione deve essere assente";
                                return false;
                            }
                        }
                    }
                    break;
                default:
                    break;
            }

            //Se il campo DO-NOTE é = a “DAI” oppure il campo DAU-CTR-DAI è = a ”N” il Codice Liquidazione (RAUE23)
            //deve essere = a “P”

            Utility.TipoDomanda tipologiaDomanda = Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto);
            if (tipologiaDomanda == Utility.TipoDomanda.Superstiti && decPensDA.HasValue)
            {
                dauCtrDai = "N";
                if (siglaCategoria == "SDAI")
                {
                    if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(1996, 12, 31)) &&
                        datiPensione.DataAcquisizione.HasValue && Utility.DataStrettamenteSuccessivaA(datiPensione.DataAcquisizione.Value, new DateTime(2003, 11, 30)))
                    {
                        GetDauCtrDai(datiPensione, ref dauCtrDai);
                    }
                }
            }
            //ENG - Spacchettate SOPGI
            if ((filtro == "DAI" || dauCtrDai == "N") && !Utility.IsDomandaENPALS(datiPensione.Gestione) && !Utility.IsDomandaSpacchettamentoSOPGIPost072022(datiPensione, danteCausa))
            {
                if (!codiceLiquidazione.HasValue || (codiceLiquidazione.Value.ToString().ToUpperInvariant() != "P"))
                {
                    messaggioVideo = "Il codice liquidazione deve essere pari a P";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsCodiceMobilita(byte? codiceMobilita, string naturaPensione, byte? codiceRequisitiRidotti,
            GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            string siglaCategoria = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';


            Utility.GetCodiciNatura(naturaPensione, out codNat1, out codNat2, out codNat3);

            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);

            siglaCategoria = datiPensione.SiglaCategoria.Trim().ToUpperInvariant();

            if (codiceMobilita.HasValue)
            {
                //Il Codice Mobilità (RAUCODMOB) può contenere :
                //1 = mobilità lunga
                //2 = mobilità ordinaria avviata ante 17/8/1996
                //3 = mobilità ordinaria avviata post 17/8/1996
                //4 = mobilità lunga legge 229/1997
                //5 = mobilità lunga legge 176/98 accordi entro 31.3.98
                //6 = mobilità lunga legge 176/98 accordi post 31.3.98
                //7 = mobilità lunga legge 81/2003
                //8 = mobilità settore Sanità privata legge 326/2003
                //9 = mobilità L.296/2006
                switch (codiceMobilita.Value)
                {
                    case 1:
                    case 2:
                    case 3:
                    case 4:
                    case 5:
                    case 6:
                    case 7:
                    case 8:
                    case 9:
                        break;
                    default:
                        messaggioVideo = "Il codice mobilità può assumere valori da 1 a 9";
                        return false;
                }

                //Se la Decorrenza Originaria (RAU104) è precedente a gennaio 1994 il
                //Codice Mobilità (RAUCODMOB) deve essere assente
                if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1994, 01, 01)))
                {
                    messaggioVideo = "Il codice mobilità deve essere assente";
                    return false;
                }


                switch (siglaCategoria)
                {
                    //Se è una Vecchiaia (Categoria (RACATEG) è = a “VO”, “VOBANC”, “VDAI” e
                    //il 1° Codice Natura (RAU1031) è diverso da “1”, “2”, “3”, “4”) il Codice
                    //Mobilità (RAUCODMOB) deve essere assente tranne che per le “VO
                    case "VO":
                    case "VOBANC":
                    case "VDAI":
                        if (codNat1 != '1' && codNat1 != '2' && codNat1 != '3' && codNat1 != '4')
                        {
                            if (siglaCategoria != "VO")
                            {
                                messaggioVideo = "Il codice mobilità deve essere assente";
                                return false;
                            }
                        }
                        //Se non è una Vecchiaia (RACATEG) è = a “VO”, “VOBANC”, “VDAI” e il 1°
                        //Codice Natura (RAU1031) è = a “1”, “2”, “3”, “4”):
                        else
                        {
                            //se la Decorrenza Originaria (RAU104) è precedente ad aprile 1998 il
                            //Codice Mobilità (RAUCODMOB) deve essere assente
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1998, 04, 01)))
                            {
                                messaggioVideo = "Il codice mobilità deve essere assente";
                                return false;
                            }

                            //Il Codice Mobilità (RAUCODMOB) può contenere solo 1, 2, 3, 4, 8, 9
                            switch (codiceMobilita.Value)
                            {
                                case 1:
                                case 2:
                                case 3:
                                case 4:
                                case 8:
                                case 9:
                                    break;
                                // Il codice mobilità può contenere il valore 6 se il primo codice natura è uguale a 1 o 2
                                // Rif. mail con oggetto "FW: doamnda 2008667300005 sviluppo" del 15/04/2015
                                case 6:
                                    if (codNat1 != '1' && codNat1 != '2')
                                    {
                                        messaggioVideo = "Il codice mobilità può contenere solo 1, 2, 3, 4, 8, 9";
                                        return false;
                                    }
                                    break;
                                default:
                                    messaggioVideo = "Il codice mobilità può contenere solo 1, 2, 3, 4, 8, 9";
                                    return false;
                            }

                            //Se la Decorrenza Originaria (RAU104) è inferiore a febbraio 2004 il
                            //Codice Mobilità (RAUCODMOB) non può contenere 8
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2004, 02, 01)))
                            {
                                if (codiceMobilita == 8)
                                {
                                    messaggioVideo = "Il codice mobilità non può contenere 8";
                                    return false;
                                }
                            }

                            //Il Codice Requisito Ridotto (RAUCODDIR) e il Codice Mobilità
                            //(RAUCODMOB) sono alternativi
                            if (!ControlsCodReqRid_CodMob(codiceRequisitiRidotti, codiceMobilita, out messaggioVideo))
                                return false;
                        }
                        break;
                    //Se la Categoria (RACATEG) è diversa da “VO”, “VOBANC”, “VDAI” il Codice
                    //Mobilità (RAUCODMOB) deve essere assente
                    default:
                        messaggioVideo = "Il codice mobilità deve essere assente";
                        return false;
                }


            }

            return true;
        }

        public static bool ControlsProvenienza(short? codiceP18PrecedentePensione, int? certificatoPrecedentePensione, DateTime? decorrenzaPrecedentePensione, int? sedePrecedentePensione,
            DateTime? dataInteressiLegali, GestionePensione.DatiPensione datiPensione, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, int? attivitaEconomica, int? professioneIndividuale, byte? codiceDomandaRicorso, bool isRiaperturaDomanda, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            string siglaCategoria = string.Empty;
            string filtro = string.Empty;
            string siglaCatProv = string.Empty;
            string certificatoProv = string.Empty;

            #region Recupero Dati
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);

            if (codiceP18PrecedentePensione.HasValue)
            {
                GestioneDecodifica.AGO_CI_GetCategoriaByCategoriaNumerica(codiceP18PrecedentePensione.Value.ToString().PadLeft(4, '0'), out siglaCatProv);
                if (!string.IsNullOrEmpty(siglaCatProv))
                    siglaCatProv = siglaCatProv.Trim().ToUpperInvariant();
            }
            if (certificatoPrecedentePensione.HasValue)
                certificatoProv = certificatoPrecedentePensione.Value.ToString().PadLeft(8, '0');
            #endregion Recupero Dati

            //Se il campo DO-NOTE è = a “TRA”, “AOI”, “STA”, “STM” i dati devono essere
            //obbligatoriamente acquisiti e devono essere coerenti con la Categoria in
            //liquidazione (RACATEG)
            //Compatibilità: Categoria di provenienza (RACATINV) è = “IO”, “IDAI”,
            //“IR”, “IOART”, “IOCOM”, “IOS”, “IRS”, “IOARTS”, “IOCOMS” e
            //Categoria della pensione in liquidazione (RACATEG) è = a “VO”,
            //“VDAI”, “VOP”, “VOMIN”, “VR”, “VOART”, “VOCOM”
            switch (filtro)
            {
                case "TRA":
                case "AOI":
                case "STA":
                case "STM":
                    switch (siglaCategoria)
                    {
                        case "VO":
                        case "VDAI":
                        case "VOP":
                        case "VOMIN":
                        case "VR":
                        case "VOART":
                        case "VOCOM":
                            switch (siglaCatProv)
                            {
                                case "IO":
                                case "IDAI":
                                case "IR":
                                case "IOART":
                                case "IOCOM":
                                case "IOS":
                                case "IRS":
                                case "IOARTS":
                                case "IOCOMS":
                                    break;
                                default:
                                    messaggioVideo = "Compatibilità tra categoria pensione e categoria provenienza non rispettata";
                                    return false;
                            }
                            break;
                        default:
                            messaggioVideo = "Compatibilità tra categoria pensione e categoria provenienza non rispettata";
                            return false;
                    }
                    break;
                default:
                    break;
            }

            if (Utility.IsDomandaTrasformazioneInvalidita(datiPensione))
            {
                switch (siglaCategoria)
                {
                    case "VO":
                    case "VDAI":
                    case "VOP":
                    case "VOMIN":
                    case "VR":
                    case "VOART":
                    case "VOCOM":
                        switch (siglaCatProv)
                        {
                            case "IO":
                            case "IDAI":
                            case "IR":
                            case "IOART":
                            case "IOCOM":
                                //Email 11-02-2015 - Non è necessaria la verifica di queste categoarie per la precedente pensione.
                                //case "IOS":
                                //case "IRS":
                                //case "IOARTS":
                                //case "IOCOMS":
                                break;
                            default:
                                messaggioVideo = "Compatibilità tra categoria pensione e categoria provenienza non rispettata";
                                return false;
                        }
                        break;
                    default:
                        messaggioVideo = "Compatibilità tra categoria pensione e categoria provenienza non rispettata";
                        return false;
                }
            }

            //In tutti i casi ammessi la categoria di provenienza (RACATINV) deve essere
            //una delle seguenti: "IO", "SO ", "VDAI", "IDAI", "SDAI", "VOBANC",
            //"IOBANC", "SOBANC", "VOS", "IOS", "SOS","VOP", "IOP", "SOP", "VOMIN",
            //"SOMIN", "VR", "IR", "SR", "VOART", "IOART", "SOART","VOCOM",
            //"IOCOM", "SOCOM", "VRS", "IRS", "SRS", "VOARTS", "IOARTS",
            //"SOARTS" "VOCOMS", "IOCOMS", "SOCOMS", "PMO"
            if (!string.IsNullOrEmpty(siglaCatProv))
            {
                switch (siglaCatProv)
                {
                    case "IO":
                    case "SO":
                    case "VDAI":
                    case "IDAI":
                    case "SDAI":
                    case "VOBANC":
                    case "IOBANC":
                    case "SOBANC":
                    case "VOS":
                    case "IOS":
                    case "SOS":
                    case "VOP":
                    case "IOP":
                    case "SOP":
                    case "VOMIN":
                    case "SOMIN":
                    case "VR":
                    case "IR":
                    case "SR":
                    case "VOART":
                    case "IOART":
                    case "SOART":
                    case "VOCOM":
                    case "IOCOM":
                    case "SOCOM":
                    case "VRS":
                    case "IRS":
                    case "SRS":
                    case "VOARTS":
                    case "IOARTS":
                    case "SOARTS":
                    case "VOCOMS":
                    case "IOCOMS":
                    case "SOCOMS":
                    case "PMO":
                    case "IOPGI":
                    //20151009 - Aggiunti categorie ENPALS
                    case "VOSPETT":
                    case "IOSPETT":
                    case "SOSPETT":
                    case "VOSPORT":
                    case "IOSPORT":
                    case "SOSPORT":
                    //20190311 - Aggiunta categoria PM (mail attività 08/03/2019)
                    case "PM":
                    //20201104 - Aggiunte categorie AUT
                    case "VOAUT":
                    case "IOAUT":
                    case "SOAUT":
                    case "PSO":
                        break;
                    case "VO":
                        List<GestioneCtrlAttEconProfInd_PensProv.AttEconProfInd_PensProv> listaAttEconProfInd_PensProv = null;
                        GestioneCtrlAttEconProfInd_PensProv.GetCtrlAttEconProfInd_PensProv(out listaAttEconProfInd_PensProv);
                        if (!(datiPensione.CausaCarico == 9 && siglaCatProv == siglaCategoria) &&
                            !listaAttEconProfInd_PensProv.Exists(x => x.AttivitaEconomica == attivitaEconomica && x.ProfessioneIndividuale == professioneIndividuale) &&
                            !(Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && codiceDomandaRicorso != null && codiceDomandaRicorso == 8 &&
                              sedePrecedentePensione.HasValue && !string.IsNullOrEmpty(certificatoProv) && decorrenzaPrecedentePensione.HasValue))
                            messaggioVideo = "Categoria di provenienza non corretta";
                        break;
                    default:
                        if (!(datiPensione.CausaCarico == 9 && siglaCatProv == siglaCategoria) &&
                            !(Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && codiceDomandaRicorso != null && codiceDomandaRicorso == 8 &&
                              sedePrecedentePensione.HasValue && !string.IsNullOrEmpty(certificatoProv) && decorrenzaPrecedentePensione.HasValue))
                        {
                            messaggioVideo = "Categoria di provenienza non corretta";
                            return false;
                        }
                        break;
                }
            }

            //Se la Categoria di provenienza (RACATINV) è = a “PMO” i primi due caratteri
            //del Certificato di provenienza (RACERINV) devono essere 2 zeri
            if (siglaCatProv == "PMO")
            {
                if (string.IsNullOrEmpty(certificatoProv) || certificatoProv.Substring(0, 2) != "00")
                {
                    messaggioVideo = "Il certificato di provenienza deve iniziare con 2 zeri";
                    return false;
                }
            }

            //Se la Categoria (RACATEG) è una pensione di reversibilità (1° lettera della
            //Categoria = a “S” o “PMO” con 3° carattere del Certificato = a “3” o “6”)
            //anche la Categoria di provenienza (RACATINV) deve essere una reversibilità
            //(1° lettera della Categoria di provenienza = a “S” o “PMO” con 3° carattere
            //del Certificato di provenienza = a “3” o “6”)
            if (!(Utility.IsDomandaBancari(datiPensione.SiglaCategoria) && Utility.IsRicostituzione(datiPensione.Gruppo)) && (siglaCategoria.StartsWith("S") || (siglaCategoria == "PMO" &&
                (certificato.Substring(2, 1) == "3" || certificato.Substring(2, 1) == "6"))))
            {
                if (!(!string.IsNullOrEmpty(siglaCatProv) && (siglaCatProv.StartsWith("S") || (siglaCatProv == "PMO" &&
                    (certificatoProv.Substring(2, 1) == "3" || certificatoProv.Substring(2, 1) == "6")))))
                {
                    messaggioVideo = "La categoria di provenienza ed il certificato di provenienza sono incompatibili con la categoria ed il certificato della pensione";
                    return false;
                }
            }

            //Se la Categoria (RACATEG) non è una pensione di reversibilità la Categoria
            //di provenienza (RACATINV) deve essere una delle seguenti: "VO",
            //"IO","VDAI", "IDAI", "VOS", "IOS", "VOP", "IOP", "VOMIN", "VR",
            //"IR","VOART", "IOART", "VOCOM", "IOCOM", "VOBANC", "IOBANC",
            //"VRS", "IRS", "VOARTS", "IOARTS", "VOCOMS", "IOCOMS" e “PMO”con 3°
            //carattere del Certificato = a “1” o “2” o “4” o “5”
            if (!siglaCategoria.StartsWith("S"))
            {
                switch (siglaCatProv)
                {
                    case "VO":
                    case "IO":
                    case "VDAI":
                    case "IDAI":
                    case "VOS":
                    case "IOS":
                    case "VOP":
                    case "IOP":
                    case "VOMIN":
                    case "VR":
                    case "IR":
                    case "VOART":
                    case "IOART":
                    case "VOCOM":
                    case "IOCOM":
                    case "VOBANC":
                    case "IOBANC":
                    case "VRS":
                    case "IRS":
                    case "VOARTS":
                    case "IOARTS":
                    case "VOCOMS":
                    case "IOCOMS":
                    case "IOPGI":
                    //20151009 - Aggiunti categorie ENPALS
                    case "VOSPETT":
                    case "IOSPETT":
                    case "SOSPETT":
                    case "VOSPORT":
                    case "IOSPORT":
                    case "SOSPORT":
                    //20190311 - Aggiunta categoria PM (mail attività 08/03/2019)
                    case "PM":
                    //20201104 - Aggiunte categorie AUT
                    case "VOAUT":
                    case "IOAUT":
                    case "SOAUT":
                    case "PSO":
                        break;
                    case "PMO":
                        if (certificatoProv.Substring(2, 1) != "1" && certificatoProv.Substring(2, 1) != "2" &&
                            certificatoProv.Substring(2, 1) != "4" && certificatoProv.Substring(2, 1) != "5")
                        {
                            messaggioVideo = "Certificato di provenienza non corretto";
                            return false;
                        }
                        break;
                    default:
                        if (!(datiPensione.CausaCarico == 9 && siglaCatProv == siglaCategoria) &&
                            !(Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && codiceDomandaRicorso != null && codiceDomandaRicorso == 8 &&
                              !string.IsNullOrEmpty(siglaCatProv) && sedePrecedentePensione.HasValue && !string.IsNullOrEmpty(certificatoProv) && decorrenzaPrecedentePensione.HasValue)
                              && !Utility.IsDomandaBancRicAnte1991(datiPensione, datiDanteCausa))
                        {
                            messaggioVideo = "Categoria di provenienza non corretta";
                            return false;
                        }
                        break;
                }
            }
            return true;
        }

        public static bool ControlsCodiceRequisitiRidotti(byte? codiceRequisitiRidotti, byte? codiceMobilita, string naturaPensione, GestionePensione.DatiPensione datiPensione, Utility.TipoCalcolo tipoCalcolo, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, bool isRiaperturaDomanda,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            Utility.GetCodiciNatura(naturaPensione, out codNat1, out codNat2, out codNat3);
            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);
            #endregion Recupero Dati

            if (Utility.IsDomandaAnte96(datiPensione, datiPensione, datiDanteCausa, isRiaperturaDomanda) == null)
            {
                if (!Utility.IsDomandaPescatoriFiltroL80(datiPensione))
                {
                    //Se la liquidazione è Contributiva (RINSIEME) è = a “SI” il Codice Requisiti
                    //Ridotti (RAUCODDIR) non va acquisito
                    if (tipoCalcolo == Utility.TipoCalcolo.Contributivo && codiceRequisitiRidotti.HasValue && codiceRequisitiRidotti.Value != 0)
                    {
                        messaggioVideo = "Il codice requisiti ridotti non va acquisito";
                        return false;
                    }

                    //Se la Decorrenza Originaria (RAU104) è precedente a gennaio 1994 il
                    //Codice Requisiti Ridotti (RAUCODDIR) non va acquisito
                    if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1994, 01, 01)) && codiceRequisitiRidotti.HasValue && codiceRequisitiRidotti.Value != 0)
                    {
                        messaggioVideo = "Il codice requisiti ridotti non va acquisito";
                        return false;
                    }
                }

                switch (siglaCategoria)
                {
                    //Se la Categoria (RACATEG) è diversa da “VO”, “VOBANC”, “VDAI” il Codice
                    //Requisiti Ridotti (RAUCODDIR) non va acquisito
                    case "VO":
                    case "VDAI":
                    case "VOSPETT":
                    case "VOSPORT":
                    case "VOP":
                    case "IOP":
                    case "SOP":
                        break;
                    case "VOBANC":
                        //Se la Categoria (RACATEG) è = a “VOBANC” il Codice Requisiti Ridotti
                        //(RAUCODDIR) non può essere = a 6
                        //Se la Categoria (RACATEG) è = a “VOBANC” il Codice Requisiti Ridotti
                        //(RAUCODDIR) non può contenere “6”
                        if (codiceRequisitiRidotti.HasValue && codiceRequisitiRidotti.Value == 6)
                        {
                            messaggioVideo = "Il codice requisiti ridotti non può essere 'invalido all'80%'";
                            return false;
                        }
                        break;
                    default:
                        if (!(Utility.IsDomandaVOPGI(datiPensione.SiglaCategoria) && (Utility.IsDomandaManualeInvaliditaOver80(datiPensione) || (Utility.IsRicostituzione(datiPensione.Gruppo) && datiPensione.IdTipoPLPerRIC.HasValue && datiPensione.IdTipoPLPerRIC == (byte)Utility.TipoPLPerRIC.RicVOPGIFiltroL80))) && Utility.IsDomandaUnicarpe(datiPensione, true) != Utility.TipoUnicarpe.Automatica &&
                            codiceRequisitiRidotti.HasValue && codiceRequisitiRidotti.Value != 0)
                        {
                            messaggioVideo = "Il codice requisiti ridotti non va acquisito";
                            return false;
                        }
                        break;
                }

                //Se è una Vecchiaia (Categoria (RACATEG) è = a “VO”, “VOBANC”, “VDAI”
                //e il 1° Codice Natura (RAU1031) è = a spazio o “6”) e la Decorrenza
                //Originaria (RAU104) è superiore a dicembre 1993 il Codice Requisiti Ridotti
                //(RAUCODDIR) può essere vuoto oppure = a 6 (escluso per “VOBANC” per la
                //quale può essere solo vuoto)
                switch (siglaCategoria)
                {
                    case "VO":
                    case "VDAI":
                        if ((codNat1 == ' ' || codNat1 == '6') && Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(1993, 12, 31)))
                        {
                            if (codiceRequisitiRidotti.HasValue && codiceRequisitiRidotti.Value != 0 && codiceRequisitiRidotti.Value != 6 &&
                                (codNat2 != 'Y' || codiceRequisitiRidotti.Value != 5) &&
                                !(codiceRequisitiRidotti == 1 && new List<string> { "BNX", "BNS" }.Contains(filtro)))
                            {
                                messaggioVideo = "Il codice requisiti ridotti può essere vuoto o pari a 'invalido all'80%'";
                                if (codNat2 == 'Y')
                                    messaggioVideo += " o pari a 'precoci'";
                                return false;
                            }
                        }
                        break;
                    case "VOBANC":
                        if ((codNat1 == ' ' || codNat1 == '6') && Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(1993, 12, 31)))
                        {
                            if (codiceRequisitiRidotti.HasValue && codiceRequisitiRidotti.Value != 0)
                            {
                                messaggioVideo = "Il codice requisiti ridotti può essere solo vuoto";
                                return false;
                            }
                        }
                        break;
                    default:
                        break;
                }

                //Se non è una Vecchiaia (RACATEG) è = a “VO”, “VOBANC”, “VDAI” e il 1°
                //Codice Natura (RAU1031) è = a “1”, “2”, “3”, “4”):
                switch (siglaCategoria)
                {
                    case "VO":
                    case "VOBANC":
                    case "VDAI":
                        if (codNat1 == '1' || codNat1 == '2' || codNat1 == '4')
                        {
                            //se la Decorrenza Originaria (RAU104) è precedente ad aprile 1998 il
                            //Codice Requisiti Ridotti (RAUCODDIR) non va acquisito
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1998, 4, 1)))
                            {
                                if (codiceRequisitiRidotti.HasValue && codiceRequisitiRidotti.Value != 0)
                                {
                                    messaggioVideo = "Il codice requisiti ridotti non va acquisito";
                                    return false;
                                }
                            }
                            //I Codici Requisiti Ridotti (RAUCODDIR) ammessi sono solo 1, 2, 3, 4,
                            //5 (escluso il 6)
                            if (codiceRequisitiRidotti.HasValue && codiceRequisitiRidotti.Value == 6)
                            {
                                messaggioVideo = "Il codice requisiti ridotti non può essere 'invalido all'80%'";
                                return false;
                            }

                            //Il Codice Requisito Ridotto (RAUCODDIR) e il Codice Mobilità
                            //(RAUCODMOB) sono alternativi
                            if (!ControlsCodReqRid_CodMob(codiceRequisitiRidotti, codiceMobilita, out messaggioVideo))
                                return false;
                        }
                        break;
                    default:
                        break;
                }
            }
            return true;
        }

        public static bool ControlsAliquotaTFResodati(decimal? aliquotaTFResodati, GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);
            #endregion Recupero Dati

            //E' obbligatorio per le Categorie (RACATEG) = a VOCRED,
            //VOCOOP
            switch (siglaCategoria)
            {
                case "VOCRED":
                case "CRED27":
                case "VOCOOP":
                case "COOP28":
                    if (!aliquotaTFResodati.HasValue || aliquotaTFResodati.Value == 0M)
                    {
                        messaggioVideo = "L'aliquota TFR esodati è obbligatoria";
                        return false;
                    }
                    break;
                default:
                    break;
            }

            //L'Aliquota TFR Esodati (RAUALIQTFR) non può essere inferiore a 23% e
            //non superiore a 45%
            if (aliquotaTFResodati.HasValue && (aliquotaTFResodati.Value < 23 || aliquotaTFResodati.Value > 45))
            {
                messaggioVideo = "L'aliquota TFR esodati non può essere inferiore al 23% e non superiore al 45%";
                return false;
            }

            //Se la Categoria (RACATEG) è = a “VOCRED” o “VOCOOP” e la Decorrenza
            //Originaria (RAU104) è superiore a dicembre 2002 l'Aliquota TFR Esodati
            //(RAUALIQTFR) non può essere inferiore al 23%
            switch (siglaCategoria)
            {
                case "VOCOOP":
                case "VOCRED":
                case "CRED27":
                case "COOP28":
                    if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2002, 12, 31)))
                    {
                        if (aliquotaTFResodati.HasValue && aliquotaTFResodati.Value < 23)
                        {
                            messaggioVideo = "L'aliquota TFR esodati non può essere inferiore al 23%";
                            return false;
                        }
                    }
                    break;
                default:
                    break;
            }

            return true;
        }

        public static bool ControlsIncrociatiSoloPreCalcolo(GestionePensione.DatiPensione datiPensione, GestioneIstruttoria.DatiIstruttoria datiIstruttoria,
            GestioneNuoveLiquidate.NuoveLiquidate datiNuoveLiquidate, GestioneAnagrafica.DatiAnagrafici datiAnagrafici, GestioneDanteCausa.DatiDanteCausa datiDA,
            Liquidazione.BLCommon.GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici datiMaggiorazioniBenefici, Utility.TipoCalcolo tipoCalcolo, DateTime dataSistema, int annoCompetenza,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';
            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            int pdirsup = 0;
            int plavaut = 0;
            #region Recupero Dati

            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            if (datiPensione.NaturaPensione != null)
            {
                datiPensione.NaturaPensione = datiPensione.NaturaPensione.PadRight(3, ' ');
                codNat1 = char.Parse(datiPensione.NaturaPensione.Substring(0, 1).ToUpperInvariant());
                codNat2 = char.Parse(datiPensione.NaturaPensione.Substring(1, 1).ToUpperInvariant());
                codNat3 = char.Parse(datiPensione.NaturaPensione.Substring(2, 1).ToUpperInvariant());
            }

            if (!datiAnagrafici.DataNascita.HasValue || !datiAnagrafici.Sesso.HasValue)
            {
                messaggioVideo = "Datititolare non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            GetPdirusp_Plavaut(datiPensione, out pdirsup, out plavaut);
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
            #endregion Recupero Dati

            //ENG - Memo 123/2024
