            //(RAU104) abbia compiuto 60 anni (codice errore 38)
            if (siglaCategoria == "VOMIN")
            {
                switch (codNat1)
                {
                    case '0':
                    case '6':
                    case '8':
                    case '9':
                        if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(60), decorrenzaOriginaria))
                        {
                            messaggioVideo = "Per la categoria " + siglaCategoria + " e il primo codice natura " + codNat1 +
                                " acquisiti, il titolare deve aver compiuto 60 anni rispetto alla decorrenza originaria";
                            return true;
                        }
                        break;
                    default:
                        break;
                }
            }

            DateTime? decorrenzaOpzione = datiIstruttoria != null ? datiIstruttoria.DecorrenzaOpzione : null;
            if (decorrenzaOpzione.HasValue)
            {
                //Se esiste la Data Decorrenza Opzione (RAU113) e la Categoria (RACATEG)
                //è = “VO”, “VDAI”, “VOP”, “VOBANC” e il 1° Codice Natura (RAU1031) è =
                //“1”, “2”, “3” “4” e la Decorrenza Originaria (RAU104) deve essere inferiore a
                //maggio 1969 (codice errore 39)
                switch (siglaCategoria)
                {
                    case "VO":
                    case "VDAI":
                    case "VOP":
                    case "VOBANC":
                        if (codNat1 == '1' || codNat1 == '2' || codNat1 == '3' || codNat1 == '4')
                        {
                            if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1969, 05, 01)))
                            {
                                messaggioVideo = "La decorrenza originaria deve essere inferiore a maggio 1969 (codice errore 39)";
                                return false;
                            }
                        }
                        break;
                    //Se esiste la Data Decorrenza Opzione (RAU113) e la Categoria (RACATEG)
                    //è = “VOMIN” e il 1° Codice Natura (RAU1031) è = “1”, “2 e la Decorrenza
                    //Originaria (RAU104) deve essere inferiore a maggio 1969 (codice errore 39)
                    case "VOMIN":
                        if (codNat1 == '1' || codNat1 == '2')
                        {
                            if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1969, 05, 01)))
                            {
                                messaggioVideo = "La decorrenza originaria deve essere inferiore a maggio 1969 (codice errore 39)";
                                return false;
                            }
                        }
                        break;
                    default:
                        break;
                }
            }

            //Se la Categoria (RACATEG è = a “IR”, “IOART”, “IOCOM”, il 1° Codice
            //Natura (RAU1031) = a “1”, “2”, “8”, “9” e la Decorrenza Originaria (RAU104)
            //superiore a luglio 1984 non possono coesistere (codice errore 48)
            switch (siglaCategoria)
            {
                case "IR":
                case "IOART":
                case "IOCOM":
                    if (codNat1 == '1' || codNat1 == '2' || codNat1 == '8' || codNat1 == '9')
                    {
                        if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(1984, 07, 31)))
                        {
                            messaggioVideo = "La decorrenza originaria non può essere superiore a luglio 1984 (codice errore 48)";
                            return false;
                        }
                    }
                    break;
                default:
                    break;
            }

            //Se la Categoria (RACATEG) è = a “VO” e il Codice Mobilità (RAUCODMOB)
            //è = a 1 e il 1° Codice Natura (RAU1031) è = a spazio o “6” il pensionando
            //deve aver compiuto 55 anni se femmina o 60 se maschio (trattasi di soggetto
            //con mobilità lunga)
            if (siglaCategoria == "VO" && datiIstruttoria != null && datiIstruttoria.CodiceMobilita.HasValue && datiIstruttoria.CodiceMobilita.Value == 1 && (codNat1 == ' ' || codNat1 == '6'))
            {
                if (datiAnagrafici.Sesso.Value == 'M')
                {
                    if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(60), dataSistema))
                    {
                        messaggioVideo = "Il pensionando deve aver compiuto 60 anni (trattasi di soggetto con mobilità lunga)";
                        return false;
                    }
                }
                else if (datiAnagrafici.Sesso.Value == 'F')
                {
                    if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(55), dataSistema))
                    {
                        messaggioVideo = "Il pensionando deve aver compiuto 55 anni (trattasi di soggetto con mobilità lunga)";
                        return false;
                    }
                }
            }

            //Se la Categoria (RACATEG) è = a “VO”, “VBANC”, “VDAI” e il 3° Codice
            //Natura (RAU1033) è = a “K” verificare che abbia compiuto 52 anni se uomini
            //o 47 anni se donne alla decorrenza originaria della pensione (RAU104) e che
            //abbia almeno 780 contributi sommando i Contributi Totali (RAU113A) e i
            //Contributi Volontari (RAU113B) (codice errore 44)
            switch (siglaCategoria)
            {
                case "VO":
                case "VBANC":
                case "VDAI":
                    if (codNat3 == 'K')
                    {
                        if (datiAnagrafici.Sesso.Value == 'M')
                        {
                            if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(52), decorrenzaOriginaria))
                            {
                                messaggioVideo = "Il pensionando deve aver compiuto 52 anni rispetto alla data di decorrenza originaria (codice errore 44)";
                                return false;
                            }
                        }
                        else if (datiAnagrafici.Sesso.Value == 'F')
                        {
                            if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(47), decorrenzaOriginaria))
                            {
                                messaggioVideo = "Il pensionando deve aver compiuto 47 anni rispetto alla data di decorrenza originaria (codice errore 44)";
                                return false;
                            }
                        }

                        if (datiIstruttoria != null)
                        {
                            int totale = datiIstruttoria.NSettimaneOBG.GetValueOrDefault() + datiIstruttoria.NContributiVolontari.GetValueOrDefault();
                            if (totale < 780)
                            {
                                messaggioVideo = "La somma del numero settimane e del numero contributi volontari diritto deve essere almeno di 780 (codice errore 44)";
                                return false;
                            }
                        }
                        else
                        {
                            messaggioVideo = "La somma del numero settimane e del numero contributi volontari diritto deve essere almeno di 780 (codice errore 44)";
                            return false;
                        }
                    }
                    break;
            }

            //Se il Campo DO-NOTE è = “ERI” verificare che il pensionando abbia
            //compiuto 65 anni alla Decorrenza Originaria (RAU104)
            if (filtro == "ERI")
            {
                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(65), decorrenzaOriginaria))
                {
                    messaggioVideo = "Il pensionando deve aver compiuto 65 anni rispetto alla data di decorrenza originaria";
                    return false;
                }
            }

            //Se la Categoria (RACATEG) è = a “VOTOT” e il 1° Codice natura (RAU1031)
            //è diverso da “1” o “2” e la Decorrenza Originaria (RAU104) è inferiore al 2011
            //il pensionando deve aver compiuto 65 anni alla Decorrenza Originaria
