            //            return false;
            //        }
            //    }
            //}
            //Se la Categoria (RACATEG) è = a “INDCOM” il pensionando deve aver
            //compiuto 57 anni e non aver compiuto 62 anni se femmina e deve aver
            //compiuto 62 anni e non aver compiuto 65 anni se maschio. Questo controllo
            //non è valido se il Campo DO-NOTE è = a “NIC” e la Decorrenza Originaria
            //(RAU104) è successiva a gennaio 2009
            if (siglaCategoria == "INDCOM" && filtro != "NIC" &&
                !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2009, 1, 1)))
            {
                if (datiAnagrafici.Sesso.Value == 'M')
                {
                    if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(62), decorrenzaOriginaria))
                    {
                        messaggioVideo = "Il pensionando deve aver compiuto 62 anni rispetto alla data di decorrenza originaria";
                        return false;
                    }
                    if (!Utility.DataSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(65), decorrenzaOriginaria))
                    {
                        messaggioVideo = "Il pensionando non deve aver compiuto 65 anni rispetto alla data di decorrenza originaria";
                        return false;
                    }
                }
                else if (datiAnagrafici.Sesso.Value == 'F')
                {
                    if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(57), decorrenzaOriginaria))
                    {
                        messaggioVideo = "Il pensionando deve aver compiuto 57 anni rispetto alla data di decorrenza originaria";
                        return false;
                    }
                    if (!Utility.DataSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(62), decorrenzaOriginaria))
                    {
                        messaggioVideo = "Il pensionando non deve aver compiuto 62 anni rispetto alla data di decorrenza originaria";
                        return false;
                    }
                }
            }

