            //Se la Categoria (RACATEG) è = a “VO”, “VR”, VOART”, “VOCOM” e la
            //Categoria altra pensione (RACATINV) è uguale alla Categoria (RACATEG) e
            //il 1° Codice Natura è = a spazio o “6” il pensionando deve aver compiuto 55
            //anni alla Decorrenza Originaria (RAU104) se femmina e 60 anni se maschio
            switch (siglaCategoria)
            {
                case "VO":
                case "VR":
                case "VOART":
                case "VOCOM":
                    if (codNat1 == ' ' || codNat1 == '6')
                    {
                        if (datiIstruttoria != null && datiIstruttoria.CodiceP18PrecedentePensione.HasValue && datiIstruttoria.CodiceP18PrecedentePensione.Value != 0)
                        {
                            string codCat = string.Empty;
                            GestioneDecodifica.GetCodCategoriaBySiglaCategoria(siglaCategoria, out codCat);
                            if (!string.IsNullOrEmpty(codCat) && int.Parse(codCat) == datiIstruttoria.CodiceP18PrecedentePensione.Value && !Utility.IsDomandaRipristinoOrRiliquidazione(datiPensione))
                            {
                                if (datiAnagrafici.Sesso.Value == 'M')
                                {
                                    if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(60), decorrenzaOriginaria))
                                    {
                                        messaggioVideo = "Il pensionando deve aver compiuto 60 anni rispetto alla data di decorrenza originaria";
                                        return false;
                                    }
                                }
                                else
                                {
                                    if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(55), decorrenzaOriginaria))
                                    {
                                        messaggioVideo = "Il pensionando deve aver compiuto 55 anni rispetto alla data di decorrenza originaria";
                                        return false;
                                    }
                                }
                            }
                        }
                    }
                    break;
                default:
                    break;
            }

            //Se la Categoria (RACATEG) è = a "VO", "VOP", "VOMIN", "VR", "VOART",
            //"VOCOM", "VOBANC", "VDAI" e il 1° Codice Natura è = a spazio o “6” e
            //l'Attività Economica è = a “99” e la Professione Individuale è = a “247” il
            //pensionando deve aver compiuto 60 anni alla Decorrenza Originaria
            //(RAU104) se femmina e 65 anni se maschio
            switch (siglaCategoria)
            {
                case "VO":
                case "VOP":
                case "VOMIN":
                case "VR":
                case "VOART":
                case "VOCOM":
                case "VOBANC":
                case "VDAI":
                    if (codNat1 == ' ' || codNat1 == '6')
                    {
                        if (datiPensione.AttivitaEconomica.HasValue && datiPensione.AttivitaEconomica.Value == 99 &&
                            datiPensione.ProfessioneIndividuale.HasValue && datiPensione.ProfessioneIndividuale.Value == 247)
                        {
                            if (datiAnagrafici.Sesso.Value == 'M')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(65), decorrenzaOriginaria))
                                {
                                    messaggioVideo = "Il pensionando deve aver compiuto 65 anni rispetto alla data di decorrenza originaria";
                                    return false;
                                }
                            }
                            else
                            {
                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(60), decorrenzaOriginaria) && !Utility.IsDomandaRipristinoOrRiliquidazione(datiPensione))
                                {
                                    messaggioVideo = "Il pensionando deve aver compiuto 60 anni rispetto alla data di decorrenza originaria";
                                    return false;
                                }
                            }
                        }
                    }

                    if (siglaCategoria == "VO")
                    {
                        //Se la Categoria (RACATEG) è = a "VO" e l'Attività Economica è = a “52” e la
                        //Professione Individuale è = a “888” e il Codice Requisiti Ridotti
                        //(RAUCODDIR) è = a “6” il pensionando deve aver compiuto 55 anni alla
                        //Decorrenza Originaria (RAU104) se femmina e 60 anni se maschio
                        if (datiPensione.AttivitaEconomica.HasValue && datiPensione.AttivitaEconomica.Value == 52 &&
                                datiPensione.ProfessioneIndividuale.HasValue && datiPensione.ProfessioneIndividuale.Value == 888 &&
                            datiIstruttoria != null && datiIstruttoria.Legge44997.HasValue && datiIstruttoria.Legge44997.Value == 6)
                        {
                            if (datiAnagrafici.Sesso.Value == 'M')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(60), decorrenzaOriginaria) && !Utility.IsDomandaRipristinoOrRiliquidazione(datiPensione))
                                {
                                    messaggioVideo = "Il pensionando deve aver compiuto 60 anni rispetto alla data di decorrenza originaria";
                                    return false;
                                }
                            }
                            else
                            {
                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(55), decorrenzaOriginaria))
                                {
                                    messaggioVideo = "Il pensionando deve aver compiuto 55 anni rispetto alla data di decorrenza originaria";
                                    return false;
                                }
                            }
                        }
                        //Se la Categoria (RACATEG) è = a "VO" e l'Attività Economica è = a “52” e la
                        //Professione Individuale è = a “888” e il Codice Requisiti Ridotti
                        //(RAUCODDIR) è diverso da “6” il pensionando deve aver compiuto 60 anni
                        //alla Decorrenza Originaria (RAU104) se femmina e 65 anni se maschio
                        if (datiPensione.AttivitaEconomica.HasValue && datiPensione.AttivitaEconomica.Value == 52 &&
                                datiPensione.ProfessioneIndividuale.HasValue && datiPensione.ProfessioneIndividuale.Value == 888 &&
                            (datiIstruttoria == null || !datiIstruttoria.Legge44997.HasValue || datiIstruttoria.Legge44997.Value != 6))
                        {
                            if (datiAnagrafici.Sesso.Value == 'M')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(65), decorrenzaOriginaria) &&
                                    !Utility.IsDomandaQuota100(datiPensione) && !Utility.IsDomandaQuota102(datiPensione) && !Utility.IsDomandaAnticipata(datiPensione) && !Utility.IsDomandaAnticipataFlessibile(datiPensione) && !Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione) &&
                                    !((!Utility.IsRicostituzione(datiPensione.Gruppo) && !Utility.IsRiaperturaDomanda(datiPensione.Id) && (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))) ||
                                      ((Utility.IsRicostituzione(datiPensione.Gruppo) || Utility.IsRiaperturaDomanda(datiPensione.Id)) && ((ctrlMemo123_2024 != null && ctrlMemo123_2024.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione)) || (ctrlMemo123_2024OpzioneContrib != null && ctrlMemo123_2024OpzioneContrib.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))))) &&
                                    !Utility.IsDomandaVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE(datiPensione))
                                {
                                    messaggioVideo = "Il pensionando deve aver compiuto 65 anni rispetto alla data di decorrenza originaria";
                                    return false;
                                }
                            }
                            else
                            {
                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(60), decorrenzaOriginaria) && !Utility.IsDomandaRipristinoOrRiliquidazione(datiPensione))
                                {
                                    messaggioVideo = "Il pensionando deve aver compiuto 60 anni rispetto alla data di decorrenza originaria";
                                    return false;
                                }
                            }
                        }
                    }
                    //Se la Categoria (RACATEG) è = a "VO", "VR", "VOART", "VOCOM",
                    //"VOBANC", "VDAI" e il 1° Codice Natura è = a spazio o “6” e l'Attività
                    //Economica è = a “65” e la Professione Individuale è = a “999” il pensionando
                    //deve aver compiuto 60 anni alla Decorrenza Originaria (RAU104) se
                    //femmina e 65 anni se maschio
                    switch (siglaCategoria)
                    {
                        case "VO":
                        case "VR":
                        case "VOART":
                        case "VOCOM":
                        case "VOBANC":
                        case "VDAI":
                            if ((codNat1 == ' ' || codNat1 == '6') && datiPensione.AttivitaEconomica.HasValue && datiPensione.AttivitaEconomica.Value == 65 &&
                                datiPensione.ProfessioneIndividuale.HasValue && datiPensione.ProfessioneIndividuale.Value == 999)
                            {
                                if (datiAnagrafici.Sesso.Value == 'M')
                                {
                                    if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(65), decorrenzaOriginaria))
                                    {
                                        messaggioVideo = "Il pensionando deve aver compiuto 65 anni rispetto alla data di decorrenza originaria";
                                        return false;
                                    }
                                }
                                else
                                {
                                    if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(60), decorrenzaOriginaria) && !Utility.IsDomandaRipristinoOrRiliquidazione(datiPensione))
                                    {
                                        messaggioVideo = "Il pensionando deve aver compiuto 60 anni rispetto alla data di decorrenza originaria";
                                        return false;
                                    }
                                }
                            }
                            break;
                        default:
                            break;
                    }
                    break;
                default:
                    break;
            }

            if (!Utility.IsRicostituzione(datiPensione.Gruppo) && !ControlsPensioneAcquisibile(decorrenzaOriginaria, siglaCategoria, codNat1, datiPensione, datiAnagrafici, datiIstruttoria != null ? datiIstruttoria.Legge44997 : null, datiMaggiorazioniBenefici,
                tipoCalcolo))
            {
                messaggioVideo = "La pensione è soggetta alle finestre di pensionamento ed è quindi non acquisibile";
                return false;
            }

            if (!ControlsEtaPensionamento(siglaCategoria, codNat1, datiPensione, datiAnagrafici, out messaggioVideo))
            {
                return false;
            }

            if (!ControlsDA(datiDA, decorrenzaOriginaria, datiPensione.AttivitaEconomica, datiPensione.ProfessioneIndividuale, out messaggioVideo))
                return false;

            //La decorrenza della Categoria (RACATEG) = a “PMO” non può essere
            //superiore a gennaio 1965, per le reversibilità identificate con Categoria
            //(RACATEG) = a “PMO” e il campo PDIRSUP = a 1 il controllo va effettuato
            //sulla Decorrenza della Diretta (DAU106)
            if (siglaCategoria == "PMO")
            {
                if (pdirsup == 1)
                {
                    if (datiDA != null && datiDA.DecorrenzaPensione.HasValue)
                    {
                        if (Utility.DataStrettamenteSuccessivaA(datiDA.DecorrenzaPensione.Value, new DateTime(1965, 1, 31)))
                        {
                            messaggioVideo = "La decorrenza della diretta non puà essere superiore a gennaio 1965";
                            return false;
                        }
                    }
                }
                else
                {
                    if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(1965, 1, 31)))
                    {
                        messaggioVideo = "La decorrenza originaria non puà essere superiore a gennaio 1965";
                        return false;
                    }
                }
            }

            //Se la Categoria (RACATEG) è diversa da “VOBIS”, “IOBIS”, “VMP”, “IMP” e il
            //campo PDIRSUP è = a zero e (il campo Provvisoria RAFLGPRW) è = “” Se
            //la Decorrenza Originaria (RAU104) è superiore alla data che ogni anno si
            //varia (attualmente a gennaio 2014) la pensione non è liquidabile prima che
            //siano disponibili i coefficienti per il nuovo anno
            if (siglaCategoria != "VOBIS" && siglaCategoria != "IOBIS" && siglaCategoria != "VMP" && siglaCategoria != "IMP")
            {
                if (pdirsup == 0 && datiNuoveLiquidate != null && (!datiNuoveLiquidate.FlagProvvisoria.HasValue || !datiNuoveLiquidate.FlagProvvisoria.Value))
                {
                    if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(annoCompetenza + 1, 1, 1)))
                    {
                        messaggioVideo = "La pensione non è liquidabile prima che siano disponibili i coefficienti per il nuovo anno";
                        return false;
                    }
                }
            }
            return true;
        }

        public static bool ControlsTipoCalcolo(GestionePensione.DatiPensione datiPensione, GestioneDatiStoricoGP.DatiStoricoGP datiStoricoGP, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, byte? tipoCalcoloEntity, bool isRiapertura, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);

            //Utility.TipoCalcolo tipoCalcolo = Utility.GetTipoCalcolo(datiPensione);
            Utility.TipoCalcolo tipoCalcolo = (Utility.TipoCalcolo)tipoCalcoloEntity.GetValueOrDefault();
            #endregion Recupero Dati

            //Se la Categoria (RACATEG) è = a “INDCOM” e il Campo DO-NOTE è = a
            //“NIC” il Campo RINSIEME (Tipo Calcolo) non può essere “SI”

            //Se la Categoria (RACATEG) è = a “INDCOM” e il Campo DO-NOTE è = a
            //“MPA”, “MPM", "ESO", “SAA”, “SVA”, “SAM”, “SVM” il Campo RINSIEME
            //(Tipo Calcolo) non può essere “SI”)

            switch (filtro)
            {
                case "NIC":
                case "MPA":
                case "MPM":
                case "ESO":
                case "SAA":
                case "SVA":
                case "SAM":
                case "SVM":
                    if (siglaCategoria == "INDCOM")
                    {
                        if (tipoCalcolo == Utility.TipoCalcolo.Contributivo)
                        {
                            messaggioVideo = "Il tipo calcolo non può essere contributivo";
                            return false;
                        }
                    }
                    break;
                default:
                    break;
            }

            if (Utility.IsPrepensionamentoEditoriaArt1c154L205_2017(datiPensione) || Utility.IsPrepensionamentoEditoriaArt1c500L160_2019(datiPensione))
            {
                if (tipoCalcolo == Utility.TipoCalcolo.Contributivo)
                {
                    messaggioVideo = "Il tipo calcolo non può essere contributivo";
                    return false;
                }
            }

            if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiapertura) && datiStoricoGP != null && datiStoricoGP.TipoCalcolo.HasValue && Utility.IsDomandaAnte96(datiPensione, datiPensione, datiDanteCausa, isRiapertura) == null)
            {
                if ((tipoCalcoloEntity == 1 && new List<byte> { 2, 21, 26, 27 }.Contains(datiStoricoGP.TipoCalcolo.Value)) ||
                    (datiStoricoGP.TipoCalcolo == 1 && new List<byte> { 2, 21, 26, 27 }.Contains(tipoCalcoloEntity.Value)))
                {
                    messaggioVideo = "Il tipo calcolo non può essere variato da/a contributivo.La pensione deve essere eliminata e riliquidata.";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsInizioFineAssicurazione(DateTime? inizioAssicurazione, DateTime? fineAssicurazione, string naturaPensione, byte? provenienzaDA,
            DateTime? decPensDA, char? codiceLiquidazione, GestionePensione.DatiPensione datiPensione, GestioneDatiGenericiAgoCi.PensioniDatiGenerici datiPensioniDatiGenerici,
            List<GestioneCalcolo.QuotePensione> lQuotePensione, Utility.TipoCalcolo tipoCalcolo, bool isRiaperturaDomanda, bool isInvioCalcolo, DateTime? inizioBonus, List<GestioneCalcolo.DatiCalcoloContributivo> lDatiContributivi,
            ref EntityBLCommon.ContenitoreDecodifica contenitoreDecodifica, bool? facoltaComputo, int? nSettimaneOBG, DateTime? dataNascitaTitolare, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            bool posticipo = false;
            int panvein = 0;

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            Utility.GetCodiciNatura(naturaPensione, out codNat1, out codNat2, out codNat3);
            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);

            byte codProv = provenienzaDA.HasValue ? provenienzaDA.Value : (byte)0;
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);
            GetPanvein_Posticipo(datiPensione.NaturaPensione, datiPensione, out panvein, out posticipo);
            #endregion Recupero Dati

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024", out ctrlMemo123_2024);

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024OpzioneContrib = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024OpzioneContrib", out ctrlMemo123_2024OpzioneContrib);

            if (!Utility.IsDomandaPSO(datiPensione.SiglaCategoria))
            {
                if (inizioAssicurazione.HasValue)
                {
                    //La Data Inizio Assicurazione (VINASS) non può essere precedente al 25
                    //maggio 1915
                    if (!Utility.DataSuccessivaA(inizioAssicurazione.Value, new DateTime(1915, 05, 25)))
                    {
                        messaggioVideo = "La data di inizio assicurazione non può essere precedente al 25 maggio 1915";
                        return false;
                    }
                    switch (filtro)
                    {
                        //Se il campo DO-NOTE è = a “CSL”, “SSA”, “SSM” la Data Inizio
                        //Assicurazione (VINASS) non può essere successiva al 31 dicembre 1995
                        case "CSL":
                        case "SSA":
                        case "SSM":
                            if (Utility.DataStrettamenteSuccessivaA(inizioAssicurazione.Value, new DateTime(1995, 12, 31)))
                            {
                                messaggioVideo = "La data di inizio assicurazione non può essere successiva al 31 dicembre 1995";
                                return false;
                            }
                            break;
                        //Se il Campo DO-NOTE è = a “SUT”, “ERI” la Data Inizio Assicurazione
                        //(VINASS) non può essere inferiore al 1996
                        case "SUT":
                        case "ERI":
                            if (!Utility.DataSuccessivaA(inizioAssicurazione.Value, new DateTime(1996, 01, 01)))
                            {
                                messaggioVideo = "La data di inizio assicurazione non può essere inferiore al 1996";
                                return false;
                            }
                            break;
                        default:
                            break;
                    }

                    //condizione prioritaria rispetto alle altre
                    if (Utility.IsDomandaIndennitaUnaTantum_AGO(datiPensione))
                    {
                        if (!Utility.DataSuccessivaA(inizioAssicurazione.Value, new DateTime(1996, 01, 01)))
                        {
                            messaggioVideo = "La data di inizio assicurazione non può essere inferiore al 1996";
                            return false;
                        }
                    }
                    else
                    {
                        switch (siglaCategoria)
                        {
                            //Se la Categoria (RACATEG) è = a “INDCOM” la Data Inizio Assicurazione
                            //(VINASS) non può essere inferiore al 1965
                            case "INDCOM":
                                if (!Utility.DataSuccessivaA(inizioAssicurazione.Value, new DateTime(1965, 01, 01)))
                                {
                                    messaggioVideo = "La data di inizio assicurazione non può essere inferiore al 1965";
                                    return false;
                                }
                                break;
                            //Se la Categoria (RACATEG) è = a “SDAI” e il 2° Codice Natura (RAU1032) è
                            //= a “O” la Data Inizio Assicurazione (VINASS) non può essere successiva al
                            //31 dicembre 1995
                            //Se la Categoria (RACATEG) è = a “SO”, “SR”, “SOART”, “SOCOM”, “SDAI” e
                            //il 2° Codice Natura è = a “O” la Data Inizio Assicurazione (VINASS) non può
                            //essere successiva al 1995
                            case "SO":
                            case "SR":
                            case "SOART":
                            case "SOCOM":
                            case "SDAI":
                                if (codNat2 == 'O')
                                {
                                    if (Utility.DataStrettamenteSuccessivaA(inizioAssicurazione.Value, new DateTime(1995, 12, 31)))
                                    {
                                        messaggioVideo = "La data di inizio assicurazione non può essere successiva al 1995";
                                        return false;
                                    }
                                }
                                break;
                            case "VO":
                                if (Utility.IsDomandaManualeInvaliditaOver80(datiPensione) && Utility.DataSuccessivaA(inizioAssicurazione.Value, new DateTime(1996, 01, 01)))
                                {
                                    messaggioVideo = "La data di inizio assicurazione non può essere maggiore o uguale al 1996";
                                    return false;
                                }
                                break;
                            case "VOP":
                                if (!Utility.IsDomandaAutomatica(datiPensione) && tipoCalcolo != Utility.TipoCalcolo.Contributivo && Utility.DataSuccessivaA(inizioAssicurazione.Value, new DateTime(1996, 01, 01)))
                                {
                                    messaggioVideo = "La data di inizio assicurazione non può essere maggiore o uguale al 1996";
                                    return false;
                                }
                                break;
                            case "VOAUT":
                            case "IOAUT":
                            case "SOAUT":
                                //AUT – Memo 123/2020 - Liquidazione Pensione > Assicurativi: Inserire un nuovo controllo che verifichi che la data inizio assicurazione sia strettamente inferiore al 1/1/1996.
                                //Si richiede di estendere il controllo anche alle PL IOAUT e alle PL SOAUT(quindi rispettivamente gruppo = 0002 e gruppo = 0003) quando facoltà di computo = SI
                                //ENG - Gestione RIC/TRF VOAUT Vecchiaia in Computo e Anticipate in  Computo(PAV e no PAV)
                                if ((Utility.IsDomandaAnzianitaInComputo(datiPensione) || Utility.IsDomandaVecchiaiaInComputo(datiPensione) ||
                                    (datiPensione.IdTipoPLPerRIC == 21 || datiPensione.IdTipoPLPerRIC == 26 || datiPensione.IdTipoPLPerRIC == 28) ||
                                    ((siglaCategoria == "IOAUT" || siglaCategoria == "SOAUT") && !Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && facoltaComputo.HasValue && facoltaComputo.Value))
                                    && Utility.DataSuccessivaA(inizioAssicurazione.Value, new DateTime(1996, 01, 01)))
                                {
                                    messaggioVideo = "La data di inizio assicurazione non può essere maggiore o uguale al 1996";
                                    return false;
                                }
                                break;
                            case "VOBANC":
                                if (!Utility.IsDomandaAutomatica(datiPensione) && !Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && tipoCalcolo != Utility.TipoCalcolo.Contributivo && Utility.DataSuccessivaA(inizioAssicurazione.Value, new DateTime(1996, 01, 01)))
                                {
                                    messaggioVideo = "La data di inizio assicurazione non può essere maggiore o uguale al 1996";
                                    return false;
                                }
                                break;
                            case "IOCUM":
                                // se contributivi nel quadro generici è a si 
                                if (Utility.IsPensioneInabilitaProficuoLavoroCumulo(datiPensione) && datiPensione.Contributivo == '2' && Utility.DataSuccessivaA(inizioAssicurazione.Value, new DateTime(1996, 01, 01)))
                                {
                                    messaggioVideo = "La data di inizio assicurazione non può essere maggiore o uguale al 1996";
                                    return false;
                                }
                                break;
                            default:
                                break;
                        }

                        //FG - Controlli tipo contributivo - data inizio assicurazione
                        //ENG - Memo 166/2023
                        if ((Utility.IsDomandaTipoContributivo(datiPensione, null, false) || Utility.isDomandaVecchiaiaTrasformazioneAOICalcoloContributivo(datiPensione)) && !isRiaperturaDomanda && !Utility.IsDomandaAUT(datiPensione))
                        {
                            if (!Utility.DataSuccessivaA(inizioAssicurazione.Value, new DateTime(1996, 01, 01)))
                            {
                                messaggioVideo = "La data di inizio assicurazione non può essere inferiore al 1996";
                                return false;
                            }
                        }

                        if (Utility.IsDomandaTipoContributivo(datiPensione, null, true) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione) ||
                            (!Utility.IsRicostituzione(datiPensione.Gruppo) && !Utility.IsRiaperturaDomanda(datiPensione.Id) && (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))) ||
                             ((Utility.IsRicostituzione(datiPensione.Gruppo) || Utility.IsRiaperturaDomanda(datiPensione.Id)) && ((ctrlMemo123_2024 != null && ctrlMemo123_2024.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione)) || (ctrlMemo123_2024OpzioneContrib != null && ctrlMemo123_2024OpzioneContrib.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione)))) ||
                            Utility.IsDomandaVOAUTAnticipataTipoContributivoFiltroGSE(datiPensione) || Utility.IsDomandaVOAUTVecchiaiaTipoContributivoFiltroGSE(datiPensione) || Utility.IsDomandaVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE(datiPensione))
                        {
                            if (Utility.DataSuccessivaA(inizioAssicurazione.Value, new DateTime(1996, 01, 01)))
                            {
                                messaggioVideo = "La data di inizio assicurazione deve essere inferiore al 1996";
                                return false;
                            }
                        }

                        if (!ControlsInizioAssicurazioneAUT(ref contenitoreDecodifica, datiPensione, lDatiContributivi, facoltaComputo, inizioAssicurazione, naturaPensione, nSettimaneOBG, out messaggioVideo))
                            return false;
                    }
                }

                if (fineAssicurazione.HasValue)
                {
                    if (Utility.IsDomandaCumulo(siglaCategoria) && datiPensioniDatiGenerici != null &&
                        datiPensioniDatiGenerici.TipoCumulo.HasValue && !datiPensioniDatiGenerici.TipoCumulo.Value)
                    {
                        if (isInvioCalcolo && lQuotePensione != null && lQuotePensione.Count > 0)
                        {
                            DateTime? dataQuotaConfronto = lQuotePensione.Select(x => x.Decorrenza).Max();
                            if (dataQuotaConfronto.HasValue && Utility.DataSuccessivaA(fineAssicurazione.Value, dataQuotaConfronto.Value))
                            {
                                messaggioVideo = string.Format("La data di fine assicurazione deve essere inferiore alla decorrenza quota pensione ({0})", dataQuotaConfronto.Value.ToString("dd/MM/yyyy"));
                                return false;
                            }
                        }
                    }
                    else
                    {
                        //La Data Fine Assicurazione (VFIASS) deve essere inferiore alla Decorrenza Originaria (RAU104)
                        if (Utility.DataSuccessivaA(fineAssicurazione.Value, decorrenzaOriginaria))
                        {
                            messaggioVideo = "La data di fine assicurazione deve essere inferiore alla decorrenza originaria";
                            return false;
                        }
                    }

                    //Se il Codice Provenienza (DAU107) è = a “1” o “2” la Data Fine
                    //Assicurazione (VFIASS) deve essere inferiore alla Data della Decorrenza
                    //Originaria della diretta (DAU106)
                    if (codProv == 1 || codProv == 2)
                    {
                        if (decPensDA.HasValue)
                        {
                            if (Utility.IsDomandaSOCUM(siglaCategoria))
                            {
                                if (Utility.DataStrettamenteSuccessivaA(new DateTime(fineAssicurazione.Value.Year, fineAssicurazione.Value.Month, 1), new DateTime(decPensDA.Value.Year, decPensDA.Value.Month, 1)))
                                {
                                    messaggioVideo = "La data di fine assicurazione deve essere inferiore alla decorrenza originaria della diretta";
                                    return false;
                                }
                            }
                            else
                            {
                                if (Utility.DataSuccessivaA(fineAssicurazione.Value, decPensDA.Value))
                                {
                                    messaggioVideo = "La data di fine assicurazione deve essere inferiore alla decorrenza originaria della diretta";
                                    return false;
                                }
                            }
                        }
                    }

                    switch (siglaCategoria)
                    {
                        case "SDAI":
                            //Se la Categoria (RACATEG) è = a”SDAI” e il Codice Provenienza (DAU107)
                            //è diverso da “1” o “2” la Data Fine Assicurazione (VFIASS) deve essere
                            //inferiore alla Data Decorrenza Originaria (RAU104)
                            if (codProv != 1 && codProv != 2)
                            {
                                if (Utility.DataSuccessivaA(fineAssicurazione.Value, decorrenzaOriginaria))
                                {
                                    messaggioVideo = "La data di fine assicurazione deve essere inferiore alla decorrenza originaria";
                                    return false;
                                }
                            }
                            break;
                        //Se trattasi di contributiva, Campo RINSIEME = a “SI”, e il 1° Codice Natura è
                        //diverso da “5” e la Categoria (RACATEG) è = a “VOAUT”, “IOAUT”, “SOAUT”
                        //e il Campo DO-NOTE è diverso da “SUT” la Data Fine Assicurazione
                        //(VFIASS) non può essere antecedente a 31 marzo 2001
                        case "VOAUT":
                        case "IOAUT":
                        case "SOAUT":
                            if (tipoCalcolo == Utility.TipoCalcolo.Contributivo && codNat1 != '5' && filtro != "SUT")
                            {
                                if (!Utility.DataSuccessivaA(fineAssicurazione.Value, new DateTime(2001, 03, 31)))
                                {
                                    messaggioVideo = "La data di fine assicurazione non può essere antecedente al 31 marzo 2001";
                                    return false;
                                }
                            }
                            break;
                        //Se la Categoria (RACATEG) è = a “VOESO” e il Campo DO-NOTE è = a
                        //“AGO”, “OBG” la Data Fine Assicurazione (VFIASS) deve essere il mese
                        //precedente la Decorrenza Originaria (RAU104)
                        case "VOESO":
                            if (filtro == "AGO" || filtro == "OBG")
                            {
                                if (!Utility.DataSuccessivaA(fineAssicurazione.Value, decorrenzaOriginaria.AddMonths(-1)) ||
                                    Utility.DataSuccessivaA(fineAssicurazione.Value, decorrenzaOriginaria))
                                {
                                    messaggioVideo = "La data di fine assicurazione deve essere il mese precedente la decorrenza originaria";
                                    return false;
                                }
                            }
                            break;
                        //Se la Categoria (RACATEG) è = a “VMP”, “IMP” la Data Fine Assicurazione
                        //(VFIASS) deve essere precedente la Decorrenza Originaria (RAU104)
                        case "VMP":
                        case "IMP":
                            if (Utility.DataSuccessivaA(fineAssicurazione.Value, decorrenzaOriginaria))
                            {
                                messaggioVideo = "La data di fine assicurazione deve essere precedente la decorrenza originaria";
                                return false;
                            }
                            break;
                        case "SOTOT":
                            //Se la Categoria (RACATEG) è = a “SOTOT” e il Campo DAU107 è = a “1”,
                            //“2” la Data Fine Assicurazione (VFIASS) deve essere inferiore alla Data della
                            //Decorrenza Originaria della diretta (DAU106)
                            if (codProv == 1 || codProv == 2)
                            {
                                if (decPensDA.HasValue)
                                {
                                    if (Utility.DataSuccessivaA(fineAssicurazione.Value, decPensDA.Value))
                                    {
                                        messaggioVideo = "La data di fine assicurazione deve essere inferiore alla decorrenza originaria della diretta";
                                        return false;
                                    }
                                }
                            }
                            //Se la Categoria (RACATEG) è = a “SOTOT” e il Campo DAU107 è diverso
                            //da “1”, “2” la Data Fine Assicurazione (VFIASS) deve essere inferiore alla
                            //Data della Decorrenza Originaria (RAU104)
                            else
                            {
                                if (Utility.DataSuccessivaA(fineAssicurazione.Value, decorrenzaOriginaria))
                                {
                                    messaggioVideo = "La data di fine assicurazione deve essere inferiore alla decorrenza originaria";
                                    return false;
                                }
                            }
                            break;
                        default:
                            break;
                    }

                    //Se posticipo = S la data fine assicurazione deve essere inferiore alla data inizio SCO
                    if (posticipo)
                    {
                        if (inizioBonus.HasValue)
                        {
                            if (Utility.DataSuccessivaA(fineAssicurazione.Value, inizioBonus.Value))
                            {
                                messaggioVideo = "La data di fine assicurazione deve essere inferiore alla data di inizio bonus";
                                return false;
                            }
                        }
                        else if (!(Utility.IsRicostituzione(datiPensione.Gruppo) || (isRiaperturaDomanda && !Utility.IsDomandaAutomatica(datiPensione))))
                        {
                            messaggioVideo = "La data di inizio bonus non è presente. Occorre lavorare la domanda con Unicarpe";
                            return false;
                        }
                    }
                }

                if (inizioAssicurazione.HasValue && fineAssicurazione.HasValue)
                {
                    switch (siglaCategoria)
                    {
                        //Se la Categoria (RACATEG) è = a “INDCOM” la Data Fine Assicurazione
                        //(VFIASS) non può essere inferiore a 5 anni dalla Data Inizio Assicurazione
                        //(VINASS)
                        case "INDCOM":
                            if (Utility.IsDomandaINDCOM175(datiPensione))
                            {
                                if (!Utility.DataSuccessivaA(fineAssicurazione.Value, new DateTime(2017, 01, 01)))
                                {
                                    messaggioVideo = "La data di fine assicurazione deve essere superiore o uguale al 01/01/2017";
                                    return false;
                                }
                                if (!Utility.DataSuccessivaA(fineAssicurazione.Value, inizioAssicurazione.Value.AddYears(5)))
                                {
                                    messaggioVideo = "La data di fine assicurazione non può essere inferiore a 5 anni dalla data di inizio assicurazione";
                                    return false;
                                }
                                if (Utility.DataSuccessivaA(new DateTime(2019, 01, 01), fineAssicurazione.Value) && Utility.DataSuccessivaA(new DateTime(2019, 11, 01), decorrenzaOriginaria))
                                {
                                    messaggioVideo = "Se la data di fine assicurazione è minore del 01/01/2019 allora la decorrenza pensione deve essere maggiore di novembre 2019";
                                    return false;
                                }
                            }
                            else if (!Utility.IsDomandaINDCOM175(datiPensione) && Utility.IsDomandaPL(datiPensione))
                            {
                                if (!Utility.DataSuccessivaA(fineAssicurazione.Value, inizioAssicurazione.Value.AddYears(5)))
                                {
                                    messaggioVideo = "La data di fine assicurazione non può essere inferiore a 5 anni dalla data di inizio assicurazione";
                                    return false;
                                }
                            }
                            break;
                        case "VMP":
                        case "IMP":
                            if (!Utility.DataSuccessivaA(fineAssicurazione.Value, inizioAssicurazione.Value.AddYears(5)) && !Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                            {
                                messaggioVideo = "La data di fine assicurazione non può essere inferiore a 5 anni dalla data di inizio assicurazione";
                                return false;
                            }
                            break;
                        default:
                            break;
                    }

                    //La Data Fine Assicurazione (VFIASS) deve essere  successiva alla Data Inizio Assicurazione (VINASS)
                    if (!Utility.DataSuccessivaA(fineAssicurazione.Value, inizioAssicurazione.Value))
                    {
                        messaggioVideo = "La data di fine assicurazione deve essere successiva alla data di inizio assicurazione";
                        return false;
                    }
                }

                if (Utility.IsDomandaBanc_91_95(datiPensione, datiPensione.DecorrenzaOriginaria, decPensDA) && Utility.IsDomandaPL(datiPensione))
                {
                    DateTime date = new DateTime(2000, 12, 31);
                    if (Utility.GetTipoCalcolo(datiPensione) == Utility.TipoCalcolo.Contributivo &&
                        (dataNascitaTitolare.HasValue && datiPensione.DecorrenzaOriginaria.HasValue) &&
                        (Utility.GetEta(dataNascitaTitolare.Value, datiPensione.DecorrenzaOriginaria.Value) >= 57) &&
                        Utility.DataStrettamenteSuccessivaA(date, fineAssicurazione.Value))
                    {
                        messaggioVideo = "La data fine assicurazione non può essere inferiore al 2000";
                        return false;
                    }
                }
                if (!(Utility.IsDomandaSPED(datiPensione) && Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda)) &&
                    !(Utility.IsDomandaENPALS(datiPensione.Gestione) && decPensDA.HasValue && !Utility.DataSuccessivaA(decPensDA.Value, new DateTime(1995, 1, 1))) &&
                    !((Utility.IsDomandaVOST(datiPensione.SiglaCategoria) || Utility.IsRenditaCasalinghe(datiPensione) || Utility.IsRenditaFacoltativa(datiPensione)) && Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda)))
                    //Se il Campo RAUE23 è = a “P” possono non esistere i dati di Inizio
                    //Assicurazione (VINASS) e Fine Assicurazione (VFIASS)
                    if (!inizioAssicurazione.HasValue || !fineAssicurazione.HasValue)
                    {
                        if (!codiceLiquidazione.HasValue || codiceLiquidazione.Value.ToString().ToUpperInvariant() != "P")
                        {
                            messaggioVideo = "Le date di inizio e fine assicurazione sono obbligatorie";
                            return false;
                        }
                    }
            }
            return true;
        }

        public static bool VerificaDataPerfezionamentoPerPensioneTipoContributivo(GestionePensione.DatiPensione datiPensione, int? nSettimaneOBG, int? nContributiVolontari, Entity.DatiAssicurativi.ENPALS datiEnpals,
            GestioneAnagrafica.DatiAnagrafici datiAnagraficiTitolare, DateTime dataSistema, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            //ENG - MEMO 166/2023
            if (Utility.IsDomandaTipoContributivo(datiPensione, null, null) || Utility.isDomandaVecchiaiaTrasformazioneAOICalcoloContributivo(datiPensione) ||
                (Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) && !Utility.IsRiaperturaDomanda(datiPensione.Id) && datiPensione.IsCumuloAutomatica.GetValueOrDefault() &&
                datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0002" && datiPensione.Tipo == "0017"))
            {
                int numSettimaneTipoContibutivo = GestioneCrossControls.AGO_GetNumeroSettimane(datiPensione, datiEnpals != null ? datiEnpals.AADiritto : (short?)null, datiEnpals != null ? datiEnpals.MMDiritto : (short?)null, nSettimaneOBG, nContributiVolontari);
                if (!GestioneCrossControls.ALL_VerificaDataPerfezionamentoPerPensioneTipoContributivo(datiPensione, datiAnagraficiTitolare, numSettimaneTipoContibutivo, out messaggioVideo))
                    return false;
            }
            return true;
        }

