        public static bool ControlsNSettimaneOBG(int nSettimaneOBG, int nContributiVolontari, string naturaPensione, char? codiceLiquidazione, byte? tipoCalcolo, DateTime? inizioAssicurazione,
            GestionePensione.DatiPensione datiPensione, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, GestioneAnagrafica.DatiAnagrafici datiAnagraficiTitolare, GestioneBeneficioVittimeTerrorismo.DatiBeneficioVittimeTerrorismo datiBeneficioVittimeTerrorismo,
            GestioneDatiGenericiAgoCi.PensioniDatiGenerici datiPensioniDatiGenerici, short? codiceAziendaEditoria, List<GestioneBeneficiParticolari.DatiBeneficiParticolari> listaDatiBeneficiParticolari, List<GestioneAnagraficaAccordi.DecodAnagraficaAccordi> listaAnagraficaAccordi, List<GestioneDecodifica.DecodificaEnteCassaProfessionale> ElencoDecodificaEnteCassaProfessionale, char? contributivo, bool isRiaperturaDomanda, INPS.Pensioni.Liquidazione.BLCommon.GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici datiMaggiorazioniBenefici,
            out string messaggioVideo, string campoGP2BB05 = null, string codiceBancaEsodatiTraduzioneSuGP = "0", int? nSettimaneOI = null)
        {
            messaggioVideo = string.Empty;

            GestioneAnagraficaAccordi.DecodAnagraficaAccordi anagraficaAccordo = listaAnagraficaAccordi.Find(x => x.Codice == codiceAziendaEditoria);
            int? sommaSettimaneBenefici = listaDatiBeneficiParticolari != null && listaDatiBeneficiParticolari.Count > 0 ? listaDatiBeneficiParticolari.Sum(x => x.Settimane) : 0;
            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';
            int pdirsup = 0;
            int plavaut = 0;
            DateTime dataSistema = Utility.DataSistemaAgo;

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            DateTime decorrenzaOriginaria = datiPensione.DecorrenzaOriginaria.HasValue ? datiPensione.DecorrenzaOriginaria.Value : DateTime.MinValue;

            Utility.GetCodiciNatura(naturaPensione, out codNat1, out codNat2, out codNat3);
            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            GetPdirusp_Plavaut(datiPensione, out pdirsup, out plavaut);

            GestioneControlliDinamici.ControlloDinamico ctrl = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo123_2021", out ctrl);

            GestioneControlliDinamici.ControlloDinamico ctrl28_2024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo28_2024", out ctrl28_2024);

            #endregion Recupero Dati

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024", out ctrlMemo123_2024);

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024OpzioneContrib = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024OpzioneContrib", out ctrlMemo123_2024OpzioneContrib);

            if (Utility.IsDomandaOrganizzazioniInternazionali(datiPensione))
            {
                nSettimaneOBG += (nSettimaneOI.HasValue ? nSettimaneOI.Value : 0);
            }

            if (Utility.IsDomandaINPDAI(datiPensione.SiglaCategoria) && !Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1997, 1, 1)) && Utility.IsDomandaRipristino(datiPensione).GetValueOrDefault() && GestioneBypassControllo.CheckBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.BYPASS_ANTE96_BANC_AGO))
                return true;

            //TODO saltare controlli di ripristini/riliq se è un ante96 
            if (datiPensione != null && datiPensione.Gruppo == "0051" && datiPensione.Prodotto == "0122" && datiPensione.Tipo == "0022")
            {
                if ((codNat1 == ' ' || codNat1 == '6') && datiPensione.DataPerfezionamentoRequisiti.HasValue && datiPensione.DataPerfezionamentoRequisiti.Value.Year > 2011 && nSettimaneOBG < 1040)
                {
                    messaggioVideo = "Il numero settimane deve essere maggiore o uguale a 1040 ";
                    return false;
                }
                if (!(inizioAssicurazione.HasValue && Utility.DataSuccessivaA(inizioAssicurazione.Value, new DateTime(1996, 01, 01)) && codNat1 == '5' && codNat3 == 'D' && datiPensione.DataPerfezionamentoRequisiti.HasValue && datiPensione.DataPerfezionamentoRequisiti.Value.Year > 2011))
                {
                    if (codNat1 == '5' && datiPensione.DataPerfezionamentoRequisiti.HasValue && datiPensione.DataPerfezionamentoRequisiti.Value.Year > 2011 && nSettimaneOBG >= 1040)
                    {
                        messaggioVideo = "Il numero settimane deve essere inferiore a 1040 ";
                        return false;
                    }
                }

                if ((codNat1 == ' ' || codNat1 == '6') && datiPensione.DataPerfezionamentoRequisiti.HasValue && datiPensione.DataPerfezionamentoRequisiti.Value.Year < 2012 && nSettimaneOBG < 780)
                {
                    messaggioVideo = "Il numero settimane deve essere maggiore o uguale a 780 ";
                    return false;
                }

                if (codNat1 == '5' && datiPensione.DataPerfezionamentoRequisiti.HasValue && datiPensione.DataPerfezionamentoRequisiti.Value.Year < 2012 && nSettimaneOBG >= 780)
                {
                    messaggioVideo = "Il numero settimane deve essere inferiore a 780 ";
                    return false;
                }
            }

            if ((Utility.IsDomandaRiliquidazioneAnzianitaAnticipata(datiPensione) && datiPensione.DataPerfezionamentoRequisiti != null && Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 12, 31))) && Utility.IsDomandaAnte96(datiPensione, datiPensione, datiDanteCausa, isRiaperturaDomanda) == null)
            {
                if (datiAnagraficiTitolare.Sesso == 'F' && (nSettimaneOBG + nContributiVolontari) < 2132)
                {
                    messaggioVideo = "Il numero settimane deve essere maggiore o uguale a 2132 ";
                    return false;
                }
                else if (datiAnagraficiTitolare.Sesso == 'M' && (nSettimaneOBG + nContributiVolontari) < 2184)
                {
                    messaggioVideo = "Il numero settimane deve essere maggiore o uguale a 2184 ";
                    return false;
                }
            }

            if (Utility.IsDomandaAnte96(datiPensione, datiPensione, datiDanteCausa, isRiaperturaDomanda) != null)
            {
                if (nSettimaneOBG <= 0)
                {
                    messaggioVideo = "Il numero settimane deve essere maggiore di 0";
                    return false;
                }
                else return true;
            }

            if (Utility.IsDomandaIndennitaUnaTantum_AGO(datiPensione))
            {
                if (nSettimaneOBG > 779)
                {
                    messaggioVideo = "Il numero settimane deve essere inferiore o uguale a 779";
                    return false;
                }

                if (siglaCategoria == "SOSPED")
                {
                    if (nSettimaneOBG % 52 != 0)
                    {
                        messaggioVideo = "Il numero settimane deve essere multiplo di 52";
                        return false;
                    }
                }
            }
            //else? 
            else
            {
                switch (siglaCategoria)
                {
                    //Se la Categoria (RACATEG) è = a “INDCOM”, “VOBIS”, “IOBIS”, “VMP”,
                    //“IMP”, "VESO29" il Numero Settimane (RAU113A) deve essere assente
                    case "INDCOM":
                    case "VOBIS":
                    case "IOBIS":
                    case "VMP":
                    case "IMP":
                    case "VESO29":
                    case "VOESO":
                        if (nSettimaneOBG != 0 && !(siglaCategoria == "VOESO" && ((Utility.IsAssegnoStraordinarioRiscossioneTributiErariali(datiPensione)) || (Utility.IsAssegnoStraordinarioFerrovieDelloStato(datiPensione) && datiPensione.CodiceTipoRichiesta == "74") || (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && codiceBancaEsodatiTraduzioneSuGP != null && (Utility.IsDomandaVOESOErarialiRic(datiPensione, isRiaperturaDomanda, codiceBancaEsodatiTraduzioneSuGP) || Utility.IsDomandaVOESOFerrovieDelloStatoRicConFiltro(datiPensione, isRiaperturaDomanda, campoGP2BB05, codiceBancaEsodatiTraduzioneSuGP)))))
                            && siglaCategoria != "VESO29")
                        {
                            messaggioVideo = "Il numero settimane deve essere assente";
                            return false;
                        }
                        //VOESO PL Riscossione Tributi Erariali (G/P/T = 6/52/34) e Ferrovie dello Stato (G/P/T = 6/52/36) con filtro = OBG (codtiporichiesta = 74) e loro RIC/TFR
                        if (nSettimaneOBG == 0 && ((siglaCategoria == "VOESO" && (Utility.IsAssegnoStraordinarioRiscossioneTributiErariali(datiPensione) || (Utility.IsAssegnoStraordinarioFerrovieDelloStato(datiPensione) && datiPensione.CodiceTipoRichiesta == "74") || (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && codiceBancaEsodatiTraduzioneSuGP != null && (Utility.IsDomandaVOESOErarialiRic(datiPensione, isRiaperturaDomanda, codiceBancaEsodatiTraduzioneSuGP) || Utility.IsDomandaVOESOFerrovieDelloStatoRicConFiltro(datiPensione, isRiaperturaDomanda, campoGP2BB05, codiceBancaEsodatiTraduzioneSuGP)))))
                            || siglaCategoria == "VESO29"))
                        {
                            messaggioVideo = "Il numero settimane non può essere assente";
                            return false;
                        }
                        break;
                    //Se la Categoria (RACATEG) è = a “VOSPED”, “IOSPED” il Numero
                    //Settimane (RAU113A) deve essere minimo 52 e massimo 2080 e comunque
                    //un multiplo di 52 (in sostanza le settimane diviso 52 non deve avere resto)
                    case "VOSPED":
                    case "IOSPED":
                        if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                        {
                            if (nSettimaneOBG < 52 || nSettimaneOBG > 2080)
                            {
                                messaggioVideo = "Il numero settimane deve essere minimo 52 e massimo 2080";
                                return false;
                            }

                            if (nSettimaneOBG % 52 != 0)
                            {
                                messaggioVideo = "Il numero settimane deve essere multiplo di 52";
                                return false;
                            }
                        }
                        break;
                    case "SOSPED":
                        //Se la Categoria (RACATEG) è = a “SOSPED” e il Codice Liquidazione
                        //(RAUE23) è = a “P” il Numero Settimane (RAU113A) deve essere assente
                        if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                        {
                            if (codiceLiquidazione.HasValue && codiceLiquidazione.Value.ToString().ToUpperInvariant() == "P")
                            {
                                if (nSettimaneOBG != 0)
                                {
                                    messaggioVideo = "Il numero settimane deve essere assente";
                                    return false;
                                }
                            }
                            //Se la Categoria (RACATEG) è = a “SOSPED” il Codice Liquidazione
                            //(RAUE23) è diverso da “P” il Numero Settimane (RAU113A) deve essere
                            //minimo 52 e massimo 2080 e comunque un multiplo di 52 (in sostanza le
                            //settimane diviso 52 non deve avere resto)
                            else
                            {
                                if (nSettimaneOBG < 52 || nSettimaneOBG > 2080)
                                {
                                    messaggioVideo = "Il numero settimane deve essere minimo 52 e massimo 2080";
                                    return false;
                                }
                                if (nSettimaneOBG % 52 != 0)
                                {
                                    messaggioVideo = "Il numero settimane deve essere multiplo di 52";
                                    return false;
                                }
                            }
                        }

                        // Se la domanda è un'indennità una tantum
                        if (Utility.IsDomandaIndennitaUnaTantum_AGO(datiPensione) || codNat2 == 'U')
                        {
                            if (nSettimaneOBG % 52 != 0)
                            {
                                messaggioVideo = "Il numero settimane deve essere multiplo di 52";
                                return false;
                            }
                        }
                        break;
                    //Se la Categoria (RACATEG) è = a “VOAUT”, “IOAUT” e il 1° Codice Natura
                    //(RAU1031) è diverso da “5” il Numero Settimane (RAU113A) non può essere
                    //inferiore a 260
                    case "VOAUT":
                    case "IOAUT":
                        if (codNat1 != '5')
                        {
                            if (!(siglaCategoria == "VOAUT" && filtro == "ERI" && Utility.IsDomandaTipoContributivo(datiPensione, false, false)) &&
                                !Utility.IsDomandaVOAUTVecchiaiaTipoContributivoFiltroGSE(datiPensione))
                            {
                                if (nSettimaneOBG < 260)
                                {
                                    messaggioVideo = "Il numero settimane non può essere inferiore a 260";
                                    return false;
                                }
                            }
                        }
                        break;
                    //Se la Categoria (RACATEG) è = a “SOAUT” e il 1° Codice Natura (RAU1031)
                    //è diverso da “5” il Codice Liquidazione (RAUE23) è diverso da “P” il Numero
                    //Settimane (RAU113A) non può essere inferiore a 260
                    case "SOAUT":
                        if (codNat1 != '5' &&
                            (!codiceLiquidazione.HasValue || codiceLiquidazione.Value.ToString().ToUpperInvariant() != "P"))
                        {
                            if (nSettimaneOBG < 260)
                            {
                                messaggioVideo = "Il numero settimane non può essere inferiore a 260";
                                return false;
                            }
                        }
                        break;
                    case "VESO92":
                        if (!string.IsNullOrEmpty(campoGP2BB05))
                        {
                            if (nSettimaneOBG == 0)
                            {
                                messaggioVideo = "Il numero settimane non può essere assente";
                                return false;
                            }
                        }
                        else
                        {
                            if (pdirsup == 0 && nSettimaneOBG == 0)
                            {
                                messaggioVideo = "Il numero settimane non può essere assente";
                                return false;
                            }
                        }
                        break;
                    case "IOTOT":
                    case "SOTOT":
                        var idEnteCassa = datiPensioniDatiGenerici != null ? datiPensioniDatiGenerici.EnteCassa : null;
                        var enteCassa = ElencoDecodificaEnteCassaProfessionale != null ? ElencoDecodificaEnteCassaProfessionale.Where(x => x.Id == idEnteCassa).Select(x => x.TraduzioneSuGP).FirstOrDefault() : null;
                        enteCassa = !string.IsNullOrEmpty(enteCassa) ? enteCassa.ToString().PadLeft(4, '0') : enteCassa;

                        if ((nSettimaneOBG + nContributiVolontari) <= 259 && ((enteCassa == "0801" && siglaCategoria == "IOTOT") || contributivo == '8'))
                        {
                            messaggioVideo = "La somma del numero settimane e del numero contributi volontari diritto deve essere superiore a 259";
                            return false;
                        }
                        break;
                    case "VOP":
                        if (Utility.IsPensioneAnzianitaOrRicostituzione(datiPensione, null) && datiPensione.Tipo == "0001" && !Utility.IsRicostituzioneOrRiapertura(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id)) && !Utility.IsDomandaAutomatica(datiPensione))
                        {
                            if (datiPensione.DataPerfezionamentoRequisiti.HasValue && Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 12, 31)))
                            {
                                //Il “Numero Settimane” deve essere maggiore o uguale a 2132
                                if (datiAnagraficiTitolare.Sesso == 'F')
                                {
                                    if (!(nSettimaneOBG >= 2132))
                                    {
                                        messaggioVideo = "Il “Numero Settimane” deve essere maggiore o uguale a 2132";
                                        return false;
                                    }
                                }
                                //Il “Numero Settimane” deve essere maggiore o uguale a 2184
                                else if (datiAnagraficiTitolare.Sesso == 'M')
                                {
                                    if (!(nSettimaneOBG >= 2184))
                                    {
                                        messaggioVideo = "Il “Numero Settimane” deve essere maggiore o uguale a 2184";
                                        return false;
                                    }
                                }
                            }
                            else
                            {
                                //Il “Numero Settimane” deve essere maggiore o uguale a 1820
                                if (!(nSettimaneOBG >= 1820))
                                {
                                    messaggioVideo = "Il “Numero Settimane” deve essere maggiore o uguale a 1820";
                                    return false;
                                }
                            }
                        }
                        break;
                    case "VOBANC":
                        if (Utility.IsVecchiaiaSupplementare(datiPensione) && ((nSettimaneOBG + nContributiVolontari) >= 780 || nSettimaneOBG == 0))
                        {
                            messaggioVideo = "Il numero di settimane deve essere strettamente inferiore a 780";
                            return false;
                        }
                        if (Utility.IsVecchiaiaNonSupplementare(datiPensione) && nSettimaneOBG < 780)
                        {
                            messaggioVideo = "Il numero di settimane deve essere maggiore o uguale a 780";
                            return false;
                        }
                        if (Utility.IsPensioneAnzianitaPL(datiPensione) && (nSettimaneOBG + nContributiVolontari) < 1820)
                        {
                            messaggioVideo = "La somma del numero settimane e del numero contributi volontari diritto deve essere almeno 1820";
                            return false;
                        }
                        break;
                    case "VOST":
                    case "PSO":
                        break;
                    case "PMO":
                        if (!((nSettimaneOBG + nContributiVolontari) >= 260))
                        {
                            messaggioVideo = "La somma del numero settimane e del numero contributi volontari diritto deve essere maggiore o uguale a 260";
                            return false;
                        }
                        break;
                    case "IOCUM":
                        if (Utility.IsPensioneInabilitaProficuoLavoroCumulo(datiPensione) && nSettimaneOBG < 778)
                        {
                            messaggioVideo = "Il numero settimane deve essere maggiore o uguale a 778";
                            return false;
                        }
                        break;
                    default:
                        if (pdirsup == 0 && nSettimaneOBG == 0)
                        {

                            messaggioVideo = "Il numero settimane non può essere assente";
                            return false;
                        }
                        break;
                }
            }

            //ENG - Domande vecchiaia Supplementari Lav. Parasubordinati: le settimane devono essere maggiore/uguale di 4
            if (Utility.IsVecchiaiaSupplementare(datiPensione) && datiPensione.Gestione == "005" && datiPensione.Fondo == "001")
            {
                if (nSettimaneOBG < 4)
                {
                    messaggioVideo = "Il numero settimane deve essere maggiore o uguale a 4";
                    return false;
                }
            }

            if (Utility.IsDomandaVESO29(siglaCategoria) || Utility.IsDomandaVOESO(siglaCategoria) || Utility.IsDomandaESOTEL(siglaCategoria) || Utility.IsDomandaESOAMB(siglaCategoria))
                return true;

            switch (filtro)
            {
                //Se il Campo DO-NOTE è = a “SUT” il Numero Settimane (RAU113A) non
                //può essere superiore a 779
                case "SUT":
                    if (nSettimaneOBG < 779)
                    {
                        messaggioVideo = "Il numero settimane non può essere inferiore a 779";
                        return false;
                    }
                    break;
            }

            //Per tutte le domande della linea AGO (Non Enpals) che siano automatiche da FELPE, è necessario rimuovere il controllo delle 3000 settimane
            //Questo controllo non viene effettuato nemmeno nel caso sia presente il Bypass
            if (!(!Utility.IsDomandaENPALS(datiPensione.Gestione) && Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica) &&
                (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.LiquidazionePensione_Assicurativi_AGO.NUM_SET_OBG_MAX)))
            {
                //Il Numero Settimane (RAU113A) non può essere superiore a 3000
                if (nSettimaneOBG > 3000)
                {
                    messaggioVideo = "Il numero settimane non può essere superiore a 3000";
                    return false;
                }

                //La somma del Numero Settimane (RAU113A) e il Numero Contributi
                //Volontari Diritto (RAU113B) non può essere superiore a 3000
                if ((nSettimaneOBG + nContributiVolontari) > 3000)
                {
                    messaggioVideo = "La somma del numero settimane e del numero contributi volontari diritto non può essere superiore a 3000";
                    return false;
                }
            }

            if (Utility.IsDomandaOrganizzazioniInternazionali(datiPensione))
            {
                if (!nSettimaneOI.HasValue || nSettimaneOI.Value == 0)
                {
                    messaggioVideo = "E' necessario specificare il Numero Settimane OI inserendo un valore maggiore di 0";
                    return false;
                }

                if (nSettimaneOBG - nSettimaneOI < 52)
                {
                    messaggioVideo = "La differenza tra il numero di settimane totali utile al diritto e il numero settimane OI deve essere maggiore o uguale a 52";
                    return false;
                }
            }

            if (Utility.IsPrepensionamentoEditoriaArt1c154L205_2017(datiPensione) || Utility.IsPrepensionamentoEditoriaArt1c500L160_2019(datiPensione))
            {
                short minNSettimane = 0;
                if (Utility.IsPrepensionamentoEditoriaArt1c154L205_2017(datiPensione))
                    minNSettimane = 1664;
                else if (Utility.IsPrepensionamentoEditoriaArt1c500L160_2019(datiPensione))
                    minNSettimane = 1820;
                if ((nSettimaneOBG + nContributiVolontari) < minNSettimane)
                {
                    messaggioVideo = string.Format("La somma del numero settimane e del numero contributi volontari diritto non può essere inferiore a {0}", minNSettimane);
                    return false;
                }
            }
            else if (Utility.IsPrepensionamentoEditoriaFiltroEAA(datiPensione) && !Utility.IsRicostituzione(datiPensione.Gruppo))
            {
                //Eng - BypassControllo per EAA sul Pannello liquidazione pensione – assicurativi "il numero settimane se inferiore a 1976 (38 anni)"
                if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Req_Contr_Prep_Editoria.REQ_CONTR_PREP_EDITORIA))
                {
                    if (nSettimaneOBG < 1976)
                    {
                        messaggioVideo = "Il numero settimane non può essere inferiore a 1976 (38 anni).";
                        return false;
                    }
                }
            }
            else if (Utility.IsPrepensionamentoEditoriaFiltroEBA(datiPensione)) //ENG - Anche per le RIC deve essere valido questo controllo
            {
                if (nSettimaneOBG < 1322)
                {
                    messaggioVideo = "Il numero settimane non può essere inferiore a 1322 (25 anni e 5 mesi).";
                    return false;
                }
            }
            //Se il 3° Codice Natura (RAU1033) è = a “O” la somma del Numero Settimane
            //(RAU113A) e il Numero Contributi Volontari Diritto (RAU113B) non può
            //essere inferiore a 1664
            else if (codNat3 == 'O' && (nSettimaneOBG + nContributiVolontari) < 1664)
            {
                messaggioVideo = "La somma del numero settimane e del numero contributi volontari diritto non può essere inferiore a 1664";
                return false;
            }

            if (!Utility.IsDomandaBeneficioTerrorismoOver80(datiPensione, datiBeneficioVittimeTerrorismo) && !Utility.IsDomandaBeneficioTerrorismoUnder80(datiPensione, datiBeneficioVittimeTerrorismo) && !Utility.IsDomandaVESO92_L92(datiPensione) && !Utility.IsDomandaVESO92WithGP2BB05(datiPensione.SiglaCategoria, datiPensione.Gruppo, campoGP2BB05))
            {
                //Se il 1° carattere della Categoria (RACATEG) è = a “V” e il 1° Codice Natura
                //(RAU1031) è = a “1”, “2” e il 3° Codice Natura (RAU1033) è = a “L”, “O”, “Q”,
                //“W”, “X”, “Y”, “Z” i controlli che seguono non vanno eseguiti
                if (!(siglaCategoria.StartsWith("V") &&
                    (codNat1 == '1' || codNat1 == '2') &&
                    (codNat3 == 'L' || codNat3 == 'O' || codNat3 == 'Q' || codNat3 == 'W' || codNat3 == 'Y' || codNat3 == 'Z')))
                {
                    //Se il 1° carattere della Categoria (RACATEG) è = a “V” escluso
                    //“VOTOT” e il 1° Codice Natura (RAU1031) è = a “1”, “2” la somma del
                    //Numero Settimane (RAU113A) e il Numero Contributi Volontari Diritto
                    //(RAU113B) non può essere inferiore a 1820
                    if (siglaCategoria.StartsWith("V") && siglaCategoria != "VOTOT" &&
                        (codNat1 == '1' || codNat1 == '2'))
                    {
                        if (!(Utility.IsRicostituzione(datiPensione.Gruppo) && codNat3 == 'X') &&
                            !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.LiquidazionePensione_Assicurativi_AGO.NUM_SET_1820) &&
                            !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.DatiCalcolo_DatiCalcolo_AGO.NUM_SET_ANTICIPATA_2019) &&
                            !Utility.IsDomandaTipoContributivo(datiPensione, null, null) &&
                            !Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione) &&
                            !Utility.IsDomandaTipoContributivoCumulo(datiPensione, null, null) &&
                            !Utility.IsDomandaAUT(datiPensione) &&
                            !Utility.isDomandaVecchiaiaTrasformazioneAOICalcoloContributivo(datiPensione) &&
                            !((!Utility.IsRicostituzione(datiPensione.Gruppo) && !Utility.IsRiaperturaDomanda(datiPensione.Id) && (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione))) ||
                               ((Utility.IsRicostituzione(datiPensione.Gruppo) || Utility.IsRiaperturaDomanda(datiPensione.Id)) && ((ctrlMemo123_2024 != null && ctrlMemo123_2024.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione)) || (ctrlMemo123_2024OpzioneContrib != null && ctrlMemo123_2024OpzioneContrib.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione)))))) //ENG - Memo 166/2023
                        {
                            if ((nSettimaneOBG + nContributiVolontari) < 1820)
                            {
                                messaggioVideo = "La somma del numero settimane e del numero contributi volontari diritto non può essere inferiore a 1820";
                                return false;
                            }
                        }
                    }
                    //ENG - Memo 166/2023
                    if (datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0002" && (datiPensione.Tipo != "0009" && datiPensione.Tipo != "0192") && !Utility.IsDomandaCumulo(siglaCategoria)
                        && !Utility.IsDomandaTipoContributivo(datiPensione, false, null) && !Utility.isDomandaVecchiaiaTrasformazioneAOICalcoloContributivo(datiPensione) && !Utility.IsDomandaSPED(datiPensione) && !Utility.IsDomandaBancari(siglaCategoria)
                        && !(siglaCategoria == "VOAUT" && Utility.IsDomandaVecchiaiaInComputo(datiPensione) && ctrl != null && !String.IsNullOrEmpty(ctrl.ValoreControllo) && ctrl.ValoreControllo == "SI"))
                    {
                        if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.LiquidazionePensione_Assicurativi_AGO.NUM_SET_780))
                        {
                            bool skip = false;
                            //bypass per Trasf AOI di VOAUT e che non hanno filtro ERI su VOAUT (viene applicato controllo ad hoc)
                            if (Utility.IsDomandaVecchiaiaTrasformazioneAOI(datiPensione).GetValueOrDefault() &&
                                Utility.IsDomandaVOAUT(datiPensione.SiglaCategoria) &&
                                !(Utility.IsDomandaVOAUT(datiPensione.SiglaCategoria) && datiPensione.GetFiltro() == "ERI"))
                                skip = true;

                            int limitValue = 780;
                            if (datiMaggiorazioniBenefici != null && !String.IsNullOrEmpty(datiMaggiorazioniBenefici.TipoSettimaneBeneficio) && !String.IsNullOrEmpty(datiMaggiorazioniBenefici.TipoSettimaneBeneficio.Trim())
                                 && datiMaggiorazioniBenefici.TipoSettimaneBeneficio == "01")
                                limitValue = 520;

                            if (!skip && (nSettimaneOBG + nContributiVolontari) < limitValue)
                            {
                                messaggioVideo = "Il numero settimane deve essere maggiore o uguale a " + limitValue.ToString() + ".";
                                return false;
                            }
                        }
                        else
                        {
                            if ((nSettimaneOBG + nContributiVolontari) < 260)
                            {
                                messaggioVideo = "Il numero settimane deve essere maggiore o uguale a 260";
                                return false;
                            }
                        }
                    }

                    //Per domande di pensione indiretta (gruppo = 0003, prodotto = 0022), il totale dei contributi ( settimane + VV diritto ) deve essere maggiore di 259.
                    //Per domande di pensione inabilità (gruppo = 0002, prodotto = 0012), il totale dei contributi ( settimane + VV diritto ) deve essere maggiore di 259.
                    //Per domande di pensione di trasformazione AOI di vecchiaia(gruppo = 0001, prodotto = 0002, tipo=0002) e anzianità(gruppo = 0001, prodotto = 0001, tipo=0002)
                    //Per domande di AOI non supplementari
                    //il totale dei contributi ( settimane + VV diritto ) deve essere maggiore di 259.
                    //Solo per le indirette supplementari (gruppo = 0003, prodotto = 0022, 0009), il numero di contributi deve solo essere maggiore di 1.
                    if (((Utility.IsDomandaPensioneIndiretta(datiPensione) && !Utility.IsPensioneIndirettaSupplementareOrRicostituzione(datiPensione)) ||
                        (Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Ricostituzione && !string.IsNullOrEmpty(datiPensione.SiglaCategoria) &&
                        datiPensione.SiglaCategoria.StartsWith("S") && !Utility.IsPensioneIndirettaSupplementareOrRicostituzione(datiPensione) && datiPensione.SiglaCategoria.Trim().ToUpperInvariant() != "SDAI" && !Utility.IsDomandaSPED(datiPensione)) ||
                        (Utility.IsDomandaPensioneInabilita(datiPensione)) ||
                        (Utility.IsDomandaTrasformazioneAOI(datiPensione).GetValueOrDefault()) ||
                        (datiPensione.Gruppo == "0002" && datiPensione.Prodotto == "0011" && datiPensione.Tipo != "0009")) &&
                        !(codNat2 == 'I' && contributivo == '8') && !(Utility.IsDomandaBancari(datiPensione.SiglaCategoria) && Utility.IsRicostituzione(datiPensione.Gruppo)))
                    {
                        if ((nSettimaneOBG + nContributiVolontari) < 260)
                        {
                            messaggioVideo = "La somma del numero settimane e del numero contributi volontari diritto non può essere inferiore a 260.";
                            return false;
                        }
                    }
                    else if (Utility.IsRicostituzione(datiPensione.Gruppo) && !String.IsNullOrEmpty(datiPensione.SiglaCategoria) && datiPensione.SiglaCategoria.Trim().ToUpperInvariant() == "SDAI")
                    {
                        if ((nSettimaneOBG + nContributiVolontari) == 0)
                        {
                            messaggioVideo = "Il valore del numero settimane diritto deve essere diverso da 0";
                            return false;
                        }
                    }
                    //ENG - Il controllo deve scattare se settimane + numero di contributi volontari è inferiori ad 1
                    if (Utility.IsPensioneIndirettaSupplementareOrRicostituzione(datiPensione))
                    {
                        if ((nSettimaneOBG + nContributiVolontari) < 1)
                        {
                            messaggioVideo = "La somma del numero settimane e del numero contributi volontari diritto non può essere inferiore a 1";
                            return false;
                        }
                        //ENG - Il controllo deve scattare se il numero di settimane è inferiore ad 1
                        else if (nSettimaneOBG < 1)
                        {
                            messaggioVideo = "Il numero settimane deve sempre essere almeno pari ad 1";
                            return false;
                        }
                    }


                    //Per le Ric Banc PostF91 la somma del numero settimane e del numero contributi volontari diritto deve essere diversa da 0
                    if (Utility.IsDomandaBancari(datiPensione.SiglaCategoria) && Utility.IsRicostituzione(datiPensione.Gruppo) && !Utility.IsDomandaBancRicAnte1991(datiPensione, datiDanteCausa))
                    {
                        if ((nSettimaneOBG + nContributiVolontari) == 0)
                        {
                            messaggioVideo = "La somma del numero settimane e del numero contributi volontari diritto non può essere uguale a 0";
                            return false;
                        }

                    }

                    //Se la Categoria (RACATEG) è = a “VOTOT” e il 1° Codice Natura
                    //(RAU1031) è = a “1” o “2” la somma del Numero Settimane
                    //(RAU113A) e il Numero Contributi Volontari Diritto (RAU113B) non può
                    //essere inferiore a 2080
                    if (siglaCategoria == "VOTOT" &&
                       (codNat1 == '1' || codNat1 == '2'))
                    {
                        if ((nSettimaneOBG + nContributiVolontari) < 2080)
                        {
                            messaggioVideo = "La somma del numero settimane e del numero contributi volontari diritto non può essere inferiore a 2080";
                            return false;
                        }
                    }

                    //Se la Categoria (RACATEG) è = a “VOTOT” e il 1° Codice Natura
                    //(RAU1031) è diverso da “1” o “2” la somma del Numero Settimane
                    //(RAU113A) e il Numero Contributi Volontari Diritto (RAU113B) non può
                    //essere inferiore a 1040
                    if (siglaCategoria == "VOTOT" &&
                       (codNat1 != '1' && codNat1 != '2'))
                    {
                        if ((nSettimaneOBG + nContributiVolontari) < 1040)
                        {
                            messaggioVideo = "La somma del numero settimane e del numero contributi volontari diritto non può essere inferiore a 1040";
                            return false;
                        }
                    }
                }
            }

            /////Aggiunti i seguenti controlli a seguito della mail del 21-05-2014 - Reeng Pensioni AGO - Modifiche richieste da referenti
            if (datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0002" && datiPensione.Tipo == "0009" && !Utility.IsDomandaAUT(datiPensione))
            {
                // Evolutiva richiesta sul documento Interventi Puntuali v.4.7 paragrafo 4.2.2.1
                if (!(tipoCalcolo.GetValueOrDefault() == 1 && new List<string> { "VO", "VR", "VOART", "VOCOM", "VOAUT", "VOPGI", "IOPGI" }.Contains(datiPensione.SiglaCategoria.Trim()) && codNat1 == '5' && codNat3 == 'D' &&
                    inizioAssicurazione.HasValue && Utility.DataSuccessivaA(inizioAssicurazione.Value, new DateTime(1996, 01, 01))))
                    if ((nSettimaneOBG + nContributiVolontari) >= 1040)
                    {
                        messaggioVideo = "Il numero settimane deve essere inferiore a 1040";
                        return false;
                    }
            }
            ////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

            if (Utility.IsDomandaBeneficioTerrorismoUnder80(datiPensione, datiBeneficioVittimeTerrorismo) && datiBeneficioVittimeTerrorismo != null && datiBeneficioVittimeTerrorismo.TipologiaPrestazione.GetValueOrDefault() == 3 && !Utility.IsRicostituzione(datiPensione.Gruppo))
            {
                if ((nSettimaneOBG + nContributiVolontari) < 2080)
                {
                    messaggioVideo = "Il numero settimane deve essere superiore a 2079.";
                    return false;
                }
            }

            // Domanda APE Sociale PL
            //ENG - Memo 57_2023: questo flusso per le APE non è stato modificato perchè le APE sono tutte automatiche e avranno filtro pari ad YAA o YCA
            if (datiPensione.Gruppo == "0006" && datiPensione.Prodotto == "0057" && datiPensione.Tipo == "0048" &&
                (datiPensione.CodiceTipoRichiesta == "YG" || datiPensione.CodiceTipoRichiesta == "YH"))
            {
                int limitValue = 1664;
                if (Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica &&
                    datiPensioniDatiGenerici != null && datiPensioniDatiGenerici.TipoCertificazioneFelpe == "CII")
                    limitValue = 52;
                else if (datiAnagraficiTitolare != null && datiAnagraficiTitolare.Sesso.HasValue && datiAnagraficiTitolare.Sesso.Equals('F'))
                    limitValue = 1560;


                if ((nSettimaneOBG + nContributiVolontari) < limitValue)
                {
                    messaggioVideo = string.Format("Il numero settimane deve essere superiore a {0}.", limitValue - 1);
                    return false;
                }
            }

            if (Utility.IsDomandaAUT(datiPensione))
            {
                if (nSettimaneOBG > 2600)
                {
                    messaggioVideo = "Il numero settimane deve essere inferiore a 2600";
                    return false;
                }

                //ENG - Memo 116/2025
                if (Utility.IsDomandaVOAUTVecchiaiaTipoContributivoFiltroGSE(datiPensione))
                {
                    if ((nSettimaneOBG + nContributiVolontari) < 1040)
                    {
                        messaggioVideo = "Non risulta soddisfatto il requisito contributivo previsto per la pensione.";
                        return false;
                    }
                }

                if (Utility.IsDomandaVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE(datiPensione))
                {
                    if (nSettimaneOBG < 2132)
                    {
                        messaggioVideo = "Il numero settimane non può essere inferiore a 2132.";
                        return false;
                    }
                }
                //

                if (Utility.IsPensioneAnzianitaOrRicostituzione(datiPensione, null) && !Utility.IsDomandaVOAUTAnticipataTipoContributivoFiltroGSE(datiPensione))
                {
                    //ENG - memo 28/2024
                    if (ctrl28_2024 != null && !String.IsNullOrEmpty(ctrl28_2024.ValoreControllo) && ctrl28_2024.ValoreControllo.ToUpperInvariant() == "SI")
                    {
                        if (((datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001" && datiPensione.Tipo == "0017") ||
                            (datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001" && datiPensione.Tipo == "0045" && datiPensione.CodiceTipoRichiesta == "AV") ||
                            (datiPensione.IdTipoPLPerRIC.HasValue && ((datiPensione.IdTipoPLPerRIC == 7 && (codNat1 == '1' || codNat1 == '2')) || datiPensione.IdTipoPLPerRIC == 26))) &&
                            Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2023, 12, 31)) &&
                            datiAnagraficiTitolare.Sesso == 'F' && datiPensione.SceltaLavMadri.GetValueOrDefault() == 1 && datiPensione.TipoCalcolo.HasValue && datiPensione.TipoCalcolo == (byte)Utility.TipoCalcolo.Contributivo)
                        {
                            int reqAA = 0;
                            int reqMM = 0;
                            GestioneDecodifica.GetCtrlRequisitoEta_Avanzato(datiPensione.DataPerfezionamentoRequisiti.Value, null, null, Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione).ToString(), datiPensione.IdTipoPLPerRIC == 7 ? "0017" : datiPensione.IdTipoPLPerRIC == 26 ? "0045" : datiPensione.Tipo, out reqAA, out reqMM);

                            int scontoMesi = 0;
                            if (datiPensione.NumeroFigli.HasValue && datiPensione.NumeroFigli.Value > 0)
                            {
                                scontoMesi = 4 * datiPensione.NumeroFigli.Value;
                                if (scontoMesi > 12)
                                    scontoMesi = 12;
                            }

                            Utility.DifferenzaDateTime etaPiuAspettativaDiVita = new Utility.DifferenzaDateTime(reqAA, reqMM - scontoMesi, true);
                            Utility.DifferenzaDateTime etaTitolareAllaDPR = Utility.DifferenzaBetweenDate(datiPensione.DataPerfezionamentoRequisiti.Value, datiAnagraficiTitolare.DataNascita, Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione).GetValueOrDefault());
                            if (etaTitolareAllaDPR < etaPiuAspettativaDiVita)
                            {
                                if (nSettimaneOBG < 1040)
                                {
                                    messaggioVideo = "Il numero settimane deve essere maggiore o uguale di 1040";
                                    return false;
                                }
                            }
                        }
                        else
                        {
                            if (nSettimaneOBG < 1040)
                            {
                                messaggioVideo = "Il numero settimane deve essere maggiore di 1040";
                                return false;
                            }
                        }
                    }
                    else
                    {
                        if (nSettimaneOBG < 1040)
                        {
                            messaggioVideo = "Il numero settimane deve essere maggiore di 1040";
                            return false;
                        }
                    }
                }

                if (Utility.IsDomandaVOAUT_SOAUT(datiPensione.SiglaCategoria))
                {
                    if (codNat1 == '5')
                    {
                        if (nSettimaneOBG >= 1040)
                        {
                            if (codNat3 != ' ' && codNat3 != 'D')
                            {
                                messaggioVideo = "Se il numero di settimane è >= 1040, il terzo codice natura può essere vuoto o uguale a D";
                                return false;
                            }
                        }
                        else if (nSettimaneOBG < 1040)
                        {
                            if (codNat3 != ' ')
                            {
                                messaggioVideo = "Se il numero di settimane è < 1040, il terzo codice natura deve essere vuoto";
