                            }
                        }

                        if (codNat3 != 'D')
                        {
                            if (Utility.DataStrettamenteSuccessivaA(datiPensione.DataPresentazioneDomanda, new DateTime(2011, 12, 31)))
                            {
                                if (nSettimaneOBG >= 1040)
                                {
                                    messaggioVideo = "Il numero settimane deve essere inferiore a 1040";
                                    return false;
                                }
                            }
                            else
                            {
                                if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.LiquidazionePensione_Assicurativi_AGO.SUPPL_ANTE2012_260))
                                {
                                    if (nSettimaneOBG > 260)
                                    {
                                        messaggioVideo = "Il numero settimane deve essere inferiore a 260";
