                        {
                            if (nSettimaneOBG < 1040)
                            {
                                messaggioVideo = "Il numero settimane deve essere maggiore di 1040";
                                return false;
                            }
                        }
                    }

                }

                if (ctrl != null && ctrl.ValoreControllo == "SI" && Utility.IsDomandaVecchiaiaInComputo(datiPensione))
                {
                    if (datiPensione.DataPerfezionamentoRequisiti.HasValue && !Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 12, 31)) &&
                        datiPensione.DataCondizioniPerComputo.HasValue && !Utility.DataStrettamenteSuccessivaA(datiPensione.DataCondizioniPerComputo.Value, new DateTime(2011, 12, 31)))
                    {
                        if (nSettimaneOBG < 780)
                        {
                            messaggioVideo = "Il numero settimane deve essere maggiore o uguale di 780";
                            return false;
                        }
                    }
                    else if (!(siglaCategoria == "VOAUT" && Utility.IsDomandaVecchiaiaInComputo(datiPensione)))
                    {
                        if (((datiPensione.DataPerfezionamentoRequisiti.HasValue && Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 12, 31))) ||
                             (datiPensione.DataCondizioniPerComputo.HasValue && Utility.DataStrettamenteSuccessivaA(datiPensione.DataCondizioniPerComputo.Value, new DateTime(2011, 12, 31)))) &&
                              !Utility.DataStrettamenteSuccessivaA(datiAnagraficiTitolare.DataNascita.Value.AddYears(70), dataSistema))
                        {
                            if (nSettimaneOBG < 780)
                            {
                                messaggioVideo = "Il numero settimane deve essere maggiore o uguale di 780";
                                return false;
                            }
                        }
                        else if ((datiPensione.DataPerfezionamentoRequisiti.HasValue && Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 12, 31))) ||
                                 (datiPensione.DataCondizioniPerComputo.HasValue && Utility.DataStrettamenteSuccessivaA(datiPensione.DataCondizioniPerComputo.Value, new DateTime(2011, 12, 31))))
                        {
                            if (nSettimaneOBG < 1040)
                            {
                                messaggioVideo = "Il numero settimane deve essere maggiore o uguale di 1040";
                                return false;
                            }
                        }
                    }
                    else
                    {
                        if ((datiPensione.DataPerfezionamentoRequisiti.HasValue && Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 12, 31)))
                            || (datiPensione.DataCondizioniPerComputo.HasValue && Utility.DataStrettamenteSuccessivaA(datiPensione.DataCondizioniPerComputo.Value, new DateTime(2011, 12, 31))))
                        {
                            if (datiAnagraficiTitolare != null && datiAnagraficiTitolare.DataNascita.HasValue)
                            {
                                Utility.DifferenzaDateTime etaTitolareAllaDPR = Utility.DifferenzaBetweenDate(datiPensione.DataPerfezionamentoRequisiti, datiAnagraficiTitolare.DataNascita, Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione));
                                //Calcolo la Data maggiore tra la DPR e la DataCondizionePerComputo
                                DateTime? dataRiferimento = null;
                                if (datiPensione.DataPerfezionamentoRequisiti.HasValue && datiPensione.DataCondizioniPerComputo.HasValue)
                                {
                                    if (Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, datiPensione.DataCondizioniPerComputo.Value))
                                        dataRiferimento = datiPensione.DataPerfezionamentoRequisiti;
                                    else
                                        dataRiferimento = datiPensione.DataCondizioniPerComputo;
                                }
                                else if (!datiPensione.DataPerfezionamentoRequisiti.HasValue && datiPensione.DataCondizioniPerComputo.HasValue)
                                    dataRiferimento = datiPensione.DataCondizioniPerComputo;
                                else if (datiPensione.DataPerfezionamentoRequisiti.HasValue && !datiPensione.DataCondizioniPerComputo.HasValue)
                                    dataRiferimento = datiPensione.DataPerfezionamentoRequisiti;

                                //ENG - Vecchiaia in Computo VOAUT Lavoratrice Madre
                                if (Utility.IsGestioneLavoratriciMadri(datiPensione)
                                    && datiAnagraficiTitolare.Sesso.HasValue && datiAnagraficiTitolare.Sesso.Value.ToString().ToUpperInvariant() == "F"
                                    && datiPensione.SceltaLavMadri.GetValueOrDefault() == 1
                                    && datiPensione.DataPerfezionamentoRequisiti.HasValue)
                                {
                                    int reqAA = 0;
                                    int reqMM = 0;
                                    GestioneDecodifica.GetCtrlRequisitoEta_Avanzato(datiPensione.DataPerfezionamentoRequisiti.Value, null, null, Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione).ToString(), datiPensione.Tipo, out reqAA, out reqMM);

                                    int scontoMesi = 0;
                                    if (datiPensione.NumeroFigli.HasValue && datiPensione.NumeroFigli.Value > 0)
                                    {
                                        scontoMesi = 4 * datiPensione.NumeroFigli.Value;
                                        if (scontoMesi > 12)
                                            scontoMesi = 12;
                                    }

                                    Utility.DifferenzaDateTime etaPiuAspettativaDiVita = new Utility.DifferenzaDateTime(reqAA, reqMM - scontoMesi, true);

                                    if (etaTitolareAllaDPR >= etaPiuAspettativaDiVita)
                                    {
                                        if (nSettimaneOBG < 780)
                                        {
                                            messaggioVideo = "Il numero settimane deve essere maggiore o uguale di 780";
                                            return false;
                                        }
                                    }
                                    else
                                    {
                                        if (nSettimaneOBG < 1040)
                                        {
                                            messaggioVideo = "Il numero settimane deve essere maggiore o uguale di 1040";
                                            return false;
                                        }
                                    }

                                }
                                else if (dataRiferimento.HasValue)
                                {
                                    int reqAA = 0;
                                    int reqMM = 0;
                                    GestioneDecodifica.GetCtrlRequisitoEta_Avanzato(dataRiferimento.Value, null, null, Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione).ToString(), datiPensione.Tipo, out reqAA, out reqMM);
                                    if (reqAA > 0 || reqMM > 0)
                                    {
                                        Utility.DifferenzaDateTime requisitoEta = new Utility.DifferenzaDateTime(reqAA, reqMM, 0);

                                        if (etaTitolareAllaDPR >= requisitoEta)
                                        {
                                            if (nSettimaneOBG < 780)
                                            {
                                                messaggioVideo = "Il numero settimane deve essere maggiore o uguale di 780";
                                                return false;
                                            }

                                        }
                                        else
                                        {
                                            if (nSettimaneOBG < 1040)
                                            {
                                                messaggioVideo = "Il numero settimane deve essere maggiore o uguale di 1040";
                                                return false;
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }

                if ((ctrl != null && ctrl.ValoreControllo == "SI" && Utility.IsDomandaAUTAnticipataInComputo(datiPensione, false)) || Utility.IsDomandaVOAUTAnticipataTipoContributivoFiltroGSE(datiPensione))
                {
                    if (!Utility.IsDomandaVOAUTAnticipataTipoContributivoFiltroGSE(datiPensione) && datiPensione.DecorrenzaOriginaria.HasValue && !Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && !Utility.DataSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, new DateTime(2011, 01, 01)))
                    {
                        if ((nSettimaneOBG + nContributiVolontari) < 1820)
                        {
                            messaggioVideo = "Il numero settimane deve essere maggiore o uguale di 1820";
                            return false;
                        }
                    }
                    else if (!Utility.IsDomandaVOAUTAnticipataTipoContributivoFiltroGSE(datiPensione) && datiPensione.DataPerfezionamentoRequisiti.HasValue && !Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 12, 31)) &&
                        datiPensione.DataCondizioniPerComputo.HasValue && !Utility.DataStrettamenteSuccessivaA(datiPensione.DataCondizioniPerComputo.Value, new DateTime(2011, 12, 31)))
                    {
                        if ((nSettimaneOBG + nContributiVolontari) < 1820)
                        {
                            messaggioVideo = "Il numero settimane deve essere maggiore o uguale di 1820";
                            return false;
                        }
                    }
                    else if ((datiPensione.DataPerfezionamentoRequisiti.HasValue && Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 12, 31))) ||
                            (datiPensione.DataCondizioniPerComputo.HasValue && Utility.DataStrettamenteSuccessivaA(datiPensione.DataCondizioniPerComputo.Value, new DateTime(2011, 12, 31))))
                    {
                        //ENG - Miglioramento controlli Settimane
                        if (datiPensione.DataPerfezionamentoRequisiti.HasValue && datiPensione.DataPerfezionamentoRequisiti.Value.Year == 2012)
                        {
                            if (datiAnagraficiTitolare.Sesso == 'F' && (nSettimaneOBG + nContributiVolontari) < 2136)
                            {
                                messaggioVideo = "Il numero settimane deve essere maggiore o uguale a 2136";
                                return false;
                            }
                            else if (datiAnagraficiTitolare.Sesso == 'M' && (nSettimaneOBG + nContributiVolontari) < 2188)
                            {
                                messaggioVideo = "Il numero settimane deve essere maggiore o uguale a 2188";
                                return false;
                            }
                        }
                        else if (datiPensione.DataPerfezionamentoRequisiti.HasValue && datiPensione.DataPerfezionamentoRequisiti.Value.Year == 2013)
                        {
                            if (datiAnagraficiTitolare.Sesso == 'F' && (nSettimaneOBG + nContributiVolontari) < 2154)
                            {
                                messaggioVideo = "Il numero settimane deve essere maggiore o uguale a 2154";
                                return false;
                            }
                            else if (datiAnagraficiTitolare.Sesso == 'M' && (nSettimaneOBG + nContributiVolontari) < 2206)
                            {
                                messaggioVideo = "Il numero settimane deve essere maggiore o uguale a 2206";
                                return false;
                            }
                        }
                        else if (datiPensione.DataPerfezionamentoRequisiti.HasValue && (datiPensione.DataPerfezionamentoRequisiti.Value.Year == 2014 || datiPensione.DataPerfezionamentoRequisiti.Value.Year == 2015))
                        {
                            if (datiAnagraficiTitolare.Sesso == 'F' && (nSettimaneOBG + nContributiVolontari) < 2158)
                            {
                                messaggioVideo = "Il numero settimane deve essere maggiore o uguale a 2158";
                                return false;
                            }
                            else if (datiAnagraficiTitolare.Sesso == 'M' && (nSettimaneOBG + nContributiVolontari) < 2210)
                            {
                                messaggioVideo = "Il numero settimane deve essere maggiore o uguale a 2210";
                                return false;
                            }
                        }
                        else if ((datiPensione.DataPerfezionamentoRequisiti.HasValue && datiPensione.DataPerfezionamentoRequisiti.Value.Year >= 2016))
                        {
                            if (datiAnagraficiTitolare.Sesso == 'F' && (nSettimaneOBG + nContributiVolontari) < 2175)
                            {
                                messaggioVideo = "Il numero settimane deve essere maggiore o uguale a 2175";
                                return false;
                            }
                            else if (datiAnagraficiTitolare.Sesso == 'M' && (nSettimaneOBG + nContributiVolontari) < 2227)
                            {
                                messaggioVideo = "Il numero settimane deve essere maggiore o uguale a 2227";
                                return false;
                            }
                        }
                    }
                }
            }
            else
            {
                //ENG - memo 28/2024
                if (ctrl28_2024 != null && !String.IsNullOrEmpty(ctrl28_2024.ValoreControllo) && ctrl28_2024.ValoreControllo.ToUpperInvariant() == "SI")
                {
                    if (((datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001" && datiPensione.Tipo == "0017") ||
                    (datiPensione.IdTipoPLPerRIC.HasValue && ((datiPensione.IdTipoPLPerRIC == 7 && (codNat1 == '1' || codNat1 == '2')) || datiPensione.IdTipoPLPerRIC == 29))) &&
                    datiPensione.DataPerfezionamentoRequisiti.HasValue && Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2023, 12, 31)) &&
                    datiAnagraficiTitolare.Sesso == 'F' && datiPensione.SceltaLavMadri.GetValueOrDefault() == 1)
                    {
                        int reqAA = 0;
                        int reqMM = 0;
                        GestioneDecodifica.GetCtrlRequisitoEta_Avanzato(datiPensione.DataPerfezionamentoRequisiti.Value, null, null, Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione).ToString(), "0017", out reqAA, out reqMM);

                        int scontoMesi = 0;
                        if (datiPensione.NumeroFigli.HasValue && datiPensione.NumeroFigli.Value > 0)
                        {
                            scontoMesi = 4 * datiPensione.NumeroFigli.Value;
                            if (scontoMesi > 12)
                                scontoMesi = 12;
                        }

                        Utility.DifferenzaDateTime etaPiuAspettativaDiVita = new Utility.DifferenzaDateTime(reqAA, reqMM - scontoMesi, true);
                        Utility.DifferenzaDateTime etaTitolareAllaDPR = Utility.DifferenzaBetweenDate(datiPensione.DataPerfezionamentoRequisiti.Value, datiAnagraficiTitolare.DataNascita, Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione).GetValueOrDefault());
                        if (etaTitolareAllaDPR < etaPiuAspettativaDiVita)
                        {
                            if (nSettimaneOBG < 1040)
                            {
                                messaggioVideo = "Il numero settimane deve essere maggiore o uguale di 1040";
                                return false;
                            }
                        }
                    }
                }
            }

            if (Utility.IsDomandaIOBANC(datiPensione.SiglaCategoria) || Utility.IsDomandaSOBANC(datiPensione.SiglaCategoria))
            {
                if (nSettimaneOBG <= 0)
                {
                    messaggioVideo = "Il numero settimane deve essere maggiore di 0";
                    return false;
                }
            }

            if (Utility.IsDomandaVOMIN(datiPensione.SiglaCategoria) && Utility.IsPensioneAnzianitaOrRicostituzione(datiPensione, null))
            {
                if (nSettimaneOBG < 1820)
                {
                    messaggioVideo = "Il numero settimane deve essere almeno 1820";
                    return false;
                }
            }

            //ENG - SOPGI pensioni di reversibilità il campo GP1AV08 prelevato dalla GAIN deve essere valorizzato sul pannello dati assicurativi (campo “Numero Settimane”) non editabile
            //Se dal prelievo GP1AV08 è vuoto o uguale a 0, il messaggio bloccante deve essere: "Il numero di settimane di anzianità contributiva non è stato prelevato dalla pensione del dante causa. Si prega di inviare una segnalazione alla casella di supportoivs."
            if (Utility.IsDomandaSOPGI(datiPensione.SiglaCategoria) && Utility.IsDomandaReversibilita(datiPensione) && nSettimaneOBG == 0)
            {
                messaggioVideo = "Il numero di settimane di anzianità contributiva non è stato prelevato dalla pensione del dante causa. Si prega di inviare una segnalazione alla casella di supportoivs.";
                return false;
            }

            return true;
        }

        public static bool IsSettimaneContributiDirittoAnzianitaInseribili(GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, string codiceBancaEsodatiTraduzioneSuGP, string campoGP2BB05)
        {
            bool isContributiDirittoAnzianitaInseribili = false;
            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            switch (siglaCategoria)
            {
                case "VO":
                case "IO":
                case "SO":
                case "VOP":
                case "SOP":
                case "VOMIN":
                case "SOMIN":
                case "PMO":
                case "VOBANC":
                case "IOBANC":
                case "SOBANC":
                case "VOSPED":
                case "IOSPED":
                case "SOSPED":
                case "VDAI":
                case "IDAI":
                case "SDAI":
                case "VOTOT":
                case "IOTOT":
                case "SOTOT":
                case "VOCUM":
                case "IOCUM":
                case "SOCUM":
                case "VOCOM":
                case "VOART":
                case "VR":
                case "IOCOM":
                case "IOART":
                case "IR":
                case "SOCOM":
                case "SOART":
                case "SR":
                case "APE":
                case "VOCRED":
                case "VOCOOP":
                case "VOESO":
                case "VESO33":
                case "VESO92":
                case "CRED27":
                case "COOP28":
                case "VESO29":
                case "ESOTEL":
                case "ESOAMB":
                case "ESPA":
                case "VOPGI":
                case "VOAUT":
                    isContributiDirittoAnzianitaInseribili = true;
                    break;
                //ENG - Aggiornamento Memo 68/2022 IOPGI
                case "IOPGI":
                    if (!Utility.IsDomandaIOPGI_AGI(datiPensione))
                        isContributiDirittoAnzianitaInseribili = true;
                    break;
            }
            //Permesso inserimento ContributiVolontariAnzianita e ContributiVolontariDiritto per tutte le domande di ESODO (JIRA L2_IST_LIQ-1835)
            //if (siglaCategoria == "VOESO" && ((Utility.IsAssegnoStraordinarioRiscossioneTributiErariali(datiPensione)) || (Utility.IsAssegnoStraordinarioFerrovieDelloStato(datiPensione) && datiPensione.CodiceTipoRichiesta == "74") || (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && codiceBancaEsodatiTraduzioneSuGP != null && (Utility.IsDomandaVOESOErarialiRic(datiPensione, isRiaperturaDomanda, codiceBancaEsodatiTraduzioneSuGP) || Utility.IsDomandaVOESOFerrovieDelloStatoRicConFiltro(datiPensione, isRiaperturaDomanda, campoGP2BB05, codiceBancaEsodatiTraduzioneSuGP)))))
            //    isContributiDirittoAnzianitaInseribili = true;

            return isContributiDirittoAnzianitaInseribili;
        }

        public static bool ControlsNContributiVolontari(int nContributiVolontari, string naturaPensione, GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, string codiceBancaEsodatiTraduzioneSuGP, string campoGP2BB05, int nContributiVVAnzianita, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            Utility.GetCodiciNatura(naturaPensione, out codNat1, out codNat2, out codNat3);
            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            #endregion Recupero Dati


            if (!IsSettimaneContributiDirittoAnzianitaInseribili(datiPensione, isRiaperturaDomanda, codiceBancaEsodatiTraduzioneSuGP, campoGP2BB05))
            {
                if (nContributiVolontari != 0)
                {
                    messaggioVideo = "Il numero contributi volontari diritto deve essere assente";
                    return false;
                }
            }

            if (Utility.IsDomandaVESO29(siglaCategoria))
                return true;

            switch (siglaCategoria)
            {
                //Se la Categoria è = a "INDCOM", "VOSPED", "IOSPED", "SOSPED",
                //"VOBIS", "IOBIS", "VMP", "IMP", "IOAUT", "SOAUT" Numero
                //Contributi Volontari Diritto (RAU113B) deve essere assente
                //ENG - Tolto controllo pel le VOAUT sul numero contributi assente
                case "INDCOM":
                case "VOSPED":
                case "SOSPED":
                case "VOBIS":
                case "IOBIS":
                case "VMP":
                case "IMP":
                case "IOAUT":
                case "SOAUT":
                    if (nContributiVolontari != 0)
                    {
                        messaggioVideo = "Il numero contributi volontari diritto deve essere assente";
                        return false;
                    }
                    break;
                default:
                    break;
            }

            //Il Numero Contributi Volontari Diritto (RAU113B) non può essere superiore a 3000
            if (nContributiVolontari > 3000)
            {
                if (nContributiVolontari != 0)
                {
                    messaggioVideo = "Il numero contributi volontari diritto non può essere superiore a 3000";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsNContributiVVAnzianita(int nContributiVVAnzianita, int nContributiVolontari, string naturaPensione, GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, string codiceBancaEsodatiTraduzioneSuGP, string campoGP2BB05, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';


            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            Utility.GetCodiciNatura(naturaPensione, out codNat1, out codNat2, out codNat3);
            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            #endregion Recupero Dati

            //Se la variabile PLAVAUT è = a 0 il Numero Contributi Volontari per Anzianità
            //(RAU113C) devessere assente
            if (!IsSettimaneContributiDirittoAnzianitaInseribili(datiPensione, isRiaperturaDomanda, codiceBancaEsodatiTraduzioneSuGP, campoGP2BB05))
            {
                if (nContributiVVAnzianita != 0)
                {
                    messaggioVideo = "Il numero contributi volontari per anzianità deve essere assente";
                    return false;
                }
            }

            if (Utility.IsDomandaVESO29(siglaCategoria))
                return true;

            //Se la Categoria (RACATEG) è = a "INDCOM", "VOSPED", "IOSPED",
            //"SOSPED", "VOBIS", "IOBIS", "VMP", "IMP", "IOAUT", "SOAUT" il
            //Numero Contributi Volontari per Anzianità (RAU113C) deve essere assente
            //ENG - Tolto controllo pel le VOAUT sul numero contributi assente
            switch (siglaCategoria)
            {
                case "INDCOM":
                case "VOSPED":
                case "IOSPED":
                case "SOSPED":
                case "VOBIS":
                case "IOBIS":
                case "VMP":
                case "IMP":
                case "IOAUT":
                case "SOAUT":
                    if (nContributiVVAnzianita != 0)
                    {
                        messaggioVideo = "Il numero contributi volontari per anzianità deve essere assente";
                        return false;
                    }
                    break;
                default:
                    break;
            }

            //Se presente l Numero Contributi Volontari Diritto (RAU113B) deve essere
            //presente anche il Numero Contributi Volontari per Anzianità (RAU113C)
            if (nContributiVolontari != 0 && nContributiVVAnzianita == 0 && siglaCategoria != "VOAUT")
            {
                messaggioVideo = "Il numero contributi volontari per anzianità deve essere presente";
                return false;
            }

            //Il Numero Contributi Volontari per Anzianità (RAU113C) non può essere
            //superiore a 3000
            if (nContributiVVAnzianita > 3000)
            {
                messaggioVideo = "Il numero contributi volontari per anzianità non può essere superiore a 3000";
                return false;
            }

            return true;
        }

        public static bool ControlsRequisiti(bool? vecch94, bool? anz94, bool? anz96, string naturaPensione, GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';
            int pdirsup = 0;
            int plavaut = 0;
            int panvein = 0;
            bool posticipo = false;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;

            if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                return true;

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            Utility.GetCodiciNatura(naturaPensione, out codNat1, out codNat2, out codNat3);
            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            GetPdirusp_Plavaut(datiPensione, out pdirsup, out plavaut);
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);
            GetPanvein_Posticipo(naturaPensione, datiPensione, out panvein, out posticipo);
            #endregion Recupero Dati

            //Se la Decorrenza Originaria (RAU104) è inferiore a febbraio 1995 i tre campi
            //non devono essere acquisiti
            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1995, 02, 01)))
            {
                if (vecch94.HasValue || anz94.HasValue || anz96.HasValue)
                {
                    messaggioVideo = "I campi riguardanti i requisiti di anzianità/vecchiaia non devono essere acquisiti";
                    return false;
                }
            }

            //Se il 1° carattere della Categoria (RACATEG) è “V” e la decorrenza è
            //superiore a dicembre 2000 i tre campi non devono essere acquisiti
            if (siglaCategoria.StartsWith("V") && Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2000, 12, 31)))
            {
                if (vecch94.HasValue || anz94.HasValue || anz96.HasValue)
                {
                    messaggioVideo = "I campi riguardanti i requisiti di anzianità/vecchiaia non devono essere acquisiti";
                    return false;
                }
            }

            //Se il campo PDIRSUP è = a 1 i tre campi non devono essere acquisiti
            if (pdirsup == 1)
            {
                if (vecch94.HasValue || anz94.HasValue || anz96.HasValue)
                {
                    messaggioVideo = "I campi riguardanti i requisiti di anzianità/vecchiaia non devono essere acquisiti";
                    return false;
                }
            }

            switch (siglaCategoria)
            {
                //Se la Categoria (RACATEG) è = a “INDCOM”, “VOBIS”, “IOBIS”, “VMP”,
                //“IMP”, “VOAUT”, “IOAUT”, “SOAUT”, “VOSPED”, “IOSPED”, “SOSPED” i tre
                //campi non devono essere acquisiti
                case "INDCOM":
                case "VOBIS":
                case "IOBIS":
                case "VMP":
                case "IMP":
                case "VOAUT":
                case "IOAUT":
                case "SOAUT":
                case "VOSPED":
                case "IOSPED":
                case "SOSPED":
                    if (vecch94.HasValue || anz94.HasValue || anz96.HasValue)
                    {
                        messaggioVideo = "I campi riguardanti i requisiti di anzianità/vecchiaia non devono essere acquisiti";
                        return false;
                    }
                    break;
                //Se la Categoria (RACATEG) è = a “VO”, “VOP”, “VOMIN”, “VOBANC”, “VR”,
                //“VOART”, “VOCOM”, “VDAI” e il 1° Codice Natura è = a “1”, “2”, “3”, “4” il
                //campo Anz. al 12/94 deve essere assente
                //Se la Categoria (RACATEG) è = a “VO”, VOP”, “VOMIN”, “VOBANC”, “VR”,
                //“VOART”, “VOCOM”, “VDAI” e il 1° Codice Natura è = a “1”, “2”, “3”, “4” e la
                //Decorrenza Originaria (RAU104) è superiore a dicembre 1997 il campo Anz.
                //al 09/96 deve essere assente
                case "VO":
                case "VOP":
                case "VOMIN":
                case "VOBANC":
                case "VR":
                case "VOART":
                case "VOCOM":
                case "VDAI":
                    switch (codNat1)
                    {
                        case '1':
                        case '2':
                        case '3':
                        case '4':
                            if (anz94.HasValue)
                            {
                                messaggioVideo = "Il campo Anz. al 12/94 deve essere assente";
                                return false;
                            }

                            if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(1997, 12, 31)))
                            {
                                if (anz96.HasValue)
                                {
                                    messaggioVideo = "Il campo Anz. al 12/96 deve essere assente";
                                    return false;
                                }
                            }
                            break;
                        default:
                            break;
                    }
                    break;
                default:
                    break;
            }

            if (panvein == 0)
            {
                //Se il campo PANVEIN è = a zero e il 3° Codice Natura (RAU1013) è diverso
                //da “J”, “K”, “Q”, “P”, “W”, “X”, “Y” non si possono avere le combinazioni
                //relativi al codice RAD411 = a 6 e 8 (SI SI SI – NO SI NO)
                //Se il campo PANVEIN è = a zero e il 3° Codice Natura (RAU1013) è = a “J”,
                //“K”, “Q”, “P”, “W”, “X”, “Y” e la Decorrenza Originaria (RAU104) è inferiore a
                //gennaio 1995 il campo Vec. al 12/94 deve essere assente altrimenti deve
                //contenere “SI” o “NO”
                switch (codNat3)
                {
                    case 'J':
                    case 'K':
                    case 'P':
                    case 'W':
                    case 'X':
                    case 'Y':
                        if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1995, 1, 1)))
                        {
                            if (vecch94.HasValue)
                            {
                                messaggioVideo = "Il campo Vec. al 12/94 deve essere assente";
                                return false;
                            }
                        }
                        else
                        {
                            if (!vecch94.HasValue && !(Utility.IsDomandaMIN(siglaCategoria) && Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2001, 1, 1))))
                            {
                                messaggioVideo = "Il campo Vec. al 12/94 deve contenere SI o NO";
                                return false;
                            }
                        }
                        break;
                    case 'Q':
                        if (!Utility.IsDomandaQuota100VESO33(datiPensione) && !Utility.IsDomandaQuota100COOP28(datiPensione) && !Utility.IsDomandaQuota100CRED27(datiPensione) &&
                            !Utility.IsDomandaQuota100VESO29(datiPensione) && !Utility.IsDomandaQuota100ESOTEL(datiPensione) && !Utility.IsDomandaQuota100ESOAMB(datiPensione))
                        {
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1995, 1, 1)))
                            {
                                if (vecch94.HasValue)
                                {
                                    messaggioVideo = "Il campo Vec. al 12/94 deve essere assente";
                                    return false;
                                }
                            }
                            else
                            {
                                if (!vecch94.HasValue)
                                {
                                    messaggioVideo = "Il campo Vec. al 12/94 deve contenere SI o NO";
                                    return false;
                                }
                            }
                        }
                        break;
                    default:
                        int rad411 = MappingVersoHost.GetGP1AXE3byReqAnzVecch(vecch94, anz94, anz96);
                        if (rad411 == 6 || rad411 == 8)
                        {
                            messaggioVideo = "Non si possono avere le seguenti combinazioni: VECCH94 = SI, ANZ94 = SI, ANZ96 = SI o " +
                                "VECCH94 = NO, ANZ94 = SI, ANZ96 = NO";
                            return false;
                        }
                        break;
                }
            }
            //Se il campo PANVEIN è = 1 e il campo Vec. al 12/94 contiene “SI” o “NO il
            //campo Anz. al 12/94 deve essere assente
            //Se il campo PANVEIN è = 1 e il campo Vec. al 12/94 contiene “SI” o “NO il
            //campo Anz. al 09/96 deve essere assente
            else if (panvein == 1)
            {
                if (vecch94.HasValue && anz94.HasValue)
                {
                    messaggioVideo = "Il campo Anz. al 12/94 deve essere assente";
                    return false;
                }

                if (vecch94.HasValue && anz96.HasValue)
                {
                    messaggioVideo = "Il campo Anz. al 12/96 deve essere assente";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsTrattenutaINPDAP(bool? trattenutaINPDAD, DateTime? dataTrattenutaINPDAD, DateTime? decEliminazione,
            GestionePensione.DatiPensione datiPensione, DateTime? dataRinunciaTrattenutaInpdapStorico, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);

            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);

            //Imposto a 1 giorno decorrenza per domande con decorrenza inframese
            if (Utility.IsDomandaIOCUM(datiPensione.SiglaCategoria))
            {
                decorrenzaOriginaria = new DateTime(decorrenzaOriginaria.Year, decorrenzaOriginaria.Month, 1);
            }
            #endregion Recupero Dati

            GestioneControlliDinamici.ControlloDinamico ctrl = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneControlliMemo86", out ctrl);

            //Il Campo Codice Trattenuta INPDAP (GP1AN87A) e la Data Decorrenza Trattenuta INPDAP (GP1AN87D) 
            //non vanno acquisiti per le seguenti Categorie (RACATEG): VOCRED", "VOCOOP", "VOESO ", "VOBANC", “IOBANC", 
            //"SOBANC", "SOTOT ", "VOBIS", "IOBIS", "VMP", "IMP", "INDCOM", "SO", "SOP", "SOMIN", "SR", “SOART", "SOCOM", 
            //"SOART", "SOSPED", "SOAUT", "SDAI", "COOP28".
            switch (siglaCategoria)
            {
                case "VOCRED":
                case "CRED27":
                case "VOCOOP":
                case "VOESO":
                case "VOBANC":
                case "IOBANC":
                case "SOBANC":
                case "VOBIS":
                case "IOBIS":
                case "VMP":
                case "IMP":
                case "INDCOM":
                case "SO":
                case "SOP":
                case "SOMIN":
                case "SR":
                case "SOART":
                case "SOCOM":
                case "SOSPED":
                case "SOAUT":
                case "SDAI":
                case "COOP28":
                    if (trattenutaINPDAD.GetValueOrDefault() || dataTrattenutaINPDAD.HasValue)
                    {
                        messaggioVideo = "Il codice trattenuta Fondo Credito e la decorrenza trattenuta Fondo Credito non vanno acquisiti";
                        return false;
                    }
                    break;
                //Se la Categoria (RACATEG) è = a “VOTOT”, “SOTOT” il Campo Codice Trattenuta INPDAP (GP1AN87A) e 
                //la Data Decorrenza Trattenuta INPDAP (GP1AN87D) può essere presente solo se il Codice Banca (RACODBAN4) è= a “0801”, “0802
                case "SOTOT":
                case "VOTOT":
                    if ((trattenutaINPDAD.GetValueOrDefault() || dataTrattenutaINPDAD.HasValue) &&
                        (datiPensione.CodiceBancaEsodati.HasValue &&
                        (datiPensione.CodiceBancaEsodati.Value != 801 && datiPensione.CodiceBancaEsodati.Value != 802)))
                    {
                        messaggioVideo = "Il codice trattenuta Fondo Credito e la decorrenza trattenuta Fondo Credito non vanno acquisiti";
                        return false;
                    }
                    break;
                case "APE":
                case "PS":
                case "AS":
                case "INVCIV":
                case "VOSPED":
                case "IOSPED":
                case "VOST":
                case "VESO33":
                case "VESO92":
                case "ESPA":
                    if (ctrl != null && ctrl.ValoreControllo == "SI" && (trattenutaINPDAD.GetValueOrDefault() || dataTrattenutaINPDAD.HasValue))
                    {
                        messaggioVideo = "Il codice trattenuta Fondo Credito e la decorrenza trattenuta Fondo Credito non vanno acquisiti";
                        return false;
                    }
                    break;
                default:
                    break;
            }
            //Il Campo Codice Trattenuta INPDAP (GP1AN87A) e la Data Decorrenza Trattenuta INPDAP (GP1AN87D) 
            //non vanno acquisiti per gli assegni ordinari di invalidità, le domande ai Superstiti e le Enpals.
            if (ctrl != null && ctrl.ValoreControllo == "SI" && (trattenutaINPDAD.GetValueOrDefault() || dataTrattenutaINPDAD.HasValue) &&
                (Utility.IsDomandaAssegnoInvaliditaOrdinario(datiPensione) || Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione) || Utility.IsDomandaENPALS(datiPensione.Gestione)))
            {
                messaggioVideo = "Il codice trattenuta Fondo Credito e la decorrenza trattenuta Fondo Credito non vanno acquisiti";
                return false;
            }

            //Il Campo Codice Trattenuta INPDAP (GP1AN87A) può contenere “SI” o essere vuoto
            //Il 2 dati devono essere presenti contemporanemente
            if ((trattenutaINPDAD.HasValue && trattenutaINPDAD.Value && !dataTrattenutaINPDAD.HasValue) ||
                (dataTrattenutaINPDAD.HasValue && (!trattenutaINPDAD.HasValue || !trattenutaINPDAD.Value)))
            {
                messaggioVideo = "La decorrenza trattenuta Fondo Credito è necessaria in presenza del codice trattenuta Fondo Credito pari a SI";
                return false;
            }

            if (dataTrattenutaINPDAD.HasValue)
            {
                if (!(ctrl != null && ctrl.ValoreControllo == "SI" && Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2022, 03, 01))))
                {
                    if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.GestioneControlliINPDAP.BYPASS_DEC_TRATTENUTA_INPDAP))
                    {
                        if (!Utility.IsRicostituzione(datiPensione.Gruppo))
                        {
                            //ENG - TRF con Data Trattenuta valorizzata dal prelievo e decorrenza minore di 03/2022
                            if (Utility.IsRiaperturaDomanda(datiPensione.Id) && dataRinunciaTrattenutaInpdapStorico.HasValue && !Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2022, 03, 01)))
                            {
                                if (!Utility.DataSuccessivaA(dataTrattenutaINPDAD.Value, decorrenzaOriginaria))
                                {
                                    messaggioVideo = "La decorrenza trattenuta Fondo Credito non deve essere minore della decorrenza originaria";
                                    return false;
                                }
                            }
                            else
                            {
                                //Se il Campo GP1AN87D (Decorrenza trattenuta dati INPDAP) è presente e
                                //la Decorrenza Originaria (RAU104) è maggiore di maggio 2008 le due
                                //decorrenze devono essere uguali
                                if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 05, 31)))
                                {
                                    if (!Utility.DataSuccessivaA(dataTrattenutaINPDAD.Value, decorrenzaOriginaria) ||
                                        Utility.DataStrettamenteSuccessivaA(dataTrattenutaINPDAD.Value, decorrenzaOriginaria))
                                    {
                                        messaggioVideo = "La decorrenza trattenuta Fondo Credito deve essere pari alla decorrenza originaria";
                                        return false;
                                    }
                                }

                                //Se il Campo GP1AN87D (Decorrenza trattenuta dati INPDAP) è presente e
                                //la Decorrenza Originaria (RAU104) è maggiore di novembre 2007 il Campo
                                //GP1AN87D (Decorrenza trattenuta dati INPDAP) deve essere = a giungo
                                //2008 oppure = alla Decorrenza Originaria (RAU104)
                                if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2007, 11, 30)))
                                {
                                    if ((!Utility.DataSuccessivaA(dataTrattenutaINPDAD.Value, decorrenzaOriginaria) ||
                                        Utility.DataStrettamenteSuccessivaA(dataTrattenutaINPDAD.Value, decorrenzaOriginaria)) &&
                                        (!Utility.DataSuccessivaA(dataTrattenutaINPDAD.Value, new DateTime(2008, 6, 1)) ||
                                        Utility.DataStrettamenteSuccessivaA(dataTrattenutaINPDAD.Value, new DateTime(2008, 6, 1))))
                                    {
                                        messaggioVideo = "La decorrenza trattenuta Fondo Credito deve essere pari alla decorrenza originaria o pari a giugno 2008";
                                        return false;
                                    }
                                }
                            }

                            //Se il Campo GP1AN87D (Decorrenza trattenuta dati INPDAP) è presente e
                            //la Decorrenza Originaria (RAU104) è inferiore a dicembre 2007 il Campo
                            //GP1AN87D (Decorrenza trattenuta dati INPDAP) deve essere = a novembre
                            //2007 oppure = a giugno 2008
                            if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2007, 12, 1)))
                            {
                                if ((!Utility.DataSuccessivaA(dataTrattenutaINPDAD.Value, new DateTime(2007, 11, 1)) ||
                                    Utility.DataStrettamenteSuccessivaA(dataTrattenutaINPDAD.Value, new DateTime(2007, 11, 1))) &&
                                    (!Utility.DataSuccessivaA(dataTrattenutaINPDAD.Value, new DateTime(2008, 6, 1)) ||
                                    Utility.DataStrettamenteSuccessivaA(dataTrattenutaINPDAD.Value, new DateTime(2008, 6, 1))))
                                {
                                    messaggioVideo = "La decorrenza trattenuta Fondo Credito deve essere pari a novembre 2007 o pari a giugno 2008";
                                    return false;
                                }
                            }

                            //La Data Decorrenza Trattenuta INPDAP (GP1AN87D) non può essere inferiore a novembre 2007
                            if (!Utility.DataSuccessivaA(dataTrattenutaINPDAD.Value, new DateTime(2007, 11, 1)))
                            {
                                messaggioVideo = "La decorrenza trattenuta Fondo Credito non può essere inferiore a novembre 2007";
                                return false;
                            }
                        }
                        else
                        {
                            if (!Utility.DataSuccessivaA(dataTrattenutaINPDAD.Value, decorrenzaOriginaria))
                            {
                                messaggioVideo = "Non è consentito l’inserimento di una decorrenza trattenuta Fondo Credito precedente alla decorrenza della pensione";
                                return false;
                            }

                            if (Utility.DataSuccessivaA(dataTrattenutaINPDAD.Value, new DateTime(2022, 03, 01)))
                            {
                                messaggioVideo = "Non è consentito l'inserimento di una decorrenza trattenuta maggiore di febbraio 2022";
                                return false;
                            }
                        }
                    }
                }
                else if (!dataRinunciaTrattenutaInpdapStorico.HasValue)
                {
                    //Aggiornamento Memo86: Per le RIC con decorrenza originaria >= 03/2022, la data trattenuta INPDAP deve essere uguale alla decorrenza originaria
                    if (!Utility.DataSuccessivaA(dataTrattenutaINPDAD.Value, decorrenzaOriginaria) || Utility.DataStrettamenteSuccessivaA(dataTrattenutaINPDAD.Value, decorrenzaOriginaria))
                    {
                        messaggioVideo = "La decorrenza trattenuta Fondo Credito deve essere pari alla decorrenza originaria";
                        return false;
                    }
                }

                //La Data Decorrenza Trattenuta INPDAP (GP1AN87D) non può essere
                //superiore alla Data Decorrenza Eliminazione (RADECELIM) quando
                //presente
                if (decEliminazione.HasValue)
                {
                    if (Utility.DataStrettamenteSuccessivaA(dataTrattenutaINPDAD.Value, decEliminazione.Value))
                    {
                        messaggioVideo = "La decorrenza trattenuta Fondo Credito non può essere superiore alla decorrenza eliminazione";
                        return false;
                    }
                }
            }

            return true;
        }

        public static bool ControlsInizioFineUltimoLavoro(DateTime? inizioUltimoLavoro, DateTime? fineUltimoLavoro, DateTime? inizioAssicurazione, DateTime? fineAssicurazione,
            GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);

            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);
            #endregion Recupero Dati

            //Le due date devono essere acquisite quando la Categoria (RACATEG) è = a
            //“VOCRED”, “VOCOOP”, (“VOESO” con il Campo DO-NOTE = a “99 “
            switch (siglaCategoria)
            {
                case "VOCRED":
                case "CRED27":
                case "VOCOOP":
                case "COOP28":
                    if (!inizioUltimoLavoro.HasValue || !fineUltimoLavoro.HasValue)
                    {
                        messaggioVideo = "Le date di inizio e fine ultimo lavoro devono essere acquisite";
                        return false;
                    }
                    break;
                case "VOESO":
                    if (filtro != "99")
                    {
                        if (inizioUltimoLavoro.HasValue || fineUltimoLavoro.HasValue)
                        {
                            messaggioVideo = "Le date di inizio e fine ultimo lavoro non devono essere acquisite";
                            return false;
                        }
                    }
                    else if (!inizioUltimoLavoro.HasValue || !fineUltimoLavoro.HasValue)
                    {
                        messaggioVideo = "Le date di inizio e fine ultimo lavoro devono essere acquisite";
                        return false;
                    }
                    break;
                case "VDAI":
                case "IDAI":
                case "SDAI":
                    // IMPORTANTE: non ci è stato specificato se i campi sono obbligatori, però per queste categorie non acquisibili
                    break;
                default:
                    if (inizioUltimoLavoro.HasValue || fineUltimoLavoro.HasValue)
                    {
                        messaggioVideo = "Le date di inizio e fine ultimo lavoro non devono essere acquisite";
                        return false;
                    }
                    break;
            }

            if (inizioUltimoLavoro.HasValue && fineUltimoLavoro.HasValue)
            {
                //La Data Fine Ultimo Rapporto (GP2BM05) Inizio Ultimo Rapporto (GP2BM04)
                //deve essere successiva alla Data Inizio Ultimo Rapporto (GP2BM04)
                if (!Utility.DataStrettamenteSuccessivaA(fineUltimoLavoro.Value, inizioUltimoLavoro.Value))
                {
                    messaggioVideo = "La data di fine ultimo lavoro deve essere successiva alla data di inizio ultimo lavoro";
                    return false;
                }

                if (inizioAssicurazione.HasValue)
                {
                    //La Data Inizio Ultimo Rapporto (GP2BM04) non può essere antecedente alla Data
                    //Inizio Assicurazione (VINASS)
                    if (!Utility.DataSuccessivaA(inizioUltimoLavoro.Value, inizioAssicurazione.Value))
                    {
                        messaggioVideo = "La data di inizio ultimo lavoro non può essere antecedente alla data di inizio assicurazione";
                        return false;
                    }
                }
                if (fineAssicurazione.HasValue)
                {
                    //La Data Fine Ultimo Rapporto (GP2BM05) non può essere successiva alla Data
                    //Fine Assicurazione (VFIASS)
                    if (Utility.DataStrettamenteSuccessivaA(fineUltimoLavoro.Value, fineAssicurazione.Value))
                    {
                        messaggioVideo = "La data di fine ultimo lavoro non può essere successiva alla data di fine assicurazione";
                        return false;
                    }
                }
            }

            return true;
        }

        public static bool ControlsDecorrenzaOpzione(DateTime? decorrenzaOpzione, byte? causaCarico, GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            int pdirsup = 0;
            int plavaut = 0;

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);

            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);
            GetPdirusp_Plavaut(datiPensione, out pdirsup, out plavaut);
            #endregion Recupero Dati

            //Se la Categoria (RACATEG) è = a “INDCOM”, “VOBIS”,“IOBIS”,“VMP”, “IMP”, “VOAUT”,“IOAUT”,“SOAUT” 
            //la Decorrenza Opzione (RAU113D) non deve essere acquisita
            switch (siglaCategoria)
            {
                case "INDCOM":
                case "VOBIS":
                case "IOBIS":
                case "VMP":
                case "IMP":
                case "VOAUT":
                case "IOAUT":
                case "SOAUT":
                    if (decorrenzaOpzione.HasValue)
                    {
                        messaggioVideo = "La decorrenza opzione non deve essere acquisita";
                        return false;
                    }
                    break;
                default:
                    break;
            }

            //Se il Campo PLAVAUT è = a zero la Decorrenza Opzione (RAU113D) non deve essere acquisita
            if (decorrenzaOpzione.HasValue && plavaut == 0)
            {
                messaggioVideo = "La decorrenza opzione non deve essere acquisita";
                return false;
            }

            //Se la causa carico (RAU101) è = a 9 la Decorrenza Opzione (RAU113D) non deve essere acquisita
            if (causaCarico.HasValue && causaCarico.Value == 9 && decorrenzaOpzione.HasValue)
            {
                messaggioVideo = "La decorrenza opzione non deve essere acquisita";
                return false;
            }

            if (decorrenzaOpzione.HasValue)
            {
                //La Decorrenza Opzione (RAU113D) deve essere superiore alla Decorrenza originaria (RAU104)
                if (!Utility.DataStrettamenteSuccessivaA(decorrenzaOpzione.Value, decorrenzaOriginaria))
                {
                    messaggioVideo = "La decorrenza opzione deve essere superiore alla decorrenza originaria";
                    return false;
                }
                //Se viene acquisita la La Decorrenza Opzione (RAU113D) la Decorrenza originaria (RAU104) deve essere precedente al 1980
                if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1980, 1, 1)))
                {
                    messaggioVideo = "Se presente la decorrenza opzione, la decorrenza originaria deve essere precedente al 1980";
                    return false;
                }
            }


            return true;
        }

        public static bool ControlsConfermaInvalidita(byte? confermaInvalidita, string naturaPensione, GestionePensione.DatiPensione datiPensione, DateTime dataSistema, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            Utility.GetCodiciNatura(naturaPensione, out codNat1, out codNat2, out codNat3);
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);
            #endregion Recupero Dati

            //Il Campo Conferma Invalidità (RA205) può essere presente con le Categorie
            //(RACATEG) = a “IO”, “IDAI”, “IR”, “IOART, “IOCOM”, “IOP”, “IOBANC”,
            //“IOAUT”
            switch (siglaCategoria)
            {
                case "IO":
                case "IDAI":
                case "IR":
                case "IOART":
                case "IOCOM":
                case "IOP":
                case "IOBANC":
                case "IOAUT":
                case "IOSPETT":
                case "IOSPORT":
                case "IOPGI":
                    break;
                default:
                    if (confermaInvalidita.HasValue)
                    {
                        messaggioVideo = "Il campo conferma invalidità non può essere presente";
                        return false;
                    }
                    break;
            }

            if (confermaInvalidita.HasValue)
            {
                //Il Campo Conferma Invalidità (RA205) può contenere 2 o 3
                if (confermaInvalidita.Value != 2 && confermaInvalidita.Value != 3)
                {
                    messaggioVideo = "Il campo conferma invalidità può contenere 2 o 3";
                    return false;
                }

                if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(1984, 07, 31)))
                {
                    //Se la Decorrenza Originaria (RAU104) è successiva a luglio 1984 e in 1°
                    //Codice Natura (RAU1031) è diverso da spazio, “6”, “8”, “9” il Campo
                    //Conferma Invalidità (RA205) deve essere assente
                    if (codNat1 != ' ' && codNat1 != '6' && codNat1 != '8' && codNat1 != '9')
                    {
                        messaggioVideo = "Il campo conferma invalidità deve essere assente";
                        return false;
                    }
                }
            }

            return true;
        }

        public static bool ControlsFlagProvvisoria(bool? flagProvvisoria, GestionePensione.DatiPensione datiPensione, int annoCompetenza, bool isRiaperturaDomanda, DateTime? inizioBonus, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            int pdirsup = 0;
            int plavaut = 0;
            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);
            GetPdirusp_Plavaut(datiPensione, out pdirsup, out plavaut);
            Utility.TipoAppartenenza? tipoAppartenenza = Utility.GetTipoAppartenenza(datiPensione.IndConvInt, datiPensione.Gestione);
            #endregion Recupero Dati

            //Il Campo PS-OKNO può contenere “X” o essere vuoto
            //Se la Categoria (RACATEG) è = a “INDCOM”, “VOBIS”, “IOBIS”, “VMP”,
            //“IMP” il Campo Provvisoria (RAFLGPRW) non va acquisito
            switch (siglaCategoria)
            {
                case "INDCOM":
                case "VOBIS":
                case "IOBIS":
                case "VMP":
                case "IMP":
                    if (flagProvvisoria.HasValue && flagProvvisoria.Value)
                    {
                        messaggioVideo = "Il campo provvisoria non va acquisito";
                        return false;
                    }
                    break;
                default:
                    break;
            }

            //Se il Campo PS-OKNO (RAFLGPRW) è = a “OK” il Campo Provvisoria
            //(RAFLGPRW) non va acquisito
            //Se il campo DO-NOTE è = a “BNX”, “MPM”, “SAM”, “SVM”, “SSM”, “STM” mettere “NO” al campo PS-OKNO altrimenti mettere “SI” al campo  PS-OKNO 
            bool ps_okno = false;
            if (Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica)
            {
                switch (filtro)
                {
                    case "BNX":
                    case "MPM":
                    case "SAM":
                    case "SVM":
                    case "SSM":
                    case "STM":
                        break;
                    default:
                        ps_okno = true;
                        if (flagProvvisoria.HasValue && flagProvvisoria.Value)
                        {
                            messaggioVideo = "Il campo provvisoria non va acquisito";
                            return false;
                        }
                        break;
                }
            }

            switch (filtro)
            {
                //Se il Campo DO-NOTE (RAFLGPRW) è = a “DAI” il Campo Provvisoria
                //(RAFLGPRW) non va acquisito
                case "DAI":
                    if (flagProvvisoria.HasValue && flagProvvisoria.Value)
                    {
                        messaggioVideo = "Il campo provvisoria non va acquisito";
                        return false;
                    }
                    break;
                //Se il Campo DO-NOTE è = a “CDP” il Campo Provvisoria (RAFLGPRW)
                //deve essere precompilato con “X” e non variato
                case "CDP":
                    if (!flagProvvisoria.HasValue || !flagProvvisoria.Value)
                    {
                        messaggioVideo = "Il campo provvisoria va acquisito";
                        return false;
                    }
                    break;
                //Se il Campo DO-NOTE è = a “BNS”, “BNX” e il Campo INIZIOSCO è
                //inferiore all'anno del Sistema il Campo Provvisoria (RAFLGPRW) non va
                //acquisito
                case "BNS":
                case "BNX":
                    //GestioneDatiControlloFelpe.ControlloFelpe controlloFelpe = null;
                    //GestioneDatiControlloFelpe.GetDatiControlloFelpeByIdPensione(datiPensione.Id, out controlloFelpe);
                    //if (controlloFelpe != null && controlloFelpe.InizioBonus.HasValue)
                    //{
                    //    if (!Utility.DataSuccessivaA(controlloFelpe.InizioBonus.Value, new DateTime(annoCompetenza + 1, 1, 1)) && flagProvvisoria.HasValue && flagProvvisoria.Value)
                    //    {
                    //        messaggioVideo = "Il campo provvisoria non va acquisito";
                    //        return false;
                    //    }
                    //}
                    if (inizioBonus.HasValue && !Utility.IsDomandaBancari(siglaCategoria))
                    {
                        if (!Utility.DataSuccessivaA(inizioBonus.Value, new DateTime(annoCompetenza + 1, 1, 1)) && flagProvvisoria.HasValue && flagProvvisoria.Value)
                        {
                            messaggioVideo = "Il campo provvisoria non va acquisito";
                            return false;
                        }
                    }
                    break;
            }

            //Se la Categoria (RACATEG) è diversa da “VOBIS”, “IOBIS”, “VMP”, “IMP” e il
            //Campo PDIRSUP è = a zero e il Campo PS-OKNO è = a “NO” e la
            //Decorrenza Originaria (RAU104) è superiore a gennaio 2014 il Campo
            //Provvisoria (RAFLGPRW) non deve contenere vuoto (PS: la data
            //gennaio 2013 per quest'anno, va variato con l'anno successivo ogni
            //anno quando la D.G. INPS - dopo i rinnovi - comunica i nuovi
            //coefficienti e i programmi centrali di calcolo sono allineati a questi)
            switch (siglaCategoria)
            {
                case "VOBIS":
                case "IOBIS":
                case "VMP":
                case "IMP":
                    break;
                default:
                    if (pdirsup == 0 && !ps_okno)
                    {
                        if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(annoCompetenza + 1, 1, 1)))
                        {
                            if (!flagProvvisoria.HasValue || !flagProvvisoria.Value)
                            {
                                messaggioVideo = "Il campo provvisoria va acquisito";
                                return false;
                            }
                        }
                    }
                    break;
            }

            if (Utility.IsDomandaUnicarpe(datiPensione, true) != Utility.TipoUnicarpe.Automatica &&
                !(Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Ricostituzione || isRiaperturaDomanda) &&
                !Utility.IsDomandaENPALS(datiPensione.Gestione) &&
                !(Utility.GetTipoDomanda(datiPensione.Gruppo, datiPensione.Prodotto) == Utility.TipoDomanda.Superstiti && datiPensione.Prodotto == "0025") &&
                !Utility.IsDomandaINDCOM(datiPensione.SiglaCategoria) && !Utility.IsRenditaCasalinghe(datiPensione) && !Utility.IsRenditaFacoltativa(datiPensione) && !Utility.IsDomandaPSO(datiPensione.SiglaCategoria) && !Utility.IsDomandaPMO(datiPensione.SiglaCategoria))
            {
                if (!flagProvvisoria.HasValue || !flagProvvisoria.Value)
                {
                    DateTime? decorrenzaProvvisoriaObbligatoria = null;
                    GestioneControlliDinamici.GetDecorrenzaProvvisoriaObbligatoria(tipoAppartenenza, out decorrenzaProvvisoriaObbligatoria);
                    if (decorrenzaProvvisoriaObbligatoria.HasValue)
                    {
                        if (Utility.DataSuccessivaA(decorrenzaOriginaria, decorrenzaProvvisoriaObbligatoria.Value))
                        {
                            messaggioVideo = "Attenzione non sono ancora disponibili i nuovi coefficienti di rivalutazione delle retribuzioni. Per proseguire è necessario selezionare il flag Provvisoria.";
                            return false;
                        }
                    }
                }
            }

            return true;
        }

        public static bool ControlsScadenzaRevSan(DateTime? scadRevSan, DateTime? inizioAssicurazione, DateTime? decEliminazione, GestionePensione.DatiPensione datiPensione, char? sessoTitolare,
            DateTime? dataNascitaTitolare, DateTime dataSistema, bool isRiaperturaDomanda, List<GestioneDecodifica.CtrlScadenzaIndennizzoINDCOM> listaCtrlScadenzaIndennizzoINDCOM, GestionePensione.DatiEliminazione datiEliminazione,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            int pdirsup = 0;
            int plavaut = 0;

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);
            GetPdirusp_Plavaut(datiPensione, out pdirsup, out plavaut);

            //ENG - Chiave per Memo 39/2023
            GestioneControlliDinamici.ControlloDinamico controlloDinamicoMemo39 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo39_2023", out controlloDinamicoMemo39);

            //ENG - Memo 28_2024
            GestioneControlliDinamici.ControlloDinamico ctrl28_2024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo28_2024", out ctrl28_2024);
            if (ctrl28_2024 != null && !String.IsNullOrEmpty(ctrl28_2024.ValoreControllo) && ctrl28_2024.ValoreControllo.ToUpperInvariant() == "SI")
            {
                if (((datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001" && datiPensione.Tipo == "0017") ||
                    (datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0001" && datiPensione.Tipo == "0045" && datiPensione.CodiceTipoRichiesta == "AV")) &&
                    ((datiPensione.TipoCalcolo.HasValue && datiPensione.TipoCalcolo == (byte)Utility.TipoCalcolo.Contributivo) ||
                    Utility.IsDomandaCumulo(datiPensione.SiglaCategoria)) && datiPensione.DecorrenzaOriginaria.HasValue &&
                    Utility.DataStrettamenteSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, new DateTime(2024, 01, 01)))
                {
                    return true;
                }

                //ENG - Memo 28 RIC Anticipate
                if (Utility.IsRicostituzione_MotiviContributivi(datiPensione) && datiPensione.DecorrenzaOriginaria.HasValue &&
                    Utility.DataStrettamenteSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, new DateTime(2024, 1, 1)) &&
                    datiPensione.TipoCalcolo.HasValue && datiPensione.TipoCalcolo == (byte)Utility.TipoCalcolo.Contributivo)
                {
                    if ((datiPensione.IdTipoPLPerRIC == 7 && !String.IsNullOrEmpty(datiPensione.NaturaPensione) && (datiPensione.NaturaPensione.Substring(0, 1) == "1" || datiPensione.NaturaPensione.Substring(0, 1) == "2"))
                        || datiPensione.IdTipoPLPerRIC == 26)
                    {
                        return true;
                    }
                }
            }
            #endregion Recupero Dati

            var label = Utility.IsDomandaINDCOM(datiPensione.SiglaCategoria) ? "indennizzo" : "revisione sanitaria";

            //Se nella Categoria (RACATEG) al 1° carattere c'è la “I” ad eccezione della
            //Categoria “INDCOM” la data può essere acquisita e il Campo è “Data
            //Revisione Sanitaria”
            if (siglaCategoria.StartsWith("I") && siglaCategoria != "INDCOM")
            {

            }

            //Se la Categoria (RACATEG) è = a “PMO” con il 3° carattere del Certificato =
            //a “2” o “5” a data può essere acquisita e il Campo è “Data Revisione
            //Sanitaria”
            if (siglaCategoria == "PMO" && (certificato.Substring(2, 1) == "2" || certificato.Substring(2, 1) == "5"))
            {

            }

            var tipoRicINDCOM = string.Empty;
            //Individuazione RIC INDCOM in base alla decorrenza
            if (Utility.IsDomandaINDCOM(datiPensione.SiglaCategoria) && Utility.IsRicostituzione(datiPensione.Gruppo))
            {
                if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2019, 02, 01)))
                    tipoRicINDCOM = "0175";
                if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2014, 02, 01)) && !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2017, 02, 01)))
                    tipoRicINDCOM = "0156";
                if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2009, 02, 01)) && !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2012, 02, 01)))
                    tipoRicINDCOM = "0129";
                if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2002, 02, 01)) && !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 02, 01)))
                    tipoRicINDCOM = "0125";
                if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1996, 02, 01)) && !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(1998, 02, 01)))
                    tipoRicINDCOM = "0124";
            }


            //Se il Campo DO-NOTE è = a “LS1”, “LS2” la data deve essere acquisita e il
            //Campo è “Data Scadenza Assegno”
            if (filtro == "LS1" || filtro == "LS2" || Utility.IsDomandaINDCOM175(datiPensione) || Utility.IsDomandaINDCOM156(datiPensione) || Utility.IsDomandaINDCOM129(datiPensione) || (Utility.IsDomandaINDCOM(datiPensione.SiglaCategoria) && Utility.IsRicostituzione(datiPensione.Gruppo) && tipoRicINDCOM != "0124"))
            {
                if (!scadRevSan.HasValue)
                {
                    messaggioVideo = "La scadenza " + label + " deve essere acquisita";
                    return false;
                }
            }


            if (scadRevSan.HasValue)
            {
                if (Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO33(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) ||
                    Utility.IsDomandaVOCRED_CRED27(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCOOP_COOP28(datiPensione.SiglaCategoria) || Utility.IsDomandaESPA(datiPensione.SiglaCategoria) || Utility.IsDomandaINDCOM124(datiPensione))
                {
                    messaggioVideo = "La scadenza " + label + " sanitaria non è ammessa.";
                    return false;
                }

                if (Utility.IsDomandaINDCOM175(datiPensione))
                {
                    if (!Utility.DataSuccessivaA(scadRevSan.Value, decorrenzaOriginaria))
                    {
                        messaggioVideo = "La scadenza indenizzo deve essere successiva alla decorrenza originaria";
                        return false;
                    }
                    if (!Utility.DataStrettamenteSuccessivaA(scadRevSan.Value, new DateTime(2019, 02, 28)))
                    {
                        messaggioVideo = "La scadenza indenizzo deve essere successiva a Febbraio 2019";
                        return false;
                    }
                }

                if (Utility.IsDomandaINDCOM156(datiPensione))
                {
                    if (!Utility.DataSuccessivaA(scadRevSan.Value, decorrenzaOriginaria))
                    {
                        messaggioVideo = "La scadenza indenizzo deve essere successiva alla decorrenza originaria";
                        return false;
                    }
                    if (!Utility.DataStrettamenteSuccessivaA(scadRevSan.Value, new DateTime(2014, 02, 28)))
                    {
                        messaggioVideo = "La scadenza indenizzo deve essere successiva a Febbraio 2014";
                        return false;
                    }
                    if (Utility.DataSuccessivaA(scadRevSan.Value, new DateTime(2028, 02, 01)))
                    {
                        messaggioVideo = "La scadenza indenizzo deve essere strettamente inferiore a Febbraio 2028";
                        return false;
                    }
                }

                if (Utility.IsDomandaINDCOM(datiPensione.SiglaCategoria) && Utility.IsRicostituzione(datiPensione.Gruppo) && (tipoRicINDCOM == "0129" || tipoRicINDCOM == "0125"))
                {
                    GestioneControlliDinamici.ControlloDinamico controlloDinamico = null;
                    GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("DataLimiteINDCOM", out controlloDinamico);
                    DateTime dataLimiteINDCOM = Utility.DataFromString(controlloDinamico.ValoreControllo, Utility.FormatoData.AAAAmmGG).GetValueOrDefault();
                    if (!(Utility.DataSuccessivaA(scadRevSan.Value, new DateTime(2009, 04, 01)) && !Utility.DataSuccessivaA(scadRevSan.Value, dataLimiteINDCOM)))
                    {
                        messaggioVideo = "La scadenza " + label + " deve essere inferiore al " + dataLimiteINDCOM.Month.ToString().PadLeft(2, '0') + "/" + dataLimiteINDCOM.Year;
                        return false;
                    }
                }

                var tipoRicINDCOMCtrl = tipoRicINDCOM == "0175" || tipoRicINDCOM == "0156" ? tipoRicINDCOM : string.Empty;

                if (Utility.IsDomandaINDCOM175(datiPensione) || Utility.IsDomandaINDCOM156(datiPensione) || (Utility.IsDomandaINDCOM129(datiPensione) && Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2011, 01, 01))) || !string.IsNullOrEmpty(tipoRicINDCOMCtrl))
                //|| (Utility.IsRicostituzione(datiPensione.Gruppo) && Utility.IsDomandaINDCOM(datiPensione.SiglaCategoria) && Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2011, 01, 01))))
                {
                    DateTime? dataCompare = null;
                    string tipo = !string.IsNullOrEmpty(tipoRicINDCOMCtrl) ? tipoRicINDCOMCtrl : datiPensione.Tipo;

                    var ctrlScadenzaIndennizzoINDCOM = listaCtrlScadenzaIndennizzoINDCOM
                        .FirstOrDefault(ctrl => ctrl.Tipologia == tipo && (!ctrl.DataNascitaDal.HasValue || Utility.DataSuccessivaA(dataNascitaTitolare.Value, ctrl.DataNascitaDal.Value)) &&
                                                (!ctrl.DataNascitaAl.HasValue || Utility.DataSuccessivaA(ctrl.DataNascitaAl.Value, dataNascitaTitolare.Value)) && (ctrl.Sesso == "ALL" || (sessoTitolare.HasValue && ctrl.Sesso == sessoTitolare.Value.ToString())));

                    if (ctrlScadenzaIndennizzoINDCOM != null)
                    {
                        dataCompare = dataNascitaTitolare;

                        if (ctrlScadenzaIndennizzoINDCOM.PrepopolaAnni.HasValue)
                            dataCompare = dataCompare.Value.AddYears(ctrlScadenzaIndennizzoINDCOM.PrepopolaAnni.Value);
                        if (ctrlScadenzaIndennizzoINDCOM.PrepopolaMesi.HasValue)
                            dataCompare = dataCompare.Value.AddMonths(ctrlScadenzaIndennizzoINDCOM.PrepopolaMesi.Value);
                        if (ctrlScadenzaIndennizzoINDCOM.PrepopolaGiorni.HasValue)
                            dataCompare = dataCompare.Value.AddDays(ctrlScadenzaIndennizzoINDCOM.PrepopolaGiorni.Value);

                        if (dataCompare == dataNascitaTitolare)
                            dataCompare = null;
                    }
                    else
                    {
                        messaggioVideo = "Non ha i requisiti per INDCOM, la domanda deve essere respinta.";
                        return false;
                    }

                    if (!dataCompare.HasValue || !Utility.DataSuccessivaA(dataCompare.Value, scadRevSan.Value))
                    {
                        var eta = ctrlScadenzaIndennizzoINDCOM != null ?
                            new Utility.DifferenzaDateTime(ctrlScadenzaIndennizzoINDCOM.ControlloAnni ?? 0, ctrlScadenzaIndennizzoINDCOM.ControlloMesi ?? 0, ctrlScadenzaIndennizzoINDCOM.ControlloGiorni ?? 0) :
                            Utility.DifferenzaBetweenDate(scadRevSan, dataNascitaTitolare, Utility.TipoAppartenenza.AGO);
                        messaggioVideo = string.Format("Il Titolare ha compiuto {0} alla scadenza indennizzo", eta.ToString());
                        return false;
                    }
                }

                if (Utility.IsDomandaINDCOM129(datiPensione) && !Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2011, 01, 01)))
                {
                    DateTime dataCompare = new DateTime();
                    string eta = string.Empty;
                    if (sessoTitolare.HasValue && sessoTitolare.Value == 'M')
                    {
                        dataCompare = new DateTime(dataNascitaTitolare.Value.AddYears(66).Year, dataNascitaTitolare.Value.AddYears(66).AddMonths(7).Month, 1);
                        eta = "66 anni e 6 mesi";
                    }
                    else if (sessoTitolare.HasValue && sessoTitolare.Value == 'F')
                    {
                        dataCompare = new DateTime(dataNascitaTitolare.Value.AddYears(61).Year, dataNascitaTitolare.Value.AddYears(61).AddMonths(7).Month, 1);
                        eta = "61 anni e 6 mesi";
                    }

                    if (Utility.DataStrettamenteSuccessivaA(scadRevSan.Value, dataCompare))
                    {
                        messaggioVideo = string.Format("Il Titolare ha compiuto {0} alla scadenza indennizzo", eta.ToString());
                        return false;
                    }
                }

                if (Utility.IsDomandaINDCOM125(datiPensione))
                {
                    DateTime dataCompare = new DateTime();
                    string eta = string.Empty;
                    if (sessoTitolare.HasValue && sessoTitolare.Value == 'M')
                    {
                        dataCompare = new DateTime(dataNascitaTitolare.Value.AddYears(65).Year, dataNascitaTitolare.Value.AddYears(65).Month, 1);
                        eta = "65 anni";
                    }
                    else if (sessoTitolare.HasValue && sessoTitolare.Value == 'F')
                    {
                        dataCompare = new DateTime(dataNascitaTitolare.Value.AddYears(60).Year, dataNascitaTitolare.Value.AddYears(60).Month, 1);
                        eta = "60 anni";
                    }

                    if (Utility.DataStrettamenteSuccessivaA(scadRevSan.Value, dataCompare))
                    {
                        messaggioVideo = string.Format("Il Titolare ha compiuto {0} alla scadenza indennizzo", eta.ToString());
                        return false;
                    }
                }
                //La Data (RAU112) deve essere almeno superiore di 1 mese alla Decorrenza
                //Originaria (RAU104)
                //ENG - Memo 39/2023
                if (!(controlloDinamicoMemo39 != null && !String.IsNullOrEmpty(controlloDinamicoMemo39.ValoreControllo)
                    && controlloDinamicoMemo39.ValoreControllo.ToUpperInvariant() == "SI" && Utility.IsRicTrfAOI_Inabilita(datiPensione, datiEliminazione)) && !Utility.DataSuccessivaA(scadRevSan.Value, decorrenzaOriginaria.AddMonths(1)))
                {
                    messaggioVideo = "La scadenza " + label + " deve essere almeno superiore di 1 mese alla decorrenza originaria";
                    return false;
                }

                //La Data Revisione Sanitaria deve essere superiore al mese in corso per domande che non sono TRF/RIC eliminate e INDCOM con scadenza revisione sanitaria successiva al 2015
                //ENG - Memo 39/2023
                if (!(decEliminazione.HasValue && Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda)) && !Utility.IsDomandaINDCOM(datiPensione.SiglaCategoria) &&
                    Utility.DataSuccessivaA(scadRevSan.Value, new DateTime(2016, 01, 01)) && !(controlloDinamicoMemo39 != null && !String.IsNullOrEmpty(controlloDinamicoMemo39.ValoreControllo)
                    && controlloDinamicoMemo39.ValoreControllo.ToUpperInvariant() == "SI" && Utility.IsRicTrfAOI_Inabilita(datiPensione, datiEliminazione)))
                {
                    if (!Utility.DataSuccessivaA(scadRevSan.Value, Utility.FirstDayOfMonth(dataSistema.AddMonths(1))))
                    {
                        messaggioVideo = "La scadenza della revisione sanitaria deve essere maggiore del mese in corso";
                        return false;
                    }
                }

                if (!Utility.IsRicostituzioneOrRiaperturaAGOAbilitata(datiPensione, isRiaperturaDomanda)
                    && !Utility.IsDomandaIOTOT(datiPensione.SiglaCategoria) && !Utility.IsDomandaIOCUM(datiPensione.SiglaCategoria)//ENG - Bypassare controllo per IOTOT/IOCUM
                    && !(Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && (datiPensione.SiglaCategoria.Trim() == "IOSPETT" || datiPensione.SiglaCategoria.Trim() == "IOSPORT")))
                {
                    //La Data (RAU112) non può essere superiore alla Decorrenza Eliminazione
                    //(RADECELIM) quando presente
                    if (decEliminazione.HasValue)
                    {
                        if (Utility.DataStrettamenteSuccessivaA(scadRevSan.Value, decEliminazione.Value))
                        {
                            messaggioVideo = "La scadenza revisione sanitaria non può essere superiore alla decorrenza eliminazione";
                            return false;
                        }
                    }
                }
            }
            return true;
        }

        public static bool ControlsAttivitaUsuranti(bool? attivitaUsuranti, string naturaPensione, GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            Utility.GetCodiciNatura(naturaPensione, out codNat1, out codNat2, out codNat3);
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);
            #endregion Recupero Dati

            //Il Codice Attività Usuranti (RAD412) può essere solo = a 1
            //Se la categoria (RACATEG) è diversa da “VO”, “VOBANC”, “VOP”, VR”,
            //“VOART”, “ VOCOM”, “VDAI” e il 1° Codice Natura è diverso da spazio, “6”,
            //“8”, “9” il Codice Attività Usuranti (RAD412) deve essere assente
            switch (siglaCategoria)
            {
                case "VO":
                case "VOBANC":
                case "VOP":
                case "VR":
                case "VOART":
                case "VOCOM":
                case "VDAI":
                    break;
                default:
                    if (codNat1 != ' ' && codNat1 != '6' && codNat1 != '8' && codNat1 != '9')
                    {
                        if (attivitaUsuranti.HasValue && attivitaUsuranti.Value)
                        {
                            messaggioVideo = "Il codice attività usuranti deve essere assente";
                            return false;
                        }
                    }
                    break;
            }

            return true;
        }

        public static bool ControlsAziendaPerEditoria(short? aziendaPerEditoria, string naturaPensione, GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            Utility.GetCodiciNatura(naturaPensione, out codNat1, out codNat2, out codNat3);
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);
            #endregion Recupero Dati

            //Il Codice Azienda per Editoria (CODICEAZIENDA) è obbligatorio se la
            //Categoria (RACATEG) è = a “VO” e il 3°Codice Natura è = a “O”
            //L'elenco del Codice Azienda per Editoria (CODICEAZIENDA) si trova nella
            //COPY CODAZIE
            if (siglaCategoria == "VO" && codNat3 == 'O' && !Utility.IsPrepensionamentoEditoriaFiltroEAA(datiPensione) && !Utility.IsPrepensionamentoEditoriaArt1c154L205_2017(datiPensione) &&
                !Utility.IsPrepensionamentoEditoriaArt1c500L160_2019(datiPensione) && (!aziendaPerEditoria.HasValue || aziendaPerEditoria.Value == 0))
            {
                messaggioVideo = "Il codice azienda per editoria è obbligatorio";
                return false;
            }

            return true;
        }

