        internal static bool ControlsBanchePerSede(short? codiceBancaEsodati, GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (!Utility.IsDomandaBancari(datiPensione.SiglaCategoria))
                return true;

            if (codiceBancaEsodati == null)
            {
                messaggioVideo = "Codice banca obbligatorio";
                return false;
            }

            List<GestioneDecodifica.DecodificaBanchePerSede> elencoBanchePerSede = null;
            GestioneDecodifica.GetDecodificaBanchePerSede(out elencoBanchePerSede);
            if (elencoBanchePerSede != null)
            {
                var bancaPerSede = elencoBanchePerSede.Find(x => x.CodiceSede == datiPensione.CodiceSede.ToString().PadLeft(4, '0') && x.Id == codiceBancaEsodati);
                if (bancaPerSede == null)
                {
                    messaggioVideo = "Codice banca incompatibile con codice sede";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsFineAssicurazioneForDatiContributivi(byte? tipoCalcolo, DateTime? FineAssicurazione, List<GestioneCalcolo.DatiCalcoloContributivo> datiCalcoloContributivo,
            List<GestioneCalcolo.DatiCalcoloRetributivo> datiCalcoloRetributivo, bool IsPensioneInabilitaPost2012, Utility.TipoUnicarpe tipoUnicarpe, bool? isPLUnicarpe, bool IsDeleteOperation)
        {
            if (!tipoCalcolo.HasValue && datiCalcoloContributivo == null && datiCalcoloRetributivo == null)
                return true;

            if (!FineAssicurazione.HasValue)
                return false;

            if (!tipoCalcolo.HasValue)
                return false;

            Utility.TipoCalcolo tipoCalcoloEnum = Utility.TipoCalcolo.NonValido;

            if (tipoCalcolo == 1)      // contrib
                tipoCalcoloEnum = Utility.TipoCalcolo.Contributivo;
            else if (tipoCalcolo == 2) // retrib
                tipoCalcoloEnum = Utility.TipoCalcolo.Retributivo;
            else if (tipoCalcolo == 21) // misto
                tipoCalcoloEnum = Utility.TipoCalcolo.Misto;

            return GestioneCrossControls.AGO_ControlsFineAssicurazioneForDatiContributivi(tipoCalcoloEnum, FineAssicurazione, datiCalcoloContributivo, datiCalcoloRetributivo, IsPensioneInabilitaPost2012, tipoUnicarpe, isPLUnicarpe, IsDeleteOperation);
        }

        public static bool ControlsAziendaPerEditoriaWithCodNatura3(string siglaCategoria, short? aziendaPerEditoria, string naturaPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            //per categorie VESO33, VESO92, VOCRED, CRED27, VOCOOP, COOP28 il codiceAzienda si vedrà sempre anche prima di salvare datiGenerici
            if (Utility.IsDomandaVESO33(siglaCategoria) || Utility.IsDomandaVESO92(siglaCategoria) || Utility.IsDomandaVOCOOP_COOP28(siglaCategoria) || Utility.IsDomandaVOCRED_CRED27(siglaCategoria) ||
                Utility.IsDomandaVESO29(siglaCategoria) || Utility.IsDomandaVOESO(siglaCategoria) || Utility.IsDomandaESOTEL(siglaCategoria) || Utility.IsDomandaESOAMB(siglaCategoria) ||
                Utility.IsDomandaESPA(siglaCategoria) || Utility.IsDomandaBancari(siglaCategoria) || Utility.IsDomandaRendita(siglaCategoria))
                return true;

            if (aziendaPerEditoria.HasValue && (string.IsNullOrEmpty(naturaPensione) || !naturaPensione.Substring(2, 1).Equals("O")))
            {
                messaggioVideo = "Salvare i 'Dati Generici' prima di procedere con il salvataggio della tab 'Istruttoria'";
                return false;
            }

            return true;
        }

