        public static bool ControlsInabilitaWithAttivitaEconomicaAndProfessioneIndividuale(GestionePensione.DatiPensione datiPensione, int? attivitaEconomica, int? professioneIndividuale, long? enteCassa, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if ((datiPensione.Gruppo.Equals("0002") && datiPensione.Prodotto.Equals("0012")) && !((Utility.IsDomandaIOCUM(datiPensione.SiglaCategoria) || Utility.IsDomandaIOTOT(datiPensione.SiglaCategoria)) && enteCassa.GetValueOrDefault() == 1))
            {
                if (Utility.IsTabPrepensionamentoVisible(datiPensione, attivitaEconomica, professioneIndividuale, null))
                {
                    string attivitaEconomicaString = string.Empty;
                    string professioneIndividualeString = string.Empty;
                    if (attivitaEconomica != null)
                        attivitaEconomicaString = attivitaEconomica.ToString().PadLeft(2, '0');
                    if (professioneIndividuale != null)
                        professioneIndividualeString = professioneIndividuale.ToString().PadLeft(3, '0');
                    messaggioVideo = "Per pensioni di inabilità non è possibile inserire attività economica e professione individuale pari a " + attivitaEconomicaString + " / " + professioneIndividualeString;
                    return false;
                }
            }

            return true;
        }

