        public static bool ControlsIndiretteInabilita(GestionePensione.DatiPensione datiPensione, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, string naturaPensione, bool? chkBenefici, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            //ENG - Integrazione Modifiche Accenture
            if (datiPensione != null && !string.IsNullOrEmpty(datiPensione.SiglaCategoria) && datiPensione.SiglaCategoria.StartsWith("S") &&
                !string.IsNullOrEmpty(naturaPensione) && (naturaPensione.StartsWith("3") || naturaPensione.StartsWith("4")) && !Utility.IsDomandaMIN(datiPensione.SiglaCategoria))
            {
                string strTipoPensione = string.Empty;
                if (Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, datiDanteCausa))
                    strTipoPensione = "di reversibilità";
                else
                    strTipoPensione = "indiretta";

                if (!chkBenefici.HasValue || !chkBenefici.Value)
                {
                    messaggioVideo = string.Format("Per una pensione {0}, con primo codice natura 3 o 4, bisogna selezionare Benefici.", strTipoPensione);
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsDatiAssicurativiPerCumulo(GestionePensione.DatiPensione datiPensione, int? nSettimaneOBG, int? nContributiVolontari, DateTime? dataNascitaTitolare, INPS.Pensioni.Liquidazione.BLCommon.GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici datiMaggiorazioniBenefici, out string messaggiovideo)
        {
            messaggiovideo = string.Empty;

            if (datiPensione.SiglaCategoria.StartsWith("V") && !(!Utility.IsRiaperturaDomanda(datiPensione.Id) &&
                (Utility.IsRicostituzione(datiPensione.Gruppo) || (datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0002" && datiPensione.Tipo == "0017")) &&
                GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.DECORR_PREC_2013_VOCUM_CONTR)))
            {
                int limitValue = 780;

                Utility.DifferenzaDateTime diff = Utility.DifferenzaBetweenDate(datiPensione.DecorrenzaOriginaria, dataNascitaTitolare, Utility.TipoAppartenenza.AGO);
                if (diff.Year >= 70)
                    limitValue = 260;

                if (datiMaggiorazioniBenefici != null && !String.IsNullOrEmpty(datiMaggiorazioniBenefici.TipoSettimaneBeneficio) && !String.IsNullOrEmpty(datiMaggiorazioniBenefici.TipoSettimaneBeneficio.Trim())
                    && datiMaggiorazioniBenefici.TipoSettimaneBeneficio == "01")
                    limitValue = 520;

                if (!(Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria) && !Utility.IsRiaperturaDomanda(datiPensione.Id) && datiPensione.IsCumuloAutomatica.GetValueOrDefault() &&
                    datiPensione.Gruppo == "0001" && datiPensione.Prodotto == "0002" && datiPensione.Tipo == "0017") && nSettimaneOBG.GetValueOrDefault() + nContributiVolontari.GetValueOrDefault() < limitValue)
                {
                    messaggiovideo = "La somma tra 'Numero Settimane' e 'Numero Contributi Volontari Diritto' non può essere inferiore a " + limitValue.ToString() + ".";
                    return false;
                }
            }

            if (datiPensione.SiglaCategoria.StartsWith("S"))
            {
                if (nSettimaneOBG.GetValueOrDefault() < 260)
                {
                    messaggiovideo = "Il 'Numero Settimane' non può essere inferiore a 260.";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsDatiAssicurativiPerVAPE(GestionePensione.DatiPensione datiPensione, GestioneAnagrafica.DatiAnagrafici datiAnagraficiTitolare,
            GestioneDatiGenericiAgoCi.PensioniDatiGenerici datiPensioniDatiGenerici, int? nSettimaneOBG, int? nContributiVolontari, out string messaggiovideo)
        {
            messaggiovideo = string.Empty;

            if (Utility.IsDomandaAPESociale(datiPensione.SiglaCategoria) && !Utility.IsRicostituzione(datiPensione.Gruppo) &&
                (datiPensione.CodiceTipoRichiesta != "YG" && datiPensione.CodiceTipoRichiesta != "YH"))
            {
                //ENG - Memo 57_2023
                GestioneControlliDinamici.ControlloDinamico controlloDinamicoAbilitazioneMemo57_2023 = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo57_2023", out controlloDinamicoAbilitazioneMemo57_2023);

                int limitValue = 1560;
                if (controlloDinamicoAbilitazioneMemo57_2023 != null && !String.IsNullOrEmpty(controlloDinamicoAbilitazioneMemo57_2023.ValoreControllo)
                  && controlloDinamicoAbilitazioneMemo57_2023.ValoreControllo.Trim().ToUpperInvariant() == "SI")
                    limitValue = 1456;

                //William 15/05/2020: è stata rimossa la condizione !Utility.IsRicostituzione(datiPensione.Gruppo) da questo if in seguito a richiesta
                //di inibire questo controllo per le RIC di ape sociale
                if (Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica &&
                    datiPensioniDatiGenerici != null && datiPensioniDatiGenerici.TipoCertificazioneFelpe == "CII")
                    limitValue = 52;
                else if (datiAnagraficiTitolare != null && datiAnagraficiTitolare.Sesso.HasValue && datiAnagraficiTitolare.Sesso.Equals('F'))
                    limitValue = 1456;


                if (nSettimaneOBG.GetValueOrDefault() + nContributiVolontari.GetValueOrDefault() < limitValue)
                {
                    messaggiovideo = string.Format("La somma tra 'Numero Settimane' e 'Numero Contributi Volontari Diritto' non può essere inferiore a {0}.", limitValue);
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsDatiAssicurativiPerAPEPrecoci(GestionePensione.DatiPensione datiPensione, DateTime? inizioAssicurazione, int? numSettimaneTipoContibutivo, int? nContributiVolontari, GestioneEnpals.DatiEnpals datiEnpals, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            int limitValue = 2132;

            if (Utility.IsDomandaAPEPrecoci(datiPensione))
            {
                if (Utility.DataStrettamenteSuccessivaA(inizioAssicurazione.Value, new DateTime(1995, 12, 31)))
                {
                    messaggioVideo = "La data di inizio assicurazione deve essere inferiore o uguale al 31/12/1995";
                    return false;
                }
                bool SuperamentoLimite = numSettimaneTipoContibutivo.GetValueOrDefault() + nContributiVolontari.GetValueOrDefault() < limitValue;
                if (!(GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.Titolare_Anagrafica_AGO.COMPARTO_SCUOLA)
                    || (!string.IsNullOrEmpty(datiPensione.NaturaPensione) && datiPensione.NaturaPensione.Substring(2, 1) == "S")) && SuperamentoLimite)
                {
                    messaggioVideo = "Il numero delle settimane deve essere maggiore o uguale a 2132";
                    return false;
                }
            }

            return true;
        }


        public static bool ControlsAttivitaEconomicaProfessioneIndividualePerCumulo(long? enteCassa, int? attivitaEconomica, int? professioneIndividuale, out string messaggioVideo,
            List<GestioneDecodifica.DecodificaEnteCassaProfessionale> listaDecodificaEnteCassaProfessionale = null)
        {
            messaggioVideo = string.Empty;

            if (listaDecodificaEnteCassaProfessionale == null)
                GestioneDecodifica.GetDecodificaEnteCassaProfessionale(out listaDecodificaEnteCassaProfessionale);

            if (enteCassa.HasValue)
            {
                GestioneDecodifica.DecodificaEnteCassaProfessionale decodificaEnteCassaProfessionale = listaDecodificaEnteCassaProfessionale.Find(x => x.Id == enteCassa.Value);
                if (decodificaEnteCassaProfessionale != null && decodificaEnteCassaProfessionale.TraduzioneSuGP == "0805")
                {
                    if (attivitaEconomica.GetValueOrDefault() != 71 || professioneIndividuale.GetValueOrDefault() != 85)
                    {
                        messaggioVideo = "Per 'Ente / Cassa' pari a '0805', attività economica e professione individuale devono essere rispettivamente uguali a '71' e '085'. Risalvare i dati Assicurativi.";
                        return false;
                    }
                }
            }

            return true;
        }

        public static bool ControlsDatiGenericiObbligatoriPerCumulo(long? enteCassa, bool? enteIstruttoreExInpdap, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!enteCassa.HasValue)
            {
                messaggioVideo = "Il campo 'Ente / Cassa' è obbligatorio.";
                return false;
            }

            if (!enteIstruttoreExInpdap.HasValue)
            {
                messaggioVideo = "Il campo 'Ente istruttore fondo ex INPDAP' è obbligatorio.";
                return false;
            }

            return true;
        }

        public static bool ControlsEnteCassaPerCumulo(GestionePensione.DatiPensione datiPensione, long? enteCassa, bool? enteIstruttoreExInpdap, bool? tipoCumulo, out string messaggioVideo)
        {
            //Per le domande IOCUM di inabilità (tipo 0012 e C1N 3 o 4) e SOCUM se “Ente istruttore fondo ex INPDAP / IPOST / FFSS” = SI allora “Ente / Cassa” = “0801 – INPS” e blindato.
            //Per le sole domande di categoria IOCUM e SOCUM se il tipo cumulo è interno allora l’ “Ente / Cassa” sarà prepopolato e blindato con 0801.

            messaggioVideo = string.Empty;
            if (Utility.IsDomandaVOCUM(datiPensione.SiglaCategoria))
                return true;

            if (enteCassa.HasValue && enteIstruttoreExInpdap.HasValue && tipoCumulo.HasValue)
            {
                if ((((Utility.IsDomandaSOCUM(datiPensione.SiglaCategoria) || Utility.IsDomandaIOCUM(datiPensione.SiglaCategoria)) && tipoCumulo.Value)
                    || ((Utility.IsDomandaSOCUM(datiPensione.SiglaCategoria) || (Utility.IsDomandaIOCUM(datiPensione.SiglaCategoria) && Utility.IsDomandaPensioneInabilita(datiPensione))) && enteIstruttoreExInpdap.Value))
                    && enteCassa != 1)
                {
                    messaggioVideo = "Il campo 'Ente / Cassa' deve essere valorizzato con '0801 – INPS' se Ente istruttore fondo è uguale a SI o se Tipo Cumulo è uguale ad interno";
                    return false;
                }

            }

            return true;
        }

        public static bool ControlsEnteCassaTOT(GestionePensione.DatiPensione datiPensione, long? enteCassa, out string messaggioVideo, List<GestioneDecodifica.DecodificaEnteCassaProfessionale> listaDecodificaEnteCassaProfessionale = null)
        {
            messaggioVideo = string.Empty;
            if (!Utility.IsDomandaTotalizzazione(datiPensione.SiglaCategoria))
                return true;

            if (enteCassa.HasValue && listaDecodificaEnteCassaProfessionale != null)
            {
                List<string> enteCassaAmmessi = new List<string>() { "0801", "0805", "0806", "0807", "0808", "0809", "0810", "0811", "0813", "0814", "0815", "0816", "0817", "0818", "0819", "0820", "0821", "0822", "0282" };
                GestioneDecodifica.DecodificaEnteCassaProfessionale decodificaEnteCassaProfessionale = listaDecodificaEnteCassaProfessionale.Find(x => x.Id == enteCassa.Value);
                if (decodificaEnteCassaProfessionale != null && !enteCassaAmmessi.Contains(decodificaEnteCassaProfessionale.TraduzioneSuGP))
                {
                    messaggioVideo = string.Format("Il campo 'Ente / Cassa' non può essere valorizzato con {0}", decodificaEnteCassaProfessionale.TraduzioneSuGP);
                    return false;
                }

            }
            return true;
        }


        public static bool ControlsDecorrenzaPensioneEnteIstruttorePerCumulo(GestionePensione.DatiPensione datiPensione, bool? enteIstruttoreExInpdap, bool isRiaperturaDomanda,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                return true;

            if (Utility.IsDomandaIOCUM(datiPensione.SiglaCategoria) && !enteIstruttoreExInpdap.GetValueOrDefault())
            {
                if (!Utility.DataStrettamenteSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, new DateTime(datiPensione.DataPresentazioneDomanda.Year, datiPensione.DataPresentazioneDomanda.Month, 1)))
                {
                    messaggioVideo = "La decorrenza originaria deve essere maggiore della data di presentazione se Ente Istruttore fondo è valorizzato con NO";
                    return false;
                }
            }
            return true;
        }

        public static bool ControlsDecorArretratiWithDecorEliminazione(DateTime? decorrenzaArretrati, DateTime? decorrenzaEliminazione, out string messaggioVideo)
        {
            bool ret = true;
            messaggioVideo = string.Empty;
            if (decorrenzaArretrati.HasValue && decorrenzaEliminazione.HasValue && decorrenzaArretrati.Value >= decorrenzaEliminazione.Value)
            {
                ret = false;
                messaggioVideo = string.Format("La decorrenza arretrati ({0}) deve essere minore della decorrenza eliminazione ({1})", decorrenzaArretrati.Value.ToString("MM/yyyy"), decorrenzaEliminazione.Value.ToString("MM/yyyy"));
            }
            return ret;
        }

        public static bool VerificaCoerenzaTipoCalcoloConTerrorismo(byte? tipoCalcolo, List<GestioneCalcoloVittimeTerrorismo.DatiCalcoloVittimeTerrorismo> listaDatiCalcoloVittimeTerrorismo,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            GestioneContrib.TipoCalcolo? tipoCalcoloEnum = tipoCalcolo.HasValue ? (GestioneContrib.TipoCalcolo)tipoCalcolo : (GestioneContrib.TipoCalcolo?)null;

            if (tipoCalcoloEnum.HasValue && tipoCalcoloEnum != GestioneContrib.TipoCalcolo.Retributivo && tipoCalcoloEnum != GestioneContrib.TipoCalcolo.Misto &&
                listaDatiCalcoloVittimeTerrorismo != null && listaDatiCalcoloVittimeTerrorismo.Exists(x => x.Tipo == 'R'))
            {
                messaggioVideo = "Tipo Calcolo " + (tipoCalcoloEnum).ToString() + " incoerente con i Dati Calcolo Vittime presenti.";
                return false;
            }

            if (tipoCalcoloEnum.HasValue && tipoCalcoloEnum != GestioneContrib.TipoCalcolo.Contributivo && tipoCalcoloEnum != GestioneContrib.TipoCalcolo.Misto &&
                listaDatiCalcoloVittimeTerrorismo != null && listaDatiCalcoloVittimeTerrorismo.Exists(x => x.Tipo == 'C' && x.Quota.HasValue && x.Quota.Value != 'D'))
            {
                messaggioVideo = "Tipo Calcolo " + ((GestioneContrib.TipoCalcolo)tipoCalcolo).ToString() + " incoerente con i Dati Calcolo Vittime presenti.";
                return false;
            }

            return true;
        }

        public static bool ControlsNaturaPensionePerIDAI(GestionePensione.DatiPensione datiPensione, List<GestioneCalcolo.DatiCalcoloRetributivo> datiCalcoloRetributivo,
            List<GestioneCalcolo.DatiCalcoloContributivo> datiCalcoloContributivo, string naturaPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';

            bool? isDatiCalcoloDAIAltraGestionePresent = GestioneLiquidazionePensione.IsDatiCalcoloDAIAltraGestionePresent(datiPensione, datiCalcoloRetributivo, datiCalcoloContributivo);
            if (isDatiCalcoloDAIAltraGestionePresent.HasValue)
            {
                Utility.GetCodiciNatura(naturaPensione, out codNat1, out codNat2, out codNat3);

                if (isDatiCalcoloDAIAltraGestionePresent.Value && codNat2 != 'E')
                {
                    messaggioVideo = "Il secondo byte dei codici natura deve essere 'E'. Salvare nuovamente i Dati Generici.";
                    return false;
                }

                if (!isDatiCalcoloDAIAltraGestionePresent.Value && codNat2 != 'B')
                {
                    messaggioVideo = "Il secondo byte dei codici natura deve essere 'B'. Salvare nuovamente i Dati Generici.";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsBancaFideiussione(GestionePensione.DatiPensione datiPensione, short? annoBancaFideiussoria, byte? progressivoBancaFideiussoria, GestioneDecodificaAzienda.DecAzienda codiceBancaEsodati,
            List<GestioneAziendeScadenzaAssegnoGGmmAAAA.DecAziendeScadenzaAssegnoGGmmAAAA> listaAziendeScadenzaAssegnoGGmmAAAA, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaVESO92(datiPensione.SiglaCategoria))
            {
                if (!annoBancaFideiussoria.HasValue)
                {
                    messaggioVideo = "L'Anno è obbligatorio.";
                    return false;
                }

                if (!progressivoBancaFideiussoria.HasValue)
                {
                    messaggioVideo = "Il Progressivo è obbligatorio.";
                    return false;
                }

                if ((Utility.IsDomandaVESO92_AGO(datiPensione) ||
                    (Utility.IsDomandaVESO92_L92(datiPensione) && codiceBancaEsodati != null && (listaAziendeScadenzaAssegnoGGmmAAAA == null || !listaAziendeScadenzaAssegnoGGmmAAAA.Exists(x => x.ProgressivoRichiesto.HasValue && codiceBancaEsodati.TraduzioneSuGP.Trim().PadLeft(4, '0') == x.TraduzioneSuGP.Trim().PadLeft(4, '0')))))
                    && progressivoBancaFideiussoria.Value == 99)
                {
                    messaggioVideo = "Non è possibile selezionare il Progressivo 99.";
                    return false;
                }
            }

            return true;
        }

        public static bool VerificaCoerenzaRiduzioneAssegno_RiduzioneRetributivaVOCRED(GestionePensione.DatiPensione datiPensione, decimal? riduzioneAssegno, bool riduzioneRetributiva, decimal? riduzioneRetributivaPercentuale,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (Utility.IsDomandaVOCRED(datiPensione.SiglaCategoria) && datiPensione.DecorrenzaOriginaria.HasValue && riduzioneAssegno.HasValue && !Utility.DataStrettamenteSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, new DateTime(2011, 07, 01)))
            {
                messaggioVideo = "La Riduzione Assegno non può essere acquisita per pensioni con decorrenza originaria precedente al 01/07/2011";
                return false;
            }

            if (Utility.IsDomandaVOCRED_CRED27(datiPensione.SiglaCategoria))
            {
                if (riduzioneAssegno.HasValue && (riduzioneRetributiva || riduzioneRetributivaPercentuale.HasValue))
                {
                    messaggioVideo = "La Riduzione Assegno è incompatibile con la Riduzione Retributiva.";
                    return false;
                }
            }

            return true;
        }

        public static bool VerificaDecorrenzaArretratiConDataAssunzioneCaricoDAI(GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, DateTime? decorrenzaArretrati, DateTime? dataAssunzioneCarico, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaINPDAI(datiPensione.SiglaCategoria) && Utility.IsRicostituzioneOrRiaperturaAGOAbilitata(datiPensione, isRiaperturaDomanda))
            {
                if (dataAssunzioneCarico.HasValue && decorrenzaArretrati.HasValue && !Utility.DataSuccessivaA(dataAssunzioneCarico.Value, new DateTime(2003, 12, 1)) &&
                    !Utility.DataSuccessivaA(decorrenzaArretrati.Value, new DateTime(2004, 1, 1)))
                {
                    messaggioVideo = "Se la data presa in carico è strettamente inferiore al 12/2003 allora la decorrenza arretrati deve essere maggiore o uguale al 01/2004.";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsCumuloEsterno(GestionePensione.DatiPensione datiPensione, char? cumuloEsterno, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (cumuloEsterno.GetValueOrDefault() == 'M' && (!Utility.IsPensioneVecchiaiaOrRicostituzione(datiPensione, null) || !Utility.IsDomandaCumulo(datiPensione.SiglaCategoria)))
            {
                messaggioVideo = "E' possibile inserire il Cumulo Esterno Incompleto solo per una domanda di vecchiaia.";
