            }

            return true;
        }

        public static bool ControlsCoerenzaResidenteEstero(GestionePensione.DatiPensione datiPensione, GestioneAnagrafica.DatiAnagrafici datiAnagrafici, byte? CodiceComunicazioneCampo4,
            GestioneDetrazioniImposta.DatiDetrazioni detrazioniImpostaStorico, bool isRiapertura, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiapertura) &&
                !GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.LiquidazionePensione_Generici_AGO.RES_EST_SUP_180_GIORNI))
            {
                if (detrazioniImpostaStorico != null &&
                    !Utility.IsResidenteEstero(datiAnagrafici.CodiceComuneResidenza) && CodiceComunicazioneCampo4 == 2 && detrazioniImpostaStorico.DetrazioniReddito == 2)
                {
                    messaggioVideo = "Non è possibile selezionare “ESENZIONE FISCALE RESIDENTE ALL’ESTERO” per titolare residente in Italia.";
                    return false;
                }
            }

            return true;
