        public static bool ControlsEsenzioneResidenzaEstera(GestionePensione.DatiPensione datiPensione, byte? codiceComunicazioCampo4, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaVESO29(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCRED(datiPensione.SiglaCategoria) || Utility.IsDomandaVOCOOP(datiPensione.SiglaCategoria) ||
                Utility.IsDomandaVOESO(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO33(datiPensione.SiglaCategoria) || Utility.IsDomandaVESO92(datiPensione.SiglaCategoria) ||
                Utility.IsDomandaCRED27(datiPensione.SiglaCategoria) || Utility.IsDomandaCOOP28(datiPensione.SiglaCategoria) || Utility.IsDomandaESOTEL(datiPensione.SiglaCategoria) ||
                Utility.IsDomandaESOAMB(datiPensione.SiglaCategoria) || Utility.IsDomandaESPA(datiPensione.SiglaCategoria))
            {
                if (codiceComunicazioCampo4 == 2)
