        public static bool ControlsRicostituzionePerEsecuzioneSentenza(GestionePensione.DatiPensione datiPensione, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, List<GestioneSentenzaArt4.DatiSentenzaArt4> lSentenzaArt4, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            DateTime? decorrenza = Utility.GetDecorrenzaPensioneOrDecorrenzaDantecausa(datiPensione.DecorrenzaOriginaria, datiDanteCausa != null ? datiDanteCausa.DecorrenzaPensione : null);

            if (lSentenzaArt4 != null)
            {
                foreach (GestioneSentenzaArt4.DatiSentenzaArt4 datoSentenzaArt4 in lSentenzaArt4)
                {
                    if (!Utility.DataSuccessivaA(datoSentenzaArt4.DecorrenzaSentenza.Value, decorrenza.Value))
                    {
                        messaggioVideo = "La 'Decorrenza Sentenza' deve essere successiva o uguale della 'Decorrenza Pensione'.";
                        return false;
                    }

                    if (!Utility.DataSuccessivaA(datoSentenzaArt4.DecorrenzaSentenza.Value, new DateTime(1995, 10, 1)))
                    {
                        messaggioVideo = "La 'Decorrenza Sentenza' deve essere successiva o uguale al 10/1995.";
                        return false;
                    }
                }

                if (lSentenzaArt4.GroupBy(x => x.DecorrenzaSentenza).Select(x => x.First()).Count() != lSentenzaArt4.Count)
                {
                    messaggioVideo = "Ogni riga dovrà avere una 'Decorrenza Sentenza' univoca.";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsNSettimanePerRequisitoAnticipatoArt1(GestionePensione.DatiPensione datiPensione, short? aaDirittoEnpals, short? mmDirittoEnpals, int? nSettimaneOBG, int? nContributiVolontari, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaVecchiaiaRequisitoAnticipatoArt1(datiPensione) ||
                Utility.IsDomandaVecchiaiaRequisitoAnticipatoArt1OpzioneContributivo(datiPensione))
            {
                if ((Utility.IsDomandaENPALS(datiPensione.Gestione) && Utility.IsRicostituzione(datiPensione.Gruppo) && !Utility.IsRicostituzione_MotiviContributivi(datiPensione)) ||
                    Utility.IsDomandaVOTOT(datiPensione.SiglaCategoria))
                    return true;

                int nLimiteSettimane = 1560;
                int nSettimane = GestioneCrossControls.AGO_GetNumeroSettimane(datiPensione, aaDirittoEnpals, mmDirittoEnpals, nSettimaneOBG, nContributiVolontari);

                if (nSettimane < nLimiteSettimane)
                {
                    messaggioVideo = string.Format("Il numero delle settimane deve essere maggiore o uguale a {0}", nLimiteSettimane);
                    return false;
                }
            }
            return true;
        }

        public static bool ControlsNSettimanePerQuota100(GestionePensione.DatiPensione datiPensione, short? aaDirittoEnpals, short? mmDirittoEnpals, int? nSettimaneOBG, int? nContributiVolontari,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaQuota100(datiPensione))
            {
                // Per cumulo comparto scuola non devono essere applicati i controlli sul requisito contributivo
                if ((Utility.IsDomandaCumulo(datiPensione.SiglaCategoria) && (!string.IsNullOrEmpty(datiPensione.NaturaPensione) && datiPensione.NaturaPensione.Substring(2, 1) == "S")) ||
                    Utility.IsDomandaVOTOT(datiPensione.SiglaCategoria) ||
                    (Utility.IsRicostituzione(datiPensione.Gruppo) && !string.IsNullOrEmpty(datiPensione.SiglaCategoria) && new List<string> { "VOSPETT", "VOSPORT", "DIR" }.Contains(datiPensione.SiglaCategoria.Trim())))
                    return true;

                int nSettimane = GestioneCrossControls.AGO_GetNumeroSettimane(datiPensione, aaDirittoEnpals, mmDirittoEnpals, nSettimaneOBG, nContributiVolontari);
                if (nSettimane < 1976)
                {
                    messaggioVideo = "Il numero settimane non può essere inferiore a 1976 (38 anni di contribuzione)";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsNSettimanePerSperimentaleDonna_DL_4_2019(GestionePensione.DatiPensione datiPensione, short? aaDirittoEnpals, short? mmDirittoEnpals, int? nSettimaneOBG, int? nContributiVolontari,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaSperimentaleDonna_DL_4_2019OrRicostituzione(datiPensione))
            {
                if ((Utility.IsDomandaENPALS(datiPensione.Gestione) && Utility.IsRicostituzione(datiPensione.Gruppo) && !Utility.IsRicostituzione_MotiviContributivi(datiPensione))
                    || Utility.IsDomandaVOTOT(datiPensione.SiglaCategoria))
                    return true;

                int nSettimane = GestioneCrossControls.AGO_GetNumeroSettimane(datiPensione, aaDirittoEnpals, mmDirittoEnpals, nSettimaneOBG, nContributiVolontari);
                if (nSettimane < 1820)
                {
                    messaggioVideo = "Il numero settimane non può essere inferiore a 1820 (35 anni di contribuzione)";
                    return false;
                }
            }

            return true;
        }

