        public static bool ControlsNSettimanePerAnzianitaPerLeggeBilancio2019(GestionePensione.DatiPensione datiPensione, short? aaDirittoEnpals, short? mmDirittoEnpals, int? nSettimaneOBG,
            int? nContributiVolontari, char? sessoTitolare, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.DatiCalcolo_DatiCalcolo_AGO.NUM_SET_ANTICIPATA_2019))
            {
                if (Utility.IsDomandaAnzianitaPerLeggeBilancio2019OrRicostituzione(datiPensione))
                {
                    // Per cumulo comparto scuola non devono essere applicati i controlli sul requisito contributivo
                    if ((Utility.IsDomandaCumulo(datiPensione.SiglaCategoria) && (!string.IsNullOrEmpty(datiPensione.NaturaPensione) && datiPensione.NaturaPensione.Substring(2, 1) == "S"))
                         || (Utility.IsDomandaENPALS(datiPensione.Gestione) && ((Utility.IsRicostituzione(datiPensione.Gruppo) && !Utility.IsRicostituzione_MotiviContributivi(datiPensione))
                         || Utility.IsRicostituzioneContributivaPerEsecuzioneSentenza(datiPensione))) || Utility.IsDomandaMIN(datiPensione.SiglaCategoria) ||
                         Utility.IsDomandaVOTOT(datiPensione.SiglaCategoria))
                        return true;

                    int nSettimane = GestioneCrossControls.AGO_GetNumeroSettimane(datiPensione, aaDirittoEnpals, mmDirittoEnpals, nSettimaneOBG, nContributiVolontari);
                    switch (sessoTitolare)
                    {
                        case 'M':
                            if (nSettimane < 2227)
                            {
                                messaggioVideo = "Il numero settimane non può essere inferiore a 2227 (42 anni e 10 mesi di contribuzione)";
                                return false;
                            }
                            break;
                        case 'F':
                            if (nSettimane < 2175)
                            {
                                messaggioVideo = "Il numero settimane non può essere inferiore a 2175 (41 anni e 10 mesi di contribuzione)";
                                return false;
                            }
                            break;
                        default:
                            messaggioVideo = "Sesso del titolare non presente nell'anagrafica";
                            return false;
                    }
                }
            }

            return true;
        }

