        #region MaggiorazioniBenefici
        public static bool ControlsSettimaneIncremento(int? settimaneIncremento1Percento, int? settimaneIncremento05Percento,
            GestionePensione.DatiPensione datiPensione, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime? decorrenza = DateTime.MinValue;
            string certificato = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            Utility.GetCodiciNatura(datiPensione.NaturaPensione, out codNat1, out codNat2, out codNat3);
            decorrenza = Utility.GetDecorrenzaPensioneOrDecorrenzaDantecausa(datiPensione.DecorrenzaOriginaria, datiDanteCausa != null ? datiDanteCausa.DecorrenzaPensione : null);
            #endregion Recupero Dati

            if (settimaneIncremento1Percento.HasValue && settimaneIncremento1Percento.Value > 0)
            {
                //Le Settimane incremento 1% (RAD413) può essere acquisito se la Categoria
                //(RACATEG) è = a “VO”, “VOBANC”, “VOP”, “VDAI” e il 1° Codice Natura
                //(RAU1031) è = a spazio, “6”, “8”, “9” e la Decorrenza Originaria (RAU104) è
                //successiva al 1993
                switch (siglaCategoria)
                {
                    case "VO":
                    case "VOBANC":
                    case "VOP":
                    case "VDAI":
                        if ((codNat1 == ' ' || codNat1 == '6' || codNat1 == '8' || codNat1 == '9') &&
                        Utility.DataStrettamenteSuccessivaA(decorrenza.Value, new DateTime(1993, 12, 31)))
                            break;
                        else
                        {
                            messaggioVideo = "Le settimane incremento 1% non possono essere acquisite";
                            return false;
                        }
                    case "SO":
                    case "SOBANC":
                    case "SOP":
                    case "SDAI":
                        if (Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, datiDanteCausa) && (codNat1 == ' ' || codNat1 == '6' || codNat1 == '8' || codNat1 == '9') &&
                        Utility.DataStrettamenteSuccessivaA(decorrenza.Value, new DateTime(1993, 12, 31)))
                            break;
                        else
                        {
                            messaggioVideo = "Le settimane incremento 1% non possono essere acquisite";
                            return false;
                        }
                    default:
                        messaggioVideo = "Le settimane incremento 1% non possono essere acquisite";
                        return false;
                }
                //Le Settimane incremento 1% (RAD413) deve essere 52 o un multiplo di 52
                if (settimaneIncremento1Percento.Value < 52)
                {
                    messaggioVideo = "Le settimane incremento 1% devono essere minimo 52";
                    return false;
                }

                if (settimaneIncremento1Percento.Value % 52 != 0)
                {
                    messaggioVideo = "Le settimane incremento 1% devono essere multiplo di 52";
                    return false;
                }

                //Il numero Settimane incremento 1% (RAD413) non deve essere maggiore
                //del numero settimane compreso tra gennaio 1999 e la Decorrenza Originaria
                //(RAU104)
                TimeSpan ts = decorrenza.Value - new DateTime(1999, 1, 1);
                int settMax = ts.Days / 7;
                if (settimaneIncremento1Percento.Value > settMax)
                {
                    if (!Utility.IsRicostituzione(datiPensione.Gruppo))
                    {
                        messaggioVideo = "Le settimane incremento 1% non devono essere maggiori del numero settimane compreso tra gennaio 1999 e la decorrenza originaria";
                        return false;
                    }
                }
            }

            if (settimaneIncremento05Percento.HasValue && settimaneIncremento05Percento.Value > 0)
            {
                //Le Settimane incremento 0,5 (RAD414) può essere acquisito se la Categoria
                //(RACATEG) è = a “VO”, “VOBANC”, “VOP”, “VDAI” e il Sesso (RASES) è = a
                //“M” e la Decorrenza Originaria (RAU104) è successiva al 1993
                switch (siglaCategoria)
                {
                    case "VO":
                    case "VOBANC":
                    case "VOP":
                    case "VDAI":
                        GestioneAnagrafica.DatiAnagrafici datiAnagrafici = null;
                        GestioneAnagrafica.GetAnagraficaByIdPensione(datiPensione.Id, out datiAnagrafici);
                        if ((datiAnagrafici.Sesso.HasValue && datiAnagrafici.Sesso.Value == 'M' &&
                            Utility.DataStrettamenteSuccessivaA(decorrenza.Value, new DateTime(1993, 12, 31))) ||
                            Utility.IsRicostituzione(datiPensione.Gruppo))
                            break;
                        else
                        {
                            messaggioVideo = "Le settimane incremento 0,5% non possono essere acquisite";
                            return false;
                        }
                    case "SO":
                    case "SOBANC":
                    case "SOP":
                    case "SDAI":
                        datiAnagrafici = null;
                        GestioneDanteCausa.GetAnagraficaDanteCausabyIdPensione(datiPensione.Id, out datiAnagrafici);
                        if (Utility.IsDomandaReversibilitaOrRicostituzione(datiPensione, datiDanteCausa) && datiAnagrafici.Sesso.HasValue && datiAnagrafici.Sesso.Value == 'M' &&
                            Utility.DataStrettamenteSuccessivaA(decorrenza.Value, new DateTime(1993, 12, 31)))
                            break;
                        else
                        {
                            messaggioVideo = "Le settimane incremento 0,5% non possono essere acquisite";
                            return false;
                        }
                    default:
                        messaggioVideo = "Le settimane incremento 0,5% non possono essere acquisite";
                        return false;
                }

                //Le Settimane incremento 0,5% (RAD414) deve essere 52 o un multiplo di 52
                if (settimaneIncremento05Percento.Value < 52)
                {
                    messaggioVideo = "Le settimane incremento 0,5% devono essere minimo 52";
                    return false;
                }

                if (settimaneIncremento05Percento.Value % 52 != 0)
                {
                    messaggioVideo = "Le settimane incremento 0,5% devono essere multiplo di 52";
                    return false;
                }

                //La somma delle Settimane incremento 1% (RAD413) e il numero Settimane
                //incremento 0,5% (RAD414) non deve essere maggiore del numero settimane
                //compreso tra gennaio 1999 e la Decorrenza Originaria (RAU104)
                TimeSpan ts = decorrenza.Value - new DateTime(1999, 1, 1);
                int settMax = ts.Days / 7;
                if (!Utility.IsRicostituzione(datiPensione.Gruppo) && settimaneIncremento05Percento.Value + (settimaneIncremento1Percento.HasValue ? settimaneIncremento1Percento.Value : 0) > settMax)
                {
                    messaggioVideo = "La somma delle settimane incremento 1% e le settimane incremento 0,5% " +
                        "non deve essere maggiore del numero settimane compreso tra gennaio 1999 e la decorrenza originaria";
                    return false;
                }
            }
            return true;
        }

        public static bool ControlsSentenze(byte? sentenze, GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            Utility.GetCodiciNatura(datiPensione.NaturaPensione, out codNat1, out codNat2, out codNat3);
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);
            #endregion Recupero Dati

            if (sentenze.HasValue && sentenze.Value > 0)
            {
                //Se il 1° carattere della Categoria (RACATEG) è = a “S” o la Categoria
                //(RACATEG) è = a “PMO” con il 3° carattere del Certificato = a 3 o 6 il Campo
                //Sentenze (RAUSENT) non deve essere acquisito
                if (siglaCategoria.StartsWith("S") || (siglaCategoria == "PMO" &&
                (certificato.Substring(2, 1) == "3" || certificato.Substring(2, 1) == "6")))
                {
                    messaggioVideo = "Il campo sentenze non deve essere acquisito";
                    return false;
                }

                //Se il 1° Codice Natura (RAU1031) è diverso da “2”, “4”, “6”, “9” il Campo
                //Sentenze (RAUSENT) può essere acquisito
                //Se il 1° Codice Natura (RAU1031) è = a “2”, “4”, “6”, “9” e la Decorrenza
                //Originaria (RAU104) è precedente a ottobre 1982 il Campo Sentenze
                //(RAUSENT) può essere acquisito
                if (codNat1 == '2' || codNat1 == '4' || codNat1 == '6' || codNat1 == '9')
                {
                    if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(1982, 10, 1)))
                    {
                        messaggioVideo = "Il campo sentenze non può essere acquisito";
                        return false;
                    }
                }

                //Il Campo Sentenze (RAUSENT) può contenere 2, 3, 4
                if (sentenze.Value != 2 && sentenze.Value != 3 && sentenze.Value != 4)
                {
                    messaggioVideo = "Il campo sentenze può contenere 2, 3, 4";
                    return false;
                }
            }
            return true;
        }

        public static bool ControlsBeneficio(string tipoBeneficio, int? nSettimaneBeneficio, char? codiceLiquidazione, byte? provenienzaDA,
            DateTime? decorrenzaPensioneDA, int? nSettimaneOBG, int? nContributiVolontari, GestionePensione.DatiPensione datiPensione, char? sessoTitolare, DateTime? dataNascitaTitolare,
            GestioneEnpals.DatiEnpals datiEnpals, bool isRiaperturaDomanda, short? settAnzContr311295, DateTime? dataAssunzioneCarico, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';
            int pdirsup = 0;
            int plavaut = 0;

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            Utility.GetCodiciNatura(datiPensione.NaturaPensione, out codNat1, out codNat2, out codNat3);
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);
            GetPdirusp_Plavaut(datiPensione, out pdirsup, out plavaut);
            #endregion Recupero Dati

            if (!string.IsNullOrEmpty(tipoBeneficio))
            {
                if (!ControlsBeneficioWithAttEconomicaProfessioneInd(datiPensione, datiPensione.AttivitaEconomica, datiPensione.ProfessioneIndividuale, tipoBeneficio, isRiaperturaDomanda,
                    out messaggioVideo))
                    return false;

                bool ammesso = false;
                switch (tipoBeneficio)
                {
                    //Il Codice 1:
                    case "01":
                        //se si tratta di un Superstite (PDIRSUP = a 1) con Codice Provenienza
                        //(DAU107) = a 1 o 2 e Data Decorrenza della Diretta (DAU106)
                        //successivo ad aprile 1991
                        //se si tratta di una Diretta (PDIRSUP = a 0) e la Decorrenza Originaria
                        //(RAU104) successivo ad aprile 1991)
                        if ((pdirsup == 1 && provenienzaDA.HasValue &&
                            (provenienzaDA.Value == 1 || provenienzaDA.Value == 2) &&
                            decorrenzaPensioneDA.HasValue && Utility.DataStrettamenteSuccessivaA(decorrenzaPensioneDA.Value, new DateTime(1991, 4, 30))) ||
                            (pdirsup == 0 && Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(1991, 4, 30))))
                            ammesso = true;
                        //per tutte le Categorie escluso le seguenti: VOBIS, IOBIS, VMP, IMP,
                        //INDCOM, PMO
                        else
                        {
                            switch (siglaCategoria)
                            {
                                case "VOBIS":
                                case "IOBIS":
                                case "VMP":
                                case "IMP":
                                case "INDCOM":
                                case "PMO":
                                    break;
                                default:
                                    ammesso = true;
                                    break;
                            }
                        }
                        break;
                    //Il Codice 2:
                    case "02":
                        //tutte con il 3° Codice Natura (RAU1033) = a “K”, “P”, “Q”, “W”, “X”, “Y”,
                        //“L”, “O”
                        switch (codNat3)
                        {
                            case 'K':
                            case 'P':
                            case 'Q':
                            case 'W':
                            case 'X':
                            case 'Y':
                            case 'L':
                            case 'O':
                                ammesso = true;
                                break;
                            default:
                                break;
                        }

                        //per la Categoria (RACATEG) = a “SDAI” e il 3° Codice Natura
                        //(RAU1033) = a “T”
                        if (siglaCategoria == "SDAI" && codNat3 == 'T')
                            ammesso = true;
                        //per tutte le Categorie escluso le seguenti: "VOSPED", "SOSPED",
                        //"VOCRED", "VOCOOP", "VOESO ", "VOBIS ", "VOBANC", "SOBANC",
                        //"VMP ", "INDCOM", "VOAUT ", "SOAUT ", "PMO "
                        else
                        {
                            switch (siglaCategoria)
                            {
                                case "VOSPED":
                                case "SOSPED":
                                case "VOCRED":
                                case "CRED27":
                                case "VOCOOP":
                                case "VOESO":
                                case "VOBIS":
                                case "VOBANC":
                                case "SOBANC":
                                case "VMP":
                                case "INDCOM":
                                case "VOAUT":
                                case "SOAUT":
                                case "PMO":
                                case "COOP28":
                                case "VOTOT":
                                case "IOTOT":
                                case "SOTOT":
                                    break;
                                default:
                                    ammesso = true;
                                    break;
                            }
                        }
                        break;
                    //Il Codice 3:
                    case "03":
                        //tutte con il 3° Codice Natura (RAU1033) = a “Z”
                        //per la Categoria (RACATEG) = a “SDAI” e il 3° Codice Natura
                        //(RAU1033) = a “T”
                        if ((codNat3 == 'Z') || (siglaCategoria == "SDAI" && codNat3 == 'T'))
                            ammesso = true;
                        //per tutte le Categorie escluso le seguenti: "VOCRED", "VOCOOP",
                        //"VOESO ", "VOBIS ", "VMP ", "INDCOM", "VOAUT ", "PMO "
                        else
                        {
                            switch (siglaCategoria)
                            {
                                case "VOCRED":
                                case "CRED27":
                                case "VOCOOP":
                                case "VOESO":
                                case "VOBIS":
                                case "VMP":
                                case "INDCOM":
                                case "VOAUT":
                                case "PMO":
                                case "COOP28":
                                case "VOTOT":
                                case "IOTOT":
                                case "SOTOT":
                                    break;
                                default:
                                    ammesso = true;
                                    break;
                            }
                        }
                        break;
                    //Il Codice 4: (obbligatorio)
                    case "04":
                        //con la presenza e l'abbinamento dei seguenti codici:
                        //Attività Economiche (RAU1013) Professione Individuale (RAU1014)
                        //92 257
                        //03 326
                        //03 350
                        //07 247
                        //02 247
                        //14 190
                        if (datiPensione.AttivitaEconomica.HasValue && datiPensione.ProfessioneIndividuale.HasValue)
                        {
                            if ((datiPensione.AttivitaEconomica.Value == 92 && datiPensione.ProfessioneIndividuale.Value == 257) ||
                                (datiPensione.AttivitaEconomica.Value == 3 && datiPensione.ProfessioneIndividuale.Value == 326) ||
                                (datiPensione.AttivitaEconomica.Value == 3 && datiPensione.ProfessioneIndividuale.Value == 350) ||
                                (datiPensione.AttivitaEconomica.Value == 7 && datiPensione.ProfessioneIndividuale.Value == 247) ||
                                (datiPensione.AttivitaEconomica.Value == 2 && datiPensione.ProfessioneIndividuale.Value == 247) ||
                                (datiPensione.AttivitaEconomica.Value == 14 && datiPensione.ProfessioneIndividuale.Value == 190) ||
                                (datiPensione.AttivitaEconomica.Value == 15 && datiPensione.ProfessioneIndividuale.Value == 208) ||
                                (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && (datiPensione.AttivitaEconomica.Value == 98 && datiPensione.ProfessioneIndividuale.Value == 176)))
                                ammesso = true;
                        }
                        break;
                    //Il Codice 5:
                    case "05":
                        //per la Categoria (RACATEG) = a “VOCOOP”, VOCRED”, VOESO
                        switch (siglaCategoria)
                        {
                            case "VOCOOP":
                            case "VOCRED":
                            case "CRED27":
                            case "VOESO":
                            case "VESO33":
                            case "VESO92":
                            case "COOP28":
                            case "VESO29":
                            case "ESOTEL":
                            case "ESOAMB":
                            case "ESPA":
                                ammesso = true;
                                break;
                            default:
                                break;
                        }
                        break;
                    //Il Codice 6:
                    case "06":
                        //per la Categoria (RACATEG) = a “SDAI”
                        //per le Categorie di Invalidità (primo carattere di RACATEG = a “I”) con
                        //il 1° Codice Natura = a “3” o “4” e la Decorrenza Originaria (RAU104)
                        //superiore a luglio 1984
                        //per le Categorie di Reversibilità (primo carattere di RACATEG = a “S”)
                        //con il 1° Codice Natura = a “3” o “4” e la Decorrenza Originaria
                        //(RAU104) superiore a luglio 1984
                        if ((siglaCategoria == "SDAI") || ((Utility.IsDomandaPensioneInabilita(datiPensione) || (siglaCategoria.StartsWith("I") && (codNat1 == '3' || codNat1 == '4'))) &&
                            Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(1984, 7, 31))) ||
                            (siglaCategoria.StartsWith("S") && (codNat1 == '3' || codNat1 == '4') &&
                            Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(1984, 7, 31))) ||
                            siglaCategoria == "IMP")
                            ammesso = true;
                        break;
                    //Il Codice 7:
                    case "07":
                        //tutte con il 3° Codice Natura (RAU1033) = a “D”
                        if (codNat3 == 'D')
                            ammesso = true;
                        break;
                    //Il Codice 8:
                    case "08":
                        //per la Categoria (RACATEG) = a “SDAI” e il Codice Provenienza
                        //(DAU107) = a “1” o “2”
                        //tutte con il 3° Codice Natura (RAU1033) = a “G” e la Decorrenza
                        //Originaria (RAU104) superiore a gennaio 2002
                        if ((siglaCategoria == "SDAI" && provenienzaDA.HasValue &&
                            (provenienzaDA.Value == 1 || provenienzaDA.Value == 2)) || (codNat3 == 'G' && Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2002, 1, 31))))
                            ammesso = true;
                        if (codNat3 == 'G' && !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2002, 1, 31)))
                            messaggioVideo = "La data decorrenza pensione deve essere successiva al 31/01/2002";
                        if (Utility.IsDomandaTotalizzazione(datiPensione.SiglaCategoria) && codNat3 != 'G')
                            messaggioVideo = "Il 'Tipo beneficio' non è corretto, terzo byte codice natura non ammesso per codice beneficio 08";
                        break;
                    //Il Codice 9: (obbligatorio)
                    case "09":
                        //con l'Attività Economiche (RAU1013) = a “04” e la Professione
                        //Individuale (RAU1014) 0 a “350”
                        if (datiPensione.AttivitaEconomica.HasValue && datiPensione.ProfessioneIndividuale.HasValue)
                        {
                            if (datiPensione.AttivitaEconomica.Value == 4 && datiPensione.ProfessioneIndividuale.Value == 350)
                                ammesso = true;
                        }
                        break;
                    case "10":
                        // Il controllo viene effettuato successivamente tramite il metodo AGO_ControlsTipoBeneficioArt24Comma15Bis
                        //Tranne per le categorie TOT/MIN per le quali non è ammesso
                        switch (siglaCategoria)
                        {
                            case "VOTOT":
                            case "IOTOT":
                            case "SOTOT":
                            case "VOMIN":
                            case "SOMIN":
                                ammesso = false;
                                break;
                            default:
                                ammesso = true;
                                break;
                        }
                        break;
                    //Il Codice 11:
                    case "11":
                        //APE Precoci
                        if (Utility.IsDomandaAPEPrecoci(datiPensione))
                            ammesso = true;
                        break;
                    case "13":
                        if (Utility.IsRicostituzione(datiPensione.Gruppo) || Utility.IsDomandaInabilitaAmianto(datiPensione))
                            ammesso = true;
                        break;
                    case "14":
                        //quota 100
                        if (Utility.IsDomandaQuota100(datiPensione))
                            ammesso = true;
                        break;
                    case "12":
                        if (Utility.IsGestioneLavoratriciMadri(datiPensione) &&
                            datiPensione.SceltaLavMadri.GetValueOrDefault() == 1)
                            ammesso = true;
                        break;
                    case "15":
                        if (Utility.IsGestioneLavoratriciMadri(datiPensione) &&
                            datiPensione.SceltaLavMadri.GetValueOrDefault() == 2)
                            ammesso = true;
                        break;
                    case "16":
                    case "17":
                        if (Utility.IsDomandaVecchiaiaENAV(datiPensione) || Utility.IsRiaperturaRicTRF_Benefici16_17(datiPensione, tipoBeneficio)) //ctrlAbilitazioneRIC_TRFMemo16_2020)
                            ammesso = true;
                        break;
                    case "18":
                        //quota 102
                        if (Utility.IsDomandaQuota102(datiPensione))
                            ammesso = true;
                        break;
                    case "19":
                        //anticipata flessibile
                        if (Utility.IsDomandaAnticipataFlessibile(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione))
                            ammesso = true;
                        break;
                    case "24":
                        //anticipata flessibile
                        if (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione) ||
                            Utility.IsDomandaVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE(datiPensione))
                            ammesso = true;
                        break;
                    default:
                        break;
                }

                //Al momento per i ripristini saltiamo i controlli di congruenza
                if (!ammesso && !Utility.IsDomandaRipristino(datiPensione).GetValueOrDefault() && !(Utility.IsDomandaVOAUT(datiPensione.SiglaCategoria) && datiPensione.IdTipoPLPerRIC.HasValue && datiPensione.IdTipoPLPerRIC.Value == 21 &&
                    dataAssunzioneCarico.HasValue && !Utility.DataStrettamenteSuccessivaA(dataAssunzioneCarico.Value, new DateTime(2024, 04, 01))))
                {
                    if (messaggioVideo == string.Empty) //messaggio personalizzato nel case
                        messaggioVideo = "Il 'Tipo beneficio' non è corretto";
                    return false;
                }

                if (!GestioneCrossControls.AGO_ControlsTipoBeneficioArt24Comma15Bis(datiPensione, tipoBeneficio, sessoTitolare, dataNascitaTitolare, datiEnpals != null ? datiEnpals.AADiritto : null,
                    datiEnpals != null ? datiEnpals.MMDiritto : null, nSettimaneOBG, nContributiVolontari, datiPensione.DecorrenzaOriginaria, datiPensione.NaturaPensione, out messaggioVideo))
                    return false;


                if (!string.IsNullOrEmpty(tipoBeneficio) && tipoBeneficio != "10" && tipoBeneficio != "11" && tipoBeneficio != "13" && tipoBeneficio != "14" && tipoBeneficio != "18" && tipoBeneficio != "12" && tipoBeneficio != "15" && tipoBeneficio != "19" && tipoBeneficio != "24" &&
                    !Utility.IsDomandaUsuranti(datiPensione) && !nSettimaneBeneficio.HasValue && !Utility.IsPrepensionamentoEditoriaArt1c500L160_2019(datiPensione) && !(Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && Utility.IsDomandaVESO92(datiPensione.SiglaCategoria)) &&
                    !(tipoBeneficio == "03" && Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && Utility.IsDomandaUnicarpe(datiPensione, false) == Utility.TipoUnicarpe.Yes) &&
                    !Utility.IsDomandaIMP(datiPensione) && !Utility.IsPrepensionamentoEditoriaFiltroEAA(datiPensione) && !Utility.IsPrepensionamentoEditoriaFiltroEBA(datiPensione) && !Utility.IsPensioneInabilitaProficuoLavoroCumulo(datiPensione) &&
                    !Utility.IsRiaperturaRicTRF_Benefici16_17(datiPensione, tipoBeneficio))
                {
                    messaggioVideo = "Numero settimane beneficio: dato obbligatorio";
                    return false;
                }
            }
            else
            {
                //quando il Codice non è inserito effettuare i seguenti controlli:
                //per le Categorie di Invalidità (primo carattere di RACATEG = a “I”) con
                //il 1° Codice Natura = a “3” o “4” e la Decorrenza Originaria (RAU104)
                //superiore a luglio 1984 e il Codice Liquidazione (RAUE23) diverso da
                //“P” è obbligatorio il Codice Benefici Particolari (COD-BEN-PAR) = a 6
                if (siglaCategoria.StartsWith("I") && (codNat1 == '3' || codNat1 == '4') &&
                            Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(1984, 7, 31)) &&
                    (!codiceLiquidazione.HasValue || codiceLiquidazione.Value != 'P'))
                {
                    messaggioVideo = "E' obbligatorio inserire il codice beneficio particolare pari a 6";
                    return false;
                }
            }
            if (nSettimaneBeneficio.HasValue && nSettimaneBeneficio.Value > 0)
            {
                //modificato e spostato più in alto
                //Le Settimane benefici Particolari (SET-BEN-PAR) devono essere presenti se
                //esiste il Codice Benefici particolari (COD-BEN-PAR) eccetto quando Codice
                //Benefici particolari (COD-BEN-PAR) è = a 6
                //if (string.IsNullOrEmpty(tipoBenefico) || tipoBenefico == "06")
                //{
                //    messaggioVideo = "Le settimane benefici particolari devono essere presenti se esiste il codice benefici particolari " +
                //         " eccetto quando è pari a 6";
                //    return false;
                //}

                if (nSettimaneBeneficio.Value > 2079)
                {
                    messaggioVideo = "Le settimane benefici particolari non possono essere superiori a 2079";
                    return false;
                }

                if (!string.IsNullOrEmpty(tipoBeneficio) && tipoBeneficio == "08")
                {
                    //Se il Codice Benefici particolari (COD-BEN-PAR) è = a 8 e il Codice
                    //Liquidazione (RAUE23) è vuoto le Settimane benefici Particolari (SET-BENPAR)
                    //deve essere inferiore al Numero Settimane Utili Diritto (RAU113A)
                    if (!codiceLiquidazione.HasValue || codiceLiquidazione.Value == ' ')
                    {
                        if (nSettimaneBeneficio.Value >= (nSettimaneOBG.HasValue ? nSettimaneOBG.Value : 0))
                        {
                            messaggioVideo = "Le settimane benefici particolari devono essere inferiori al numero settimane utili diritto";
                            return false;
                        }
                    }

                    //Se il Codice Benefici particolari (COD-BEN-PAR) è = a 8 le Settimane
                    //benefici Particolari (SET-BEN-PAR) non può eccedere 260 ad eccezione per
                    //la Categoria (RACATEG) = a “SDAI” con il Campo DAU107 = a “1”, “2”
                    if (!(siglaCategoria == "SDAI" && provenienzaDA.HasValue && (provenienzaDA.Value == 1 || provenienzaDA.Value == 2))
                        && nSettimaneBeneficio > 260)
                    {
                        messaggioVideo = "Le settimane benefici particolari non possono eccedere 260";
                        return false;
                    }
                }

                if ((Utility.IsDomandaVOCRED(siglaCategoria) || Utility.IsDomandaVOCOOP(siglaCategoria)) && nSettimaneBeneficio > 364)
                {
                    messaggioVideo = "Il Numero settimane beneficio non possono eccedere 364.";
                    return false;
                }

                if (Utility.IsDomandaVESO92(siglaCategoria) || Utility.IsDomandaESOTEL(siglaCategoria) || Utility.IsDomandaESOAMB(siglaCategoria))
                {
                    if (decorrenzaOriginaria.Year >= 2018 && decorrenzaOriginaria.Year <= (Utility.IsDomandaVESO92(siglaCategoria) ? 2023 : 2020))
                    {
                        if (nSettimaneBeneficio > 364)
                        {
                            messaggioVideo = "Il Numero settimane beneficio non possono eccedere 364.";
                            return false;
                        }
                    }
                    else if (!Utility.IsDomandaVESO92(siglaCategoria))
                    {
                        if (nSettimaneBeneficio > 260)
                        {
                            messaggioVideo = "Il Numero settimane beneficio non possono eccedere 260.";
                            return false;
                        }
                    }
                }

                if (Utility.IsDomandaCRED27(siglaCategoria) || Utility.IsDomandaCOOP28(siglaCategoria))
                {
                    if (decorrenzaOriginaria.Year >= 2017 && decorrenzaOriginaria.Year <= 2019)
                    {
                        if (nSettimaneBeneficio > 364)
                        {
                            messaggioVideo = "Il Numero settimane beneficio non possono eccedere 364.";
                            return false;
                        }
                    }
                }

                // Se il codice beneficio è 10, allora non è possibile inserire le settimane beneficio
                if (!string.IsNullOrEmpty(tipoBeneficio) && tipoBeneficio == "10")
                {
                    messaggioVideo = "Il Numero settimane beneficio non è ammesso.";
                    return false;
                }

                if (Utility.IsPrepensionamentoEditoriaFiltroEAA(datiPensione))
                {
                    if (nSettimaneBeneficio > 156)
                    {
                        messaggioVideo = "Il Numero settimane beneficio deve essere minore o uguale di 156";
                        return false;
                    }
                    if (!Utility.IsRicostituzione(datiPensione.Gruppo) && ((nSettimaneOBG + nSettimaneBeneficio) > 1820))
                    {
                        messaggioVideo = "La somma tra 'Numero settimane' e 'Numero settimane beneficio' deve essere minore o uguale di 1820";
                        return false;
                    }
                }

                if (Utility.IsPrepensionamentoEditoriaArt1c154L205_2017(datiPensione))
                {
                    byte capienza = 156;
                    if (nSettimaneBeneficio > capienza)
                    {
                        messaggioVideo = string.Format("Il Numero settimane beneficio deve essere minore o uguale di {0}.", capienza);
                        return false;
                    }
                }

                if (Utility.IsDomandaESPA(siglaCategoria) && Utility.IsDomandaUnicarpe(datiPensione, true) == Utility.TipoUnicarpe.Automatica && codNat1 == ' ' && nSettimaneBeneficio > 0)
                {
                    messaggioVideo = string.Format("Il Numero settimane beneficio deve essere zero.");
                    return false;
                }

                if (Utility.IsDomandaVecchiaiaENAV(datiPensione) && nSettimaneBeneficio >= 260 && settAnzContr311295.HasValue && settAnzContr311295.Value != 0)
                {
                    messaggioVideo = string.Format("Il campo Num settimane anz contrib successive al 31/12/1995 deve essere 0 o vuoto.");
                    return false;
                }
            }
            else
            {
                if (Utility.IsDomandaVecchiaiaENAV(datiPensione) && (!settAnzContr311295.HasValue || settAnzContr311295.Value == 0))
                {
                    messaggioVideo = string.Format("Il campo Num settimane anz contrib successive al 31/12/1995 deve essere valorizzato.");
                    return false;
                }
            }

            if (nSettimaneBeneficio.HasValue)
            {
                if (!ControlsBeneficioENAVWithSettAnzContrib(datiPensione, tipoBeneficio, settAnzContr311295, nSettimaneOBG, nSettimaneBeneficio, out messaggioVideo))
                    return false;

                if ((Utility.IsDomandaAnzianitaMaggiorazioneAmiantoLegge208_2015(datiPensione) || Utility.IsDomandaVecchiaiaMaggiorazioneAmiantoLegge208_2015(datiPensione)) &&
                     Utility.IsDomandaUnicarpe(datiPensione, true) != Utility.TipoUnicarpe.Automatica && settAnzContr311295.HasValue)
                {
                    if (nSettimaneBeneficio < settAnzContr311295)
                    {
                        messaggioVideo = "Il Numero settimane beneficio deve essere maggiore o uguale del Numero settimane anz contrib successiva al 31/12/1995";
                        return false;
                    }
                }
            }

            return true;
        }

        public static bool ControlsBeneficioWithAttEconomicaProfessioneInd(GestionePensione.DatiPensione datiPensione, int? attEconomica, int? profInd, string tipoBeneficio,
            bool isRiaperturaDomanda, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (attEconomica.HasValue && profInd.HasValue)
            {
                if (attEconomica.Value == 4 && profInd.Value == 350 && (string.IsNullOrEmpty(tipoBeneficio) || tipoBeneficio != "09"))
                {
                    messaggioVideo = "E' obbligatorio inserire il codice beneficio particolare pari a 9 per l'attività economica " +
                        attEconomica.Value.ToString().PadLeft(2, '0') + " e la professione individuale " +
                        profInd.Value.ToString().PadLeft(3, '0');
                    return false;
                }
                else if (((attEconomica.Value == 92 && profInd.Value == 257) ||
                            (attEconomica.Value == 3 && profInd.Value == 326) ||
                            (attEconomica.Value == 3 && profInd.Value == 350) ||
                            (attEconomica.Value == 7 && profInd.Value == 247) ||
                            (attEconomica.Value == 2 && profInd.Value == 247) ||
                            (attEconomica.Value == 14 && profInd.Value == 190)) && (string.IsNullOrEmpty(tipoBeneficio) || tipoBeneficio != "04"))
                {
                    messaggioVideo = "E' obbligatorio inserire il codice beneficio particolare pari a 4 per l'attività economica " +
                        attEconomica.Value.ToString().PadLeft(2, '0') + " e la professione individuale " +
                        profInd.Value.ToString().PadLeft(3, '0');
                    return false;
                }
            }
            if (!string.IsNullOrEmpty(tipoBeneficio) && attEconomica.HasValue && profInd.HasValue)
            {
                if ((tipoBeneficio == "09" && (attEconomica.Value != 4 || profInd.Value != 350)) ||
                    (tipoBeneficio == "04" && (attEconomica.Value != 92 || profInd.Value != 257) &&
                    (attEconomica.Value != 3 || profInd.Value != 326) &&
                    (attEconomica.Value != 3 || profInd.Value != 350) &&
                    (attEconomica.Value != 7 || profInd.Value != 247) &&
                    (attEconomica.Value != 2 || profInd.Value != 247) &&
                    (attEconomica.Value != 14 || profInd.Value != 190) &&
                    (attEconomica.Value != 15 || profInd.Value != 208)))
                {
                    messaggioVideo = "L'attività economica " +
                            attEconomica.Value.ToString().PadLeft(2, '0') + " e la professione individuale " +
                            profInd.Value.ToString().PadLeft(3, '0') + " non sono ammesse per il codice beneficio " +
                            tipoBeneficio;
                    return false;
                }
            }
            return true;
        }
        public static bool ControlsBeneficioENAVWithSettAnzContrib(GestionePensione.DatiPensione datiPensione, string tipoBeneficio, short? settAnzContr311295, int? nSettimaneOBG, int? nSettimaneBeneficio, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaVecchiaiaENAV(datiPensione))
            {
                //profilo A: settimane anz contrib al 31/12/1995 <= (num. Sett. Diritto - 3 * num. Sett. Benef.)
                if (tipoBeneficio == "16" && settAnzContr311295.HasValue && nSettimaneOBG.HasValue && nSettimaneBeneficio.HasValue && settAnzContr311295 > (nSettimaneOBG - 2.5 * nSettimaneBeneficio))
                {
                    messaggioVideo = "Il campo Num settimane anz contrib successive al 31/12/1995 deve essere minore o uguale a " + (nSettimaneOBG - 2.5 * nSettimaneBeneficio);
                    return false;
                }
                //profilo B: settimane anz contrib al 31/12/1995<= (num. Sett. Diritto - 5 * num. Sett. Benef.)
                else if (tipoBeneficio == "17" && settAnzContr311295.HasValue && nSettimaneOBG.HasValue && nSettimaneBeneficio.HasValue && nSettimaneBeneficio.HasValue && settAnzContr311295 > (nSettimaneOBG - 4.5 * nSettimaneBeneficio))
                {
                    messaggioVideo = "Il campo Num settimane anz contrib successive al 31/12/1995 deve essere minore o uguale a " + (nSettimaneOBG - 4.5 * nSettimaneBeneficio);
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsDecMaggiorazioneSociale(DateTime? decMaggSociale, GestionePensione.DatiPensione datiPensione, GestioneAnagrafica.DatiAnagrafici datiAnagraficiTitolare,
            DateTime dataSistema, DateTime? decMaggSocialeFromPrelievo, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, bool isRiaperturaDomanda, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            Utility.GetCodiciNatura(datiPensione.NaturaPensione, out codNat1, out codNat2, out codNat3);
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);
            if (Utility.IsDomandaIOCUM(datiPensione.SiglaCategoria))
            {
                decorrenzaOriginaria = new DateTime(decorrenzaOriginaria.Year, decorrenzaOriginaria.Month, 1);
            }
            #endregion Recupero Dati

            if (decMaggSociale.HasValue)
            {
                //Se la Categoria (RACATEG) è = a “”VOBIS”, “IOBIS”, “VMP”, “IMP” la
                //Decorrenza Maggiorazione 544 (VRP544) non deve essere acquisita
                switch (siglaCategoria)
                {
                    case "VOBIS":
                    case "IOBIS":
                    case "VMP":
                    case "IMP":
                        messaggioVideo = "La decorrenza maggiorazione 544 non deve essere acquisita";
                        return false;
                    default:
                        break;
                }

                //La Decorrenza Maggiorazione 544 (VRP544) non può essere superiore di 1
                //mese dalla Data del Sistema tenendo conto solo del mese ed anno
                if (Utility.DataStrettamenteSuccessivaA(new DateTime(decMaggSociale.Value.Year, decMaggSociale.Value.Month, 1),
                    new DateTime(dataSistema.AddMonths(1).Year, dataSistema.AddMonths(1).Month, 1)))
                {
                    messaggioVideo = "La decorrenza maggiorazione sociale non può essere superiore di 1 mese dalla data odierna tenendo conto solo del mese ed anno";
                    return false;
                }

                //La Decorrenza Maggiorazione 544 (VRP544) non può essere anteriore a
                //luglio 1988
                if (!Utility.DataSuccessivaA(decMaggSociale.Value, new DateTime(1988, 7, 1)))
                {
                    messaggioVideo = "La decorrenza maggiorazione 544 non può essere anteriore a luglio 1988";
                    return false;
                }

                //La Decorrenza Maggiorazione 544 (VRP544) non può essere inferiore alla
                //Decorrenza originaria (RAU104)
                if (!Utility.DataSuccessivaA(decMaggSociale.Value, decorrenzaOriginaria))
                {
                    messaggioVideo = "La decorrenza maggiorazione sociale non può essere inferiore alla decorrenza originaria";
                    return false;
                }

                //ENG - creato bypass DECORRENZA_MAGG_SOCIALE
                if (!GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.MaggiorazioniBenefici_Maggiorazioni_AGO.DECORRENZA_MAGG_SOCIALE))
                    if (Utility.IsRicostituzione(datiPensione.Gruppo) && decMaggSocialeFromPrelievo.HasValue && !Utility.DataSuccessivaA(decMaggSociale.Value, decMaggSocialeFromPrelievo.Value))
                    {
                        messaggioVideo = "La decorrenza maggiorazione sociale deve essere maggiore o uguale alla decorrenza già presente.";
                        return false;
                    }

                GestioneControlliDinamici.ControlloDinamico ctrl = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneControlliMemo72", out ctrl);
                GestioneControlliDinamici.ControlloDinamico ctrl1 = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("SbloccoRIC_SO_TitDomDiversoTitPens", out ctrl1);
                //Per le categorie IR, IOART, IOCOM, IOTOT, IDAI, IOCUM, IOP, IOBANC, IO, IOSPETT, IOSPORT  con decorrenza maggiore di 31/07/1984,
                // primo byte codice natura uguale a 1, 2, 3 o 4 e decorrenza maggiorazione sociale maggiore di 31/07/2020
                // non va verificata la condizione dei 60 anni
                if (ctrl != null && ctrl.ValoreControllo == "SI")
                {
                    if (!(((Utility.IsDomandaAnte96(datiPensione, datiPensione, datiDanteCausa, isRiaperturaDomanda) != null && Utility.IsDomandaRipristinoOrRiliquidazione(datiPensione)) || Utility.IsDomandaINPDAI(siglaCategoria) || Utility.IsCategoriaAutonomi(siglaCategoria) || Utility.IsDomandaTotalizzazione(siglaCategoria) || Utility.IsDomandaCumulo(siglaCategoria) ||
                        siglaCategoria == "IOP" || siglaCategoria == "IOBANC" || siglaCategoria == "IO" || siglaCategoria == "IOSPETT" || siglaCategoria == "IOSPORT") && siglaCategoria.StartsWith("I") &&
                        Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(1984, 7, 31)) && (codNat1 == '1' || codNat1 == '2' || codNat1 == '3' || codNat1 == '4') &&
                        Utility.DataStrettamenteSuccessivaA(decMaggSociale.Value, new DateTime(2020, 7, 31)))
                        && datiAnagraficiTitolare != null && datiAnagraficiTitolare.DataNascita.HasValue &&
                        !Utility.DataStrettamenteSuccessivaA(decMaggSociale.Value, datiAnagraficiTitolare.DataNascita.Value.AddYears(60)))
                    {
                        //ENG - per le ricostituzioni per variazioni dati contitolari, se il controllo dinamico "SbloccoRIC_SO_TitDomDiversoTitPens" = SI, deve essere saltato il blocco:
                        //"La decorrenza maggiorazione sociale deve essere maggiore del mese di compimento del 60esimo anno di età del titolare."
                        if (!(ctrl1 != null && ctrl1.ValoreControllo == "SI" && datiPensione.Gruppo == "0031" && datiPensione.Prodotto == "0413" && datiPensione.Tipo == "0001"))
                        {
                            messaggioVideo = "La decorrenza maggiorazione sociale deve essere maggiore del mese di compimento del 60esimo anno di età del titolare.";
                            return false;
                        }
                    }
                }
                else
                {
                    if (datiAnagraficiTitolare != null && datiAnagraficiTitolare.DataNascita.HasValue &&
                        !Utility.DataStrettamenteSuccessivaA(decMaggSociale.Value, datiAnagraficiTitolare.DataNascita.Value.AddYears(60)))
                    {
                        //ENG - per le ricostituzioni per variazioni dati contitolari, se il controllo dinamico "SbloccoRIC_SO_TitDomDiversoTitPens" = SI, deve essere saltato il blocco:
                        //"La decorrenza maggiorazione sociale deve essere maggiore del mese di compimento del 60esimo anno di età del titolare."
                        if (!(ctrl1 != null && ctrl1.ValoreControllo == "SI" && datiPensione.Gruppo == "0031" && datiPensione.Prodotto == "0413" && datiPensione.Tipo == "0001"))
                        {
                            messaggioVideo = "La decorrenza maggiorazione sociale deve essere maggiore del mese di compimento del 60esimo anno di età del titolare.";
                            return false;
                        }
                    }
                }

            }
            return true;
        }

        public static bool ControlsMaggiorazioneSocialeCUM(ref EntityBLCommon.ContenitoreObject contenitore, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if ((Utility.IsDomandaIOCUM(contenitore.DatiPensione.SiglaCategoria) || Utility.IsDomandaSOCUM(contenitore.DatiPensione.SiglaCategoria)
                || Utility.IsDomandaTotalizzazione(contenitore.DatiPensione.SiglaCategoria))
                && contenitore.ListaQuotePensione != null)
            {
                EntityBLCommon.ContenitoreDecodifica contenitoreDecodifica = new EntityBLCommon.ContenitoreDecodifica(contenitore);
                var listaDecEnteGestioneFondo = contenitoreDecodifica.ElencoDecEnteGestioneFondo;
                if (listaDecEnteGestioneFondo == null)
                    GestioneDecodifica.GetDecEnteGestioneFondo(out listaDecEnteGestioneFondo);
                var lstRecordCodGestione = from Record in contenitore.ListaQuotePensione
                                           join dec in listaDecEnteGestioneFondo on Record.EnteGestioneFondo equals dec.Id
                                           select new { Record, TraduzioneSuGP = dec.Codice.Trim() };
                if (lstRecordCodGestione != null)
                {
                    List<string> lstCodiciVerify;
                    if (Utility.IsDomandaTotalizzazione(contenitore.DatiPensione.SiglaCategoria))
                        lstCodiciVerify = new List<string> { "A1", "A2", "A3", "A4", "A5", "A6", "A7", "A8", "A9", "B1", "B2", "B3", "B4", "B5", "F0", "C1", "C2", "C3", "C4", "C5", "D1", "E1", "E2", "SP" };
                    else
                        lstCodiciVerify = new List<string> { "A1", "A2", "A3", "A4", "A5", "A6", "A7", "A8", "A9", "B1", "B2", "B4", "C1", "C2", "C3", "C4", "C5", "D1", "E1", "E2", "F0" };
                    List<string> recNat = lstRecordCodGestione.Select(x => x.TraduzioneSuGP).Where(x => lstCodiciVerify.Contains(x)).ToList();
                    if (recNat == null || recNat.Count == 0)
                    {
                        messaggioVideo = string.Format("Maggiorazione sociale non prevista per tali fondi");
                        return false;
                    }
                }
            }
            return true;
        }

        public static bool ControlsCessMaggiorazioneSociale(DateTime? cessMaggSociale, DateTime dataSistema, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (cessMaggSociale.HasValue && Utility.DataStrettamenteSuccessivaA(cessMaggSociale.Value, new DateTime(dataSistema.AddMonths(1).Year, dataSistema.AddMonths(1).Month, 1)))
            {
                messaggioVideo = "La cessazione maggiorazione 544 non può essere superiore di 1 mese dalla data odierna tenendo conto solo del mese ed anno";
                return false;
            }
            return true;
        }

        public static bool ControlsAnniRiduzioneBenefici(DateTime dataSistema, short? anniRiduzioneBenefici, DateTime? decMaggSociale, GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }
            #endregion Recupero Dati

            if (anniRiduzioneBenefici.HasValue && anniRiduzioneBenefici.Value > 0)
            {
                //Se non viene acquisita la Decorrenza Maggiorazione 544 (VRP544) gli Anni
                //Riduzione per maggiorazioni (RIDUZIONE) non deve essere acquisito
                if (!decMaggSociale.HasValue)
                {
                    messaggioVideo = "Il campo 'Anni Riduzione benefici Art.38 finanziaria 2002' non deve essere acquisito in assenza della decorrenza maggiorazione 544";
                    return false;
                }

                if (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                {
                    //Gli Anni Riduzione per maggiorazioni (RIDUZIONE) possono essere i
                    //seguenti rispetto all'età del pensionando:
                    //Età Anni Riduzione
                    //69 1
                    //68 da 1 a 2
                    //67 da 1 a 3
                    //66 da 1 a 4
                    //65 da 1 a 5
                    GestioneAnagrafica.DatiAnagrafici datiAnagrafici = null;
                    GestioneAnagrafica.GetAnagraficaByIdPensione(datiPensione.Id, out datiAnagrafici);
                    if (datiAnagrafici.DataNascita.HasValue)
                    {
                        if (!Utility.DataSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(69), dataSistema))
                        {
                            if (anniRiduzioneBenefici.Value != 1)
                            {
                                messaggioVideo = "Per pensionandi con almeno 69 anni il campo anni riduzione per maggiorazioni può contenere il valore 1";
                                return false;
                            }
                        }
                        else if (!Utility.DataSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(68), dataSistema))
                        {
                            if (anniRiduzioneBenefici.Value < 1 || anniRiduzioneBenefici.Value > 2)
                            {
                                messaggioVideo = "Per pensionandi con 68 anni il campo anni riduzione per maggiorazioni può contenere valori da 1 a 2";
                                return false;
                            }
                        }
                        else if (!Utility.DataSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(67), dataSistema))
                        {
                            if (anniRiduzioneBenefici.Value < 1 || anniRiduzioneBenefici.Value > 3)
                            {
                                messaggioVideo = "Per pensionandi con 67 anni il campo anni riduzione per maggiorazioni può contenere valori da 1 a 3";
                                return false;
                            }
                        }
                        else if (!Utility.DataSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(66), dataSistema))
                        {
                            if (anniRiduzioneBenefici.Value < 1 || anniRiduzioneBenefici.Value > 4)
                            {
                                messaggioVideo = "Per pensionandi con 66 anni il campo anni riduzione per maggiorazioni può contenere valori da 1 a 4";
                                return false;
                            }
                        }
                        else if (!Utility.DataSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(65), dataSistema))
                        {
                            if (anniRiduzioneBenefici.Value < 1 || anniRiduzioneBenefici.Value > 5)
                            {
                                messaggioVideo = "Per pensionandi con 65 anni il campo anni riduzione per maggiorazioni può contenere valori da 1 a 5";
                                return false;
                            }
                        }
                        else
                        {
                            messaggioVideo = "Il campo anni riduzione per maggiorazioni deve essere assente";
                            return false;
                        }
                    }
                }
            }

            return true;
        }

        public static bool ControlsExCombattente(byte? codiceCieco, DateTime? decExComb, GestionePensione.DatiPensione datiPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            string certificato = string.Empty;
            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';
            int pdirsup = 0;
            int plavaut = 0;

            #region Recupero Dati
            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            Utility.GetCodiciNatura(datiPensione.NaturaPensione, out codNat1, out codNat2, out codNat3);
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);
            GetPdirusp_Plavaut(datiPensione, out pdirsup, out plavaut);
            if (Utility.IsDomandaIOCUM(datiPensione.SiglaCategoria))
            {
                decorrenzaOriginaria = new DateTime(decorrenzaOriginaria.Year, decorrenzaOriginaria.Month, 1);
            }
            #endregion Recupero Dati

            if (codiceCieco.HasValue && codiceCieco.Value > 0)
            {
                //Deve essere assente per le Categorie (RACATEG) = a "INDCOM",
                //"SOSPED", "VOSPED", "SOSPED", "VOBIS", "IOBIS", "VMP", "IMP"
                switch (siglaCategoria)
                {
                    case "INDCOM":
                    case "VOSPED":
                    case "SOSPED":
                    case "IOSPED":
                    case "VOBIS":
                    case "IOBIS":
                    case "VMP":
                    case "IMP":
                        messaggioVideo = "Il codice cieco deve essere assente";
                        return false;
                    //Per le Categorie (RACATEG) = a “VOAUT, “IOAUT”, “SOAUT” il Codice può
                    //essere solo 8
                    case "VOAUT":
                    case "IOAUT":
                    case "SOAUT":
                        if (codiceCieco.Value != 8)
                        {
                            messaggioVideo = "Il codice cieco può essere solo 8";
                            return false;
                        }
                        break;
                    case "VOTOT":
                    case "IOTOT":
                    case "SOTOT":
                        if (codiceCieco.Value == 9 || codiceCieco.Value == 0)
                        {
                            messaggioVideo = "Il codice cieco non può essere 9 o 0";
                            return false;
                        }
                        break;
                    default:
                        break;
                }

                if (decExComb.HasValue)
                {
                    //Se la Categoria (RACATEG) è = a “INDCOM”, “VOSPED”, “IOSPED”,
                    //“SOSPED”, “VOBIS”, “IOBIS”, “VMP”, “IMP”, “VOAUT”, “IOAUT”, “SOAUT” la
                    //Decorrenza ex combattente (RAUE22) deve essere assente
                    switch (siglaCategoria)
                    {
                        case "INDCOM":
                        case "VOSPED":
                        case "SOSPED":
                        case "IOSPED":
                        case "VOBIS":
                        case "IOBIS":
                        case "VMP":
                        case "IMP":
                            messaggioVideo = "La decorrenza ex combattente deve essere assente";
                            return false;
                        case "VOAUT":
                        case "IOAUT":
                        case "SOAUT":
                            if (codiceCieco.Value != 8 && codiceCieco.Value != 9)
                            {
                                messaggioVideo = "La decorrenza ex combattente deve essere assente";
                                return false;
                            }
                            break;
                        default:
                            break;
                    }

                    //La Decorrenza ex combattente (RAUE22) non può essere inferiore a gennaio
                    //1985
                    if (!Utility.DataSuccessivaA(decExComb.Value, new DateTime(1985, 1, 1)))
                    {
                        messaggioVideo = "La decorrenza ex combattente non può essere inferiore a gennaio 1985";
                        return false;
                    }

                    //Se il Campo PDIRSUP è = a zero la Decorrenza ex combattente (RAUE22)
                    //non può essere inferiore alla Decorrenza Originaria (RAU104)
                    if (pdirsup == 0)
                    {
                        if (!Utility.DataSuccessivaA(decExComb.Value, decorrenzaOriginaria))
                        {
                            messaggioVideo = "La decorrenza ex combattente non può essere inferiore alla decorrenza originaria";
                            return false;
                        }
                    }

                    //Se il Campo cieco-ex combattente (RAU206) è diverso da “8” la Decorrenza
                    //ex combattente (RAUE22) deve essere assente
                    if (codiceCieco.Value != 8 && codiceCieco.Value != 9)
                    {
                        messaggioVideo = "La decorrenza ex combattente deve essere assente";
                        return false;
                    }
                }
                else
                {
                    //Se il Campo cieco-ex combattente (RAU206) è = a “8” deve essere presente
                    //anche la Decorrenza ex combattente (RAUE22)
                    if (codiceCieco.Value == 8)
                    {
                        messaggioVideo = "La decorrenza ex combattente deve essere presente";
                        return false;
                    }
                }
            }
            return true;
        }

        public static bool ControlsSettimaneBeneficioWithDatiContribQuotaD(int? settimaneBeneficio, GestionePensione.DatiPensione datiPensione, List<GestioneCalcolo.DatiCalcoloContributivo> listaDatiCalcoloContributivo, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!Utility.IsDomandaOrganizzazioniInternazionali(datiPensione))
            {
                //ENG - Bypassare il controllo per le IOPGI
                if (Utility.IsPensioneInabilitaPost2012(datiPensione) && Utility.IsDomandaUnicarpe(datiPensione, true) != Utility.TipoUnicarpe.Automatica &&
                    !Utility.IsDomandaENPALS(datiPensione.Gestione) && !Utility.IsDomandaSPED(datiPensione) && !Utility.IsDomandaIOPGI(datiPensione.SiglaCategoria))
                {
                    if (settimaneBeneficio.GetValueOrDefault() > 0)
                    {
                        if (listaDatiCalcoloContributivo == null || listaDatiCalcoloContributivo.Count == 0 || listaDatiCalcoloContributivo.FindIndex(x => (x.NSettimaneQuotaDL214.HasValue || x.MontanteQuotaDL214.HasValue || x.ImportoContribTotaleQuotaDL214.HasValue)) == -1)
                        {
                            messaggioVideo = "Quota 'D' obbligatoria nella sezione dei dati calcolo in presenza del Numero Settimane Beneficio";
                            return false;
                        }
                    }
                }

                if (Utility.IsPensioneInabilitaPost2012(datiPensione) && datiPensione.FineAssicurazione.HasValue && !Utility.DataSuccessivaA(datiPensione.FineAssicurazione.Value, new DateTime(2012, 01, 01)))
                {
                    if (settimaneBeneficio.GetValueOrDefault() == 0)
                    {
                        if (!(listaDatiCalcoloContributivo == null || listaDatiCalcoloContributivo.Count == 0 || listaDatiCalcoloContributivo.FindIndex(x => (x.NSettimaneQuotaDL214.HasValue || x.MontanteQuotaDL214.HasValue || x.ImportoContribTotaleQuotaDL214.HasValue)) == -1))
                        {
                            messaggioVideo = "La Quota 'D' non deve essere acquisita nella sezione dei dati calcolo in presenza del Numero Settimane Beneficio pari a 0";
                            return false;
                        }
                    }
                }
            }

            return true;
        }

        public static bool ControlsTipoBeneficiForPensioneInabilitaIndiretta(char codiceNatura1, char codiceNatura3, GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, string tipoBeneficio, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            bool? isDomandaInabilitaIndiretta = IsDomandaInabilitaIndiretta(codiceNatura1, datiPensione.SiglaCategoria);
            if (isDomandaInabilitaIndiretta.HasValue && tipoBeneficio != null && isDomandaInabilitaIndiretta.Value && tipoBeneficio != "06")
            {
                if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) || (Utility.IsDomandaPensioneIndiretta(datiPensione) && Utility.IsDomandaSOTOT(datiPensione.SiglaCategoria) && codiceNatura3 == 'G'))
                    return true;
                messaggioVideo = "Per una pensione indiretta con 'Codice Natura 1' uguale a 3 o 4 il 'Tipo beneficio' deve essere '06'";
                return false;
            }
            return true;
        }

        public static bool ControlsTipoBeneficiForCumulo(char codiceNatura1, GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, string tipoBeneficio, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            int codiceLegge = 0;
            string tipoSettimaneBeneficio = string.Empty;

            if (datiPensione != null && Utility.IsTabPrepensionamentoVisible(datiPensione, datiPensione.AttivitaEconomica, datiPensione.ProfessioneIndividuale,
                datiPensione.NaturaPensione, out codiceLegge, out tipoSettimaneBeneficio))
                if ((tipoSettimaneBeneficio == "04" || tipoSettimaneBeneficio == "09") && (tipoBeneficio == "04" || tipoBeneficio == "09")) return true;

            if (Utility.IsDomandaSOCUM(datiPensione.SiglaCategoria) && tipoBeneficio != null && tipoBeneficio != "01" && codiceNatura1 == ' ')
            {
                messaggioVideo = "Per una pensione SOCUM con primo byte del codice natura uguale a 'vuoto' il 'Tipo beneficio' deve essere '01'";
                return false;
            }
            return true;
        }

        public static bool ControlsTipoBeneficiForPensioneAUT(char codiceNatura1, GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, string tipoBeneficio, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            bool isDomandaInabilitaIndiretta = IsDomandaInabilitaIndiretta(codiceNatura1, datiPensione.SiglaCategoria).GetValueOrDefault();

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024 = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024", out ctrlMemo123_2024);

            //ENG - Memo 123/2024
            GestioneControlliDinamici.ControlloDinamico ctrlMemo123_2024OpzioneContrib = null;
            GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneRIC_TRFMemo123_2024OpzioneContrib", out ctrlMemo123_2024OpzioneContrib);

            if (!isDomandaInabilitaIndiretta && !Utility.IsDomandaInabilitaOrdinaria(datiPensione) && !datiPensione.SceltaLavMadri.HasValue && !Utility.IsDomandaQuota100(datiPensione) && !Utility.IsDomandaQuota102(datiPensione) && !Utility.IsDomandaAnticipataFlessibile(datiPensione) && !Utility.IsDomandaAnticipataFlessibileOpzioneContributivo(datiPensione) && !Utility.IsDomandaAPEPrecoci(datiPensione)
                && !((!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && (Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione) || Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione)))
                || (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) && ((ctrlMemo123_2024 != null && ctrlMemo123_2024.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileLeggeBilancio2024(datiPensione)) || (ctrlMemo123_2024OpzioneContrib != null && ctrlMemo123_2024OpzioneContrib.ValoreControllo == "SI" && Utility.IsDomandaAnticipataFlessibileOpzioneContributivoLeggeBilancio2024(datiPensione)))))
                && !Utility.IsDomandaVOAUTAnticipataFlessibileLeggeBilancio2024FiltroGSE(datiPensione)
                && tipoBeneficio != null && tipoBeneficio != "01" && Utility.IsDomandaAUT(datiPensione))
            {
                if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                    return true;

                messaggioVideo = "Per una pensione AUT che non sia inabilità, Quota100, Quota102, ApePrecoce, Anticipata Flessibile o lavoratrice madre, il 'Tipo beneficio' deve essere '01'";
                return false;
            }
            return true;
        }

        public static bool ControlsCoerenzaBeneficioVittimeTerrorismo(long? tipologiaPrestazione, long? tipologiaBeneficio, long? soggettoBeneficiario, string soggettoBeneficiarioTraduzioneSuGP,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!string.IsNullOrEmpty(soggettoBeneficiarioTraduzioneSuGP) && soggettoBeneficiarioTraduzioneSuGP.Trim() == "V2")
            {
                if (tipologiaPrestazione.GetValueOrDefault() != 2 && tipologiaPrestazione.GetValueOrDefault() != 3)
                {
                    messaggioVideo = "Per Soggetto Beneficiario \"Vittima con invalidità => 25%\" la Tipologia di Prestazione può essere solo \"Art. 2 e 3 L. 206/2004\" o \"Art. 4 comma 2 bis L. 206/2004\"";
                    return false;
                }

                if (tipologiaPrestazione.GetValueOrDefault() == 2)
                {
                    if (tipologiaBeneficio.GetValueOrDefault() != 1 && tipologiaBeneficio.GetValueOrDefault() != 2)
                    {
                        messaggioVideo = "Per Tipologia di Prestazione \"Art. 2 e 3 L. 206/2004\" la Tipologia di Beneficio può essere solo \"Benefici art. 2-3 con decorrenza dal 1° settembre 2004\" o \"Benefici art. 2-3 con decorrenza dal 1° gennaio 2007\"";
                        return false;
                    }
                }

                if (tipologiaPrestazione.GetValueOrDefault() == 3)
                {
                    if (tipologiaBeneficio.GetValueOrDefault() != 5)
                    {
                        messaggioVideo = "Per Soggetto Beneficiario \"Vittima con invalidità < 25%\" e Tipologia di Prestazione \"Art. 4 comma 2 bis L. 206/2004\" la Tipologia di Beneficio può essere solo \"Benefici art. 4 con decorrenza dal 1° gennaio 2007\"";
                        return false;
                    }
                }
            }

            if (!string.IsNullOrEmpty(soggettoBeneficiarioTraduzioneSuGP) && soggettoBeneficiarioTraduzioneSuGP.Trim() == "V1")
            {
                if (tipologiaPrestazione.GetValueOrDefault() != 2)
                {
                    messaggioVideo = "Per Soggetto Beneficiario \"Vittima con invalidità < 25%\" la Tipologia di Prestazione può essere solo \"Art. 2 e 3 L. 206/2004\"";
                    return false;
                }

                if (tipologiaPrestazione.GetValueOrDefault() == 2)
                {
                    if (tipologiaBeneficio.GetValueOrDefault() != 1 && tipologiaBeneficio.GetValueOrDefault() != 2)
                    {
                        messaggioVideo = "Per Tipologia di Prestazione \"Art. 2 e 3 L. 206/2004\" la Tipologia di Beneficio può essere solo \"Benefici art. 2-3 con decorrenza dal 1° settembre 2004\" o \"Benefici art. 2-3 con decorrenza dal 1° gennaio 2007\"";
                        return false;
                    }
                }
            }

            if (!string.IsNullOrEmpty(soggettoBeneficiarioTraduzioneSuGP) && soggettoBeneficiarioTraduzioneSuGP.Trim() == "G")
            {
                if (tipologiaPrestazione.GetValueOrDefault() != 2)
                {
                    messaggioVideo = "Per Soggetto Beneficiario \"Genitore\" la Tipologia di Prestazione può essere solo \"Art. 2 e 3 L. 206/2004\"";
                    return false;
                }

                if (tipologiaBeneficio.GetValueOrDefault() != 2)
                {
                    messaggioVideo = "Per Soggetto Beneficiario \"Genitore\" la Tipologia di Beneficio può essere solo \"Benefici art. 2-3 con decorrenza dal 1° gennaio 2007\"";
                    return false;
                }
            }

            if (soggettoBeneficiario.GetValueOrDefault() == 4 || soggettoBeneficiario.GetValueOrDefault() == 7)
            {
                if (tipologiaPrestazione.GetValueOrDefault() != 2)
                {
                    messaggioVideo = "Per Soggetto Beneficiario \"Coniuge/Vedovo\" o \"Figlio/orfano\" la Tipologia di Prestazione può essere solo \"Art. 2 e 3 L. 206/2004\"";
                    return false;
                }

                if (tipologiaBeneficio.GetValueOrDefault() != 2 && tipologiaBeneficio.GetValueOrDefault() != 3)
                {
                    messaggioVideo = "Per Soggetto Beneficiario \"Coniuge/Vedovo\" o \"Figlio/orfano\" la Tipologia di Beneficio può essere solo \"Benefici art. 2-3 con decorrenza dal 1° gennaio 2007\" o \"Benefici art. 2-3 con decorrenza sia dal 1° settembre 2004 che dal 1° gennaio 2007\"";
                    return false;
                }
            }

            if (soggettoBeneficiario.GetValueOrDefault() == 5 || soggettoBeneficiario.GetValueOrDefault() == 8)
            {
                if (tipologiaPrestazione.GetValueOrDefault() != 2)
                {
                    messaggioVideo = "Per Soggetto Beneficiario \"Coniuge\" o \"Figlio\" la Tipologia di Prestazione può essere solo \"Art. 2 e 3 L. 206/2004\"";
                    return false;
                }

                if (tipologiaBeneficio.GetValueOrDefault() != 2)
                {
                    messaggioVideo = "Per Soggetto Beneficiario \"Coniuge\" o \"Figlio\" la Tipologia di Beneficio può essere solo \"Benefici art. 2-3 con decorrenza dal 1° gennaio 2007\"";
                    return false;
                }
            }

            return true;
        }

        public static bool ControlsDecorrenzaEventoTerroristico(DateTime? dataEventoTerroristico, DateTime dataPresentazioneDomanda, char? codiceEvento, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;
            if (dataEventoTerroristico.HasValue && codiceEvento == 'I' && (!Utility.DataSuccessivaA(dataEventoTerroristico.Value, new DateTime(1961, 1, 1)) ||
                Utility.DataSuccessivaA(dataEventoTerroristico.Value, dataPresentazioneDomanda)))
            {
                messaggioVideo = string.Format("Se il Codice Evento è ITALIA la Data Evento Terroristico deve essere successiva al 01/01/1961 e antecedente alla data di presentazione della domanda ({0:dd/MM/yyyy})", dataPresentazioneDomanda);
                return false;
            }

            return true;
        }
