        /// <summary>
        /// Verifica se il sindacato passato in input è presente nella lista dei sindacati attivi
        /// </summary>
        /// <param name="sindacato"></param>
        /// <param name="msg"></param>
        /// <returns></returns>
        public static bool VerificaSindacatoAttivo(GestionePensione.DatiSindacato sindacato, string siglaCategoria, out string msg)
        {
            msg = string.Empty;
            List<Liquidazione.BLCommon.Entity.Sindacato> elencoSindacato = null;
            if (sindacato != null)
            {
                string idCategoria = Liquidazione.BLCommon.GestioneSindacati.GetIdCategoriaForSindacato(siglaCategoria, out msg);
                if (!string.IsNullOrEmpty(msg))
                    return false;

                GestioneDelegheSindacali.GetElencoSindacatiPerCategoria(idCategoria, out elencoSindacato, out msg);
                if (!string.IsNullOrEmpty(msg))
                    return false;

                elencoSindacato = Liquidazione.BLCommon.GestioneSindacati.GetElencoSindacatiAttivi(elencoSindacato, out msg);
                if (!string.IsNullOrEmpty(msg))
                    return false;

                int index = elencoSindacato.FindIndex(x => x.Id == sindacato.CodiceSindacato.Trim());
                if (index < 0)
                {
                    msg = "Il Sindacato attualmente salvato non è più attivo.";
                    return false;
                }
            }
            return true;
        }

        public static bool VerificaDecorrenzaOriginariaInabilitaCumulo(GestionePensione.DatiPensione datiPensione, bool? enteIstruttoreExInpdap, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (datiPensione.SiglaCategoria.Trim().ToUpperInvariant() == "IOCUM" && !enteIstruttoreExInpdap.GetValueOrDefault())
            {
                if (!Utility.DataSuccessivaA(datiPensione.DecorrenzaOriginaria.Value, Utility.FirstDayOfMonth(datiPensione.DataPresentazioneDomanda.AddMonths(1))))
                {
                    messaggioVideo = "La decorrenza originaria deve decorrere dal primo giorno del mese successivo alla data di presentazione (" +
                        String.Format("{0:dd/MM/yyyy}", Utility.FirstDayOfMonth(datiPensione.DataPresentazioneDomanda.AddMonths(1))) + ").";
                    return false;
                }
            }

            return true;
        }

        public static bool VerificaRequisitoEtaENAV(GestionePensione.DatiPensione datiPensione, DateTime? dataPerfezionamentoRequisiti, DateTime? dataNascitaTitolare, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            Utility.DifferenzaDateTime requisitoEta = new Utility.DifferenzaDateTime(60, 0, 0);
            if (Utility.IsDomandaVecchiaiaENAV(datiPensione))
            {
                Utility.DifferenzaDateTime diff = Utility.DifferenzaBetweenDate(dataPerfezionamentoRequisiti, dataNascitaTitolare, Utility.TipoAppartenenza.AGO);
                if (diff < requisitoEta)
                {
                    messaggioVideo = string.Format("Il titolare della domanda non ha compiuto {0} alla data di perfezionamento del requisito ({1:dd/MM/yyyy})", requisitoEta, dataPerfezionamentoRequisiti);
                    return false;
                }
            }
            return true;
        }
