        #region LiquidazionePensione
        private static bool ControlsPensioneAcquisibile(DateTime decorrenzaOriginaria, string siglaCategoria, char codNat1, GestionePensione.DatiPensione datiPensione,
            GestioneAnagrafica.DatiAnagrafici datiAnagrafici, byte? legge44997, Liquidazione.BLCommon.GestioneMaggiorazioniBenefici.DatiMaggiorazioniBenefici datiMaggiorazioniBenefici,
            Utility.TipoCalcolo tipoCalcolo)
        {
            byte codRequisitiRidotti = legge44997.GetValueOrDefault();
            DateTime dataNascita = datiAnagrafici != null ? datiAnagrafici.DataNascita.HasValue ? datiAnagrafici.DataNascita.Value : DateTime.MinValue : DateTime.MinValue;
            char sesso = datiAnagrafici != null ? datiAnagrafici.Sesso.HasValue ? datiAnagrafici.Sesso.Value : ' ' : ' ';
            int attivitaEconomica = datiPensione.AttivitaEconomica.HasValue ? datiPensione.AttivitaEconomica.Value : 0;
            int professioneIndividuale = datiPensione.ProfessioneIndividuale.HasValue ? datiPensione.ProfessioneIndividuale.Value : 0;
            byte codiceCieco = datiMaggiorazioniBenefici != null ? datiMaggiorazioniBenefici.CodiceCieco.HasValue ? datiMaggiorazioniBenefici.CodiceCieco.Value : (byte)0 : (byte)0;
            string tipoBeneficio = datiMaggiorazioniBenefici != null ? !string.IsNullOrEmpty(datiMaggiorazioniBenefici.TipoSettimaneBeneficio) ? datiMaggiorazioniBenefici.TipoSettimaneBeneficio : string.Empty : string.Empty;

            // Bypass controlli su finestre di pensionamento per invalidi al 80% - rif. "LiqPens AGO - Interventi Puntuali@20190806_v10.0.docx"
            if (codRequisitiRidotti == 6)
                return true;

            switch (siglaCategoria)
            {
                //Se la Categoria (RACATEG) è = a "VO", “VDAI” e il Codice Requisiti Ridotti
                //(RAUCODDIR) è = a “6” e la Decorrenza Originaria (RAU104) è compresa
                //tra febbraio 2008 e giugno 2008 e il 1° Codice Natura (RAU1031) è = a
                //spazio o “6” e la Data Nascita del pensionando (RADANAS) se maschio è
                //successiva al 31 dicembre 1947 la pensione è di vecchiaia soggetta alle
                //finestre di pensionamento
                //Se la Categoria (RACATEG) è = a "VO", “VDAI” e il Codice Requisiti Ridotti
                //(RAUCODDIR) è = a “6” e la Decorrenza Originaria (RAU104) è compresa
                //tra febbraio 2008 e giugno 2008 e il 1° Codice Natura (RAU1031) è = a
                //spazio o “6” e la Data Nascita del pensionando (RADANAS) se femmina è
                //successiva al 31 dicembre 1952 la pensione è di vecchiaia soggetta alle
                //finestre di pensionamento
                case "VO":
                case "VDAI":
                    if (codRequisitiRidotti == 6 && (codNat1 == ' ' || codNat1 == '6'))
                    {
                        if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 02, 01)) &&
                            !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 06, 01)))
                        {
                            if (sesso == 'M')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(dataNascita, new DateTime(1947, 12, 31)))
                                    return false;
                            }
                            else if (sesso == 'F')
