                    //Professione Individuale è = a “999” e la Decorrenza Originaria (RAU104) è
                    //compresa tra febbraio 2008 e giugno 2008 e il 1° Codice Natura (RAU1031)
                    //è = a spazio o “6” e la Data Nascita del pensionando (RADANAS) è
                    //successiva al 31 dicembre 1952 la pensione è di vecchiaia soggetta alle
                    //finestre di pensionamento
                    if (siglaCategoria == "VO")
                    {
                        if (attivitaEconomica == 52 && professioneIndividuale == 999 && (codNat1 == ' ' || codNat1 == '6'))
                        {
                            if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 02, 01)) &&
                                !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 06, 01)))
                            {
                                if (Utility.DataStrettamenteSuccessivaA(dataNascita, new DateTime(1952, 12, 31)))
                                    return false;
