                    break;

                default:
                    break;
            }

            switch (siglaCategoria)
            {
                case "VO":
                case "VOP":
                case "VOBANC":
                case "VDAI":
                    //Se la Categoria (RACATEG) è = a "VO", “VOP”, “VOBANC”, “VDAI” e il
                    //Codice Cieco ex-combattente (RAU206) è = a “1” e la Decorrenza Originaria
                    //(RAU104) è compresa tra febbraio 2008 e giugno 2008 e il 1° Codice Natura
                    //(RAU1031) è = a spazio o “6” e la Data Nascita del pensionando
                    //(RADANAS) se maschio è successiva al 31 dicembre 1952 la pensione è di
                    //vecchiaia soggetta alle finestre di pensionamento
                    //Se la Categoria (RACATEG) è = a "VO", “VOP”, “VOBANC”, “VDAI” e il
                    //Codice Cieco ex-combattente (RAU206) è = a “1” e la Decorrenza Originaria
                    //(RAU104) è compresa tra febbraio 2008 e giugno 2008 e il 1° Codice Natura
                    //(RAU1031) è = a spazio o “6” e la Data Nascita del pensionando
                    //(RADANAS) se femmina è successiva al 31 dicembre 1957 la pensione è di
                    //vecchiaia soggetta alle finestre di pensionamento
                    if (codiceCieco == 1 && (codNat1 == ' ' || codNat1 == '6'))
                    {
                        if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 02, 01)) &&
                                        !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 06, 01)))
                        {
                            if (sesso == 'M')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(dataNascita, new DateTime(1952, 12, 31)))
                                    return false;
                            }
                            else if (sesso == 'F')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(dataNascita, new DateTime(1957, 12, 31)))
                                    return false;
                            }
                        }
                    }
                    //Se la Categoria (RACATEG) è = a "VO", “VOP”, “VOBANC”, “VDAI” e il
                    //Codice Benefici particolari (COD-BEN-PAR) è = a “1” e la Decorrenza
                    //Originaria (RAU104) è compresa tra febbraio 2008 e giugno 2008 e il 1°
                    //Codice Natura (RAU1031) è = a spazio o “6” e la Data Nascita del
                    //pensionando (RADANAS) se maschio è successiva al 31 dicembre 1952 la
                    //pensione è di vecchiaia soggetta alle finestre di pensionamento
                    //Se la Categoria (RACATEG) è = a "VO", “VOP”, “VOBANC”, “VDAI” e il
                    //Codice Benefici particolari (COD-BEN-PAR) è = a “1” e la Decorrenza
                    //Originaria (RAU104) è compresa tra febbraio 2008 e giugno 2008 e il 1°
                    //Codice Natura (RAU1031) è = a spazio o “6” e la Data Nascita del
                    //pensionando (RADANAS) se femmina è successiva al 31 dicembre 1957 la
                    //pensione è di vecchiaia soggetta alle finestre di pensionamento
                    if (tipoBeneficio == "01" && (codNat1 == ' ' || codNat1 == '6'))
                    {
                        if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 02, 01)) &&
                                            !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 06, 01)))
                        {
                            if (sesso == 'M')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(dataNascita, new DateTime(1952, 12, 31)))
                                    return false;
                            }
                            else if (sesso == 'F')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(dataNascita, new DateTime(1957, 12, 31)))
                                    return false;
                            }
                        }
                    }
                    break;
                case "VR":
                case "VOART":
                case "VOCOM":
                    //Se la Categoria (RACATEG) è = a "VR", “VOART”, “VOCOM” e il Codice
                    //Cieco ex-combattente (RAU206) è = a “1” e la Decorrenza Originaria
                    //(RAU104) è compresa tra febbraio 2008 e giugno 2008 e il 1° Codice Natura
                    //(RAU1031) è = a spazio o “6” e la Data Nascita del pensionando
                    //(RADANAS) se maschio è successiva al 31 dicembre 1947 la pensione è di
                    //vecchiaia soggetta alle finestre di pensionamento
                    //Se la Categoria (RACATEG) è = a "VR", “VOART”, “VOCOM” e il Codice
                    //Cieco ex-combattente (RAU206) è = a “1” e la Decorrenza Originaria
                    //(RAU104) è compresa tra febbraio 2008 e giugno 2008 e il 1° Codice Natura
                    //(RAU1031) è = a spazio o “6” e la Data Nascita del pensionando
                    //(RADANAS) se femmina è successiva al 31 dicembre 1952 la pensione è di
                    //vecchiaia soggetta alle finestre di pensionamento
                    if (codiceCieco == 1 && (codNat1 == ' ' || codNat1 == '6'))
                    {
                        if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 02, 01)) &&
                                        !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 06, 01)))
                        {
                            if (sesso == 'M')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(dataNascita, new DateTime(1947, 12, 31)))
                                    return false;
                            }
                            else if (sesso == 'F')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(dataNascita, new DateTime(1952, 12, 31)))
                                    return false;
                            }
                        }
                    }
                    //Se la Categoria (RACATEG) è = a "VR", “VOART”, “VOCOM” e il Codice
                    //Benefici particolari (COD-BEN-PAR) è = a “1” e la Decorrenza Originaria
                    //(RAU104) è compresa tra febbraio 2008 e giugno 2008 e il 1° Codice Natura
                    //(RAU1031) è = a spazio o “6” e la Data Nascita del pensionando
                    //(RADANAS) se maschio è successiva al 31 dicembre 1947 la pensione è di
                    //vecchiaia soggetta alle finestre di pensionamento
                    //Se la Categoria (RACATEG) è = a "VR", “VOART”, “VOCOM” e il Codice
                    //Benefici particolari (COD-BEN-PAR) è = a “1” e la Decorrenza Originaria
                    //(RAU104) è compresa tra febbraio 2008 e giugno 2008 e il 1° Codice Natura
                    //(RAU1031) è = a spazio o “6” e la Data Nascita del pensionando
                    //(RADANAS) se femmina è successiva al 31 dicembre 1952 la pensione è di
                    //vecchiaia soggetta alle finestre di pensionamento
                    if (tipoBeneficio == "01" && (codNat1 == ' ' || codNat1 == '6'))
                    {
                        if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 02, 01)) &&
                                            !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 06, 01)))
                        {
                            if (sesso == 'M')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(dataNascita, new DateTime(1947, 12, 31)))
                                    return false;
                            }
                            else if (sesso == 'F')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(dataNascita, new DateTime(1952, 12, 31)))
                                    return false;
                            }
                        }
                    }
                    break;
                default:
                    break;
            }

            //Se il Campo RINSIEME (Tipo Calcolo) è = a “SI” e il 1° carattere della
            //Categoria (RACATEG) è = a “V” e la Decorrenza Originaria (RAU104) è
            //compresa tra febbraio 2008 e giugno 2008 e il 1° Codice Natura (RAU1031)
            //è = a spazio o “6” e la Data Nascita del pensionando (RADANAS) è
            //successiva al 31 dicembre 1950 la pensione è di vecchiaia soggetta alle
            //finestre di pensionamento
            if (siglaCategoria.StartsWith("V") && (codNat1 == ' ' || codNat1 == '6') && tipoCalcolo == Utility.TipoCalcolo.Contributivo)
            {
                if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 02, 01)) &&
                                    !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 06, 01)))
                {
                    if (Utility.DataStrettamenteSuccessivaA(dataNascita, new DateTime(1950, 12, 31)))
                        return false;
                }
            }


            //controlli finali
            switch (siglaCategoria)
            {
                //Se la Categoria (RACATEG) è = a “VO”, “VOP”, "VR", "VOART", "VOCOM",
                //"VOBANC", "VDAI" e la Decorrenza Originaria (RAU104) è compresa tra
                //febbraio 2008 e giugno 2008 e il 1° Codice Natura (RAU1031) è = a spazio o
                //“6” e la Data Nascita del pensionando (RADANAS) se maschio è successiva
                //al 31 dicembre 1942 la pensione è di vecchiaia soggetta alle finestre di
                //pensionamento
                //Se la Categoria (RACATEG) è = a “VO”, “VOP”, "VR", "VOART", "VOCOM",
                //"VOBANC", "VDAI" e la Decorrenza Originaria (RAU104) è compresa tra
                //febbraio 2008 e giugno 2008 e il 1° Codice Natura (RAU1031) è = a spazio o
                //“6” e la Data Nascita del pensionando (RADANAS) se femmina è successiva
                //al 31 dicembre 1947 la pensione è di vecchiaia soggetta alle finestre di
                //pensionamento
                case "VO":
                case "VOP":
                case "VR":
                case "VOART":
                case "VOCOM":
                case "VOBANC":
                case "VDAI":
                    if (codNat1 == ' ' || codNat1 == '6')
                    {
                        if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 02, 01)) &&
                                        !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 06, 01)))
                        {
                            if (sesso == 'M')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(dataNascita, new DateTime(1942, 12, 31)))
                                    return false;
                            }
                            else if (sesso == 'F')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(dataNascita, new DateTime(1947, 12, 31)))
                                    return false;
                            }
                        }
                    }
                    break;
                case "VOMIN":
                    //Se la Categoria (RACATEG) è = a “VOMIN” e la Decorrenza Originaria
                    //(RAU104) è compresa tra febbraio 2008 e giugno 2008 e il 1° Codice Natura
                    //(RAU1031) è = a spazio e la Data Nascita del pensionando (RADANAS) sè
                    //successiva al 31 dicembre 1952 la pensione è di vecchiaia soggetta alle
                    //finestre di pensionamento
                    if (codNat1 == ' ')
                    {
                        if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 02, 01)) &&
                                            !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 06, 01)))
                        {
                            if (Utility.DataStrettamenteSuccessivaA(dataNascita, new DateTime(1952, 12, 31)))
                                return false;
                        }
                    }

                    //Se la Categoria (RACATEG) è = a “VOMIN” e la Decorrenza Originaria
                    //(RAU104) è compresa tra febbraio 2008 e giugno 2008 e il 1° Codice Natura
                    //(RAU1031) è = a “6” e la Data Nascita del pensionando (RADANAS) sè
                    //successiva al 31 dicembre 1947 la pensione è di vecchiaia soggetta alle
                    //finestre di pensionamento
                    if (codNat1 == '6')
                    {
                        if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 02, 01)) &&
                                            !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 06, 01)))
                        {
                            if (Utility.DataStrettamenteSuccessivaA(dataNascita, new DateTime(1947, 12, 31)))
                                return false;
                        }
                    }
                    break;
                case "VOAUT":
                    //Se la Categoria (RACATEG) è = a “VOAUT” e la Decorrenza Originaria
                    //(RAU104) è compresa tra febbraio 2008 e giugno 2008 e il 1° Codice Natura
                    //(RAU1031) è = a spazio o “6” e la Data Nascita del pensionando
                    //(RADANAS) sè successiva al 31 dicembre 1950 la pensione è di vecchiaia
                    //soggetta alle finestre di pensionamento
                    if (codNat1 == ' ' || codNat1 == '6')
                    {
                        if (Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 02, 01)) &&
                                            !Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2008, 06, 01)))
                        {
                            if (Utility.DataStrettamenteSuccessivaA(dataNascita, new DateTime(1950, 12, 31)))
                                return false;
                        }
                    }
                    break;
                default:
                    break;
            }

            return true;
        }

        private static bool ControlsEtaPensionamento(string siglaCategoria, char codNat1, GestionePensione.DatiPensione datiPensione, GestioneAnagrafica.DatiAnagrafici datiAnagrafici, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            char sesso = datiAnagrafici != null ? datiAnagrafici.Sesso.HasValue ? datiAnagrafici.Sesso.Value : ' ' : ' ';

            //Se il 1° Codice Natura è = a “5” e se la Data Domanda (RAUE24) è
            //successiva al 31 dicembre 2011 e la Data Perfezionamento Requisiti è
            //successiva al 31 dicembre 2011:
            if (codNat1 == '5' &&
                Utility.DataStrettamenteSuccessivaA(datiPensione.DataPresentazioneDomanda, new DateTime(2011, 12, 31)) &&
                datiPensione.DataPerfezionamentoRequisiti.HasValue && Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2011, 12, 31)) &&
                datiAnagrafici != null)
            {
                switch (siglaCategoria)
                {

                    case "VO":
                    case "VOBANC":
                    case "VDAI":
                        //Se la Categoria (RACATEG) è = a “VO”, “VOBANC”, “VDAI” e la
                        //data perfezionamento requisiti (RAU104) è compresa tra gennaio 2012 e
                        //dicembre 2012 ed è femmina il pensionando deve aver compiuto 62
                        //anni alla data perfezionamento requisiti
                        if (Utility.DataSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2012, 01, 01)) &&
                            !Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2012, 12, 01)))
                        {
                            if (sesso == 'F')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(62), datiPensione.DataPerfezionamentoRequisiti.Value))
                                {
                                    messaggioVideo = "Il pensionando deve aver compiuto 62 anni alla data perfezionamento requisiti";
                                    return false;
                                }
                            }
                        }
                        //Se la Categoria (RACATEG) è = a “VO”, “VOBANC”, “VDAI” e la
                        //data perfezionamento requisiti (RAU104) è compresa tra gennaio 2013 e
                        //dicembre 2013 ed è femmina il pensionando deve aver compiuto 62
                        //anni e 3 mesi alla data perfezionamento requisiti
                        if (Utility.DataSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2013, 01, 01)) &&
                            !Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2013, 12, 01)))
                        {
                            if (sesso == 'F')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(62).AddMonths(3), datiPensione.DataPerfezionamentoRequisiti.Value))
                                {
                                    messaggioVideo = "Il pensionando deve aver compiuto 62 anni e 3 mesi alla data perfezionamento requisiti";
                                    return false;
                                }
                            }
                        }
                        //Se la Categoria (RACATEG) è = a “VO”, “VOBANC”, “VDAI” e la
                        //data perfezionamento requisiti (RAU104) è compresa tra gennaio 2014 e
                        //dicembre 2015 ed è femmina il pensionando deve aver compiuto 63
                        //anni e 9 mesi alla data perfezionamento requisiti
                        if (Utility.DataSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2014, 01, 01)) &&
                            !Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2015, 12, 01)))
                        {
                            if (sesso == 'F')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(63).AddMonths(9), datiPensione.DataPerfezionamentoRequisiti.Value))
                                {
                                    messaggioVideo = "Il pensionando deve aver compiuto 63 anni e 9 mesi alla data perfezionamento requisiti";
                                    return false;
                                }
                            }
                        }

                        //Se la Categoria (RACATEG) è = a “VO”, “VOBANC”, “VDAI” e la
                        //data perfezionamento requisiti (RAU104) è compresa tra gennaio 2012 e
                        //dicembre 2012 ed è maschio il pensionando deve aver compiuto 66
                        //anni alla data perfezionamento requisiti
                        if (Utility.DataSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2012, 01, 01)) &&
                            !Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2012, 12, 01)))
                        {
                            if (sesso == 'M')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(66), datiPensione.DataPerfezionamentoRequisiti.Value))
                                {
                                    messaggioVideo = "Il pensionando deve aver compiuto 66 anni alla data perfezionamento requisiti";
                                    return false;
                                }
                            }
                        }

                        //Se la Categoria (RACATEG) è = a “VO”, “VOBANC”, “VDAI” e la
                        //data perfezionamento requisiti (RAU104) è compresa tra gennaio 2013 e
                        //dicembre 2015 ed è maschio il pensionando deve aver compiuto 66
                        //anni e 3 mesi alla data perfezionamento requisiti
                        if (Utility.DataSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2013, 01, 01)) &&
                            !Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2015, 12, 01)))
                        {
                            if (sesso == 'M')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(66).AddMonths(3), datiPensione.DataPerfezionamentoRequisiti.Value))
                                {
                                    messaggioVideo = "Il pensionando deve aver compiuto 66 anni e 3 mesi alla data perfezionamento requisiti";
                                    return false;
                                }
                            }
                        }
                        break;
                    case "VR":
                    case "VOART":
                    case "VOCOM":
                        //Se la Categoria (RACATEG) è = a “VR”, “VOART”, “VOCOM”,
                        //“VOAUT” e la data perfezionamento requisiti è compresa tra gennaio
                        //2012 e dicembre 2012 ed è femmina il pensionando deve aver
                        //compiuto 63 anni e 6 mesi alla data perfezionamento requisiti
                        if (Utility.DataSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2012, 01, 01)) &&
                            !Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2012, 12, 01)))
                        {
                            if (sesso == 'F')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(63).AddMonths(6), datiPensione.DataPerfezionamentoRequisiti.Value))
                                {
                                    messaggioVideo = "Il pensionando deve aver compiuto 63 anni e 6 mesi alla data perfezionamento requisiti";
                                    return false;
                                }
                            }
                        }
                        //Se la Categoria (RACATEG) è = a ““VR”, “VOART”, “VOCOM”,
                        //“VOAUT” e la data perfezionamento requisiti è compresa tra
                        //gennaio 2013 e dicembre 2013 ed è femmina il pensionando deve aver
                        //compiuto 3 anni e 9 mesi alla data perfezionamento requisiti
                        if (Utility.DataSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2013, 01, 01)) &&
                            !Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2013, 12, 01)))
                        {
                            if (sesso == 'F')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(63).AddMonths(9), datiPensione.DataPerfezionamentoRequisiti.Value))
                                {
                                    messaggioVideo = "Il pensionando deve aver compiuto 63 anni e 9 mesi alla data perfezionamento requisiti";
                                    return false;
                                }
                            }
                        }
                        //Se la Categoria (RACATEG) è = a “VR”, “VOART”, “VOCOM”,
                        //“VOAUT” e la data perfezionamento requisiti (RAU104) è compresa tra
                        //gennaio 2014 e dicembre 2015 ed è femmina il pensionando deve aver
                        //compiuto 64 anni e 9 mesi alla data perfezionamento requisiti
                        if (Utility.DataSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2014, 01, 01)) &&
                            !Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2015, 12, 01)))
                        {
                            if (sesso == 'F')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(64).AddMonths(9), datiPensione.DataPerfezionamentoRequisiti.Value))
                                {
                                    messaggioVideo = "Il pensionando deve aver compiuto 64 anni e 9 mesi alla data perfezionamento requisiti";
                                    return false;
                                }
                            }
                        }
                        //Se la Categoria (RACATEG) è = a “VR”, “VOART”, “VOCOM”,
                        //“VOAUT” e la data perfezionamento requisiti (RAU104) è compresa tra
                        //gennaio 2012 e dicembre 2012 ed è maschio il pensionando deve aver
                        //compiuto 66 anni alla data perfezionamento requisiti
                        if (Utility.DataSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2012, 01, 01)) &&
                            !Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2012, 12, 01)))
                        {
                            if (sesso == 'M')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(66), datiPensione.DataPerfezionamentoRequisiti.Value))
                                {
                                    messaggioVideo = "Il pensionando deve aver compiuto 66 anni alla data perfezionamento requisiti";
                                    return false;
                                }
                            }
                        }
                        //Se la Categoria (RACATEG) è = a “VR”, “VOART”, “VOCOM”,
                        //“VOAUT” e la data perfezionamento requisiti (RAU104) è compresa tra
                        //gennaio 2013 e dicembre 2015 ed è maschio il pensionando deve aver
                        //compiuto 66 anni e 3 mesi alla data perfezionamento requisiti
                        if (Utility.DataSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2013, 01, 01)) &&
                            !Utility.DataStrettamenteSuccessivaA(datiPensione.DataPerfezionamentoRequisiti.Value, new DateTime(2015, 12, 01)))
                        {
                            if (sesso == 'M')
                            {
                                if (Utility.DataStrettamenteSuccessivaA(datiAnagrafici.DataNascita.Value.AddYears(66).AddMonths(3), datiPensione.DataPerfezionamentoRequisiti.Value))
                                {
                                    messaggioVideo = "Il pensionando deve aver compiuto 66 anni e 3 mesi alla data perfezionamento requisiti";
                                    return false;
                                }
                            }
                        }
                        break;
                }
            }

            return true;
        }

        //Il Codice Requisito Ridotto (RAUCODDIR) e il Codice Mobilità
        //(RAUCODMOB) sono alternativi
        private static bool ControlsCodReqRid_CodMob(byte? codiceRequisitiRidotti, byte? codiceMobilita, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (codiceRequisitiRidotti.HasValue && codiceMobilita.HasValue)
            {
                messaggioVideo = "Il codice requisiti ridotti e il codice mobilità sono alternativi";
                return false;
            }

            return true;
        }

        //Se il campo DO-NOTE è = a “LSU”, “LS1”, “LS2” e il 1° Codice Natura è = a
        //spazio, “1”, “2”, “6” e il 3° Codice Natura è = a “L” l'Attività Economica
        //(RAU1013) deve essere = a “98”
        private static bool ControlsNatura_AttEc(char codNat1, char codNat3, string filtro, int? attivitaEconomica, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            switch (filtro)
            {
                case "LSU":
                case "LS1":
                case "LS2":
                    switch (codNat1)
                    {
                        case ' ':
                        case '1':
                        case '2':
                        case '6':
                            if (codNat3 == 'L')
                            {
                                if (attivitaEconomica.GetValueOrDefault() != 98)
                                {
                                    messaggioVideo = "L'attività economica deve essere uguale a 98 in funzione dei codici natura acquisiti";
                                    return false;
                                }
                            }
                            break;
                        default:
                            break;
                    }
                    break;
                default:
                    break;
            }

            return true;
        }

        //Se il campo DO-NOTE è = a “LSU”, “LS1”, “LS2” e il 1° Codice Natura è = a
        //spazio, “1”, “2”, “6” e il 3° Codice Natura è = a “L” la Professione Individuale deve essere =
        //a“176”
        private static bool ControlsNatura_ProfInd(char codNat1, char codNat3, string filtro, int? professioneIndividuale, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            switch (filtro)
            {
                case "LSU":
                case "LS1":
                case "LS2":
                    switch (codNat1)
                    {
                        case ' ':
                        case '1':
                        case '2':
                        case '6':
                            if (codNat3 == 'L')
                            {
                                if (!professioneIndividuale.HasValue || professioneIndividuale.Value != 176)
                                {
                                    messaggioVideo = "La professione individuale deve essere uguale a 176 in funzione dei codici natura inseriti";
                                    return false;
                                }
                            }
                            break;
                        default:
                            break;
                    }
                    break;
                default:
                    break;
            }

            return true;
        }

        private static bool ControlsDA(GestioneDanteCausa.DatiDanteCausa datiDA, DateTime decorrenzaOriginaria, int? attivitaEconomica, int? professioneIndividuale, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (datiDA != null)
            {
                //Se il Codice Provenienza (DAU107) è = a 1 o 2 e il Codice Attività
                //Economica (RAU1013) e il Codice Professione Individuale (RAU1014) sono
                //rispettivamente 3 e 326 o 3 e 350 la Decorrenza Originaria della Diretta
                //(DAU106) non può essere inferiore a novembre 2003
                if (datiDA.ProvenienzaPensione.HasValue &&
                    (datiDA.ProvenienzaPensione.Value == 1 || datiDA.ProvenienzaPensione.Value == 2))
                {
                    if (attivitaEconomica.HasValue && attivitaEconomica.Value == 3 &&
                        professioneIndividuale.HasValue && (professioneIndividuale.Value == 326 || professioneIndividuale.Value == 350))
                    {
                        if (datiDA.DecorrenzaPensione.HasValue && !Utility.DataSuccessivaA(datiDA.DecorrenzaPensione.Value, new DateTime(2003, 11, 1)))
                        {
                            messaggioVideo = "La decorrenza originaria della diretta non può essere inferiore a novembre 2003";
                            return false;
                        }
                    }
                    //Se il Codice Provenienza (DAU107) è = a 1 o 2 e il Codice Attività
                    //Economica (RAU1013) e il Codice Professione Individuale (RAU1014) sono
                    //rispettivamente 9 e 257 la Decorrenza Originaria della Diretta (DAU106) non
                    //può essere successiva ad ottobre 2003
                    if (attivitaEconomica.HasValue && attivitaEconomica.Value == 9 &&
                        professioneIndividuale.HasValue && professioneIndividuale.Value == 257)
                    {
                        if (datiDA.DecorrenzaPensione.HasValue && Utility.DataStrettamenteSuccessivaA(datiDA.DecorrenzaPensione.Value, new DateTime(2003, 10, 31)))
                        {
                            messaggioVideo = "La decorrenza originaria della diretta non può essere successiva ad ottobre 2003";
                            return false;
                        }
                    }
                }
                else
                {
                    //Se il Codice Provenienza (DAU107) è diverso da 1 o 2 e il Codice Attività
                    //Economica (RAU1013) e il Codice Professione Individuale (RAU1014) sono
                    //rispettivamente 3 e 326 o 3 e 350 la Decorrenza Originaria (RAU104) non
                    //può essere inferiore a novembre 2003
                    if (attivitaEconomica.HasValue && attivitaEconomica.Value == 3 &&
                        professioneIndividuale.HasValue && (professioneIndividuale.Value == 326 || professioneIndividuale.Value == 350))
                    {
                        if (!Utility.DataSuccessivaA(decorrenzaOriginaria, new DateTime(2003, 11, 1)))
                        {
                            messaggioVideo = "La decorrenza originaria  non può essere inferiore a novembre 2003";
                            return false;
                        }
                    }
                    //Se il Codice Provenienza (DAU107) è diverso da 1 o 2 e il Codice Attività
                    //Economica (RAU1013) e il Codice Professione Individuale (RAU1014) sono
                    //rispettivamente 9 e 257 la Decorrenza Originaria (RAU104) non può essere
                    //successiva ad ottobre 2003
                    if (attivitaEconomica.HasValue && attivitaEconomica.Value == 9 &&
                        professioneIndividuale.HasValue && professioneIndividuale.Value == 257)
                    {
                        if (Utility.DataStrettamenteSuccessivaA(decorrenzaOriginaria, new DateTime(2003, 10, 31)))
                        {
                            messaggioVideo = "La decorrenza originaria della diretta non può essere successiva ad ottobre 2003";
                            return false;
                        }
                    }
                }

            }

            return true;
        }
