        private static string GetGestioneRetributiva(long? codiceGestione, List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> listaCodeGestioneCalcoloRetributivo)
        {
            if (listaCodeGestioneCalcoloRetributivo != null)
            {
                GestioneDecodifica.CodeGestioneCalcoloRetributivo gestione = listaCodeGestioneCalcoloRetributivo.Find(x => x.Id == codiceGestione);
                if (gestione != null)
                    return gestione.TraduzioneSuGP.Trim().ToUpperInvariant();
            }
            return string.Empty;
        }

        private static long GetIdGestioneRetributiva(string codiceGestioneTraduzioneSuGP)
        {
            List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> listaCodeGestioneCalcoloRetributivo = null;
            GestioneDecodifica.GetCodeGestioneCalcoloRetributivo(out listaCodeGestioneCalcoloRetributivo);
            if (listaCodeGestioneCalcoloRetributivo != null)
            {
                GestioneDecodifica.CodeGestioneCalcoloRetributivo gestione = listaCodeGestioneCalcoloRetributivo.Find(x => x.TraduzioneSuGP == codiceGestioneTraduzioneSuGP);
                if (gestione != null)
                    return gestione.Id;
            }
            return 0;
        }


