        internal static void OrdinaDatiRetributivi(GestionePensione.DatiPensione datiPensione, List<GestioneAggiornamentoPECO.DatiRetributivi> datiRetr,
            DateTime? decorrenzaOpzione, List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> listaCodeGestioneCalcoloRetributivo, GestioneDanteCausa.DatiDanteCausa datiDanteCausa,
            GestioneDatiControlloFelpe.ControlloFelpe datiControlloFelpe, List<Liquidazione.BLCommon.CtrlDecorrenzaRetrExINPDAI> elencoCtrlDecorrenzaRetrExINPDAI,
            out List<GestioneAggiornamentoPECO.DatiRetributivi> datiRetrOrdered)
        {
            List<GestioneCalcolo.DatiCalcoloRetributivo> ldatiRetributivi = GestioneContrib.MappingDatiRetributiviFromViewToBL(datiRetr);
            List<GestioneCalcolo.DatiCalcoloRetributivo> ldatiRetributiviOrdered = null;

            List<short> mesiDecDatiRetr = new List<short>();
            List<short> anniDecDatiRetr = new List<short>();
            if (ldatiRetributivi != null)
            {
                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in ldatiRetributivi)
                {
                    short mese = 0;
                    short anno = 0;
                    MappingVersoHost.GetDecorrenzaRetr(GetGestioneRetributiva(r.CodiceGestione, listaCodeGestioneCalcoloRetributivo),
                        r.QuotePrimeLiquidate.HasValue ? r.QuotePrimeLiquidate.Value : ' ', r.CodiceTipoQuota, datiPensione, datiDanteCausa, datiControlloFelpe, elencoCtrlDecorrenzaRetrExINPDAI,
                        decorrenzaOpzione, r.DecorrenzaOriginariaPensione.HasValue ? new Utility.DifferenzaDateTime(r.DecorrenzaOriginariaPensione.Value) : null, r.RMS, out mese, out anno);
                    mesiDecDatiRetr.Add(mese);
                    anniDecDatiRetr.Add(anno);
                }

                var IsAnte96 = Utility.IsDomandaAnte96(datiPensione, datiPensione, datiDanteCausa, Utility.IsRiaperturaDomanda(datiPensione.Id));
                if (IsAnte96 == null)
                    OrdinaDatiRetributivi(datiPensione, ldatiRetributivi, mesiDecDatiRetr, listaCodeGestioneCalcoloRetributivo, out ldatiRetributiviOrdered);
                else
                    ldatiRetributiviOrdered = ldatiRetributivi;

            }

            datiRetrOrdered = GestioneContrib.MappingDatiRetributiviFromBLToView(ldatiRetributiviOrdered);
        }

        private static void OrdinaDatiRetributivi(GestionePensione.DatiPensione datiPensione, List<GestioneCalcolo.DatiCalcoloRetributivo> datiRetr, List<short> mesiDecDatiRetr,
            List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> listaCodeGestioneCalcoloRetributivo, out List<GestioneCalcolo.DatiCalcoloRetributivo> datiRetrOrdered)
        {
            if (Utility.IsDomandaINPDAI(datiPensione.SiglaCategoria))
                OrdinaDatiRetributiviINPDAI(datiRetr, mesiDecDatiRetr, listaCodeGestioneCalcoloRetributivo, out datiRetrOrdered);
            else
                OrdinaDatiRetributiviAGO(datiPensione.Id, datiRetr, mesiDecDatiRetr, listaCodeGestioneCalcoloRetributivo, out datiRetrOrdered);
        }

        private static void OrdinaDatiRetributiviAGO(long idPensione, List<GestioneCalcolo.DatiCalcoloRetributivo> datiRetr, List<short> mesiDecDatiRetr,
            List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> listaCodeGestioneCalcoloRetributivo, out List<GestioneCalcolo.DatiCalcoloRetributivo> datiRetrOrdered)
        {
            datiRetrOrdered = new List<GestioneCalcolo.DatiCalcoloRetributivo>();

            List<GestioneCalcolo.DatiCalcoloRetributivo> datiRetrApp = null;

            //Si ordina la tabella RETRIB nella sequenza che segue: (PNLCR51 all'etichetta SORTA-DATI.) 
            //VRGEST =  a “S” 
            //VRGEST = a “1” e VRQUOTA = a “A” e VRDECMM diverso dalla codifica 61, 62, 63, 64, 65, 71 
            //VRGEST = a ”Q” e VRQUOTA = a “A” e VRDECMM diverso dalla codifica 61, 62, 63, 64, 65, 71 
            //VRGEST = a “1H” e VRQUOTA = a “A” e VRDECMM diverso dalla codifica 61, 62, 63, 64, 65, 71 
            //VRGEST = a "1H" e VRQUOTA = a "B" allora se non esiste un record con VRGEST = a "1" o "1H" e VRQUOTA = a "A" allora inserisci il record di quota fittizia A è composto 
            // da VRGEST = a ‘1’ VRQUOTA = a ‘A’ VRDEC = a RAU104, VRSET = a 1 e VRRETR = a 0.004.
            //VRGEST = “1” e VRQUOTA = a “B” e VRDECMM = a 61 
            //VRGEST = “Q” e VRQUOTA = a “B” e VRDECMM = a 61 
            //VRGEST = “1H” e VRQUOTA = a “B” e VRDECMM = a 61 
            //VRDECMM = a 62 
            //VRDECMM = a 63 
            //VRDECMM = a 64 
            //VRDECMM = a 65 
            //VRGEST = a “1” e VRDECMM = a 71 
            //VRGEST = a “1H” e VRDECMM = a 71 
            //VRGEST = a “Q” e VRDECMM = a 71 
            //VRDECMM = a 72 
            //VRDECMM = a 73 
            //VRDECMM = a 74 
            //VRDECMM = a 75 
            //VRDECMM = a 98 
            //VRDECMM = a 99

            datiRetrApp = datiRetr.FindAll(x => GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "S");
            if (datiRetrApp != null && datiRetrApp.Count > 0)
            {
                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrApp)
                {
                    datiRetrOrdered.Add(r);
                }
            }

            datiRetrApp = new List<GestioneCalcolo.DatiCalcoloRetributivo>();
            for (int i = 0; i < datiRetr.Count; i++)
            {
                if (GetGestioneRetributiva(datiRetr[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "P" &&
                    datiRetr[i].QuotePrimeLiquidate.HasValue && datiRetr[i].QuotePrimeLiquidate.Value == 'A' &&
                    mesiDecDatiRetr[i] != 61 && mesiDecDatiRetr[i] != 62 && mesiDecDatiRetr[i] != 63 &&
                    mesiDecDatiRetr[i] != 64 && mesiDecDatiRetr[i] != 65 && mesiDecDatiRetr[i] != 71)
                {
                    datiRetrApp.Add(datiRetr[i]);
                }
            }
            if (datiRetrApp != null && datiRetrApp.Count > 0)
            {
                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrApp)
                {
                    datiRetrOrdered.Add(r);
                }
            }

            datiRetrApp = new List<GestioneCalcolo.DatiCalcoloRetributivo>();
            for (int i = 0; i < datiRetr.Count; i++)
            {
                if (GetGestioneRetributiva(datiRetr[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1" &&
                    datiRetr[i].QuotePrimeLiquidate.HasValue && datiRetr[i].QuotePrimeLiquidate.Value == 'A' &&
                    mesiDecDatiRetr[i] != 61 && mesiDecDatiRetr[i] != 62 && mesiDecDatiRetr[i] != 63 &&
                    mesiDecDatiRetr[i] != 64 && mesiDecDatiRetr[i] != 65 && mesiDecDatiRetr[i] != 71)
                {
                    datiRetrApp.Add(datiRetr[i]);
                }
            }
            if (datiRetrApp != null && datiRetrApp.Count > 0)
            {
                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrApp)
                {
                    datiRetrOrdered.Add(r);
                }
            }

            datiRetrApp = new List<GestioneCalcolo.DatiCalcoloRetributivo>();
            for (int i = 0; i < datiRetr.Count; i++)
            {
                if (GetGestioneRetributiva(datiRetr[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "Q" &&
                    datiRetr[i].QuotePrimeLiquidate.HasValue && datiRetr[i].QuotePrimeLiquidate.Value == 'A' &&
                    mesiDecDatiRetr[i] != 61 && mesiDecDatiRetr[i] != 62 && mesiDecDatiRetr[i] != 63 &&
                    mesiDecDatiRetr[i] != 64 && mesiDecDatiRetr[i] != 65 && mesiDecDatiRetr[i] != 71)
                {
                    datiRetrApp.Add(datiRetr[i]);
                }
            }
            if (datiRetrApp != null && datiRetrApp.Count > 0)
            {
                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrApp)
                {
                    datiRetrOrdered.Add(r);
                }
            }

            datiRetrApp = new List<GestioneCalcolo.DatiCalcoloRetributivo>();
            for (int i = 0; i < datiRetr.Count; i++)
            {
                if (GetGestioneRetributiva(datiRetr[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1H" &&
                    datiRetr[i].QuotePrimeLiquidate.HasValue && datiRetr[i].QuotePrimeLiquidate.Value == 'A' &&
                    mesiDecDatiRetr[i] != 61 && mesiDecDatiRetr[i] != 62 && mesiDecDatiRetr[i] != 63 &&
                    mesiDecDatiRetr[i] != 64 && mesiDecDatiRetr[i] != 65 && mesiDecDatiRetr[i] != 71)
                {
                    datiRetrApp.Add(datiRetr[i]);
                }
            }
            if (datiRetrApp != null && datiRetrApp.Count > 0)
            {
                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrApp)
                {
                    datiRetrOrdered.Add(r);
                }
            }

            datiRetrApp = new List<GestioneCalcolo.DatiCalcoloRetributivo>();
            for (int i = 0; i < datiRetr.Count; i++)
            {
                if (GetGestioneRetributiva(datiRetr[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1H" &&
                    datiRetr[i].QuotePrimeLiquidate.HasValue && datiRetr[i].QuotePrimeLiquidate.Value == 'B')
                {
                    bool flag = false;
                    for (int j = 0; j < datiRetr.Count; j++)
                    {
                        if ((GetGestioneRetributiva(datiRetr[j].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1H" || GetGestioneRetributiva(datiRetr[j].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1") &&
                            datiRetr[j].QuotePrimeLiquidate.HasValue && datiRetr[j].QuotePrimeLiquidate.Value == 'A')
                        {
                            flag = true;
                            break;
                        }
                    }
                    if (!flag)
                    {
                        GestioneCalcolo.DatiCalcoloRetributivo retrApp = new GestioneCalcolo.DatiCalcoloRetributivo();
                        retrApp.CodiceGestione = GetIdGestioneRetributiva("1");
                        retrApp.QuotePrimeLiquidate = 'A';
                        retrApp.NSettimaneQuotaA = 1;
                        retrApp.RMSQuotaA = 0.004M;
                        retrApp.IdPensione = idPensione;
                        datiRetrApp.Add(retrApp);
                    }
                }
            }
            if (datiRetrApp != null && datiRetrApp.Count > 0)
            {
                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrApp)
                {
                    datiRetrOrdered.Add(r);
                }
            }

            datiRetrApp = new List<GestioneCalcolo.DatiCalcoloRetributivo>();
            for (int i = 0; i < datiRetr.Count; i++)
            {
                if (GetGestioneRetributiva(datiRetr[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "P" &&
                    datiRetr[i].QuotePrimeLiquidate.HasValue && datiRetr[i].QuotePrimeLiquidate.Value == 'B' &&
                    mesiDecDatiRetr[i] == 61)
                {
                    datiRetrApp.Add(datiRetr[i]);
                }
            }
            if (datiRetrApp != null && datiRetrApp.Count > 0)
            {
                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrApp)
                {
                    datiRetrOrdered.Add(r);
                }
            }

            datiRetrApp = new List<GestioneCalcolo.DatiCalcoloRetributivo>();
            for (int i = 0; i < datiRetr.Count; i++)
            {
                if (GetGestioneRetributiva(datiRetr[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1" &&
                    datiRetr[i].QuotePrimeLiquidate.HasValue && datiRetr[i].QuotePrimeLiquidate.Value == 'B' &&
                    mesiDecDatiRetr[i] == 61)
                {
                    datiRetrApp.Add(datiRetr[i]);
                }
            }
            if (datiRetrApp != null && datiRetrApp.Count > 0)
            {
                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrApp)
                {
                    datiRetrOrdered.Add(r);
                }
            }

            datiRetrApp = new List<GestioneCalcolo.DatiCalcoloRetributivo>();
            for (int i = 0; i < datiRetr.Count; i++)
            {
                if (GetGestioneRetributiva(datiRetr[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "Q" &&
                    datiRetr[i].QuotePrimeLiquidate.HasValue && datiRetr[i].QuotePrimeLiquidate.Value == 'B' &&
                    mesiDecDatiRetr[i] == 61)
                {
                    datiRetrApp.Add(datiRetr[i]);
                }
            }
            if (datiRetrApp != null && datiRetrApp.Count > 0)
            {
                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrApp)
                {
                    datiRetrOrdered.Add(r);
                }
            }

            datiRetrApp = new List<GestioneCalcolo.DatiCalcoloRetributivo>();
            for (int i = 0; i < datiRetr.Count; i++)
            {
                if (GetGestioneRetributiva(datiRetr[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1H" &&
                    datiRetr[i].QuotePrimeLiquidate.HasValue && datiRetr[i].QuotePrimeLiquidate.Value == 'B' &&
                    mesiDecDatiRetr[i] == 61)
                {
                    datiRetrApp.Add(datiRetr[i]);
                }
            }
            if (datiRetrApp != null && datiRetrApp.Count > 0)
            {
                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrApp)
                {
                    datiRetrOrdered.Add(r);
                }
            }

            datiRetrApp = new List<GestioneCalcolo.DatiCalcoloRetributivo>();
            for (int i = 0; i < datiRetr.Count; i++)
            {
                if (mesiDecDatiRetr[i] == 62)
                {
                    datiRetrApp.Add(datiRetr[i]);
                }
            }
            if (datiRetrApp != null && datiRetrApp.Count > 0)
            {
