                    datiRetrApp.Add(datiRetr[i]);
                }
            }

            if (datiRetrApp != null && datiRetrApp.Count > 0)
            {
                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrApp)
                {
                    datiRetrOrdered.Add(r);
                }
            }

            datiRetrApp = new List<GestioneCalcolo.DatiCalcoloRetributivo>();
            for (int i = 0; i < datiRetr.Count; i++)
            {
                if (GetGestioneRetributiva(datiRetr[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "O" &&
                    datiRetr[i].QuotePrimeLiquidate.HasValue && datiRetr[i].QuotePrimeLiquidate.Value == 'A' &&
                    mesiDecDatiRetr[i] == 87)
                {
                    datiRetrApp.Add(datiRetr[i]);
                }
            }

            if (datiRetrApp != null && datiRetrApp.Count > 0)
            {
                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrApp)
                {
                    datiRetrOrdered.Add(r);
                }
            }

            // Caso per gestione assente
            datiRetrApp = new List<GestioneCalcolo.DatiCalcoloRetributivo>();
            for (int i = 0; i < datiRetr.Count; i++)
            {
                if (string.IsNullOrEmpty(GetGestioneRetributiva(datiRetr[i].CodiceGestione, listaCodeGestioneCalcoloRetributivo)) &&
                    mesiDecDatiRetr[i] == 0)
                {
                    datiRetrApp.Add(datiRetr[i]);
                }
            }
            if (datiRetrApp != null && datiRetrApp.Count > 0)
            {
                foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetrApp)
                {
                    datiRetrOrdered.Add(r);
                }
            }
        }

        internal static void OrdinaDatiContributivi(GestionePensione.DatiPensione datiPensione, ref EntityBLCommon.ContenitoreDecodifica contenitoreDecodifica, ref EntityBLCommon.ContenitoreObject contenitore, List<GestioneAggiornamentoPECO.DatiContributivi> datiContr,
            List<GestioneDecodifica.CodeGestioneCalcoloContributivo> listaCodeGestioneCalcoloContributivo, GestioneDanteCausa.DatiDanteCausa datiDanteCausa, out List<GestioneAggiornamentoPECO.DatiContributivi> datiContrOrdered)
        {
            List<GestioneCalcolo.DatiCalcoloContributivo> ldatiContributivi = GestioneContrib.MappingDatiContributiviFromViewToBL(ref contenitoreDecodifica, datiContr, datiPensione, datiDanteCausa);
            List<GestioneCalcolo.DatiCalcoloContributivo> ldatiContributiviOrdered = null;
            var IsAnte96 = Utility.IsDomandaAnte96(datiPensione, datiPensione, datiDanteCausa, Utility.IsRiaperturaDomanda(datiPensione.Id));
            if (IsAnte96 == null)
                OrdinaDatiContributivi(datiPensione, ldatiContributivi, listaCodeGestioneCalcoloContributivo, out ldatiContributiviOrdered);
            else
                ldatiContributiviOrdered = ldatiContributivi;

            datiContrOrdered = GestioneContrib.MappingDatiContributiviFromBLToView(ref contenitoreDecodifica, ref contenitore, ldatiContributiviOrdered, datiPensione);
        }

        private static void OrdinaDatiContributivi(GestionePensione.DatiPensione datiPensione, List<GestioneCalcolo.DatiCalcoloContributivo> datiContr,
            List<GestioneDecodifica.CodeGestioneCalcoloContributivo> listaCodeGestioneCalcoloContributivo, out List<GestioneCalcolo.DatiCalcoloContributivo> datiContrOrdered)
        {
            //Per le Ricostituzioni il metodo di ordinamento deve essere bypassato
            if (!Utility.IsRicostituzione(datiPensione.Gruppo))
            {
                if (Utility.IsDomandaINPDAI(datiPensione.SiglaCategoria))
                    OrdinaDatiContributiviINPDAI(datiContr, listaCodeGestioneCalcoloContributivo, out datiContrOrdered);
                else
                    OrdinaDatiContributiviAGO(datiPensione, datiContr, listaCodeGestioneCalcoloContributivo, out datiContrOrdered);
            }
            else
                datiContrOrdered = datiContr;
        }

        private static void OrdinaDatiContributiviAGO(GestionePensione.DatiPensione datiPensione, List<GestioneCalcolo.DatiCalcoloContributivo> datiContr, List<GestioneDecodifica.CodeGestioneCalcoloContributivo> listaCodeGestioneCalcoloContributivo,
            out List<GestioneCalcolo.DatiCalcoloContributivo> datiContrOrdered)
        {
            datiContrOrdered = new List<GestioneCalcolo.DatiCalcoloContributivo>();

            List<GestioneCalcolo.DatiCalcoloContributivo> datiContrApp = null;

            //Si ordina la tabella VCTR335 secondo il Campo e la sequenza che segue: 
            //(PNLCR111 all'etichetta SORTA-CONTRIBUTIVO) 
            //Codice Gestione 1 quota C
            //Codice Gestione 1 quota D
            //Codice Gestione 1H quota C
            //Codice Gestione 1H quota D
            //Codice Gestione 2 quota C
            //Codice Gestione 2 quota D
            //Codice Gestione 2H quota C
            //Codice Gestione 2H quota D
            //Codice Gestione 3 quota C
            //Codice Gestione 3 quota D
            //Codice Gestione 3H quota C
            //Codice Gestione 3H quota D
            //Codice Gestione 4 quota C
            //Codice Gestione 4 quota D
            //Codice Gestione 4H quota C
            //Codice Gestione 4H quota D
            //Codice Gestione 7 quota C
            //Codice Gestione 7 quota D
            //Codice Gestione G quota C
            //Codice Gestione G quota D
            //Codice Gestione C1 quota C
            //Codice Gestione C1 quota D
            //Codice Gestione C2 quota C
            //Codice Gestione C2 quota D
            //Codice Gestione C3 quota C
            //Codice Gestione C3 quota D
            //Codice Gestione C4 quota C
            //Codice Gestione C4 quota D
            //Codice Gestione C5 quota C
            //Codice Gestione C5 quota D
            //Codice Gestione D1 quota C
            //Codice Gestione D1 quota D
            //Codice Gestione E1 quota C
            //Codice Gestione E1 quota D
            //Codice Gestione E2 quota C
            //Codice Gestione E2 quota D
            //Codice Gestione F0 quota C
            //Codice Gestione F0 quota D
            //Codice Gestione F1 quota C
            //Codice Gestione F1 quota D
            //Codice Gestione A quota C
            //Codice Gestione A quota D
            //Codice Gestione H quota C
            //Codice Gestione H quota D
            //Codice Gestione I quota C
            //Codice Gestione I quota D
            //Codice Gestione M quota C
            //Codice Gestione M quota D
            //Codice Gestione N quota C
            //Codice Gestione N quota D
            List<string> listaGestioni = new List<string> { "1", "1H", "2", "2H", "3", "3H", "4", "4H", "7", "G", "C1", "C2", "C3", "C4", "C5", "D1", "E1", "E2", "F0", "F1", "A", "H", "I", "M", "N" , "A5", "A6", "A7", "A8", "A9",
                "B1", "B2", "B3", "B4", "L", "FB" };

            string primaGestione = GetGestioneContributiva(datiContr.First().CodiceGestione, listaCodeGestioneCalcoloContributivo);
            listaGestioni.Remove(primaGestione);
            listaGestioni.Insert(0, primaGestione);

            foreach (string codiceGestione in listaGestioni)
            {
                datiContrApp = new List<GestioneCalcolo.DatiCalcoloContributivo>();
                for (int i = 0; i < datiContr.Count; i++)
                {
                    bool isBypassAUT = false;
                    if (Utility.IsDomandaAUT(datiPensione) && !datiContr[i].NSettimane.HasValue && !datiContr[i].NSettimaneQuotaDL214.HasValue)
                        isBypassAUT = true;
                    if (GetGestioneContributiva(datiContr[i].CodiceGestione, listaCodeGestioneCalcoloContributivo) == codiceGestione &&
                        (datiContr[i].NSettimane.HasValue ||
                        (isBypassAUT && (datiContr[i].ImportoContributivoTotale.GetValueOrDefault() > 0 || datiContr[i].Montante.GetValueOrDefault() > 0)) ||
                        (!datiContr[i].NSettimane.HasValue && !datiContr[i].NSettimaneQuotaDL214.HasValue && Utility.IsRicostituzioneOrRiapertura(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id)) && Utility.IsDomandaVOCRED_CRED27(datiPensione.SiglaCategoria) && GetGestioneContributiva(datiContr[i].CodiceGestione, listaCodeGestioneCalcoloContributivo) == "L")))
                    {
                        if (isBypassAUT)
                            datiContr[i].NSettimane = 0;
                        datiContrApp.Add(datiContr[i]);
                    }
                }
                if (datiContrApp != null && datiContrApp.Count > 0)
                {
                    foreach (GestioneCalcolo.DatiCalcoloContributivo r in datiContrApp)
                    {
                        datiContrOrdered.Add(r);
                    }
                }

                datiContrApp = new List<GestioneCalcolo.DatiCalcoloContributivo>();
                for (int i = 0; i < datiContr.Count; i++)
                {
                    bool isBypassAUT = false;
                    if (Utility.IsDomandaAUT(datiPensione) && !datiContr[i].NSettimane.HasValue && !datiContr[i].NSettimaneQuotaDL214.HasValue)
                        isBypassAUT = true;
                    if (GetGestioneContributiva(datiContr[i].CodiceGestione, listaCodeGestioneCalcoloContributivo) == codiceGestione &&
                        (datiContr[i].NSettimaneQuotaDL214.HasValue ||
                        (isBypassAUT && (datiContr[i].ImportoContribTotaleQuotaDL214.GetValueOrDefault() > 0 || datiContr[i].MontanteQuotaDL214.GetValueOrDefault() > 0))))
                    {
                        if (isBypassAUT)
                            datiContr[i].NSettimaneQuotaDL214 = 0;
                        datiContrApp.Add(datiContr[i]);
                    }
                }
                if (datiContrApp != null && datiContrApp.Count > 0)
                {
                    foreach (GestioneCalcolo.DatiCalcoloContributivo r in datiContrApp)
                    {
                        datiContrOrdered.Add(r);
                    }
                }
            }


            // Caso per gestione assente
            datiContrApp = new List<GestioneCalcolo.DatiCalcoloContributivo>();
            for (int i = 0; i < datiContr.Count; i++)
            {
                if (string.IsNullOrEmpty(GetGestioneContributiva(datiContr[i].CodiceGestione, listaCodeGestioneCalcoloContributivo)))
                {
                    datiContrApp.Add(datiContr[i]);
                }
            }
            if (datiContrApp != null && datiContrApp.Count > 0)
            {
                foreach (GestioneCalcolo.DatiCalcoloContributivo r in datiContrApp)
                {
                    datiContrOrdered.Add(r);
                }
            }
        }

