        private static Comparison<GestioneCalcolo.DatiCalcoloContributivo> sortDatiContr = delegate
            (GestioneCalcolo.DatiCalcoloContributivo d1, GestioneCalcolo.DatiCalcoloContributivo d2)
        {
            try
            {
                int retValue = 0;
                retValue = d1.CodiceGestione.Value.CompareTo(d2.CodiceGestione.Value);
                if (retValue == 0)
                {
                    if ((d1.NSettimane.HasValue && d2.NSettimane.HasValue) || (d1.NSettimaneQuotaDL214.HasValue && d2.NSettimaneQuotaDL214.HasValue))
                        retValue = 0;
                    else if (d1.NSettimane.HasValue)
                        retValue = -1;
                    else
                        retValue = 1;
                }
                return retValue;
            }
            catch (INPS.DNA.DnaExceptionBase)
            {
                throw;
            }
            catch (Exception ex)
            {
                throw new INPS.DNA.DnaApplicationException("Errore nel metodo sortDatiContr" + ex);
            }
        };

        private static bool ControlsGestioneDatiCalcolo(string siglaCategoria, string filtro, string gestione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            //Devono essere obbligatori presenti i Codici Gestione Contributiva o Retributiva così come appresso specificato: 
            //Categoria (RACATEG) Codice Gestione
            //VO 1 
            //IO 1 
            //SO 1 
            //VOBANC 1 
            //IOBANC 1 
            //SOBANC 1 
            //VOCRED 1 
            //VOCOOP 1 
            //VOESO 1 
            //VOP 1 
            //IOP 1 
            //SOP 1 
            //VOMIN 1 
            //SOMIN 1 
            //VR 2 
            //IR 2 
            //SR 2 
            //VOART 3 
            //IOART 3 
            //SOART 3 
            //VOCOM 4 
            //IOCOM 4 
            //SOCOM 4 
            //VOAUT G 
            //IOAUT G 
            //SOAUT G
            switch (siglaCategoria)
            {
                case "VO":
                case "IO":
                case "SO":
                case "VOBANC":
                case "IOBANC":
                case "SOBANC":
                case "VOCRED":
                case "CRED27":
                case "VOCOOP":
                case "VOESO":
                case "VOP":
                case "IOP":
                case "SOP":
                case "VOMIN":
                case "SOMIN":
                case "COOP28":
                    if (gestione != "1" && ((siglaCategoria == "VO" || siglaCategoria == "IO" || siglaCategoria == "SO") && gestione != "1H"))
                    {
                        if (filtro == "RAL" || filtro == "R44" || filtro == "R45")
                            messaggioVideo = "E' necessario inserire un codice gestione contributiva e/o retributiva pari a 1 o 1H";
                        else
                            messaggioVideo = "E' necessario inserire un codice gestione contributiva e/o retributiva pari a 1";
                        return false;
                    }
                    break;
                case "VR":
                case "IR":
                case "SR":
                    if (gestione != "2" && gestione != "2H")
                    {
                        if (filtro == "RAL" || filtro == "R44" || filtro == "R45")
                            messaggioVideo = "E' necessario inserire un codice gestione contributiva e/o retributiva pari a 2 o 2H";
                        else
                            messaggioVideo = "E' necessario inserire un codice gestione contributiva e/o retributiva pari a 2";
                        return false;
                    }
                    break;
                case "VOART":
                case "IOART":
                case "SOART":
                    if (gestione != "3" && gestione != "3H")
                    {
                        if (filtro == "RAL" || filtro == "R44" || filtro == "R45")
                            messaggioVideo = "E' necessario inserire un codice gestione contributiva e/o retributiva pari a 3 o 3H";
                        else
                            messaggioVideo = "E' necessario inserire un codice gestione contributiva e/o retributiva pari a 3";
                        return false;
                    }
                    break;
                case "VOCOM":
                case "IOCOM":
                case "SOCOM":
                    if (gestione != "4" && gestione != "4H")
                    {
                        if (filtro == "RAL" || filtro == "R44" || filtro == "R45")
                            messaggioVideo = "E' necessario inserire un codice gestione contributiva e/o retributiva pari a 4 o 4H";
                        else
                            messaggioVideo = "E' necessario inserire un codice gestione contributiva e/o retributiva pari a 4";
                        return false;
                    }
                    break;
                case "VOAUT":
                case "IOAUT":
                case "SOAUT":
                    if (gestione != "G")
                    {
                        messaggioVideo = "E' necessario inserire un codice gestione contributiva e/o retributiva pari a G";
                        return false;
                    }
                    break;
            }
            return true;
        }

        private static bool ControlsSettimaneGestioneDatiCalcolo(GestionePensione.DatiPensione datiPensione, List<GestioneCalcolo.DatiCalcoloContributivo> datiContr,
            List<GestioneCalcolo.DatiCalcoloRetributivo> datiRetrib, List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> listaCodeGestioneCalcoloRetributivo,
            List<GestioneDecodifica.CodeGestioneCalcoloContributivo> listaCodeGestioneCalcoloContributivo, GestioneDanteCausa.DatiDanteCausa danteCausa, GestioneIntegrazioneArt11.IntegrazioneArt11 datiIntegrazioneArt11, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (GestioneBypassControllo.CheckAndLockBypassControlloByNomeBypass(datiPensione, GestioneBypassControllo.NomeBypass.DatiCalcolo_DatiCalcolo_AGO.NUM_SET_MAGG_2080))
                return true;

            Dictionary<long, int> listaSettimanePerGestioneContr = new Dictionary<long, int>();
            if (datiContr != null && datiContr.Count > 0 && !Utility.IsDomandaAUT(datiPensione))
            {
                for (int i = 0; i < datiContr.Count; i++)
                {
                    if (datiContr[i].CodiceGestione.HasValue)
                    {
                        List<GestioneCalcolo.DatiCalcoloContributivo> datiContrFiltered = datiContr.FindAll(x =>
                            x.CodiceGestione.HasValue && x.CodiceGestione.Value == datiContr[i].CodiceGestione.Value &&
                            !listaSettimanePerGestioneContr.ContainsKey(x.CodiceGestione.Value));
                        if (datiContrFiltered != null && datiContrFiltered.Count > 0)
                        {
                            int sommaSett = 0;
                            foreach (GestioneCalcolo.DatiCalcoloContributivo c in datiContrFiltered)
                            {
                                sommaSett += c.NSettimane.HasValue ? c.NSettimane.Value : 0;
                            }
                            if (sommaSett > 2080)
                            {
                                messaggioVideo = "La somma delle settimane per la gestione " + GetGestioneContributiva(datiContrFiltered[0].CodiceGestione, listaCodeGestioneCalcoloContributivo) +
                                    " supera le 2080 settimane";
                                return false;
                            }
                            listaSettimanePerGestioneContr.Add(datiContrFiltered[0].CodiceGestione.Value, sommaSett);

                        }
                    }
                }
            }

            Dictionary<long, int> listaSettimanePerGestioneRetr = new Dictionary<long, int>();
            if (datiRetrib != null && datiRetrib.Count > 0)
            {
                for (int i = 0; i < datiRetrib.Count; i++)
                {
                    if (datiRetrib[i].CodiceGestione.HasValue)
                    {
                        List<GestioneCalcolo.DatiCalcoloRetributivo> datiRetribFiltered = datiRetrib.FindAll(x =>
                            x.CodiceGestione.HasValue && x.CodiceGestione.Value == datiRetrib[i].CodiceGestione.Value &&
                            !listaSettimanePerGestioneRetr.ContainsKey(x.CodiceGestione.Value));
                        if (datiRetribFiltered != null && datiRetribFiltered.Count > 0)
                        {
                            int sommaSett = 0;
                            foreach (GestioneCalcolo.DatiCalcoloRetributivo r in datiRetribFiltered)
                            {
                                sommaSett += r.NSettimaneQuotaA.HasValue ? r.NSettimaneQuotaA.Value : 0;
                                sommaSett += r.NSettimaneQuotaB.HasValue ? r.NSettimaneQuotaB.Value : 0;
                                sommaSett += r.NSettimaneQuotaC.HasValue ? r.NSettimaneQuotaC.Value : 0;
                            }
                            if (!Utility.IsDomandaINPDAI(datiPensione.SiglaCategoria)
                                && !((Utility.IsDomandaAnte96(datiPensione, datiPensione, danteCausa, Utility.IsRiaperturaDomanda(datiPensione.Id)) != null && Utility.IsRicostituzione(datiPensione.Gruppo))
                                && ((datiIntegrazioneArt11 != null && datiIntegrazioneArt11.ImportoIVS.HasValue && datiIntegrazioneArt11.ImportoIVS > 0) || (datiIntegrazioneArt11 != null && datiRetrib[i].NSettAnzianitaVV.HasValue && datiRetrib[i].NSettAnzianitaVV > 0))))
                            {
                                if (sommaSett > 2080)
                                {
                                    messaggioVideo = "La somma delle settimane per la gestione " + GetGestioneRetributiva(datiRetribFiltered[0].CodiceGestione, listaCodeGestioneCalcoloRetributivo) +
                                        " supera le 2080 settimane";
                                    return false;
                                }
                            }
                            //I controlli relativa ai massimi valori inseribili per le DAI sono stati implementati nel metodo GestioneContrib.ControlsDatiCalcoloINPDAI(...)
                            //else
                            //{
                            //    if (sommaSett > maxGiorniDatiRetrINPDAI)
                            //    {
                            //        messaggioVideo = "La somma dei giorni per la gestione " + GetGestioneRetributiva(datiRetribFiltered[0].CodiceGestione, listaCodeGestioneCalcoloRetributivo) +
                            //            " supera i 14400 giorni.";
                            //        return false;
                            //    }
                            //}
                            listaSettimanePerGestioneRetr.Add(datiRetribFiltered[0].CodiceGestione.Value, sommaSett);

                        }
                    }
                }
            }
            //Commentato in seguito a mail del 2015-11-02 con oggetto 'I: produzione 2082683300020' 
            //if (listaSettimanePerGestioneContr.Count > 0 && listaSettimanePerGestioneRetr.Count > 0)
            //{
            //    foreach (var dC in listaSettimanePerGestioneContr)
            //    {
            //        if (listaSettimanePerGestioneRetr.ContainsKey(dC.Key) && dC.Value + listaSettimanePerGestioneRetr[dC.Key] > 2080)
            //        {
            //            messaggioVideo = "La somma delle settimane per la gestione " + GetGestioneContributiva(dC.Key, listaCodeGestioneCalcoloContributivo) +
            //                            " supera le 2080 settimane";
            //            return false;
            //        }
            //    }
            //}

            if (Utility.IsDomandaBancari(datiPensione.SiglaCategoria))
            {
                //si verificherà solo per gestione 1
                if (listaSettimanePerGestioneContr.Count > 0 && listaSettimanePerGestioneRetr.Count > 0)
                {
                    foreach (var dC in listaSettimanePerGestioneContr)
                    {
                        if (listaSettimanePerGestioneRetr.ContainsKey(dC.Key) && dC.Value + listaSettimanePerGestioneRetr[dC.Key] > 2080)
                        {
                            messaggioVideo = "La somma delle settimane per la gestione " + GetGestioneContributiva(dC.Key, listaCodeGestioneCalcoloContributivo) +
                                            " supera le 2080 settimane";
                            return false;
                        }
                    }
                }
            }

            return true;
        }

        private static bool ControlsGestioneHContribRetrib(List<GestioneCalcolo.DatiCalcoloContributivo> datiContr, List<GestioneCalcolo.DatiCalcoloRetributivo> datiRetrib,
            string filtro, List<GestioneDecodifica.CodeGestioneCalcoloRetributivo> listaCodeGestioneCalcoloRetributivo,
            List<GestioneDecodifica.CodeGestioneCalcoloContributivo> listaCodeGestioneCalcoloContributivo, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (!string.IsNullOrEmpty(filtro))
            {
                if (filtro == "RAL" || filtro == "R44" || filtro == "R45")
                {
                    bool isPresente = false;
                    if (datiContr != null && datiContr.Count > 0)
                        isPresente = datiContr.Exists(x => GetGestioneContributiva(x.CodiceGestione, listaCodeGestioneCalcoloContributivo) == "1H" ||
                                                           GetGestioneContributiva(x.CodiceGestione, listaCodeGestioneCalcoloContributivo) == "2H" ||
                                                           GetGestioneContributiva(x.CodiceGestione, listaCodeGestioneCalcoloContributivo) == "3H" ||
                                                           GetGestioneContributiva(x.CodiceGestione, listaCodeGestioneCalcoloContributivo) == "4H");
                    if (datiRetrib != null && datiRetrib.Count > 0)
                        if (!isPresente)
                            isPresente = datiRetrib.Exists(x => GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "1H" ||
                                                                GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "2H" ||
                                                                GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "3H" ||
                                                                GetGestioneRetributiva(x.CodiceGestione, listaCodeGestioneCalcoloRetributivo) == "4H");

                    if (!isPresente)
                    {
                        messaggioVideo = "Deve esistere almeno un elemento con codice gestione 1H o 2H o 3H o 4H";
                        return false;
                    }
                }
            }

            return true;
        }

