        #region Bititolarita
        private static bool ControlsUlterioriBititolarita(GestionePensione.DatiPensione datiPensione, List<Entity.AltraPensione> LaltraPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (LaltraPensione == null || LaltraPensione.Count == 0)
                return true;

            #region Recupero Dati

            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione mancanti";
                return false;
            }

            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';
            Utility.GetCodiciNatura(datiPensione.NaturaPensione, out codNat1, out codNat2, out codNat3);
            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            int pdirsup = 0;
            int plavaut = 0;
            GetPdirusp_Plavaut(datiPensione, out pdirsup, out plavaut);
            string certificato = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);

            string catNum = string.Empty;
            GestioneDecodifica.GetCodCategoriaBySiglaCategoria(siglaCategoria, out catNum);

            #endregion Recupero Dati

            bool nonAmmessa = false;
            bool? supplementareConDecorrenzaAntecedente = null;
            bool? supplementareConDecorrenzaPosteriore = null;
            bool? supplementareOR_BR = null; // true se la pensione è una supplementare ed è presente un'altra pensione con categoria OR o BR
            bool? presenteG = null;
            bool? presenteL = null;
            bool? presenteR = null;
            bool? presenteA = null;
            bool? presenteT = null;
            bool presenteCatPerPensioneSupplementare = false;
            bool presenteCatPerPensioneSupplementareEnpals = false;
            bool presenteCatPerPensioneSupplementareAltraPensioneNoEnpals = false;
            bool presenteRenditaVitaliziaINADEL = false; // rendita vitalizia INADEL tra le altre pensioni (categoria = "LA", certificato = "094*****")
            //E’ possibile acquisire le bititolarità se il primo codice natura è pari a 2, 4, 5, 6, 9
            if (codNat1 != '2' && codNat1 != '4' && codNat1 != '5' && codNat1 != '6' && codNat1 != '9')
            {
                messaggioVideo = "Non è possibile acquisire le bititolarità se il primo codice natura è pari a " + codNat1;
                return false;
            }

            bool isSuperstiteOrfano = false;
            if (Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione))
            {
                List<GestioneFamiliari.Familiare> listaFamiliari = null;
                List<GestioneAnagrafica.DatiAnagrafici> listaAnagraficheFamiliari = null;
                GestioneFamiliari.GetFamiliariByIdPensione(datiPensione.Id, out listaFamiliari, out listaAnagraficheFamiliari);

                GestioneAnagrafica.DatiAnagrafici datiAnagrafici = null;
                GestioneAnagrafica.GetAnagraficaByIdPensione(datiPensione.Id, out datiAnagrafici);

                if (listaFamiliari != null)
                {
                    GestioneFamiliari.Familiare familiareTitolare = listaFamiliari.FirstOrDefault(x => x.IdAnagrafica == datiAnagrafici.Id);
                    if (familiareTitolare != null)
                    {
                        if (new List<char> { 'M', 'S', 'U', 'I' }.Contains(familiareTitolare.SiglaFamiliare.GetValueOrDefault()))
                            isSuperstiteOrfano = true;
                    }
                }
            }

            if (!isSuperstiteOrfano)
            {
                foreach (Entity.AltraPensione aP in LaltraPensione)
                {
                    if (!GestioneAltrePensioni.VerifyCtrlBititolarita(aP.Categoria, aP.CodiceUC.GetValueOrDefault(), aP.CodiceImporto.GetValueOrDefault(), Utility.TipoAppartenenza.AGO)
                        && !((siglaCategoria == "VOTOT" || siglaCategoria == "IOTOT") && (new List<string> { "024", "037", "040", "069", "045", "048", "051", "054", "057", "060", "063", "066", "079", "094", "097" }.Contains(aP.Categoria)) && aP.CodiceImporto.GetValueOrDefault() == '4'))
                    {
                        messaggioVideo = "La combinazione categoria (" + (!string.IsNullOrEmpty(aP.Categoria) ? aP.Categoria.ToUpperInvariant() : " ") + ") codice U/C (" + aP.CodiceUC.GetValueOrDefault() +
                            ") e codice importo (" + aP.CodiceImporto.GetValueOrDefault() + ") non è ammessa";
                        return false;
                    }

                    //Categoria = "070"
                    //Implica che importo = "0” con PDIRSUP = 0 e RAU1031 = 5
                    if (aP.Categoria == "070" && codNat1 == '5' && pdirsup == 0)
                    {
                        if (aP.CodiceImporto.GetValueOrDefault() != '0')
                        {
                            messaggioVideo = "Per la categoria " + aP.Categoria + " il codice importo deve essere pari a 0";
                            return false;
                        }
                    }

                    //Categoria = "070" OR "071"
                    //Implica che codice U/C = U o C; importo = "0” con RAU1031 = 6 e categ = VOSPED, IOSPED e SOSPED
                    if ((aP.Categoria == "070" || aP.Categoria == "071") && codNat1 == '6' &&
                        (siglaCategoria == "VOSPED" || siglaCategoria == "IOSPED" || siglaCategoria == "SOSPED"))
                    {
                        if (aP.CodiceImporto.GetValueOrDefault() != '0')
                        {
                            messaggioVideo = "Per la categoria " + aP.Categoria + " il codice importo deve essere pari a 0";
                            return false;
                        }
                    }

                    //Categoria = "070" OR "071"
                    //Implica che importo = "0” con PDIRSUP = 1 e RAU1031 = 2,4,5,6,9
                    if ((aP.Categoria == "070" || aP.Categoria == "071") &&
                        (codNat1 == '2' || codNat1 == '4' || codNat1 == '5' || codNat1 == '6' || codNat1 == '9') &&
                        pdirsup == 1)
                    {
                        if (aP.CodiceImporto.GetValueOrDefault() != '0')
                        {
                            messaggioVideo = "Per la categoria " + aP.Categoria + " il codice importo deve essere pari a 0";
                            return false;
                        }
                    }

                    //controlli incompatibilità tra sigla categoria e categoria altra pensione
                    switch (siglaCategoria)
                    {
                        case "VDAI":
                        case "IDAI":
                            if (aP.Categoria == "082" || aP.Categoria == "083")
                                nonAmmessa = true;
                            break;
                        case "VO":
