                List<string> categorieAmmesseSuperstitiSupplementari = new List<string> { "GA", "GR", "CA", "CR", "EA", "ER", "FA", "FR" };
                if (codNat1 == '5' && siglaCategoria.StartsWith("S") && LaltraPensione.Exists(x => categorieAmmesseSuperstitiSupplementari.Contains(x.Categoria.Trim())) && !supplementareOR_BR.GetValueOrDefault())
                {
