                                            case "061":
                                            case "079":
                                            case "080":
                                            case "082":
                                            case "083":
                                            case "088":
                                            case "089":
                                            case "091":
                                            case "092":
                                            case "095":
                                            case "098":
                                            case "801":
                                            case "802":
                                                nonAmmessa = true;
                                                break;
                                            case "014":
                                            case "016":
                                            case "085":
                                            case "086":
                                                switch (LaltraPensioneNonCessate[i].Categoria)
                                                {
                                                    case "018":
                                                    case "019":
                                                    case "021":
                                                    case "022":
                                                    case "088":
                                                    case "089":
                                                    case "091":
                                                    case "092":
                                                        nonAmmessa = true;
                                                        break;
                                                }
                                                break;
                                        }
                                        break;
                                    case "010":
                                    case "011":
                                        switch (LaltraPensioneNonCessate[j].Categoria)
                                        {
                                            case "010":
                                            case "011":
                                                nonAmmessa = true;
                                                break;
                                        }
                                        break;
                                    case "015":
                                    case "016":
                                    case "085":
                                    case "086":
                                        switch (LaltraPensioneNonCessate[j].Categoria)
                                        {
                                            case "037":
                                            case "038":
                                            case "040":
                                            case "041":
                                            case "048":
                                            case "049":
                                            case "060":
                                            case "061":
                                            case "095":
                                            case "098":
                                            case "014":
                                            case "016":
                                            case "085":
                                            case "086":
                                                nonAmmessa = true;
                                                break;
                                        }
                                        break;
                                }
                            }
                        }
                    }
                    if (nonAmmessa)
                    {
                        messaggioVideo = "Incompatibilità tra categoria " + altraPensione1 + " non cessata con categoria " + altraPensione2 + " non cessata";
                        return false;
                    }
                }

                if (codNat1 == '5' && siglaCategoria.StartsWith("S"))
                {
                    List<string> listaCategorieObblPerSuperstitiSupplementari = new List<string> { "003", "006", "009", "012", "014", "017", "020", "023", "024", "034", "072", "075", "084", "087", "090",
                    "093", "172", "203", "206", "803", "BR", "CR", "ER", "FR", "GR", "HR", "LR", "NR", "OR" };
                    if (LaltraPensione != null && LaltraPensione.Count > 0 && !LaltraPensione.Exists(x => listaCategorieObblPerSuperstitiSupplementari.Contains(x.Categoria.Trim())))
                    {
                        messaggioVideo = "Per le pensioni ai superstiti supplementari è obbligatorio inserire almeno un record con categoria uguale ad una delle seguenti: " + string.Join(", ", listaCategorieObblPerSuperstitiSupplementari.ToArray()) + ".";
                        return false;
                    }
                }

                int? categoriaNumerica = Utility.StringToNullableInt(catNum);
                if ((categoriaNumerica.GetValueOrDefault() > 0 && categoriaNumerica.GetValueOrDefault() < 99) || categoriaNumerica.GetValueOrDefault() == 170 || categoriaNumerica.GetValueOrDefault() == 171)
                {
                    if (LaltraPensione != null && LaltraPensione.Count > 0 && LaltraPensione.Exists(x => x.Categoria.Trim() == catNum.Trim()))
                    {
                        messaggioVideo = "Non è possibile inserire un codice categoria uguale alla categoria della pensione in liquidazione se questa è erogata dall'INPS (Categoria: " + catNum + ").";
                        return false;
                    }
                }
            }
            else
            {
                if (codNat1 == '5' && siglaCategoria.StartsWith("S"))
                {
                    if (Utility.IsDomandaENPALS(datiPensione.Gestione))
                    {
                        List<string> listaCategorieNecessarie = new List<string> { "OR", "BR", "ER", "FR", "017", "020", "023", "045", "048", "051", "054", "057", "060", "063", "066", "087", "090", "093", "094", "097" };
                        if (!LaltraPensione.Exists(x => listaCategorieNecessarie.Contains(x.Categoria.Trim())))
                        {
                            messaggioVideo = "Per una domanda ai superstiti supplementare ENPALS deve esistere almeno una registrazione relativa ad altra pensione avente codice categoria " +
                                "OR, BR, ER, FR, 017, 020, 023, 045, 048, 051, 054, 057, 060, 063, 066, 087, 090, 093, 094, 097.";
                            return false;
                        }
                    }
                    else
                    {
                        List<string> listaCategorieNecessarie = new List<string> { "OR", "BR", "CR", "ER", "FR", "GR", "024", "045", "048", "051", "054", "057", "060", "063", "066", "094", "097", "203", "206" };
                        if (!LaltraPensione.Exists(x => listaCategorieNecessarie.Contains(x.Categoria.Trim())))
                        {
                            messaggioVideo = "Per una domanda ai superstiti supplementare non ENPALS deve esistere almeno una registrazione relativa ad altra pensione avente codice categoria " +
                                "OR, BR, CR, ER, FR, GR, 024, 045, 048, 051, 054, 057, 060, 063, 066, 094, 097, 203, 206.";
                            return false;
                        }
                    }
                }
            }

            return true;
        }

        public static bool ControlsBititolaritaAnte96(GestionePensione.DatiPensione datiPensione, List<Entity.AltraPensione> LaltraPensione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (LaltraPensione == null || LaltraPensione.Count == 0)
                return true;

            #region Recupero Dati

            if (datiPensione == null)
            {
                messaggioVideo = "Dati pensione mancanti";
                return false;
            }

            char codNat1 = ' ';
            char codNat2 = ' ';
            char codNat3 = ' ';
            Utility.GetCodiciNatura(datiPensione.NaturaPensione, out codNat1, out codNat2, out codNat3);
            string filtro = string.Empty;
            string siglaCategoria = string.Empty;
            GetFiltro_SiglaCategoria(datiPensione, out filtro, out siglaCategoria);
            int pdirsup = 0;
            int plavaut = 0;
            GetPdirusp_Plavaut(datiPensione, out pdirsup, out plavaut);
            string certificato = string.Empty;
            DateTime decorrenzaOriginaria = DateTime.MinValue;
            GetCertificato_DecorrenzaPensione(datiPensione, out decorrenzaOriginaria, out certificato);

            string catNum = string.Empty;
            GestioneDecodifica.GetCodCategoriaBySiglaCategoria(siglaCategoria, out catNum);

            #endregion Recupero Dati

            bool isSuperstiteOrfano = false;
            if (Utility.IsDomandaPensioneSuperstitiOrRicostituzione(datiPensione))
            {
                List<GestioneFamiliari.Familiare> listaFamiliari = null;
                List<GestioneAnagrafica.DatiAnagrafici> listaAnagraficheFamiliari = null;
                GestioneFamiliari.GetFamiliariByIdPensione(datiPensione.Id, out listaFamiliari, out listaAnagraficheFamiliari);

                GestioneAnagrafica.DatiAnagrafici datiAnagrafici = null;
                GestioneAnagrafica.GetAnagraficaByIdPensione(datiPensione.Id, out datiAnagrafici);

                if (listaFamiliari != null)
                {
                    GestioneFamiliari.Familiare familiareTitolare = listaFamiliari.FirstOrDefault(x => x.IdAnagrafica == datiAnagrafici.Id);
                    if (familiareTitolare != null)
                    {
                        if (new List<char> { 'M', 'S', 'U', 'I' }.Contains(familiareTitolare.SiglaFamiliare.GetValueOrDefault()))
                            isSuperstiteOrfano = true;
                    }
                }
            }

            if (!isSuperstiteOrfano)
            {
                foreach (Entity.AltraPensione aP in LaltraPensione)
                {
                    if (!GestioneAltrePensioni.VerifyCtrlBititolarita(aP.Categoria, aP.CodiceUC.GetValueOrDefault(), aP.CodiceImporto.GetValueOrDefault(), Utility.TipoAppartenenza.AGO)
                        && !((siglaCategoria == "VOTOT" || siglaCategoria == "IOTOT") && (new List<string> { "024", "037", "040", "069", "045", "048", "051", "054", "057", "060", "063", "066", "079", "094", "097" }.Contains(aP.Categoria)) && aP.CodiceImporto.GetValueOrDefault() == '4'))
                    {
                        messaggioVideo = "La combinazione categoria (" + (!string.IsNullOrEmpty(aP.Categoria) ? aP.Categoria.ToUpperInvariant() : " ") + ") codice U/C (" + aP.CodiceUC.GetValueOrDefault() +
                            ") e codice importo (" + aP.CodiceImporto.GetValueOrDefault() + ") non è ammessa";
                        return false;
                    }

                }

            }

            return true;
        }

        #endregion Bititolarita
        #endregion private members

        internal static bool ControlsCapienzaAreaHostENPALS(GestionePensione.DatiPensione datiPensione, List<Liquidazione.BLCommon.Entity.DatiSuppRecordENPALS> listaSuppRecordENPALS,
            GestioneCalcolo.DatiCalcoloContributivoENPAL datiContributiviENPALS, List<Liquidazione.BLCommon.Entity.DatiSupplementiENPALS> listaSupplementiENPALS, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaENPALS(datiPensione.Gestione))
            {
                int listaSuppRecordENPALSCount = listaSuppRecordENPALS != null ? listaSuppRecordENPALS.Count : 0;
                int listaDatiCalcoloENPALSCount = datiContributiviENPALS != null ? 1 : 0;
                int listaSupplementiENPALSCount = listaSupplementiENPALS != null ? listaSupplementiENPALS.Count : 0;

                // LISTGPINTAR11
                // Integrazione Art. 11
                if (listaSuppRecordENPALSCount > 8)
                {
                    messaggioVideo = "La quantità dei record dei supplementi è superiore alla capienza del calcolo. Eliminare qualche record.";
                    return false;
                }

                // LISTT_GP2BB03
                // Record con Gestione "M1" + "1" + "M0"
                if (listaSuppRecordENPALSCount + listaDatiCalcoloENPALSCount + 1 > 20)
                {
                    messaggioVideo = "La quantità dei record dei supplementi e dei dati contributivi è superiore alla capienza del calcolo. Eliminare qualche record.";
                    return false;
                }

                // LISTT_GP2BE00
                if (listaSupplementiENPALSCount > 30)
                {
                    messaggioVideo = "La quantità dei record dei supplementi retributivi e contributivi è superiore alla capienza del calcolo. Eliminare qualche record.";
                    return false;
                }
            }

            return true;
        }

        /// <summary>
        /// Verifica se è possibile calcolare la domanda per l'azienda di editoria specificata per domande di prepensionamento con tipo 0171
        /// </summary>
        /// <param name="datiPensione"></param>
        /// <param name="isRiaperturaDomanda"></param>
        /// <param name="codiceAziendaEditoria"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool ControlsDomandaPrepensionamentoEditoriaCalcolabile(GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, short? codiceAziendaEditoria, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                return true;

            if (Utility.IsPrepensionamentoEditoriaFiltroEAA(datiPensione))
            {
                if (codiceAziendaEditoria.HasValue)
                {
                    List<GestioneAnagraficaAccordi.DecodAnagraficaAccordi> listaAnagraficaAccordi = null;
                    GestioneAnagraficaAccordi.GetDecAnagraficaAccordi(out listaAnagraficaAccordi);

                    if (listaAnagraficaAccordi != null && listaAnagraficaAccordi.Count > 0)
                    {
                        GestioneAnagraficaAccordi.DecodAnagraficaAccordi anagraficaAccordo = listaAnagraficaAccordi.Find(x => x.Codice == codiceAziendaEditoria);
                        if (anagraficaAccordo != null)
                        {
                            if (!anagraficaAccordo.Abilitata.GetValueOrDefault())
                            {
                                messaggioVideo = "Attenzione: l'azienda/accordo indicati risultano non abilitati.";
                                return false;
                            }

                            if (anagraficaAccordo.DomandeLiquidate >= anagraficaAccordo.DomandeLiquidabili)
                            {
                                messaggioVideo = "Attenzione: è stato superato il numero di domande liquidabili per l’azienda/accordo indicati. È necessario inviare un’email all’indirizzo prepensionamento.editoria@inps.it";
                                return false;
                            }
                        }
                    }
                }
            }

            return true;
        }

