        /// <summary>
        /// Verifica se è possibile calcolare la domanda per l'azienda di editoria specificata per domande di prepensionamento con tipo 0179
        /// </summary>
        /// <param name="datiPensione"></param>
        /// <param name="isRiaperturaDomanda"></param>
        /// <param name="codiceAziendaEditoriaPerTipo0171"></param>
        /// <param name="messaggioVideo"></param>
        /// <returns></returns>
        public static bool ControlsDomandaPrepensionamentoEditoriaPerTipo0179Calcolabile(GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, short? codiceAziendaEditoriaPerTipo0179,
            out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                return true;

            if (Utility.IsPrepensionamentoEditoriaArt1c500L160_2019(datiPensione))
            {
                if (codiceAziendaEditoriaPerTipo0179.HasValue)
                {
                    List<GestioneAnagraficaAccordiPerTipo0179.DecodAnagraficaAccordiPerTipo0179> listaAnagraficaAccordi = null;
                    GestioneAnagraficaAccordiPerTipo0179.GetDecAnagraficaAccordi(out listaAnagraficaAccordi);

                    if (listaAnagraficaAccordi != null && listaAnagraficaAccordi.Count > 0)
                    {
                        GestioneAnagraficaAccordiPerTipo0179.DecodAnagraficaAccordiPerTipo0179 anagraficaAccordo = listaAnagraficaAccordi.Find(x => x.Codice == codiceAziendaEditoriaPerTipo0179);
                        if (anagraficaAccordo != null)
                        {
                            if (!datiPensione.FlagVerify.GetValueOrDefault())
                            {
                                if (!anagraficaAccordo.Abilitata.GetValueOrDefault())
                                {
                                    if (datiPensione.StatoPensione == (int)Utility.StatoPensione.CalcoloVerify)
                                    {
                                        messaggioVideo = "Attenzione: Non è possibile procedere al calcolo della prestazione in attesa della verifica della capienza degli stanziamenti.";
                                        return false;
                                    }
                                    else
                                    {
                                        messaggioVideo = "Attenzione: Pensione da calcolare in verify per controllo capienza oneri.";
                                        return false;
                                    }
                                }
                                if (datiPensione.StatoPensione != (int)Utility.StatoPensione.CalcoloVerify)
                                {
                                    messaggioVideo = "Attenzione: La pensione deve essere calcolata prima in verify per controllo capienza numerica.";
                                    return false;
                                }
                            }
                            else if (!datiPensione.DataElaborazione.HasValue)
                            {
                                if (anagraficaAccordo.DomandeLiquidate >= anagraficaAccordo.DomandeLiquidabili)
                                {
                                    messaggioVideo = "Attenzione: è stato superato il numero di domande liquidabili per l’azienda/accordo indicati.";
                                    return false;
                                }
                            }
                        }
                    }
                }
            }

            return true;
        }

        public static bool VerificaScadenzaIndennitaPerApeSociale(ref EntityBLCommon.ContenitoreObject contenitore, Entity.DatiIstruttoria datiIstruttoriaEntity, out string messaggioVideo)
        {
            messaggioVideo = "";
            if (contenitore.DatiStoricoGP != null && contenitore.DatiStoricoGP.ScadenzaAssegno.HasValue && datiIstruttoriaEntity.ScadenzaAssegno.HasValue &&
