            return true;
        }

        /// <summary>
        /// Verifica se la domanda è una RIC SDAI con codice K nei dati contributivi per bypassare eventualmente i controlli
        /// </summary>
        public static bool BypassaControlliRicSdaiContributivoK(GestionePensione.DatiPensione datiPensione, List<GestioneCalcolo.DatiCalcoloContributivo> listaDatiCalcoloContributivo, List<GestioneDecodifica.CodeGestioneCalcoloContributivo> listaCodeGestioneCalcoloContributivo)
        {
            bool bypassaControlli = false;

            if (datiPensione != null && Utility.IsRicostituzione(datiPensione.Gruppo) && !String.IsNullOrEmpty(datiPensione.SiglaCategoria)
                   && datiPensione.SiglaCategoria.Trim().ToUpperInvariant() == "SDAI")
            {
                if (listaCodeGestioneCalcoloContributivo != null && listaCodeGestioneCalcoloContributivo.Count > 0
                    && listaDatiCalcoloContributivo != null && listaDatiCalcoloContributivo.Count > 0)
                {
                    GestioneDecodifica.CodeGestioneCalcoloContributivo gestioneK = listaCodeGestioneCalcoloContributivo.Find(x => x.TraduzioneSuGP.Trim().ToUpperInvariant() == "K");
                    if (gestioneK != null)
                    {
                        if (listaDatiCalcoloContributivo.Exists(x => x.CodiceGestione == gestioneK.Id))
                            bypassaControlli = true;
                    }
                }
            }

            return bypassaControlli;
        }

        /// <summary>
        /// Verifica se la domanda è RIC/TRF di tipo VOCRED/CRED27 con codice L nei dati contributivi per bypassare i controlli
        /// </summary>
        public static bool BypassaControlliRic_VOCRED_CRED27_ContributivoL(GestionePensione.DatiPensione datiPensione, List<GestioneCalcolo.DatiCalcoloContributivo> listaDatiCalcoloContributivo, List<GestioneDecodifica.CodeGestioneCalcoloContributivo> listaCodeGestioneCalcoloContributivo)
        {
            bool bypassaControlli = false;

            if (datiPensione != null && Utility.IsRicostituzioneOrRiapertura(datiPensione, Utility.IsRiaperturaDomanda(datiPensione.Id)) &&
                Utility.IsDomandaVOCRED_CRED27(datiPensione.SiglaCategoria))
            {
                if (listaCodeGestioneCalcoloContributivo != null && listaCodeGestioneCalcoloContributivo.Count > 0
                    && listaDatiCalcoloContributivo != null && listaDatiCalcoloContributivo.Count > 0)
                {
                    GestioneDecodifica.CodeGestioneCalcoloContributivo gestioneL = listaCodeGestioneCalcoloContributivo.Find(x => x.TraduzioneSuGP.Trim().ToUpperInvariant() == "L");
                    if (gestioneL != null)
                    {
                        if (listaDatiCalcoloContributivo.Exists(x => x.CodiceGestione == gestioneL.Id))
                            bypassaControlli = true;
                    }
                }
            }

            return bypassaControlli;
        }

        /// <summary>
        /// Il metodo verifica se la domanda è una totalizzazione cassa esterna
        /// </summary>
        /// <param name="datiPensione"></param>
        /// <param name="ListaQuotePensione"></param>
        /// <returns></returns>
        public static bool IsCassaEsternaTotalizzazione(GestionePensione.DatiPensione datiPensione, List<GestioneCalcolo.QuotePensione> listaQuotePensione, EntityBLCommon.ContenitoreDecodifica contenitoreDecodifica)
        {
            if (Utility.IsDomandaTotalizzazione(datiPensione.SiglaCategoria) && listaQuotePensione != null && listaQuotePensione.Count > 0)
            {
                GestioneControlliDinamici.ControlloDinamico ctrlAbilitazioneMemo93 = null;
                GestioneControlliDinamici.GetControlloDinamicoByNomeControllo("AbilitazioneMemo93", out ctrlAbilitazioneMemo93);

                List<string> lstCodiciEsterni = new List<string> { "F0", "F1", "G0", "H0", "I0", "J0", "K0", "L0", "N0", "O0", "P0", "Q0", "R0", "S0", "T0", "U0", "V0", "Z0", "Z1", "PR" };
                if (ctrlAbilitazioneMemo93 != null && !String.IsNullOrEmpty(ctrlAbilitazioneMemo93.ValoreControllo) && ctrlAbilitazioneMemo93.ValoreControllo.ToUpperInvariant().Trim() == "SI")
                    lstCodiciEsterni.Remove("F0");

                var listaDecEnteGestioneFondo = contenitoreDecodifica.ElencoDecEnteGestioneFondo;
                if (listaDecEnteGestioneFondo == null)
                    GestioneDecodifica.GetDecEnteGestioneFondo(out listaDecEnteGestioneFondo);

                var lstRecordCodGestione = from Record in listaQuotePensione
                                           join dec in listaDecEnteGestioneFondo on Record.EnteGestioneFondo equals dec.Id
                                           select new { Record, TraduzioneSuGP = dec.Codice.Trim() };

                if (lstRecordCodGestione.Where(x => lstCodiciEsterni.Contains(x.TraduzioneSuGP)).FirstOrDefault() != null)
                    return true;
            }

            return false;
        }

        public static bool IsRiduzioneAssegnoAmmissibile(ref EntityBLCommon.ContenitoreObject contenitore, ref EntityBLCommon.ContenitoreDecodifica contenitoreDecodifica, Entity.DatiIstruttoria datiIstruttoriaEntity, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (contenitore == null || contenitore.DatiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            if (!Utility.IsDomandaCRED27(contenitore.DatiPensione.SiglaCategoria) || Utility.IsDomandaVOCRED_CRED27__DAP(contenitore.DatiPensione))
                return true;

            bool isPresenteQuotaC = VerificaPresenzaQuotaC_Cred27(ref contenitore, ref contenitoreDecodifica, contenitore.ListaDatiContributivi);

            if (isPresenteQuotaC && datiIstruttoriaEntity != null && datiIstruttoriaEntity.RiduzioneAssegno.GetValueOrDefault() > 0)
            {
                messaggioVideo = "Riduzione non consentita in caso di presenza di quota C";
                return false;
            }

            return true;
        }

        public static bool IsRiduzioneAssegnoAmmissibile(ref EntityBLCommon.ContenitoreObject contenitore, ref EntityBLCommon.ContenitoreDecodifica contenitoreDecodifica, List<GestioneCalcolo.DatiCalcoloContributivo> lDatiContributivi, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (contenitore == null || contenitore.DatiPensione == null)
            {
                messaggioVideo = "Dati pensione non disponibili";
                return false;
            }

            if (!Utility.IsDomandaCRED27(contenitore.DatiPensione.SiglaCategoria) || Utility.IsDomandaVOCRED_CRED27__DAP(contenitore.DatiPensione))
                return true;

            bool isPresenteQuotaC = VerificaPresenzaQuotaC_Cred27(ref contenitore, ref contenitoreDecodifica, lDatiContributivi);

            if (isPresenteQuotaC && contenitore != null && contenitore.DatiIstruttoria != null && contenitore.DatiIstruttoria.RiduzioneAssegno.GetValueOrDefault() > 0)
            {
                messaggioVideo = "Riduzione non consentita in caso di presenza di quota C";
                return false;
            }

            return true;
        }

        public static bool VerificaPresenzaQuotaC_Cred27(ref EntityBLCommon.ContenitoreObject contenitore, ref EntityBLCommon.ContenitoreDecodifica contenitoreDecodifica, List<GestioneCalcolo.DatiCalcoloContributivo> lDatiContributivi)
        {
            GestioneDecodifica.CodeGestioneCalcoloContributivo decGestioneL = (contenitoreDecodifica != null && contenitoreDecodifica.ElencoCodeGestioneCalcoloContributivo != null) ? (contenitoreDecodifica.ElencoCodeGestioneCalcoloContributivo.Exists(x => x.TraduzioneSuGP.Trim() == "L") ? contenitoreDecodifica.ElencoCodeGestioneCalcoloContributivo.FirstOrDefault(x => x.TraduzioneSuGP.Trim() == "L") : null) : null;
            GestionePensione.DatiPensione datiPensione = contenitore.DatiPensione;
            bool isRiaperturaDomanda = contenitore.IsRiaperturaDomanda;
            bool isPresenteQuotaC = (lDatiContributivi != null) ? lDatiContributivi.Exists(x => (x.NSettimane.GetValueOrDefault() > 0 || x.Montante.GetValueOrDefault() > 0 || x.MontanteContributivo.GetValueOrDefault() > 0) && (!Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda) || (decGestioneL != null && x.CodiceGestione != decGestioneL.Id))) : false;

            return isPresenteQuotaC;
        }

        //ENG - Prepensionamento Editoria Filtro EBA
        public static bool ControlsDomandaPrepensionamentoEditoriaFiltroEBACalcolabile(GestionePensione.DatiPensione datiPensione, bool isRiaperturaDomanda, short? codiceAziendaEditoria, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsRicostituzioneOrRiapertura(datiPensione, isRiaperturaDomanda))
                return true;

            if (Utility.IsPrepensionamentoEditoriaFiltroEBA(datiPensione))
            {
                if (codiceAziendaEditoria.HasValue)
                {
                    List<GestioneAnagraficaAccordiLetteraB.DecodAnagraficaAccordiLetteraB> listaAnagraficaAccordiLetteraB = null;
                    GestioneAnagraficaAccordiLetteraB.GetDecAnagraficaAccordi(out listaAnagraficaAccordiLetteraB);

                    if (listaAnagraficaAccordiLetteraB != null && listaAnagraficaAccordiLetteraB.Count > 0)
                    {
                        GestioneAnagraficaAccordiLetteraB.DecodAnagraficaAccordiLetteraB anagraficaAccordo = listaAnagraficaAccordiLetteraB.Find(x => x.Codice == codiceAziendaEditoria);
                        if (anagraficaAccordo != null)
                        {
                            if (!anagraficaAccordo.Abilitata.GetValueOrDefault())
                            {
                                messaggioVideo = "Attenzione: l'azienda/accordo indicati risultano non abilitati.";
                                return false;
                            }

                            if (anagraficaAccordo.DomandeLiquidate >= anagraficaAccordo.DomandeLiquidabili)
                            {
                                messaggioVideo = "Attenzione: è stato superato il numero di domande liquidabili per l’azienda/accordo indicati";
                                return false;
                            }
                        }
                    }
                }
            }

            return true;
        }
        //ENG - MEMO 74_2023
        public static bool VerificaDecorrenzaImportiEsteriWithDecorrenzaOriginaria(DateTime? decorrenzaImportoEstero, DateTime? decorrenzaOriginaria, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (decorrenzaImportoEstero.HasValue)
            {
                if (!Utility.DataSuccessivaA(decorrenzaImportoEstero.Value, decorrenzaOriginaria.Value))
                {
                    messaggioVideo = "Decorrenza Prestazione Estera anteriore a Decorrenza Originaria";
                    return false;
                }
            }

            return true;
        }

        public static bool VerificaCoerenzaDecorrenzaCessazione(DateTime? decorrenza, DateTime? cessazione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (cessazione.HasValue)
            {
                if (!Utility.DataSuccessivaA(cessazione.Value, decorrenza.Value))
                {
                    messaggioVideo = "Cessazione Prestazione Estera non posteriore a Decorrenza";
                    return false;
                }

                if (decorrenza.Value.Year != cessazione.Value.Year && Utility.DataStrettamenteSuccessivaA(cessazione.Value, new DateTime(1996, 01, 31)))
                {
                    if (!(cessazione.Value.Year == decorrenza.Value.Year + 1 && cessazione.Value.Month == 1))
                    {
                        messaggioVideo = "Anno Cessazione diverso da anno Decorrenza";
                        return false;
                    }
                }
            }

            return true;
        }

        public static bool VerificaCodiceConvenzioneWithStatoEstero(DateTime? decorrenzaOriginaria, string codiceStato, byte? codiceConvenzione)
        {
            List<GestioneCtrlCodiceConvenzionePrestazioniEE.DatiCtrlCodiceConvenzionePrestazioniEE> listaCodiciConvenzione = null;
            GestioneCtrlCodiceConvenzionePrestazioniEE.GetListaCodiceConvenzionePerStato(codiceStato, decorrenzaOriginaria, out listaCodiciConvenzione);

            if (listaCodiciConvenzione == null || !listaCodiciConvenzione.Exists(x => x.CodiceConvenzione == codiceConvenzione))
                return false;


            return true;
        }

        //ENG - VOPGI NO AGI
        public static bool ControllaInizioAssicurazioneTipoCalcoloVOPGINOAGI(GestionePensione.DatiPensione datiPensione, byte? tipoCalcolo, DateTime? inizioAssicurazione, out string messaggioVideo)
        {
            messaggioVideo = string.Empty;

            if (Utility.IsDomandaVOPGI(datiPensione.SiglaCategoria) && !Utility.IsDomandaVOPGI_AGI(datiPensione))
            {
                if ((Utility.IsPensioneAnzianitaPL(datiPensione) && datiPensione.Tipo == "0001") || Utility.IsDomandaVecchiaiaPL(datiPensione))
                {
                    if (tipoCalcolo.HasValue && tipoCalcolo.Value == 1) //contributivo
                    {
                        if (inizioAssicurazione.HasValue && !Utility.DataSuccessivaA(inizioAssicurazione.Value, new DateTime(1996, 1, 1)))
                        {
                            messaggioVideo = "La data di inizio assicurazione non può essere inferiore al 1996";
                            return false;
                        }
                    }
                    else if (tipoCalcolo.HasValue && (tipoCalcolo.Value == 2 || tipoCalcolo.Value == 21)) //retributivo o misto
                    {
                        if (inizioAssicurazione.HasValue && Utility.DataSuccessivaA(inizioAssicurazione.Value, new DateTime(1996, 1, 1)))
                        {
                            messaggioVideo = "La data di inizio assicurazione non può essere superiore al 1995";
                            return false;
                        }
                    }
                }
            }

            return true;
        }
    }
}
